  var C=window.YLT_CFG||{};var books=C.books||(window.GAME_CONFIG&&window.GAME_CONFIG.books)||[];var byId={};for(var i=0;i<books.length;i++)byId[books[i].id]=books[i];
  function acc(id,chs){var b=byId[id];if(!b)return;b.chapters=(b.chapters||[]).concat(chs);}
  acc("b_jingyue",[{"n": 19, "text": "卷十九\n\n则生风，且疠风尤染肃杀之气而成者，若非汗法，何以去其毒风？所以汗之一法，乃治疠之 \n最要者。其余诸方，次第用之可也。凡患人身上痒甚，盖以风邪气郁，血不荣敷而然，宜四 \n物汤加黄芩、白芷调浮萍末服，发汗而愈。 \n一、疠风灸法，先服桦皮散，自少至多，服五七日，灸承浆穴七壮。灸疮愈后，再灸之 \n。凡三灸之后，服二圣散泄热，祛血中之风邪，时更以升麻汤送下泻清丸为佳。倘年深日久 \n，即以愈风丹、换骨丹等方，详而用之。 \n一、凡大风初起，头面搔痒，更有红紫疹块起者，即可服防风通圣散加苦参、天麻、蝉 \n蜕数十帖，外用七珍汤浴洗，发汗则易愈。大忌五辛荤腥浓味半年，必不再发。 \n\n\n\n<目录>卷之三十四天集·杂证谟\\疠风\n\n<篇名>述古变证治法（共三条）\n\n属性：立斋曰∶一身起疙瘩，搔破脓水淋漓，若寒热往来者，肝经气血虚而有火也。用八珍汤 \n加丹皮、柴胡。寒热内热者，血气弱而虚热也。八珍汤倍加参、术。若恶寒形寒者，阳气虚 \n寒也。用十全大补汤。若肌肤搔如帛隔者，气血不能外荣也，人参养营汤。若面部抓之麻木 \n，气血不能上荣也。补中益气汤。若痿弱筋挛者，血气不能滋养也。补中益气汤佐以六味地 \n黄丸。 \n一、遍身疙瘩，或隐疹搔痒，此风热伤血，用羌活当归散。气虚者，佐以补中益气汤加 \n山栀、钩藤钩。血虚者，佐以加味逍遥散加钩藤钩。若手足皴裂，不问黯白，或于手足腿腕 \n搔起白皮，此风热燥涩也。用清胃散加芍药。 \n一、面赤搔痒，或眉毛脱落，此属肺经风热。用人参消风散、桦皮散。气虚用补中益气 \n汤加天麻、僵蚕。血虚用加味逍遥散加钩藤钩。若面发紫泡，或成块，或眉毛脱落，属肝经 \n风热。先用小柴胡汤加山栀、丹皮、钩藤钩，后用加味逍遥散。凡证属肝经血燥生风者，但 \n宜滋肾水生肝血，则火自息，风自定，痒自止。 \n\n\n\n<目录>卷之三十四天集·杂证谟\\疠风\n\n<篇名>兼证治法\n\n属性：一、疠疡之有兼证变证，凡如表里脏腑诸病，无不有之，其各治法亦已具悉各门。但有 \n所值，即宜随证参用之，左右逢源，无弗善也，重录资繁，兹不赘及。 \n\n\n\n<目录>卷之三十四天集·杂证谟\\疠风\n\n<篇名>解诸毒\n\n属性：一、敷砒霜，患处作痛或腐溃者，用湿泥频涂换之。若毒瓦斯入腹，胸膈苦楚，或作吐泻 \n，饮冷米醋一二杯即止，多亦不妨。生绿豆末、芝麻油俱可。敷贴雄黄药，闷乱或吐泻，用 \n防己煎汤解之。服辛热药而眉发脱落者，乃肝经血伤而火动，非风也。用四物汤、六味丸， \n以滋肝血生肾水。服川乌、草乌等药，闷乱流涎，或昏愦呕吐，或出血、吐血。用大豆、远 \n志、防风、甘草，任用一味煎汤解之。大凡服风药过多，皆宜用之，如未应，急用甘草生姜 \n汁。敷贴巴豆之药，患处作痛，肌肉溃烂，以生黄连为末，水调敷之。若毒入内，吐泻等证 \n，更以水调服一二钱，或大小豆、菖蒲汁，皆可。敷贴藜芦，毒入内，煎葱汤解之。服祛风 \n克伐之药，呕吐少食，胸膈不利，或形气倦怠等证，用六君子汤以补阳气。若烦热作渴，饮 \n食不思，或晡热内热，面赤发热。用四物汤加参、术以生阴血。余从各门治之。 \n\n\n\n<目录>卷之三十四天集·杂证谟\\疠风\n\n<篇名>禁忌\n\n属性：人之患斯疾者，多由嗜欲不谨所致。治斯疾者，速当断戒荤腥盐酱，一切浓味。只宜清 \n心寡欲，绝色忘虑，幽陷林泉，屏弃世务，早早救疗，庶几可活。稍不守禁，每见愈而复作 \n，及致危剧，莫能再救，总以其不守禁忌也。 \n\n\n\n<目录>卷之三十四天集·杂证谟\\疠风\n\n<篇名>疠风论列方\n\n属性：醉仙散（外二百七十） 再造散（外二七三） 黄连解毒汤（寒一） 换肌散（外二七二） 换 \n骨丹（和二七九） 七味白术散（小七） 七珍汤（外二八三） 八珍汤（补十九） 六味地黄丸（ \n补百二十） 四物汤（补八） 二圣散（外二六七） 十全大补汤（补二十） 愈风丹（外二六六） \n泻黄散（寒五七） 补中益气汤（补三十） 桦皮散（外二六八） 六君子汤（补五） 人参消风 \n散（散四七） 清胃散（寒五四） 小柴胡汤（散十九） 人参养营汤（补二一） 泻清丸（寒一五 \n一） 防风通圣散（攻十六） 加味逍遥散（补九四三） 《局方》犀角地黄汤（寒七九） \n\n\n\n<目录>卷之三十四天集·杂证谟\\疠风\n\n<篇名>论外备用方\n\n属性：升麻汤（外二六九） 浮萍散（外二七一） 白花蛇丸（外二七四） 皂角散（外二七八） 雷 \n丸散（外二七九） 白花蛇膏（外二七五） 行药方（外二七七） 硫黄酒（外二八二） 防风天麻 \n丸（外二七六） 苦参酒（外二八一） 乌头汤（外二八四） 洗疠方（外二八六） 敷疠方（外二 \n八五） 黑虎丹（外二百八十） \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>经义\n\n属性：《厥病篇》曰∶肠中有虫瘕及蛟 ，皆不可取以小针。心肠痛， 作痛肿聚 \n，往来上下行，痛有休止，腹热喜渴，涎出者，是蛟 也。以手按聚而坚持之，无令 \n得移，以大针刺之，久持之，虫不动，乃出针也。HT 腹 痛，形中上者。 \n《口问篇》帝曰∶人之涎下者，何气使然？岐伯曰∶饮食者，皆入于胃，胃中有热则 \n虫动，虫动则胃缓，胃缓则廉泉开，故涎下。补足少阴。 \n《五癃津液别篇》曰∶中热则胃中消谷，消谷则虫上下作，肠胃充郭，故胃缓。胃缓则 \n气逆，故唾出。 \n《上膈篇》曰∶气为上膈者，食饮入而还出。虫为下膈，下膈者，食 时乃出。（ \n详噎膈门） \n《气交变大论》曰∶岁木不及，收杀气行，寒雨害物，虫食甘黄，脾土受邪。岁土不及 \n，复则收政严峻，名木苍凋，虫食甘黄，气客于脾。 \n《论疾诊尺篇》曰∶肘后粗以下三四寸热者，肠中有虫。 \n《邪气脏腑病形篇》曰∶脾脉微滑为虫毒 蝎腹热。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>论证（共三条）\n\n属性：虫之为病，人多有之，由于化生，诚为莫测。在古方书虽曰由湿、由热、由口腹不节、 \n由食饮停积而生，是固皆有之矣。然以常见验之，则凡脏强气盛者，未闻其有虫，正以随食 \n随化，虫自难存；而虫能为患者，终是脏气之弱，行化之迟，所以停聚而渐致生虫耳。然则 \n或由湿热，或由生冷，或由肥甘，或由滞腻，皆可生虫，非独湿热已也。然以上数者之中， \n又惟生冷生虫为最。即如收藏诸物，但着生水，或近阴湿，则最易蛀腐，非其义乎？故凡欲 \n爱养小儿，即当节其水果，以防败脾，此实紧要之一端也。至若治虫之法，虽当去虫，而欲 \n治生虫之本以杜其源，犹当以温养脾肾元气为主，但使脏气阳强，非惟虫不能留，亦自不能 \n生也。余制有温脏丸方，最所宜也。 \n一、虫之为病，其类不一，或由渐而甚，或由少而多，及其久而为害，则为腹痛食减， \n渐至羸瘠而危者有之。凡虫痛证，必时作时止，来去无定，或呕吐青黄绿水，或吐出虫，或 \n痛而坐卧不安，或大痛不可忍，面色或青或黄或白，而唇则红，然痛定则能饮食者，便是虫 \n积之证，速宜逐之。 \n《本事方》云∶心虫曰蛔，脾虫曰寸白，肾虫如寸截丝缕，肝虫如烂杏，肺虫如蚕，皆 \n能杀人，惟肺虫为急。肺虫居叶之内，蚀人肺系，故成瘵疾。咯血声嘶，药所不到，治之为 \n难。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>论治（共四条）\n\n属性：治虫之剂，凡虫势骤急，上攻心腹作痛者，宜扫虫煎先治其标。若虫积坚固者，宜猎虫 \n丸、遇仙丹、木香槟榔丸、百顺丸之类主之。或稍缓而质弱者，宜芜荑散、化虫散之类主之 \n。丹溪云∶打虫方用楝树根、槟榔、鹤虱，夏取汁，冬浓煎饮之。又万应丸最妙。 \n一、治虫之法，按丹溪云∶上半月虫头向上，易治，下半月虫头向下，难治。先以肉汁 \n或糖蜜引虫头向上，然后用药。此皆法之善者，然此惟缓治之法耳。然虫证甚急，又安能必 \n待其时乎？且以望前望后辨虫头，亦若渺茫无据，惟先用香饵而虫头可引，岂非望后之治， \n亦自有法。又何虑其难治也。 \n徐东皋云∶治虫之方固多，而用之者不知其法，则亦不能下虫。如丹溪云虫头向下之时 \n，必须俟其向上，法当行于月半之前也。若虫得食，则不食药，亦不能下虫，而徒泻其虚也 \n。故虽有方，不知其法，则方亦不效。凡欲下虫，必先一日不食，而使虫饥，次早五更用油 \n煎肉，嚼之良久，腹内虫闻肉香，头皆向上而欲食，乃以鸡蛋煎饼和药，嚼而食之，须臾服 \n葱汤或白水，少少以助药力下行，不超时而虫俱下，甚至数升。然后以白粥补之，随服补剂 \n调理脾胃，而疾可悉愈。 \n一、验治法。昔一人患心腹大痛，或止或作，痛不可忍，凡用去积行气等药，百方不效 \n。但于痛极时须用拳捶之，痛得少止，而旋止旋作，久不能愈，日加困弊，莫测其故。忽一 \n胡僧见之，曰余能治也。遂令病者，先食香饵，继进一丸，打下一硬嘴异虫，遂愈。此因虫 \n啮肠脏，所以痛极，捶之，则五内震动，虫亦畏而敛伏。不捶而虫得自由，所以复作。此亦 \n验虫奇法。故凡见心腹痛证，但用揉按，重捻而痛得暂止者，多有因虫而然也。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>蛔虫（共五条）\n\n属性：凡诸虫之中，惟蛔虫最多，其逐治之法总若前条，然旋逐旋生，终非善策，欲杜其源， \n必须温养脾胃，脾胃气强，虫自不生矣。故凡逐虫之后，或于未逐之先。若欲调补脾肾，则 \n如归脾汤、温胃饮、五君子煎、理中汤，或理阴煎之属，皆所宜也。若欲兼虫而治之，则惟 \n温脏丸为最善。凡治虫之法，或攻或补，自有缓急先后之宜，所当详辨，不可任意忽略也。 \n《巢氏病源》曰∶凡腹中痛，其脉法当沉弱，今脉反洪大者，是蛔虫也。 \n《医余》曰∶蛔虫亦九虫之数，人腹中皆有之。小儿失乳而哺早，或食甜食过多，胃虚 \n而热，生虫。令人腹痛恶心，口吐清水，腹上青筋。用火煨使君子与食，以壳煎汤送下，甚 \n妙。然世人多于临卧服之，又无日分，多不验。惟月初四五里五更而服之，至日午前虫尽下 \n，可用温平和胃药调理一二日。凡虫在腹中，月上旬头向上，中旬横之，下旬头向下。故中 \n旬下旬用药则不入虫口，所以不验也。牛马之生子，上旬生者，行在母前，中旬生者，并肩 \n而行，下旬生者，后随之。猫之食鼠亦然。天地自然之理，物皆由之而莫知之。 \n伤寒门有吐蛔、蛔厥证治。呕吐门有吐蛔治法，并吐蛔治按。肿胀门有孙一奎蛔虫按， \n俱当参阅。 \n《外台》用苦楝汤治蛔虫。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>寸白虫（共三条）\n\n属性：此虫长寸许，色白，其状如蛆，母子相生，有独行者，有个个相接不断者，故能长至一 \n二丈。治寸白虫无如榧子煎，其效如神。 \n《本事方》云∶用《良方》锡灰、芜荑、槟榔者极佳，五更服则虫尽下。以此为末，用 \n石榴根煎汁送下三钱，或丸服亦可。 \n《庚志》云∶赵子山，字景高，寓居邵武军天王寺，苦寸白虫为患。医者咸云∶是疾当 \n止酒。然以素所耽嗜，欲罢不能。一夕醉于外舍，至夜半口干舌燥，仓卒无汤饮，适见廊庑 \n下有瓮水，月色下照，莹然可掬，即酌而饮之，甚甘如饴，连饮数酌，乃就寝。迨晓虫出盈 \n席，觉心腹顿宽，宿疾遂愈。一家皆惊异，验其所饮，盖寺仆日织草履浸红藤根水也。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>小儿疳虫（名曰疳）\n\n属性：小儿疳 ，亦由饮食过伤，致成疳积。身热腹大，面黄，四肢无力，昏睡，鼻烂汁 \n臭，齿龈生疮，或下痢黑血。皆腹中有虫故也。宜九味芦荟丸、追虫丸、四味肥儿丸、七味 \n肥儿丸、蟾蜍丸之类主之。虫去之后，仍当调补气血。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>应声虫（共二条）\n\n属性：《泊宅编》云∶水州通判听军员毛景得奇疾，每语喉中必有物作声相应。有道人教令诵 \n本草药名，至蓝而默然。遂取蓝捣汁饮之，少顷吐出肉块长一寸余，人形悉具，自后无声。 \n陈正敏《遁斋闲览》载杨 中年得异病，每发言应答，腹中有小声效之，数年间 \n其声渐大。有道人见而惊曰∶此应声虫也，久不治，延及妻子，宜读本草，遇虫不应者，当 \n取服之。 如言，读至雷丸，虫无声，乃顿服之，遂愈。后正敏至长沙，遇一丐者亦 \n有是疾，环而观之者甚众。因教服雷丸，丐者亦愈。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>九虫\n\n属性：《千金要方》云∶人腹中生虫，大率有九，皆能食人脏腑。一曰伏虫，长四分，群虫之 \n主也。二曰蛔虫，长一尺，生发多则贯心而杀人。三曰白虫，长一寸，子孙相生，其母转大 \n，长至四五丈，亦能杀人。四曰内虫，状如烂杏，令人烦满。五曰肺虫，状如蚕，令人咳嗽 \n。六曰胃虫，状如虾蟆，令人呕吐胃逆喜哕。七曰弱虫，又名膈虫，状如瓜瓣，令人多唾。 \n八曰赤虫，状如生肉，令人肠鸣。九曰蛲虫，致细微，形如菜虫，居广肠之间，多则为痔， \n剧则为癞。因人疮痍，即生诸痈疽、癣 、 疥、龋虫，无所不为，其害匪细。凡此 \n诸虫，大则根据附脏腑之间，小则侵蚀肌肤之内。若元气尚实，未为大害，稍有虚损，遂肆其 \n毒，甚至如劳瘵杀人，及传尸疰怪，或应声溪鼠之类。而非理之可测者多矣。业医者，不可 \n不究其所致之本，及治之之法也。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>狐惑（共二条）\n\n属性：仲景曰∶狐惑之为病，状如伤寒，默默欲眠，目不得闭，起卧不安，蚀于喉为惑，蚀于 \n阴为狐，不欲饮食，恶闻食臭，其面目乍赤、乍白、乍黑。蚀于上部则声哑，甘草泻心汤 \n主之。蚀于下部则咽干，苦参汤洗之。蚀于肛者，雄黄熏之。愚按∶此仲景云狐惑之为病， \n状如伤寒，则可见本非伤寒也。而后世即以狐惑为伤寒者，岂非误乎！ \n《千金要方》曰∶凡得伤寒及天行热病，腹中有热。又食少，肠胃空虚，三虫行作求食 \n，蚀人五脏及下部。若齿龈无色，舌上尽白，甚者唇里有疮，四肢沉重，忽忽喜眠，当数看 \n其上唇内有疮唾血，唇内如粟疮者，心内懊 痛闷，此虫在上蚀其五脏；下唇内生疮者 \n，其人喜眠，此虫在下，蚀其下部。人不能知，可服此蚀虫药，不尔， 虫杀人。又曰 \n∶凡患湿 者，多是热病后，或久泻不止，或有客热结在腹中，或易水土，温凉气着， \n多生此病。亦有干 ，不甚泻痢，而下部疮痒。不问干湿，久则杀人。凡湿得冷则苦痢 \n，单煮黄连及艾叶、苦参之属，皆可用之。若病患齿龈无色，舌上白者，或喜眠烦愦，不知 \n痛痒处，或下痢，急治下部。不晓此者，但攻其上，不以下部为意，下部生虫，虫蚀其肛， \n肛烂见五脏便死，烧艾于竹筒熏之。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>诸虫方\n\n属性：一、传尸劳瘵未甚者，宜早用神授散。（因二五五） \n一、 虫内蚀，下部生疮，宜雄黄兑散主之。（因二五七） \n一、大孔虫痒方。（因二五八） \n一、银朱烟，用治肤腠诸虫，无不神妙。（新因五三） \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>诸虫论列方\n\n属性：扫虫煎（新和十四） 猎虫丸（新攻五） 芜荑散（和三一九） 追虫丸（攻九七） 化虫散（ \n攻九八） 五君子煎（新热六） 百顺丸（新攻六） 苦楝汤（攻四七） 榧子煎（和三二一） 甘 \n草泻心汤（寒二八） 温脏丸（新热二四） 蟾蜍丸（小一二三） 四味肥儿丸（小百十一） 理中 \n汤（热一） 理阴煎（新热三） 七味肥儿丸（小百十三） 温胃饮（新热五） 归脾汤（补三二） \n九味芦荟丸（小百十五） 万应丸（攻九九） 遇仙丹（攻五一） 木香槟榔丸（攻四九） \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸虫\n\n<篇名>论外备用方\n\n属性：圣效方（和三二二 寸白虫） 妙应丸（攻百 杀虫） 《直指》芜荑散（和三百二十 取 \n虫） 仲景乌梅丸（和三二二 胃寒吐蛔） \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>论饮食诸毒\n\n属性：《风俗通》曰∶禽兽自死者，俱有毒，不可食。鱼无腮者，有毒，腮大者亦有毒。鳖肚 \n下有红藻纹者，有毒。蟹腹下有毛者，有毒。煮酒初出火者，有毒。江南谓之火头酒，饮之 \n则生痔、溢血。夏月饮食但过宿者，即有毒。夏月酒在铜锡器中过夜，即有毒。铜器盖热食 \n，气上蒸成汗，滴下食中，即有毒。炊汤过宿，饮之有毒，盥洗则生疥。桃、杏仁，双仁者 \n毒，能杀人。果未成核者，俱有毒，令人发疮疖。夏秋果熟落地，虫缘者，有毒，人食 \n之作漏。屋漏水有毒，人食之有胀而死者。用之沐手，则生浸淫之疥，屡验。泽中死水有毒 \n，饮之令人生瘕。汤池中温泉水不可饮，令人胀闷，惟澡浴可以疏风愈疥癣。盖其泉自硫黄 \n中出，故温也。患疥者，宜饱食入浴之，连日数次，汗透而愈；体虚者，不可轻浴。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>解一切饮食诸毒\n\n属性：芝麻油总能解一切饮食诸毒，不可不知。凡造肴馔，必先用真麻油于净锅熬熟，却下肉 \n炒过，然后入清水煮之，则并不犯毒。今徽州、池州地方食牛肉，不论春夏，无日不食，惟 \n制之有方，所以鲜有中毒。但犯一切饮食毒者，即用麻油一二杯饮之，得吐即毒释而无不愈 \n者。 \n一、解饮食中毒共有十五方，俱载古方因阵中，自二百七起至二二一止。 \n一、善解毒者无如火，盖火能革物之性。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>解一切药毒\n\n属性：凡解诸药毒者，宜以荠 汁，白扁豆汁、绿豆汁、甘草汁、饧糖汁、米糖汁、蚕 \n蜕纸烧灰，随便用之，俱可解。 \n凡解毒药汤剂，不可热服，宜凉饮之。盖毒得热而势愈盛也。虽然，此特以热毒为言耳 \n。若解木鳖、菌蕈、黄连、石膏之类以中阴毒者，岂仍避热而犹堪以寒饮乎？此有医按在呕 \n吐门，当兼察之。 \n一、解毒药共十四方，俱载古方因阵中，自二二二起至二三五止。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>解诸毒通用简易方\n\n属性：一方 雄黄、青黛等分为末，新汲水调服。 \n一方 拣净土地掘窟，用井水倾入，搅，澄清，多饮则愈。 \n一方 晋矾、建茶等分为末，新汲水调服三钱，吐即效，不吐再服。 \n一方 黄连、甘草节二味水煎，凉服，不拘多少。 \n一方 荠 、黑豆、甘草 咀，每用一两，水二盏，煎一盏，温服，未效再 \n服。 \n一方 白扁豆生为末，水调服二三钱。 \n一方 伏龙肝为细末，凉水调三四钱，搅动服之，吐者，再一服。（即灶心土） \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>解一切虫兽毒\n\n属性：凡虎伤、犬伤、蛇蝎蜈蚣、水蛭之类皆是也，共二十三方，俱载古方因阵中，自二三六 \n起至二五八止。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>蛊毒（共三条）\n\n属性：蛊之为毒，中土少见之，世传广奥深山之人，于端午日以毒蛇、蜈蚣、虾蟆三物同器盛 \n之，任其互相吞食，俟一物独存者，则以为蛊，又谓之挑生。凡欲害人，密置其蛊于饮食中 \n，人中其毒，必心腹 痛如有虫啮，吐下皆如烂絮。若不即治，食人五脏而死，亦有 \n十余日而死者。更有缓者，待以数月，气血羸惫，食尽五脏而后死。 \n一说两广山谷间有草曰胡蔓草，又名断肠草。若人以急水吞之则急死，以缓水吞之则缓 \n死。今见荆楚之地，有曰鼠莽草者，人食之则毒死，意即胡蔓草也。 \n一说岭南人取毒蛇杀之，以草覆之，以水洒之，数日菌生，取菌为末，酒调以毒人。始 \n亦无患，再后饮酒则毒作而死。其俗淫妇多自合北人，日久情好，又不肯逐人归，乃阴以毒 \n投饮食中，北人归则戒之曰∶子去几时还。若从其言，则复以药解之。若过期不往则死矣， \n名曰定年蛊。北人至彼，宜预防之，须备解毒丹之类，随身勿忘。凡稍觉饮食之后，四大不 \n调，宜即服解药。若不预识其机，备有药饵，恐一时仓卒不救，所谓有备无患，重生者，不 \n可忽也。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>验蛊毒法\n\n属性：《遁斋闲览》云∶海南鱼有石首，盖鱼枕也。取其石为器，可盛饮食，如遇蛊毒，器必 \n爆裂，其效甚着。闽人制作最精，人但玩其色而鲜有识其用者。 \n一、验蛊之法，唾津在净水中，沉则是，浮则非。 \n又法∶口含大豆，中蛊者，豆即胀而皮脱。无蛊者，豆不胀脱。 \n又法∶煮鸡蛋一枚，去壳，以银簪一双插入其中，并含入口内，一饮之顷，取视簪卵俱 \n黑，即为中蛊。 \n孙真人曰∶凡中蛊者，嚼生黑豆不腥，噙白矾而味反甘者，皆中蛊也。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>蛊证\n\n属性：《直指》云∶中蛊之候，面目青黄，力乏身痛，唇口焦干，眉须脱落，烦躁闷瞀，胸腹 \n痞满，肚胀皮坚，腹中切痛如虫啮，又如虫行，唾吐鲜血，小便淋沥，大便脓血，病患所食 \n之物，皆变而为虫，侵蚀脏腑，伤甚则死。死则毒瓦斯流注，复染他人，所谓蛊疰。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>蛊脉\n\n属性：脉紧数如钗股，弦直而吐甚者，此中蛊毒也。急治之。中蛊脉洪大者，生。微细者，死 \n。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>防蛊\n\n属性：凡入有蛊之乡，所用饮食，但以犀角搅试。有毒则白沫竦起，无沫即无毒也。若自幼时 \n食猫肉者，则毒不能为害。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>知禁忌\n\n属性：凡中蛊者，但能记何物之中中毒，须终身再不食此物，犯之则毒作。若用药而愈，自后 \n饮食永不可吃冷，吃冷则蛊毒复生，竟不能救。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>反蛊及主法\n\n属性：《卫生》云∶凡入蛊乡，见人家门限屋梁绝无灰尘，洁净者，其家必蓄蛊，当用心防之 \n。如不得已吃其饮食，即潜于初下箸时，收藏一片在手，尽吃不妨。少顷，却将手藏之物潜 \n埋于人行十字路下，则蛊神反于本家作闹，蛊主必反来恳求。或食时让主人先动箸，或明问 \n主人云∶莫有蛊么？以箸筑桌而后食，如是则蛊皆不能为害。此皆验于蛊乡云。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>治蛊大法有二\n\n属性：胸膈痛胀，则毒在上焦，宜吐之。法以热水半盏，投入胆矾末五分，通口服，少顷，以 \n鹅翎探吐，毒物出尽自愈。或服升麻汤探而吐之，亦妙。 \n腹痛胀，为毒在下焦，宜泻之。法以郁金末二钱，米汤调下，空腹取泻，恶毒尽为妙。 \n泻后，以四君子汤，服二三剂调理，慎忌口。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>咒语破蛊法\n\n属性：《大藏经》云∶治蛊毒、挑生毒有咒法。凡人在外饮食，先默诵咒七遍，其毒自不为害 \n。咒曰∶姑苏琢，磨耶琢，吾知蛊毒生四角，父是穹窿穹，母是舍耶女，眷属百千万，吾今 \n悉知汝，摩诃萨，摩诃萨。凡见饮食上有蛛丝便莫吃。又法，每遇所到处，念药王万福七遍 \n，亦可避。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>灸蛊毒法\n\n属性：凡灸一切蛊毒，于两足小指尽处，各灸三壮，即有物出。酒中者，随酒出，饮食中者， \n随饮食出，屡验。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>解一切中恶邪鬼崇毒\n\n属性：凡卒时中恶垂死者，宜朱砂丸急服之。方在攻阵百三。 \n凡遭一切鬼崇、鬼疰等毒者，急与八毒赤丸攻之。方在攻阵百四。 \n凡中恶心腹胀痛，大便不通，及飞尸鬼击等急证，惟《外台》走马汤最捷最妙。方在攻 \n阵百十三。 \n\n\n\n<目录>卷之三十五天集·杂证谟\\诸毒（附虫毒）\n\n<篇名>治蛊毒方\n\n属性：丹砂丸（因二百六十） 雄麝散（因二五九） 万病解毒丹（因二百二） 七宝丸（因二六一） \n蜜髓煎（因二六二） 挑生蛊毒简易方（因二六五） 解毒散（因二四四） 归魂散（因二六三） \n三因解毒丸（因二百三） 麦面散（因二六四） \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《本神篇》曰∶天之在我者德也，地之在我者气也，德流气薄而生者也。（详二十九卷，遗精门） \n《天元纪大论》曰∶在天为气，在地成形，形气相感而化生万物矣。 \n《生气通天论》帝曰∶夫自古通天者生之本，本于阴阳。天地之间，六合之内，其气 \n九州九窍、五脏、十二节，皆通于天气。其生五，其气三，数犯此者，则邪气伤人，此寿命 \n之本也。苍天之气，清净则志意治，顺之则阳气固，虽有贼邪，勿能害也，此因时之序。故 \n圣人传精神，服天气，而通神明。失之则内闭九窍，外壅肌肉，卫气解散，此谓自伤，气之削也。 \n《阴阳应象大论》曰∶清阳为天，浊阴为地；地气上为云，天气下为雨；雨出地气，云 \n出天气。故清阳出上窍，浊阴出下窍；清阳发腠理，浊阴走五脏；清阳实四肢，浊阴归六腑 \n。惟贤人上配天以养头，下象地以养足，中傍人事以养五脏。天气通于肺，地气通于嗌，风 \n气通于肝，雷气通于心，谷气通于脾，雨气通于肾。六经为川，肠胃为海，九窍为水注之气 \n。以天地为之阴阳，阳之汗，以天地之雨名之；阳之气，以天地之疾风名之。暴气象雷，逆 \n气象阳，故治不法天之纪，不用地之理，则灾害至矣。 \n《四气调神论》曰∶天气，清净光明者也，藏德不止，故不下也。天明则日月不明，邪 \n害空窍，阳气者闭塞，地气者冒明，云雾不精，则上应白露不下。交通不表，万物命故不施 \n，不施则名木多死。恶气不发，风雨不节，白露不下，则菀槁不荣。贼风数至，豪雨数起， \n天地四时不相保，与道相失，则未央绝灭。惟圣人从之，故身无奇病，万物不失，生气不竭。 \n《六元正纪大论》帝曰∶天地之气，盈虚如何？岐伯曰∶天气不足，地气随之。地气不 \n足，天气从之。运居其中而常先也。故上胜则天气降而下，下胜则地气迁而上，多少而差其 \n分。微者，小差；甚者，大差。甚则位易气交易，则大变生而病作矣。 \n《五常政大论》帝曰∶天不足西北，左寒而右凉，地不满东南，右热而左温。故其何也 \n？岐伯曰∶阴阳之气，高下之理，大小之异也。东南方，阳也。阳者，其精降于下，故右热 \n而左温。西北方，阴也。阴者，其精奉于上，故左寒而右凉。是以地有高下，气有温凉，高 \n者气寒，下者气热。故适寒凉者，胀。之温热者，疮。下之则胀已，汗之则疮已，此腠理开 \n闭之常，大小之异耳。 \n《五营运大论》帝曰∶地之为下否乎？岐伯曰∶地为人之下，太虚之中者也。帝曰∶凭 \n乎？曰∶大气举之也。燥以干之，暑以蒸之，风以动之，湿以润之，寒以坚之，火以温之。 \n故风寒在下，燥热在上，湿气在中，火游行其间，寒暑六入，故令虚而化生也。 \n《方盛衰论》曰∶至阴虚，天气绝；至阳盛，地气不足。阴阳并交，至人之所行。阴阳 \n并交者，阳气先至，阴气后至，是以圣人持诊之道，先后阴阳而持之。 \n《太阴阳明论》曰∶喉主天气，咽主地气。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《至真要大论》帝曰∶愿闻阴阳之三也，何谓？岐伯曰∶气有多少，异用也。帝曰∶阳 \n明，何谓也？曰∶两阳合明也。帝曰∶厥阴何也？曰∶两阴交尽也，气之相守司也，如权衡之 \n不得相失也。夫阴阳之气，清静则生化治，动则苛疾起，此之谓也。 \n《生气通天论》曰∶阳气者，若天与日，失其所则折寿而不彰。故天运当以日光明。是 \n故阳因而上，卫外者也。阳气者，烦劳则张，精绝，辟积于夏，使人煎厥，目盲不可以视， \n耳闭不可以听，溃溃乎若坏都， 乎不可止。阳气者，大怒则形气绝而血菀于上，使人薄 \n厥。阳气者，精则养神，柔则养筋。开阖不得，寒气从之，乃生大偻。阴者，藏精而起亟也 \n；阳者，卫外而为固也。阴不胜其阳，则脉流薄疾，并乃狂。阳不胜其阴，则五脏气争，九 \n窍不通。是以圣人陈阴阳、筋脉和同，骨髓坚固，气血皆从。如是则内外调和，邪不能害， \n耳目聪明，气立如故。故阳强不能密，阴气乃绝。阴平阳秘，精神乃治。阴阳离决，精气乃绝。 \n《阴阳应象大论》曰∶阳化气，阴成形。寒极生热，热极生寒。寒气生浊，热气生清。 \n清气在下，则生飧泄；浊气在上，则生 胀。壮火之气衰，少火之气壮。壮火食气，气 \n食少火。壮火散气，少火生气。阴胜则阳病，阳胜则阴病。阳胜则热，阴胜则寒。重寒则热 \n。重热则寒。寒伤形，热伤气。气伤痛，形伤肿。故先痛而后肿者，气伤形也；先肿而后痛 \n者，形伤气也。年四十，而阴气自半也，起居衰矣。年五十，体重，耳目不聪明矣。年六十 \n，阴痿，气大衰，九窍不利，下虚上实，涕泣俱出矣。故曰∶知之则强，不知则老。 \n《太阴阳明论》曰∶阳者，天气也，主外；阴者，地气也，主内。故阳道实，阴道虚。 \n阴气从足上行至头，而下行循臂至指端；阳气从手上行至头，而下行至足。故曰∶阳病者上 \n行极而下。阴病者，下行极而上。（详脾胃门） \n《终始篇》曰∶阴者，主脏，阳者，主腑。阳受气于四末，阴受气于五脏。 \n《痹论》岐伯曰∶阴气者，静则神藏，躁则消亡，饮食自倍，肠胃乃伤。 \n《阴阳别论》曰∶刚与刚，阳气破散，阴气乃消亡。淖则刚柔不和，经气乃绝。 \n《寒热病篇》曰∶足太阳入脑乃别。阴跷、阳跷，阴阳相交。阳入阴，阴出阳，交于目 \n，锐 。阳气盛则 目，阴气盛则瞑目。 \n《口问篇》曰∶阳气尽，阴气盛，则目瞑；阴气尽而阳气盛，则寤矣。 \n《大惑论》曰∶夫卫气者，昼日行于阳，夜行于阴。故阳气尽则卧，阴气尽则寤。 \n《方盛衰论》曰∶雷公请问，气之多少，何者为逆？何者为从？帝曰∶阳从左，阴从右， \n老从上，少从下。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《六元正纪大论》帝曰∶四时之气，至有早晏高下左右，其候何如？岐伯曰∶行有逆顺 \n，至有迟速。故太过者，化先天；不及者，化后天。帝曰∶愿闻其行何谓也？曰∶春气西行 \n，夏气北行，秋气东行，冬气南行。故春气始于下，秋气始于上，夏气始于中，冬气始于标 \n。春气始于左，秋气始于右，冬气始于后，夏气始于前。此四时正化之常。故至高之地，冬 \n气常在，至下之地，春气常在，必谨察之。帝曰∶愿闻同化何如？岐伯曰∶风温春化同，热 \n曛昏火夏化同，胜与复同，燥清烟露秋化同，云雨昏暝埃长夏化同，寒气霜雪冰冬化 \n同。此天地五运六气之化，更用之盛衰也。 \n《四气调神论》曰∶春三月，此谓发陈，天地俱生，万物以荣，此春气之应，养生之道 \n也。逆之则伤肝，夏为寒变，奉长者少。夏三月，此谓蕃莠，天地气交，万物华实，此夏气 \n之应，养长之道也。逆之则伤心，秋为 疟，奉收者少。秋三月，此谓容平，天气以急，地 \n气以明。此秋气之应，养收之道也。逆之则伤肺，冬为飧泄，奉藏者少。冬三月，此谓闭藏 \n，水冰地坼，无扰乎阳。此冬气之应，养藏之道也。逆之则伤肾，春为痿厥，奉生者少。逆 \n春气，则少阳不生，肝气内变；逆夏气，则太阳不长，心气内洞；逆秋气，则太阴不收，肺 \n气焦满；逆冬气，则少阴不藏，肾气独沉。夫四时阴阳者，万物之根本也。所以圣人春夏养 \n阳，秋冬养阴，以从其根。故与万物浮沉于生长之门。逆其根，则伐其本，坏其真矣。 \n《生气通天论》曰∶阳气者，一日而主外，平旦人气生，日中而阳气隆，日西而阳气已 \n虚，气门乃闭。是故暮而收拒，无扰筋骨，无见雾露，反此三时，形乃困薄。 \n《至真要大论》帝曰∶分至何如？岐伯曰∶气至谓之至，气分谓之分，至则气同，分则 \n气异。所谓天地之正纪也。 \n《脉要精微论》曰∶冬至四十五日，阳气微上，阴气微下；夏至四十五日，阴气微上， \n阳气微下。阴阳有时，与脉为期，期而相失，如脉所分，分之有期，故知死时。 \n《顺气一日分为四时篇》帝曰∶夫百病者，多以旦慧昼安，夕加夜甚者，何也？岐伯曰 \n∶四时之气使然。春生夏长，秋收冬藏，人亦应之。以一日分为四时，朝则为春，日中为夏 \n，日入为秋，夜半为冬。朝则人气始生，病气始衰，故旦慧；日中人气长，长则胜邪，故安 \n；夕则人气始衰，邪气始生，故加；夜半人气入脏，邪气独居于身，故甚也。帝曰∶其时有 \n反者何也？曰∶是不应四时之气，脏独主其病者，是必以脏气之所不胜时者甚，以其所胜时 \n者起也。 \n《四时刺逆从论》曰∶春气在经脉，夏气在孙络，长夏气在肌肉，秋气在皮肤，冬气在 \n骨髓中。帝曰∶敢问其故。岐伯曰∶春者，天气始开，地气始泄，冻解冰释，水行经通。故 \n人气在脉。夏者，经满气溢，入孙络受血，皮肤充实。长夏者，经络皆盛，内溢肌中。秋者 \n，天气始收，腠理闭塞，皮肤引急。冬者盖藏，血气在中，内着骨髓，通于五脏。是故邪气 \n者，常随四时之气血而入客也。至其变化，不可为度，然必从其经气，辟除其邪，除其邪则 \n乱气不生。 \n《金匮真言论》曰∶春气者，病在头。夏气者，病在脏。秋气者，病在肩背。冬气者， \n病在四肢。故春，善病鼽衄。仲夏，善病胸胁。长夏，善病洞泄寒中。秋，善病风疟。冬， \n善病痹厥。 \n《营卫生会篇》曰∶卫气行于阴二十五度，行于阳二十五度，分为昼夜。故气至阳而起 \n，至阴而止。夜半为阴陇，夜半后而为阴衰，平旦阴尽而阳受气矣。日中为阳陇，日西而阳 \n衰，日入阳尽而阴受气矣。夜半而大会，万民皆卧，命曰合阴。平旦阴尽而阳受气，如是无 \n已，与天地同纪。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《天元纪大论》曰∶所以欲知天地之阴阳者，应天之气，动而不息。故五岁而右迁；应 \n地之气，静而守位。故六期而环会。动静相召，上下相临，阴阳相错，而变由生也。天以六 \n为节，地以五为制，五六相合而七百二十气为一纪。凡三十岁；千四百四十气。凡六十岁为 \n一周，不及太过，斯皆见矣。 \n《六节藏象论》曰∶天度者，所以制日月之行也。气数者，所以纪化生之用也。五日谓 \n之候，三候谓之气，六气谓之时，四时谓之岁。五气更立，各有所胜，盛虚之变，此其常也 \n。故春胜长夏，长夏胜冬，冬胜夏，夏胜秋，秋胜春。所谓得五行时之胜，各以气命其脏。 \n帝曰∶何以知其胜？岐伯曰∶求其至也。皆归始春，未至而至，此谓太过。则薄所不胜而乘 \n所胜也，命曰气淫。至而不至，此谓不及。则所胜妄行而所生受病，所不胜薄之也，命曰气 \n迫。所谓求其至者，气至之时也。谨候其时，气可与期，失时反候，五治不分，邪僻内生， \n工不能禁也。 \n《五营运大论》曰∶丹天之气经于牛女戊分， 天之气经于心尾己分，苍天之气 \n经于危室柳鬼，素天之气经于亢氏昴毕，玄天之气经于张异娄胃。所谓戊己分者，奎壁角轸 \n，则天地之门户也。上下相遘，寒暑相临，气相得则和，不相得则病。东方生风，在气为柔 \n。南方生火，在气为息。中央生湿，在气为充。西方生燥，在气为成。北方生寒，在气为坚 \n。气有余，则制己所胜而侮所不胜；其不及，则己所不胜侮而乘之。己所胜轻而侮之。侮反 \n受邪，侮而受邪，寡于畏也。 \n《五常政大论》帝曰∶太虚廖廓，五运回薄，衰盛不同，损益相从。愿闻平气何如而名 \n？何如而纪也？岐伯曰∶木曰敷和，火曰升明，土曰备化，金曰审平，水曰静顺。帝曰∶其不 \n及奈何？曰∶木曰委和，火曰伏明，土曰卑监，金曰从革，水曰涸流。帝曰∶太过何谓？曰∶ \n木曰发生，火曰赫曦，土曰敦阜，金曰坚成，水曰流衍。帝曰∶其岁有不病，而脏气不应不 \n用者，何也？岐伯曰∶天气制之，气有所从也。少阳司天，火气下临，肺气上从，白起金用 \n，草木HT 。阳明司天，燥气下临，肝气上从，苍起木用而立，土乃HT 。太阳司天 \n，寒气下临，心气上从，而火且明，丹起金乃HT 。厥阴司天，风气下临，脾气上从， \n而土且隆，黄起水乃HT 。少阴司天，热气下临，肺气上从，白起金用，草木HT 。 \n太阴司天，湿气下临，肾气上从，黑起水变。 \n《至真要大论》帝曰∶五气交合，盈虚更作，余知之矣。六气分治，司天地者，其至何 \n如？岐伯曰∶天地之大纪，人神之通应也。厥阴司天，其化以风；少阴司天，其化以热；太 \n阴司天，其化以湿；少阳司天，其化以火；阳明司天，其化以燥；太阳司天，其化以寒。 \n帝曰∶地化奈何？曰∶司天同候，间气皆然。帝曰∶间气何谓？曰∶司左右者，是谓间气 \n也。主岁者，纪岁。间气者，纪步也。帝曰∶岁主奈何？曰∶厥阴司天为风化，在泉为酸化 \n，司气为苍化，间气为动化。少阴司天为热化，在泉为苦化。不司气化，居气为灼化。太阴 \n司天为湿化，在泉为甘化，司气为HT 化，间气为柔化。少阳司天为火化，在泉为苦化 \n，司气为丹化，间气为明化。阳明司天为燥化，在泉为辛化，司气为素化，间气为清化。太 \n阳司天为寒化，在泉为咸化，司气为玄化，间气为藏化。故治病者，必明六化分治，五味五 \n色所生，五脏所宜。乃可以言盈虚病生之绪也。本乎天者，天之气也。本乎地者，地之气也 \n。天地合气，六节分而万物化生矣。故曰∶谨候气宜，无失病机，此之谓也。帝曰∶气之上 \n下何谓也？岐伯曰∶身半以上，其气三矣，天之分也，天气主之。身半以下，其气三矣，地 \n之分也，地气主之。以名命气，以气命处，而言其病。半，所谓天枢也。帝曰∶胜复之动， \n时有常乎？气有必乎？岐伯曰∶时有常位，而气无必也。初气终三气，天气主之，胜之常也。 \n四气尽终气，地气主之，复之常也。有胜则复，无胜则否。帝曰∶六气之胜，何以候之？岐 \n伯曰∶清气大来，燥之胜也。风木受邪，肝病生焉。热气大来，火之胜也。金燥受邪，肺病 \n生焉。寒气大来，水之胜也。火热受邪，心病生焉。湿气大来，土之胜也。寒水受邪，肾病 \n生焉。风气大来，木之胜也。土湿受邪，脾病生焉。所谓感邪而生病也。乘年之虚，则邪甚 \n也。失时之和，亦邪甚也。遇月之空，亦邪甚也。重感于邪，则病危矣。 \n《六微旨大论》曰∶至而至者和。至而不至，来气不及也。未至而至，来气有余也。应 \n则顺，否则逆，逆则变生，变生则病。帝曰∶请言其应。岐伯曰∶物生其应也。气脉其应也 \n。相火之下，水气承之；水位之下，土气承之；土位之下，风气承之；风位之下，金气承之 \n；金位之下，火气承之；君火之下，阴精承之。帝曰∶何也？岐伯曰∶亢则害，承乃制，制 \n则生化，外列盛衰，害则败乱，生化大病。帝曰∶六气应五行之变何如？岐伯曰∶位有始终 \n，气有国中，上下不同，求之亦异也。天气始于甲，地气始于子，子甲相合，命曰岁立。谨 \n候其时，气可与期。岐伯曰∶言天者，求之本。言地者，求之位。言人者，求之气交。帝曰 \n∶何谓气交？曰∶上下之位，气交之中，人之居也。故曰∶天枢之上，天气主之；天枢之下 \n，地气主之；气交之分，人气从之，万物由之。帝曰∶何谓国中？岐伯曰∶初凡三十度而有 \n奇，中气同法。帝曰∶国中何也？曰∶所以分天地也。初者，地气也。中者，天气也。帝曰 \n∶其升降何如？岐伯曰∶气之升降，天地之更用也。帝曰∶其用何如？曰∶升已而降，降者谓 \n天；降已而升，升者谓地。天气下降，气流于地；地气上升，气腾于天。故高下相召，升降 \n相因，而变作矣。岐伯曰∶出入废则神机化灭，升降息则气立孤危。故非出入，则无以生长 \n壮老已；非升降，则无以生长化收藏。是以升降出入，无器不有。 \n《六元正纪大论》帝曰∶气至而先后者，何？岐伯曰∶运太过，则其至先；运不及，则 \n气至后；非太过非不及，则至当时，非是者HT 也。岐伯曰∶数之始，起于上而终于下 \n，岁半之前，天气主之，岁半之后，地气主之，上下交互，气交主之，岁纪毕矣。故曰∶位 \n明气月可知乎。所谓气也，风胜则动，热胜则肿，燥胜则干，寒胜则浮，湿胜则濡泄，甚则 \n水闭 肿，随气所在，以言其变耳。帝曰∶水发而雹雪，土发而飘骤，木发而毁折，金 \n发而清明，火发而曛昧。何气使然？岐伯曰∶气有多少，发有微甚。微者当其气，甚者 \n兼其下，征其下气而见可知也。帝曰∶五气之发，不当位者，何也？曰∶命其差。帝曰∶差 \n有数乎？曰∶后皆三十度而有奇也。 \n《气交变大论》岐伯曰∶德化者，气之祥。政令者，气之章。变易者，复之纪。灾HT \n者，伤之始。气相胜者，和。不相胜者，病。重感于邪则甚也。帝曰∶善言天者，必应 \n于人。善言古者，必验于今。善言气者，必彰于物。善言应者，同天地之化。善言化言变者 \n，通神明之理。非夫子孰能言至道欤！ \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《天元纪大论》曰∶天有五行御五位，以生寒暑燥湿风。人有五脏化五气，以生喜怒思 \n忧恐。 \n《阴阳应象大论》曰∶人有五脏化五气，以生喜怒悲忧恐。故喜怒伤气，寒暑伤形，暴 \n怒伤阴，暴喜伤阳。厥气上行，满脉去形。喜怒不节，寒暑过度，生乃不固。 \n《本藏篇》曰∶五脏者，所以藏精神血气魂魄者也；六腑者，所以化水谷而行津液者也 \n。此人之所以具受于天者也。 \n《六节藏象论》曰∶心者，生之本，神之变也，为阳中之太阳，通于夏气。肺者，气之 \n本，魄之处也，为阳中之太阴，通于秋气。肾者主蛰，封藏之本，精之处也。为阴中之少阴 \n，通于冬气。肝者，罢极之本，魂之居也。为阳中之少阳，通于春气。脾、胃、大肠、小肠 \n、三焦、膀胱者，仓廪之本，营之居也。此至阴之类，通于土气。凡十一脏，皆取决于胆也。 \n《金匮真言论》曰∶东方青色，入通于肝。其味酸，其臭臊。南方赤色，入通于心。其 \n味苦，其臭焦。中央黄色，入通于脾。其味甘，其臭香。西方白色，入通于肺。其味辛，其 \n臭腥。北方黑色，入通于肾。其味咸，其臭腐。 \n《天年篇》曰∶人生十岁，五脏始定，血气已通，其气在下，故好走。二十岁，血气始 \n盛，肌肉方长，故好趋。三十岁，五脏大定，肌肉坚固，血脉盛满，故好步。四十岁，五脏 \n六腑十二经脉皆大盛以平定，腠理始疏，荣华颓落，发颇班白，平盛不摇，故好坐。五十岁 \n，肝气始衰，肝叶始薄，胆汁始减，目始不明。六十岁，心气始衰，苦忧悲，血气懈惰，故 \n好卧。七十岁，脾气虚，皮肤枯。八十岁，肺气衰，魄离，故言善误。九十岁，肾气焦，四 \n脏经脉虚空。百岁，五脏皆虚，神气皆去，形骸独居而终矣。 \n《上古天真论》曰∶女子七岁，肾气盛，齿更发长。二七而天癸至，任脉通，太冲脉盛 \n，月事以时下，故有子。丈夫八岁，肾气实，发长齿更。二八，肾气盛，天癸至，精气溢泻 \n，阴阳和，故能有子。 \n《脉度篇》曰∶肺气通于鼻，肺和则鼻能知香臭矣。心气通于舌，心和则舌能知五味矣 \n。肝气通于目，肝和则目能辨五色矣。脾气通于口，脾和则口能知五谷矣。肾气通于耳，肾 \n和则耳能闻五音矣。 \n《五藏生成篇》曰∶诸脉者，皆属于目。诸髓者，皆属于脑。诸筋者，皆属于节。诸血 \n者，皆属于心。诸气者，皆属于肺。此四肢八溪之朝夕也。 \n《海论》曰∶人有髓海，有血海，有气海，有水谷之海。胃为水谷之海，冲脉为十二经 \n之海，膻中为气之海，脑为髓之海。得顺者生，得逆者败；知调者和，不知调者害。 \n《五味篇》曰∶胃者，五脏六腑之海也，水谷皆入于胃，五脏六腑皆禀气于胃。其大气 \n之搏而不行者，积于胸中，命曰气海。出于肺，循喉咽，故呼则出，吸则入。 \n《大惑论》曰∶五脏六腑之精气，皆上注于目而为之精。目者，五脏六腑之精也，营卫 \n魂魄之所常营也，神气之所生也。（详眼目门） \n《卫气篇》曰∶请言气街∶胸气有街，腹气有街，头气有街。故气在头者，止之于脑。 \n气在胸者，止之膺与背 。气在腹者，止之背 ，与冲脉于脐左右之动脉者。气在胫者，止 \n之于气街，与承山踝上以下。 \n《动输篇》曰∶夫四末阴阳之会者，此气之大络也。四街者，气之径路也。故络绝则径 \n通，四末解则气从合，相输如环，莫知其纪，终而复始。 \n《平人气象论》曰∶胃之大络，名曰虚里，脉宗气也。（详脾胃门） \n《邪客篇》帝曰∶人有八虚，各何以候？岐伯曰∶以候五脏。心肺有邪，其气留于两肘 \n；肝有邪，其气留于两腋；脾有邪，其气流于两髀；肾有邪，其气流于两 。凡此八虚者， \n皆机关之室，真气之所过，血络之所游，邪气恶血，固不得住留，住留则伤经络骨节机关， \n不得屈伸。故病挛也。 \n《太阴阳明论》曰∶四肢皆禀于胃，而不得至经，必因于脾，乃得禀也。（详脾胃门） \n《五藏别论》曰∶脑髓、骨、脉、胆、女子胞，此六者，地气之所生也。皆藏于阴而象 \n于地。故藏而不泻，名曰奇恒之府。夫胃、大肠、小肠、三焦、膀胱，此五者，天气之所生 \n也，其气象天，故泻而不藏。此受五脏浊气，名曰传化之府，此不能久留，输泻者也。魄门 \n亦为五脏使，水谷不得久藏。所谓五脏者，藏精气而不泻也，故满而不能实。六腑者，传化 \n物而不藏。故实而不能满也。所以然者，水谷入口，则胃实而肠虚；食下，则肠实而胃虚。 \n故曰实而不满，满而不能实也。 \n《平人绝谷篇》曰∶平人胃满则肠虚，肠满则胃虚，更实更虚。故气得上下，五脏安定 \n，血脉和则精神乃居。 \n《邪气脏腑病形篇》帝曰∶天寒地冰，而其面不衣何也？岐伯曰∶十二经脉，三百六十 \n五络，其血气皆上于面而走空窍。（详面病门） \n《灵兰秘典论》曰∶膀胱者，州都之宫，津液藏焉，气化则能出矣。 \n《忧恚无言篇》帝曰∶人之卒然忧恚而言无音者，何道之塞，何气出行，使音不彰？愿 \n闻其方。少师曰∶咽喉者，水谷之道也。喉咙者，气之所以上下者也。（详声喑门） \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《五脏别论》帝曰∶气口何以独为五脏主？岐伯曰∶胃者，水谷之海，五脏六腑之大源 \n也。五味入口藏于胃，以养五脏气，气口亦太阴也，是以五脏六腑之气味，皆出于胃，变见 \n于气口。故五气入鼻，藏于心肺，心肺有病而鼻为之不利也。 \n《动输篇》曰∶胃为五脏六腑之海，其清气上注于肺，肺脉从太阴而行之，其行也以息 \n往来。（详脾胃门） \n《五十营篇》曰∶人一呼，脉再动，气行三寸；一吸，脉亦再动，气行三寸，呼吸定息 \n，气行六寸。（详脉神章） \n《根结篇》曰∶一日一夜五十营，以营五脏之精。所谓五十营者，五脏皆受气。持其脉 \n口，数其至也，五十动而不一代者，五脏皆受气。四十动一代者，一脏无气。三十动一代者 \n，二脏无气。二十动一代者，三脏无气。十动一代者，四脏无气。不满十动一代者，五脏无 \n气，予之短期。所谓五十动而不一代者，以为常也，以知五脏之期。予之短期者，乍数乍疏 \n也。 \n《玉机真藏论》曰∶春脉如弦。春脉者，肝也。东方木也，万物之所以始生也。故其气 \n来软弱轻虚而滑。端直以长，故曰弦，反此者病。其气来实而强，此谓太过，病在外。其气 \n来不实而微，此谓不及，病在中。夏脉如钩。（详脉神章） \n《脉要精微论》曰∶夫脉者，血之府也，长则气治，短则气病，数则烦心，大则病进， \n上盛则气高，下盛则气胀，代则气衰，细则气少。（详脉神章） \n《平人气象论》曰∶人一呼脉一动，一吸脉一动，曰少气。平人之常气禀于胃，人无胃 \n气曰逆，逆者死。脉无胃气亦死。（详脾胃门） \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《阴阳清浊篇》帝曰∶愿闻人气之清浊。岐伯曰∶受谷者，浊。受气者，清。清者注 \n阴，浊者注阳。浊而清者，上出于咽；清而浊者，则下行。清浊相干，命曰乱气。帝曰∶夫 \n阴清而阳浊，浊者有清，清者有浊，别之奈何？岐伯曰∶气之大别，清者，上注于肺；浊者 \n，下走于胃。胃之清气，上出于口；肺之浊气，下注于经，内积于海。清者，其气滑；浊者 \n，其气涩。此气之常也。 \n《决气篇》帝曰∶余闻人有精，气、津、液、血、脉，余意为一气耳，今乃辨为六名 \n，余不知其所以然。岐伯曰∶两神相搏，合而成形，常先身生，是谓精。何谓气？曰∶上焦 \n开发，宣五谷味，熏肤、充身、泽毛，若雾露之溉，是谓气。何谓津？曰∶腠理发泄，汗出 \n溱溱，是谓津。何谓液？曰∶谷入气满，淖泽注于骨，骨属屈伸，泄泽，补益脑髓，皮肤润 \n泽，是谓液。何谓血？曰∶中焦受气取汁，变化而赤，是谓血。何谓脉？曰∶壅遏营气，令无 \n所避，是谓脉。精脱者，耳聋；气脱者，目不明；津脱者，腠理开，汗大泄；液脱者，骨属 \n屈伸不利，色夭，脑髓消，胫酸，耳数鸣；血脱者，色白，夭然不泽，其脉空虚，此其 \n候也。 \n《卫气失常篇》曰∶人有肥、有膏、有肉。膏者多气，多气者热，热者耐寒。肉者多血 \n则充形，充形则平。脂者其血清，气滑少，故不能大。此别于众人者也。 \n《寿夭刚柔篇》曰∶形与气相任则寿，不相任则夭。（详生死门） \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《营卫生会篇》∶曰∶夫血之与气，异名同类，何谓也？（详血证门） \n《五音五味篇》曰∶今妇人之生，有余于气，不足于血，以其数脱血也。冲任之脉，不 \n荣口唇，故须不生焉。是故圣人视其颜色，黄赤者，多热气。青白者，少热气。黑色者，多 \n血少气。夫人之常数，太阳，常多血少气。少阳，常多气少血。阳明，常多血多气。厥阴， \n常多气少血。少阴，常多血少气。太阴，常多血少气。此天数之常也。 \n《八正神明论》曰∶故养神者，必知形之肥瘦，营卫血气之盛衰。血气者，人之神，不 \n可不谨养。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《本藏篇》曰∶经脉者，所以行血气而营阴阳，濡筋骨，利关节者也。卫气者，所以温 \n分肉，充皮肤，肥腠理，司关阖者也。 \n《营卫生会篇》帝曰∶人受气于谷，谷入于胃，以传于肺，五脏六腑，皆以受气，其 \n清者为营，浊者为卫，营行脉中，卫行脉外。 \n《卫气行篇》曰∶卫气之行，一日一夜五十周于身，昼日行于阳二十五周，夜行于阴二 \n十五周。是以平旦阴尽，阳气出于目，目张则气上行于头。 \n《痹论》曰∶营者，水谷之精气也，和调于五脏，洒陈于六腑，乃能入于脉也，故循脉 \n上下，贯五脏，络六腑也。卫者，水谷之悍气也，其气剽疾滑利，不能入于脉也。故循 \n皮肤之中，分肉之间，熏于盲膜，散于胸腹。 \n《禁服篇》曰∶审察卫气，为百病母。 \n《逆调论》曰∶营气虚则不仁，卫气虚则不用，营卫俱虚，则不仁且不用。 \n《生气通天论》曰∶营气不从，逆于肉理，乃生痈肿。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《营气篇》曰∶营气之道，内谷为宝。谷入于胃，乃传之肺，流溢于中，布散于外。精 \n专者行于经隧，常营无已，终而复始，是谓天地之纪。 \n《邪客篇》曰∶五谷入于胃也，其糟粕、津液、宗气，分为三隧。故宗气积于胸中。（ \n详脾胃门） \n《经脉篇》曰∶谷入于胃，脉道以通，血气乃行。 \n《玉版篇》曰∶人之所受气者，谷也。谷之所注者，胃也。胃者，水谷气血之海也。（ \n详脾胃门） \n《五味篇》曰∶天地之精气，其大数常出三入一。故谷不入，半日则气衰，一日则气少 \n矣。 \n《平人绝谷篇》曰∶神者，水谷之精气也。（详死生门） \n《终始篇》曰∶邪气来也，紧而疾；谷气来也，徐而和。 \n《平人气象论》曰∶人以水谷为本。故人绝水谷则死，脉无胃气亦死。（详饮食门） \n《病能论》曰∶食人于阴，长气于阳。 \n《阴阳清浊篇》帝曰∶愿闻人气之清浊。岐伯曰∶受谷者浊，受气者清。清者注阴，浊 \n者注阳。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《六节藏象论》曰∶天食人以五气，地食人以五味。（详脾胃门） \n《阴阳应象大论》曰∶水为阴，火为阳，阳为气，阴为味。味归形，形归气，气归精， \n精归化，精食气，形食味，化生精，气化形。味伤形，气伤精，精化为气，气伤于味。阴味 \n出下窍，阳气出上窍。味浓者为阴，薄为阴之阳。气浓者为阳，薄为阳之阴。味浓则泄，薄 \n则通。气薄则发泄，浓则发热。气味，辛甘发散为阳，酸苦涌泄为阴。形不足者，温之以气 \n；精不足者，补之以味。 \n《经脉别论》曰∶食气入胃，散精于肝。（详脾胃门） \n《生气通天论》曰∶阴之所生，本在五味，阴之五宫，伤在五味。是故味过于酸，肝气 \n以津，脾气乃绝。味过于咸，大骨气劳，短肌，心气抑。味过于甘，心气喘满，色黑，肾气 \n不衡。味过于苦，脾气不濡，胃气乃浓。味过于辛，筋脉沮弛，精神乃央。是故谨和五味， \n骨正筋柔，气血以流，腠理以密，如是则气骨以精，谨道如法，长有天命。 \n《宣明五气篇》曰∶五味所禁，辛走气，气病无多食辛。（详饮食门） \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《经脉篇》曰∶饮酒者，卫气先行皮肤，先充络脉，络脉先盛。故卫气已平，营气乃满 \n，而经脉大盛。 \n《厥论》曰∶酒入于胃，则络脉满而经脉虚。夫酒气盛而剽悍，肾气日衰，阳气独 \n胜。故手脚为之热也。 \n《营卫生会篇》帝曰∶人饮酒，酒亦入胃，谷未熟而小便独先下者，何也？岐伯曰∶ \n酒者，熟谷之液也。其气悍以清，故后谷而入，先谷而液出焉。 \n《论勇篇》帝曰∶怯士之得酒，怒不避勇士者，何藏使然？少俞曰∶酒者，水谷之精， \n熟谷之液也。其气剽悍，其入于胃中，则胃胀，气上逆，满于胸中，肝浮胆横。当是之 \n时，固比于勇士，气衰则悔。与勇士同类，不知避之，名曰酒悖也。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《刺节真邪论》帝曰∶有一脉生数十病者，或痛，或痈，或热，或寒，或痒，或痹， \n或不仁，变化无穷，其故何也？岐伯曰∶此皆邪气之所生也。帝曰∶余闻气者，有真气，有 \n正气，有邪气。何谓真气？岐伯曰∶真气者，所受于天，与谷气并而充身也。正气者，正风 \n也，从一方来，非实风，又非虚风也。邪气者，虚风之贼伤人也，其中人也深，不能自去。 \n正风者，其中人也浅，合而自去，其气来柔弱，不能胜真气，故自去。虚邪之中人也。洒淅 \n动形，起毫毛而发腠理。其入深，内搏于骨，则为骨痹。搏于筋，则为筋挛。搏于脉中，则 \n为血闭不通，则为痈。搏于肉，与卫气相搏。阳胜者，则为热；阴胜者，则为寒。寒则真气 \n去，去则虚，虚则寒。搏于皮肤之间，其气外发，腠理开，毫毛摇，气往来行，则为痒。留 \n而不去，则为痹。卫气不行，则为不仁。（余义详本经） \n《通评虚实论》曰∶邪气盛则实，精气夺则虚。帝曰∶虚实如何？岐伯曰∶气虚者，肺 \n虚也。气逆者，足寒也。非其时则生，当其时则死。余藏皆如此。 \n《评热病论》曰∶邪之所凑，其气必虚。 \n《小针解》曰∶夫气之在脉也，邪气在上者，言邪气之中人也高，故邪气在上也。浊气 \n在中者，言水谷皆入于胃，其精气上注于肺，浊溜于肠胃。言寒温不适，饮食不节，而病生 \n肠胃，故曰浊气在中也。清湿在下者，言清湿地气之中人也，必从足始。故曰清气在下也。 \n《阴阳应象大论》曰∶天之邪气，感则害人五脏；水谷之寒热，感则害于六腑；地之湿 \n气，感则害皮肉筋脉。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《寿夭刚柔篇》曰∶风寒伤形，忧恐忿怒伤气。气伤脏，乃病藏；寒伤形，乃应形；风 \n寒伤筋，筋脉乃应，此形气外内之相应也。 \n《脉要精微论》曰∶阳气有余，为身热无汗。阴气有余，为多汗身寒。阴阳有余，则无 \n汗而寒。言而微，终日乃复言者，此夺气也。 \n《刺志论》曰∶气实形实，气虚形虚，此其常也。反此者，病。谷盛气盛，谷虚气虚， \n此其常也。反此者，病。脉实血实，脉虚血虚，此其常也。反此者，病。气虚身热，此谓反 \n也。谷入多而气少，此谓反也。谷不入而气多，此谓反也。脉盛血少，此谓反也。脉少血多 \n，此谓反也。气盛身寒，得之伤寒。气虚身热，得之伤暑。谷入多而气少者，得之有所脱血 \n，湿居下也。谷入少而气多者，邪在胃及与肺也。脉小血多者，饮中热也。脉大血少者，脉 \n有风气，水浆不入，此之谓也。夫实者，气入也。虚者，气出也。气实者，热也。气虚者， \n寒也。 \n《宣明五气篇》曰∶五气所病∶心为噫，肺为咳，肝为语，脾为吞，肾为欠为嚏，胃为 \n气逆、为哕、为恐，大肠小肠为泄，膀胱不利为癃，不约为遗溺，胆为怒，是谓五病。五积 \n所并∶精气并于心则喜，并于肺则悲，并于肝则忧，并于脾则畏，并于肾则恐，是谓五并。 \n虚而相并者也。五劳所伤∶久视伤血，久卧伤气，久坐伤肉，久立伤骨，久行伤筋，是为五 \n劳所伤。 \n《举痛论》帝曰∶余知百病生于气也。怒则气上，喜则气缓，悲则气消，恐则气下， \n寒则气收，炅则气泄，惊则气乱，劳则气耗，思则气结，九气不同，何病之生？岐伯曰∶怒 \n则气逆，甚则呕血及飧泄，故气上矣。喜则气和志达，营卫通利，故气缓矣。悲则心系急， \n肺布叶举，而上焦不通，营卫不散，热气在中，故气消矣。恐则气却，却则上焦闭，闭则气 \n还，还则下焦胀，故气不行矣。寒则腠理闭，气不行，故气收矣。炅则腠理开，营卫通，汗 \n大泄，故气泄矣。惊则心无所倚，神无所归，虑无所定，故气乱矣。劳则喘息汗出，外内皆 \n越，故气耗矣。思则心有所存，神有所归，正气留而不行，故气结矣。 \n《举痛论》曰∶寒气客于脉外则脉寒，脉寒则缩蜷，缩蜷则脉绌急，绌急则 \n外引小络，故卒然而痛。得炅则痛立止，因重中于寒，则痛久矣。（诸寒气等义详心腹痛门） \n《本神篇》曰∶肝气虚则恐，实则怒。脾气虚则四肢不用，五脏不安，实则腹胀泾溲不 \n利。心气虚则悲，实则笑不休。肺气虚则鼻塞不利少气，实则喘喝胸盈仰息。肾气虚则厥， \n实则胀，五脏不安。必审五脏之病形，以知其气之虚实，谨而调之也。忧愁者，气闭塞而不 \n行。 \n《口问篇》曰∶上气不足，脑为之不满。（详虚损门） \n《生气通天论》曰∶因于气，为肿，四维相代，阳气乃竭。俞气化薄，传为善畏，及为 \n惊骇。 \n《厥论》曰∶阳气衰于下，则为寒厥；阴气衰于下，则为热厥。（详厥逆门） \n《逆调论》帝曰∶人身非常温也，非常热也，为之热而烦满者，何也？（详寒热门） \n《痹论》曰∶风寒湿三气杂至，合而为痹也。（详风痹门） \n《痿论》帝曰∶五脏使人痿何也？岐伯曰∶肺热叶焦，则皮毛虚弱急薄者，则生痿 \n也。心气热，则下脉厥而上，上则下脉虚，虚则生脉痿，枢折挈，胫纵不任地也。（详痿 \n证门） \n《百病始生篇》帝曰∶积之始生，至其已成奈何？岐伯曰∶积之始生，得寒乃生，厥 \n乃成积也。（详积聚门） \n《评热病论》曰∶诸有水气者，微肿先见于目下也。月事不来者，胞脉闭也。胞脉者， \n属心而络于胞中。今气上迫肺，心气不得下通，故月事不来也。 \n《至真要大论》曰∶诸气 郁，皆属于肺。 \n《病能论》曰∶有病怒狂者，生于阳也。阳气者，因暴折而难决，故善怒也。（详癫狂 \n门） \n《阴阳别论》曰∶一阳发病，少气善咳善泄，其传为心掣，其传为隔。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：《五常政大论》曰∶必先岁气，无伐天和，无盛盛，无虚虚，而遗人夭殃；无致邪，无 \n失正，绝人长命。 \n《上古天真论》曰∶夫上古圣人之教下也，皆谓之虚邪贼风，避之有时，恬 虚无 \n，真气从之，病安从来。上古有真人者，提挈天地，把握阴阳，呼吸精气，独立守神，肌肉若一。 \n《玉机真藏论》曰∶凡治病，察其形气色泽，脉之盛衰，病之新故，乃治之。无后其时 \n。形气相得，谓之可治；色泽以浮，谓之易已；脉从四时，谓之可治；脉弱以滑，是有胃气 \n，命曰易治，取之以时。形气相失，谓之难治；色夭不泽，谓之难已；脉实以坚，谓之益甚 \n；脉逆四时，为不可治。必察四难，而明告之。 \n《疏五过论》曰∶凡欲诊病者，必问饮食居处，暴乐暴苦，始乐后苦，皆伤精气，精气 \n竭绝，形体毁沮）治病之道，气内为宝，循求其理，求之不得，过在表里。 \n《六元正纪大论》曰∶司气以热，用热无犯。司气以寒，用寒无犯。司气以凉，用凉无 \n犯。司气以温，用温无犯。间气同其主无犯。异其主则小犯之，是谓四畏。必谨察之。故曰 \n∶无失天信，无逆气宜，无翼其胜，无赞其复，是谓至治。 \n《至真要大论》帝曰∶服寒而反热，服热而反寒。其故何也？岐伯曰∶治其王气，是以 \n反也。帝曰∶不治王气而然者，何也？曰∶不治五味属也。夫五味入胃，各归所喜攻。酸先 \n入肝，苦先入心，甘先入脾，辛先入肺，咸先入肾。久而增气，物化之常也；气增而久，夭 \n之由也。审察病机，无失气宜，此之谓也。补上治上制以缓，补下治下制以急。急则气味浓 \n，缓则气味薄。适其至所，此之谓也。 \n《根结篇》曰∶形气不足，病气有余，是邪胜也，急泻之。形气有余，病气不足，急补 \n之。形气不足，病气不足，此阴阳气俱不足也，不可刺之，刺之则重不足，重不足则阴阳俱 \n竭，血气皆尽，五脏空虚，筋骨髓枯，老者绝灭，壮者不复矣。形气有余，病气有余，此阴 \n阳俱有余也，急泻其邪，调其虚实。故曰有余者泻之，不足者补之，此之谓也。 \n《刺法论》帝曰∶五疫之至，皆相染易，如何可得不相移易者？岐伯曰∶不相染者， \n正气存内，邪不可干，避其毒瓦斯，天牝从来，复得其往，气出于脑，即不邪干。（以上俱经 \n旨） \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：夫人之有生，无非受天地之气化耳。及其成形，虽有五行五志，五脏六腑之辨，而总惟 \n血气为之用。然血无气不行。血非气不化，故经曰∶血者，神气也。然则血之与气，诚异名 \n而同类，而实惟气为之主。是以天地间阴阳变迁，运数治乱，凡神神奇奇，作于杳冥莫测之 \n乡者，无非气化之所为。使能知此而气得其正，则何用弗臧。一有违和，而气失其正，则何 \n往弗否？故帝曰∶百病生于气也。又近见应震王氏曰∶行医不识气，治病从何据？堪笑道中人 \n，未到知音处。旨哉斯言！是实治身治病第一大纲，而后学鲜有知者。且轩岐言气，既已靡 \n遗，奈何久未发明，终将冥讳。故余摭其精微，类述一十五条，详列如前。俾后学得明造化 \n之大源，则因理触机，而拯济无穷，斯见轩岐赞育之恩，与地同矣。时崇祯丙子，后学介宾 \n谨识。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：夫百病皆生于气，正以气之为用，无所不至，一有不调，则无所不病。故其在外则有六 \n气之侵，在内则有九气之乱。而凡病之为虚为实，为热为寒，至其变态，莫可名状。欲求其 \n本，则止一气字足以尽之。盖气有不调之处，即病本所在之处也。是为明哲不凡者，乃能独 \n见其处。撮而调之，调得其妙，则犹之解结也，犹之雪污也。污去结解，而活人于举指之间 \n，诚非难也。然而人多难能者，在不知气之理，并不知调之法。即自河间相传以来，咸谓木 \n香槟榔可以调气，陋亦甚矣。夫所谓调者，调其不调之谓也。凡气有不正，皆赖调和。如邪 \n气在表，散即调也；邪气在里，行即调也；实邪壅滞，泻即调也；虚羸困惫，补即调也。由 \n是类推，则凡寒之、热之，温之、清之，升之、降之，抑之、举之，发之、达之，劫之、夺 \n之，坚之，削之，泄之、利之，润之、燥之，收之、涩之，缓之、峻之，和之、安之。正者 \n，正之。假者，反之。必清必静，各安其气，则无病不除。是皆调气之大法也。 \n此外有如按摩导引、针灸熨洗，可以调经络之气。又如喜能胜忧，悲能胜怒，怒能胜思 \n，思能胜恐，恐能胜喜，可以调情志之气。又如五谷、五果、五菜、五畜可以调化育之气。 \n又春夏养阳，秋冬养阴，避风寒，节饮食，慎起居，和喜怒，可以调卫生之气。及其至也， \n则精气有互根之用，阴阳有颠倒之施。或以塞之而实以通之，或以启之而实以封之，或人见 \n其有而我见其无，或病若在此反以治彼。惟智者能见事之未然，惟仁人能惜人之固有。若此 \n者，何莫非调之之谓。人能知此，岂惟却病。而凡内而身心，外而庶政，皆可因之而无弗调 \n矣。甚矣，调之为义，其道圆矣！其用广矣！有神有据，无方无隅，有不可以言宣者，言难尽 \n意也。有不可迹拘者，迹难求全也。故余于本门，但援经悉理，不敢执方。盖亦恐一曲之谈 \n，有不可应无穷之变也。倘有所须，则各门具列论治，所当互证酌宜，而无负调和之手，斯 \n于斯道可无愧矣。 \n\n\n\n<目录>卷之三十六天集·杂证谟\\诸气\n\n<篇名>经义\n\n属性：张子和云∶九气之气，如天地之气，常则安，变则病。而况人禀天地之气，五运迭侵于 \n外，七情交战于中。是以圣人啬气，如持至宝。庸人役物，反伤太和。此轩岐之所以谓诸痛 \n皆因于气，百病皆生于气，遂有九气不同之说。气本一也，因所触而为九。怒、喜、悲、恐 \n、寒、炅、惊、思、劳也。怒气所致，为呕血，为飧泄，为煎厥，为薄厥，为阳厥，为胸满 \n胁痛。食则气逆而不下，为喘喝烦心，为消瘅，为肥气，为目盲，为耳闭筋缓；发于外，为 \n痈疽。喜气所致，为笑不休，为毛革焦，为肉病；为阳气不收，甚则为狂。悲气所致，为阴 \n缩，为筋挛，为肌痹，为肺痿；男为溲血，女为血崩；为酸鼻辛 ，为目昏，为少气不 \n能接息，为泣则臀麻。恐气所致，为破 脱肉，为骨酸痿厥，为暴下清水，为面 \n热肤急，为阴痿，为惧而脱颐。惊气所致，为潮涎，为目HT ，为口噤，为痴痫，为不 \n省人事，为僵仆，久则为 痹。思气所致，为不眠，为嗜卧，为昏瞀，为中痞，三焦 \n闭塞，为咽嗌不利，为胆瘅呕苦，为筋痿，为白淫，为得后与气则快然而衰，为不嗜食。寒 \n气所致，为上下所出水液澄澈清冷，下利青白。炅气所致，为喘呕吐酸，暴注下迫。 \n丹溪曰∶气无补法，世俗之误也。气实而壅盛者不必补。内伤劳役，正气虚者，不补而 \n何？若正气虚而不补，是虚而益虚，则脾胃运化纳受皆失其职，阴不升而阳不降，所谓天地 \n不交之否也。经曰∶虚者补之，人参、黄 之属是也。若不审虚实，悉以破气行气之药与之 \n，以天真元气耗绝而死者，医杀之耳。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《上古天真论》∶黄帝问于天师曰∶余闻上古之人，春秋皆度百岁，而动作不衰。今时 \n之人，年半百而动作皆衰者，时热异耶？人将失之耶？岐伯曰∶上古之人，其知道者，法于阴 \n阳，和于术数，食饮有节，起居有常，不妄作劳。故能形与神俱，而尽终其天年，度百岁乃 \n去。今时之人不然也，以酒为浆，以妄为常，醉以入房，以欲竭其精，以耗散其真，不知持 \n满，不时御神，务快其心，逆于生乐，起居无节，故半百而衰也。 \n《阴阳应象大论》曰∶是以圣人为无为之事，乐恬 之能，从欲快志于虚无之守。 \n故寿命无穷，与天地终，此圣人之治身也。 \n《天年篇》帝曰∶愿闻人之始生，何气筑为基，何立而为 ，何失而死，何得而生？ \n岐伯曰∶以母为基，以父为 。失神者，死；得神者，生也。帝曰∶人之寿夭各不同，或卒 \n死、或病久，愿闻其道。岐伯曰∶五脏坚固，血脉和调，肌肉解利，皮肤致密、营卫之行， \n不失其常，呼吸微徐，气以度行，六腑化谷，津液布扬，各如其常。故能久长。帝曰∶人之 \n寿百岁而死，何以致之？岐伯曰∶使道隧以长，基墙高以方，通调营卫，三部三里起，骨高 \n肉满，百岁乃得终。帝曰∶其不能终寿而死者，何如？岐伯曰∶其五脏皆不坚，使道不长， \n空外以张，喘息暴疾，又卑基墙，薄脉少血，其肉不石，数中风寒，血气虚，脉不通，真邪 \n相攻，乱而相引，故中寿而尽也。 \n《五阅五使篇》曰∶脉出于气口，色见于明堂。（详面病门） \n《五色篇》曰∶明堂者，鼻也。阙者，眉间也。庭者，颜也。蕃者，颊侧也。蔽者，耳 \n门也。其间欲方大，去之十步皆见于外，如是者寿必中百岁。（详面病门） \n《寿夭刚柔篇》曰∶形与气相任则寿，不相任则夭。皮与肉相果则寿，不相果则夭。血 \n气经络胜形则寿，不胜形则夭。形充而皮肤缓者则寿，形充而皮肤急者则夭。形充而而脉坚大 \n者顺也，形充而脉小以弱者气衰，气衰则危矣。形充而颧不起者骨小，骨小则夭矣。形充而 \n大肉 坚而有分者肉坚，肉坚则寿矣；形充而大肉无分理不坚者肉脆，肉脆则夭矣。墙 \n基卑，高不及其地者，不满三十而死。其有因加疾者，不满二十而死。平人而气胜形者寿， \n病而形肉脱，气胜形者死，形胜气者危矣。 \n《五常政大论》曰∶阴精所奉其人寿，阳精所降其人夭。帝曰∶一州之气，生化寿夭不 \n同，其故何也？岐伯曰∶高下之理，地势使然也。崇高则阴气治之，污下则阳气治之。阳胜 \n者先天，阴胜者后天，此地理之常，生化之道也。帝曰∶其有寿夭乎？曰∶高者，其气寿； \n下者，其气夭。地之小大异也。小者小异，大者大异。故治病者，必明天道地理，阴阳更胜 \n，气之先后，人之寿夭，生化之期，乃可以知人之形气矣。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《五常政大论》曰∶根于中者，命曰神机，神去则机息。根于外者，命曰气立，气止则化绝。 \n《移精变气论》帝曰∶余欲临病患，观死生，决嫌疑，欲知其要。如日月光，可得闻 \n乎？岐伯曰∶色脉者，上帝之所贵也。先师之所传也。色以应日，脉以应月，常求其要，则 \n其要也治之要极，无失色脉，用之不惑，治之大则。得神者，昌；失神者，亡。帝曰∶善。 \n《邪客篇》曰∶心者，五脏六腑之大主也，精神之所舍也。其脏坚固，邪弗能容也。容 \n之则心伤，心伤则神去，神去则死矣。 \n《营卫生会篇》曰∶营卫者，精气也；血者，神气也。血之与气，异名同类焉。故夺血 \n者无汗，夺汗者无血。故人生有两死，而无两生。 \n《疏五过论》曰∶故贵脱势，虽不中邪，精神内伤，身必败亡。 \n《汤液 体论》帝曰∶形弊血尽而功不立者何？岐伯曰∶神不使也。帝曰∶何谓神不 \n使？曰∶针石，道也。精神不进，志意不治，故病不可愈。今精坏神去，营卫不可复收。何 \n者？嗜欲无穷，而忧患不止，精神弛坏，营涩卫除，故神去之而病不愈也。病成名曰逆，则 \n针石不能治，良药不能及也。 \n《逆调论》曰∶人生与志不相有，曰死。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《四气调神论》曰∶夫四时阴阳者，万物之根本也。所以圣人春夏养阳，秋冬养阴，以 \n从其根，故与万物浮沉于生长之门。逆其根，则伐其本，坏其真矣。故阴阳四时者，万物之 \n终始也，死生之本也。逆之则灾害生，从之则苛疾不起，是谓得道。道者，圣人行之，愚者 \n佩之。从阴阳则生，逆之则死；从之则治，逆之则乱。反顺为逆，是谓内格。 \n《阴阳应象大论》曰∶阳胜则身热，腠理闭，喘粗为之俯仰，汗不出，齿干以烦冤腹满 \n死，能冬不能夏；阴胜则身寒，汗出身常清，数栗而寒，寒则厥，厥则腹满死，能夏不能冬。 \n《寿夭刚柔篇》曰∶阴阳俱动，乍有形，乍无形，加以烦心，命曰阴胜其阳，此谓不表不里，其形不久。 \n《阴阳别论》曰∶二阳之病发心脾，有不得隐曲，女子不月；其传为风消，其传为息贲者，死不治。 \n《通天篇》曰∶太阳之人，多阳而少阴，必谨调之，无脱其阴而泻其阳。阳重脱者，易 \n狂；阴阳皆脱者，暴死不知人也。 \n《阴阳二十五人篇》曰∶火形之人，似于赤帝，好颜急心，不寿暴死；能春夏不能秋冬 \n。水形之人，似于黑帝，善欺 人，戮死；能秋冬不能春夏。 \n《至真要大论》帝曰∶六气之复何如？岐伯曰∶厥阴之复，甚则入脾。冲阳绝，死不 \n治。少阴之复，甚则入肺，咳而鼻渊。天府绝，死不治。太阴之复，甚则入肾，窍泻无度。 \n太溪绝，死不治。少阳之复，甚则入肺，咳而血泄。尺泽绝，死不治。阳明之复，甚则入肝 \n，惊骇筋挛。太冲绝，死不治。太阳之复，甚则入心，善忘善悲。神门绝，死不治。阳明司 \n天，清复内余，咳不止而白血出者死。乘年之虚，则邪甚也。失时之和，亦邪甚也。遇月之 \n空，亦邪甚也。重感于邪，则病危矣。至而和则平，至而甚则病，至而反者病，至而不至者 \n病，未至而至者病，阴阳易者危，反者死。 \n《五营运大论》曰∶从其气则和，违其气则病，不当其位者病，迭移其位者病，失守其 \n位者危，尺寸反者死，阴阳交者死。先立其年，以知其气，左右应见，然后乃可以言死生之逆顺。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《平人气象论》曰∶人一呼，脉四动以上曰死，脉绝不至曰死，乍疏乍数曰死。春胃微 \n弦曰平，弦多胃少曰肝病，但弦无胃曰死。人以水谷为本，故人绝水谷则死，脉无胃气亦死 \n（上二条详四卷脉神章）。死心脉来，前曲后居，如操带钩，曰心死。死肺脉来，如物之浮， \n如风吹毛，曰肺死。死肝脉来，急益劲，如新张弓弦，曰肝死。死脾脉来，锐坚如鸟之喙， \n如鸟之距，如屋之漏，如水之流，曰脾死。死肾脉来，发如夺索，辟辟如弹石，曰肾死。 \n《三部九候论》曰∶五脏已败，其色必夭，夭必死矣。形盛脉细，少气不足以息者危。 \n形瘦脉大，胸中多气者死。参伍不调者病。三部九候皆相失者死。上下左右相失不可数者死 \n。中部之候虽独调，与众脏相失者死。中部之候相减者死。目内陷者死。脱肉身不去者死。 \n中部乍疏乍数者死。真脏脉见者胜死。足太阳气绝者，其足不可屈伸，死必戴眼。九候之脉 \n，皆沉细悬绝者为阴，主冬，故以夜半死。躁盛喘数者为阳，主夏，故以日中死。其脉乍数"}, {"n": 20, "text": "卷二十\n\n乍疏乍迟乍疾者，日乘四季死。形肉已脱，九候虽调，犹死。若有七诊之病，其脉候亦败者 \n死矣，必发哕噫。脉不往来者死。皮肤着者死。瞳子高者太阳不足，戴眼者太阳已绝，此决 \n死生之要，不可不察也。 \n《方盛衰论》曰∶形弱气虚死。形气有余，脉气不足死；脉气有余，形气不足生。 \n《玉机真藏论》曰∶形气相失，谓之难治；色夭不泽，谓之难已；脉实以坚，谓之益甚 \n；脉逆四时，为不可治。所谓逆四时者，春得肺脉，夏得肾脉，秋得心脉，冬得脾脉，其至 \n皆悬绝沉涩者，命曰逆四时。 \n《大奇论》曰∶胃脉沉鼓涩，胃外鼓大，心脉小坚急，皆鬲偏枯，男子发左，女子发右 \n，不喑舌转，可治。三十日起，其从者喑；三岁起，年不满二十者，三岁死。脉至而搏，血 \n衄身热者死。脉至浮合，浮合如数，一息十至以上，是经气予不足也。微见九十日死。脉至 \n如火薪然，是心精之予夺也，草干而死。脉至如散叶，是肝气予虚也，木叶落而死。脉至如 \n省客，省客者脉塞而鼓，是肾气予不足也，悬去枣华而死。脉至如丸泥，是胃精予不足也， \n榆荚落而死。脉至如横格，是胆气予不足也，禾熟而死。脉至如弦缕，是胞精予不足也，病 \n善言，下霜而死；不言，可治。脉至如交漆，交漆者左右傍至也，微见三十日死。脉至如涌 \n泉，浮鼓肌中，太阳气予不足也，少气味，韭英而死。脉至如颓土之状，按之不得，是肌气 \n予不足也，五色先见黑白，垒发死。脉至如悬雍，悬雍者浮揣切之益大，是十二俞之予不足 \n也，水凝而死。脉至如偃刀，偃刀者浮之小急，按之坚大急，五脏菀热，寒热独并于肾也， \n如此其人不得坐，立春而死。脉至如丸滑不直手，不直手者，按之不可得也，是大肠气予不 \n足也，枣叶生而死。脉至如华者，令人善恐，不欲坐卧，行立常听，是小肠气予不足也，季 \n秋而死。 \n《宣明五气篇》曰∶五邪所见，春得秋脉，夏得冬脉，长夏得春脉，秋得夏脉，冬得长 \n夏脉，名曰阴出之阳，病善怒不治，是谓五邪，皆同命，死不治。 \n《玉版论要篇》曰∶色夭面脱，不治，百日尽已。脉短气绝死。病温虚甚死。女子右为 \n逆，左为从；男子左为逆，右为从。易，重阳死，重阴死。 \n《通评虚实论》曰∶气虚者，肺虚也；气逆者，足寒也。非其时则生，当其时则死。帝 \n曰∶何谓重虚？岐伯曰∶脉气上虚尺虚，是谓重虚。帝曰∶何以治之？曰∶所谓气虚者，言无 \n常也。尺虚者，行步 然。脉虚者，不象阴也。如此者，滑则生，涩则死也。帝曰∶ \n寒气暴上，脉满而实何如？曰∶实而滑则生，实而逆则死。帝曰∶脉实满，手足寒，头热， \n何如？曰∶春秋则生，冬夏则死。脉浮而涩，涩而身有热者死。帝曰∶其形尽满何如？曰∶其 \n形尽满者，脉急大坚，尺涩而不应也。如是者，从则生，逆则死。所谓从者，手足温也；所 \n谓逆者，手足寒也。 \n《阴阳别论》曰∶所谓阴者，真脏也，见则为败，败必死也；所谓阳者，胃脘之阳也。 \n别于阳者，知病处也；别于阴者，知死生之期。三阴俱搏，二十日夜半死；二阴俱搏，十三 \n日夕时死；一阴俱搏，十日平旦死。三阳俱搏且鼓，三日死；三阴三阳俱搏，心腹满，发尽 \n不得隐曲，五日死；二阳俱搏，其病温，死不治，不过十日死。凡持真脉之脏脉者，肝至悬 \n绝急，十八日死；心至悬绝，九日死；肺至悬绝，十二日死；肾至悬绝，七日死；脾至悬绝 \n，四日死。 \n《玉机真藏论》曰∶真肝脉至，中外急，如循刀刃责责然，如按琴瑟弦，色青白不泽， \n毛折乃死。（五脏脉详脉神章真藏条） \n《终始篇》曰∶脉口四盛，且大且数者，名曰溢阴。溢阴为内关，内关不通，死不治。 \n（诸脉俱详关格门） \n《五脏生成篇》曰∶凡相五色之奇脉，面黄目青，面黄目赤，面黄目白，面黄目黑者， \n皆不死也。面青目赤，面赤目白，面青目黑，面黑目白，面赤目青，皆死也。故色见青如草 \n兹者死，黄如枳实者死，黑如 者死，赤如HT 血者死，白如枯骨者死，此五色之见 \n死也。青如翠羽者生，赤如鸡冠者生，黄如蟹腹者生，白如豕膏者生，黑如乌羽者生，此五 \n色之见生也。 \n《论疾诊尺篇》曰∶诊寒热，赤脉上下至瞳子，见一脉一岁死，见一脉半一岁半死，见 \n二脉二岁死，见二脉半二岁半死，见三脉三岁死。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《玉机真藏论》曰∶五脏受气于其所生，传之于其所胜，气舍于其所生，死于其所不胜 \n，病之且死，必先传行至其所不胜，病乃死。此言气之逆行也，故死。肝受气于心，传之于 \n脾，气舍于肾，至肺而死。脾受气于肺，传之于肾，气舍于心，至肝而死。肺受气于肾，传 \n之于肝，气舍于脾，至心而死。肾受气于肝，传之于心，气舍于肺，至脾而死。此皆逆死也 \n。一日一夜五分之，此所以言死生之旦暮也。帝曰∶五脏相通，移皆有次，五脏有病，则各 \n传其所胜。不治，法三月若六月，若三日若六日，传五脏而当死，是顺传所胜之次也。故曰 \n∶别于阳者，知病从来；别于阴者，知死生之期。言知至其所困而死。风者，百病之长也。 \n肾传之心，病筋脉相引而急，病名曰螈，当此之时，可灸可药。弗治，满十日，法当死。肾 \n因传之心，心即复反传而行之肺，发寒热，法当三岁死。 \n《标本病传论》曰∶夫病传者，心病先心痛，一日而咳，三日胁支痛，五日闭塞不通， \n身痛体重，三日不已死，冬夜半，夏日中。肺病喘咳，三日而胁支满痛，一日身重体痛，五 \n日而胀，十日不已死，冬日入，夏日出。肝病头目眩，胁支满，三日体重身痛，五日而胀， \n三日腰脊少腹痛胫酸，三日不已死，冬日入，夏早食。脾病身痛体重，一日而胀，二日 \n少腹腰脊痛胫酸，三日背KT 筋痛小便闭，十日不已死，冬人定，夏晏食。肾病 \n少腹腰脊痛 酸，三日背KT 筋痛小便闭，三日腹胀，三日两胁支痛，三日不 \n已死，冬大晨，夏晏晡。胃病胀满，五日少腹腰脊痛 酸，三日背KT 筋痛小 \n便闭，五日身体重，六日不已死，冬夜半后，夏日 。膀胱病小便闭，五日少腹胀腰 \n脊痛 酸，一日腹胀，一日身体痛，二日不已死，冬难鸣，夏下晡。诸病以次相 \n传，如是者，皆有死期，不可刺。间一脏止，及至三四脏者，乃可刺也。 \n《病传篇》曰∶大气入脏，腹痛下淫，可以致死，不可以致生。帝曰∶大气入脏奈何？ \n岐伯曰∶病先发于心，一日而之肺，五日而之脾，三日不已，死，冬夜半，夏日中。病先发 \n于肺，三日而之肝，一日而之脾，五日而之胃，十日不已，死，冬日入，夏日出。病先发于 \n肝，三日而之脾，五日而之胃，三日而之肾，三日不已，死，冬日入，夏早食。病先发于脾 \n，一日而之胃，二日而之肾，三日而之膂膀胱，十日不已，死，冬人定，夏晏食。病先发于 \n胃，五日而之肾，三日而之膂膀胱，五日而上之心，二日不已，死，冬夜半，夏日 \n。病先发于肾，三日而之膂膀胱，三日而上之心，三日而之小肠，三日不已，死，冬大晨， \n夏晏晡。病先发膀胱，五日而之肾，一日而之小肠，一日而之心，二日不已，死，冬难鸣， \n夏下晡。 \n《气厥论》曰∶心移寒于肺，肺消，肺消者饮一溲二，死不治。肝移热于心则死。肾移 \n热于脾，传为虚，肠 死，不可治。 \n《阴阳别论》曰∶死阴之属，不过三日而死；生阳之属，不过四日而死。所谓生阳死阴 \n者，肝之心谓之生阳，心之肺谓之死阴，肺之肾谓之重阴，肾之肝谓之辟阴，死不治。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《九宫八风篇》曰∶太一移日，天必应之以风雨，以其日风雨则吉，岁美民安少病矣。 \n因视风所从来而占之∶风从其所居之乡来为实风，主生，长养万物；从其冲后来为虚风，主 \n杀主害者。谨候虚风而避之。故圣人日避虚邪之道，如避矢石然，邪弗能害，此之谓也。风 \n从西北方来，名曰折风，其伤人也，内舍于小肠，外在于手太阳脉，脉绝则溢，脉闭则结不 \n通，善暴死。三虚相搏，则为暴病卒死。 \n《岁露论》帝曰∶其有卒然暴病暴死者何也？少师曰∶三虚者，其死暴疾也。得三实 \n者，邪不能伤人也。帝曰∶愿闻三虚。曰∶乘年之衰，逢月之空，失时之和，因为贼风所伤 \n，是为三虚。故论不知三虚，工反为粗。帝曰∶愿闻三实。曰∶逢年之盛，遇月之满，得时 \n之和，虽有贼风邪气，不能危之也。故诸逢其风雨遇其雨者，命曰遇岁露焉。因岁之和，而 \n少贼风者，民少病而少死；岁多贼风邪气，寒温不和，则民多病而死矣。帝曰∶虚邪之风， \n其所伤贵贱何如？候之奈何？曰∶正月朔日，太一居天留之宫，其日西北风，不雨，人多死矣 \n。正月朔日，平旦北风，春，民多死。正月朔日，平旦北风行，民病多者，十有三也。正月 \n朔日，日中北风，夏，民多死。正月朔日，夕时北风，秋，民多死。终日北风，大病死者十 \n有六。正月朔日，风从南方来，命曰旱乡，从西方来，命曰白骨，将国有殃，人多死亡。正 \n月朔日，风从东方来，发屋，扬沙石，国有大灾也。正月朔日，风从东南方行，春有死亡。 \n正月朔日，天和温不风，籴贱，民不病；天寒而风，籴贵，民多病。此所以候岁之风，残伤 \n人者也。二月丑不风，民多心腹病。三月戍不温，民多寒热。四月巳不暑，民多瘅病。十月 \n申不寒，民多暴死。诸所谓风者，皆发屋，折树木，扬砂石，起毫毛，发腠理者也。 \n《本神篇》曰∶心怵惕思虑则伤神，神伤则恐惧自失，破 脱肉，毛悴色夭，死于 \n冬。脾忧愁而不解则伤意，意伤则 乱，四肢不举，毛悴色夭，死于春。肝悲哀动中则 \n伤魂，魂伤则狂忘不精，不精则不正当人，阴缩而挛筋，两胁骨不举，毛悴色夭，死于秋。 \n肺喜乐无极则伤魄，魄伤则狂，狂者意不存人，皮革焦，毛悴色夭，死于夏。肾盛怒而不止 \n则伤志，志伤则喜忘其前言，腰脊不可以俯仰屈伸，毛悴色夭，死于季夏。恐惧而不解则伤 \n精，精伤则骨酸痿厥，精时自下。是故五脏主藏精者也，不可伤，伤则失守而阴虚，阴虚则 \n无气，无气则死矣。是故用针者，察观病患之态，以知精神魂魄之存亡得失之意，五者以伤 \n，针不可以治之也。 \n《玉机真藏论》曰∶大骨枯槁，大肉陷下，胸中气满，喘息不便，其气动形，期六月死 \n，真脏脉见，乃予之期日。大骨枯槁，大肉陷下，胸中气满，喘息不便，内痛引肩项，期一 \n月死，真脏脉见，乃予之期日。大骨枯槁，大肉陷下，胸中气满，喘息不便，内痛引肩项， \n身热脱肉破 ，真脏见，十月之内死。大骨枯槁，大肉陷下，肩髓内消，动作益衰，真 \n脏来见，期一岁死，见其真脏，乃予之期日。大骨枯槁，大肉陷下，胸中气满，腹内痛，心 \n中不便，肩项痛身热，破 脱肉，目眶陷，真脏见，目不见人，立死；其见人者，至其 \n所不胜之时则死。急虚身中卒至，五脏绝闭，脉道不通，气不往来，譬于堕溺，不可为期。 \n其脉绝不来，若人一息五六至，其形肉不脱，真脏虽不见，犹死也。 \n《三部九候论》曰∶寒热病者，以平旦死。热中及热病者，以日中死。病风者，以日夕 \n死。病水者，以夜半死。 \n《平人气象论》曰∶肝见庚辛死，心见壬癸死，脾见甲乙死，肺见丙丁死，肾见戊己死 \n。是谓真脏见皆死。 \n《气交变大论》曰∶岁木太过，风气流行，脾土受邪，上应岁星，冲阴绝者，死不治。 \n岁火太过，炎暑流行，肺金受邪，上应荧惑星，太渊绝者，死不治。岁土太过，雨湿流行， \n上应镇星，太溪绝者，死不治。岁金太过，燥气流行，肝木受邪，上应太白星，太冲绝者， \n死不治。岁水太过，寒气流行，邪害心火，上应辰星，神门绝者，死不治。 \n《六元正纪大论》帝曰∶六位之气，盈虚何如？岐伯曰∶太少异也。太者之至徐而常 \n，少者暴而亡。木郁之发，甚则耳鸣眩转，目不识人，善暴僵仆。火郁之发，甚则瞀闷懊 \n，善暴死。 \n《六微旨大论》曰∶天符为执法，岁位为行令，太一天符为贵人。帝曰∶邪之中也奈何 \n？岐伯曰∶中执法者，其病速而危；中行令者，其病徐而持；中贵人者，其病暴而死。帝曰 \n∶位之易也何如？曰∶君位臣则顺，臣位君则逆。逆则其病近，其害速；顺则其病远，其害 \n微。所谓二火也。 \n《本病论》帝曰∶人气不足，天气如虚，人神失守，神光不聚，邪鬼外干，致有夭亡 \n，可得闻乎？岐伯曰∶人之五脏，一脏不足，又会天虚，感邪之至也。人忧愁思虑即伤心， \n又或遇少阴司天，天数不及，此即天气人气同虚也。又遇惊而夺精，汗出于心，因而三虚， \n神明失守，却遇火不及之岁，有黑尸鬼犯之，令人暴亡。人饮食劳倦即伤脾，又或遇太阴司 \n天，天数不及，此即人虚而天虚也。又遇饮食饱甚，汗出于胃，醉饱行房，汗出于脾，因而 \n三虚，脾神失守，却遇土不及之年，即有青尸鬼犯之，令人卒亡。人久坐湿地，强力入水即 \n伤肾，因而三虚，肾神失守，却遇水不及之年，有黄尸鬼见之，令人暴亡。人或恚怒，气逆 \n上而不下即伤肝，又遇厥阴司天，天数不及，此谓天虚人虚也。又遇疾走恐惧，汗出于肝， \n神位失守，神光不聚，又遇木不及之年，有白尸鬼犯之，令人暴亡也。以上五失守者，天虚 \n而人虚也，神游失守其位，即有五尸鬼干人，令人暴亡也，谓之曰尸厥。此谓得守者生，失 \n守者死；得神者昌，失神者亡。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《经脉篇》曰∶手太阴气绝则皮毛焦。太阴者，行气温于皮毛者也，故气不荣则皮毛焦 \n，皮毛焦则津液去皮节，津液去皮节则爪枯毛折，毛折者则毛先死，丙笃丁死，火胜金也。 \n手少阴气绝则脉不通，脉不通则血不流，血不流则髦色不泽，故其面黑如漆柴者，血先死， \n壬笃癸死，水胜火也。足太阴气绝者，则脉不荣肌肉。唇舌者，肌肉之本也。脉不荣则肌肉 \n软，肌肉软则舌萎人中满，人中满则唇反，唇反者肉先死，甲笃乙死，木胜土也。足少阴气 \n绝则骨枯。少阴者，冬脉也，伏行而濡骨髓者也。故骨不濡则肉不能着也，骨肉不相亲则肉 \n软却，肉软却故齿长而垢，发无泽，发无泽者骨先死，戊笃己死，土胜水也。足厥阴气绝则 \n筋绝。厥阴者，肝脉也，肝者筋之合也，筋者聚于阴器而脉络于舌本也。故脉弗荣则筋急， \n筋急则引舌与卵，故唇青舌卷卵缩则筋先死，庚笃辛死，金胜木也。五阴气俱绝则目系转， \n转则目运，目运者为志先死，志先死则远一日半死矣。六阳气绝则阴与阳相离，离则腠理发 \n泄，绝汗乃出，故旦占夕死，夕占旦死。 \n《诊要经终论》帝曰∶愿闻十二经脉之终奈何？岐伯曰∶太阳之脉，其终也戴眼反折 \n螈，其色白，绝汗乃出，出则死矣。少阳终者，耳聋百节皆纵，目HT 绝系，绝系一 \n日半死，其死也色先青白，乃死矣。阳明终者，口目动作，善惊妄言，色黄，其上下经盛， \n不仁则终矣。少阴终者，面黑齿长而垢，腹胀闭，上下不通而终矣。太阴终者，腹胀闭不得 \n息，善噫善呕，呕则逆，逆则面赤，不逆则上下不通，不通则面黑皮毛焦而终矣。厥阴终者 \n，中热嗌干，善溺心烦，甚则舌卷卵上缩而终矣。此十二经之所败也。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《脉要精微论》曰∶五脏者，中之守也。言而微，终日乃复言者，此夺气也。衣被不敛 \n，言语善恶不避亲疏者，此神明之乱也。仓廪不藏者，是门户不要也。水泉不止者，是膀胱 \n不藏也。得守者生，失守者死。夫五脏者，身之强也。头者精明之府，头倾视深，精神将夺 \n矣。背者胸中之府，背曲肩垂，府将坏矣。腰者肾之府，转摇不能，肾将惫矣。膝者筋之府 \n，屈伸不能，行则偻附，筋将惫矣。骨者髓之府，不能久立，行则振掉，骨将惫矣。得强则生，失强则死。 \n《玉版篇》帝曰∶诸病皆有逆顺，可得闻乎？岐伯曰∶腹胀、身热、脉大，是一逆也 \n。腹鸣而满，四肢清、泄，其脉大，是二逆也。衄而不止，脉大，是三逆也。咳且溲血脱形 \n，其脉小劲，是四逆也。咳，脱形身热，脉小以疾，是五逆也。如是者，不过十五日而死矣 \n。其腹大胀，四末清，脱形，泄甚，是一逆也。腹胀便血，其脉大，时绝，是二逆也。咳溲 \n血，形肉脱，脉搏，是三逆也。呕血，胸满引背，脉小而疾，是四逆也。咳呕腹胀，且飧泄 \n，其脉绝，是五逆也。如是者，不过一时而死矣。 \n《五禁篇》帝曰∶何谓五逆？岐伯曰∶热病脉静，汗已出，脉躁盛，是一逆也。病泄 \n，脉洪大，是二逆也。着痹不移， 肉破，身热，脉偏绝，是三逆也。淫而夺形，身热 \n，色夭然白，及后下血HT ，血HT 笃重，是四逆也。寒热夺形，脉坚搏，是谓五逆也。 \n《玉机真藏论》曰∶五实死，五虚死。帝曰∶愿闻五实五虚。岐伯曰∶脉盛，皮热，腹 \n胀，前后不通，闷瞀，此谓五实；脉细，皮寒，气少，泄利前后，饮食不入，此谓五虚。帝 \n曰∶其时有生者何也？岐伯曰∶浆粥入胃，注泄止，则虚者活；身汗得后利，则实者活。此 \n其候也。 \n《宝命全角论》曰∶夫盐之味咸者，其气令器津泄；弦绝者，其音嘶败；木敷者，其叶 \n发；病深者，其声哕。人有此三者，是谓坏府，毒药无治，短针无取。 \n《五色篇》∶雷公曰∶人不病卒死，何以知之？帝曰∶大气入于脏腑者，不病而卒死矣 \n。雷公曰∶病小愈而卒死者，何以知之？帝曰∶赤色出两颧，大如母指者，病虽小愈，必卒 \n死。黑色出于庭，大如母指者，必不病而卒死。 \n《奇病论》帝曰∶有癃者，一日数十溲，此不足也。身热如炭，颈膺如格，人迎躁盛 \n，喘息气逆，此有余也。太阴脉细微如发者，此不足也，其病安在？名为何病？岐伯曰∶病在 \n太阴，其盛在胃，颇在肺，病名曰厥，死不治，此所谓五有余二不足也。帝曰∶何谓五有余 \n二不足？曰∶所谓五有余者，五病之气有余也；二不足者，亦病气之不足也。今外得五有余 \n，内得二不足，此其身不表不里，亦正死明矣。 \n《阳明脉解篇》曰∶阳明厥则喘而惋，惋则恶人。帝曰∶或喘而死者，或喘而生者何也 \n？岐伯曰∶厥逆连脏则死，连经则生。 \n《厥论》曰∶三阴俱逆，不得前后，使人手足寒，三日死。少阳厥逆，机关不利，腰不 \n可以行，项不可以顾，发肠痈不可治，惊者死。手心主少阴厥逆，心痛引喉，身热，死不可治。（详厥逆门） \n《通评虚实论》帝曰∶消瘅虚实何如？岐伯曰∶脉实大，病久可治；脉悬小坚，病久 \n不可治。帝曰∶癫疾何如？曰∶脉搏大滑，久自已；脉小坚急，死不治。帝曰∶癫疾之脉， \n虚实何如？曰虚则可治，实则死。帝曰∶肠 便血何如？曰∶身热则死，寒则生。肠 下白沫 \n何如？曰∶脉沉则生，脉浮则死。帝曰∶肠 下脓血何如？曰∶脉悬绝则死，滑大则生。 \n《癫狂篇》曰∶癫疾者，癫发如狂者，死不治。 \n《厥病篇》曰∶风痹淫泺，病不可已者，足如履冰，时如入汤中，股胫淫泺，烦心头痛 \n，时呕时 ，眩已汗出，久则目眩，悲以喜恐，短气不乐，不出三年死也。真心痛，手 \n足清至节，心痛甚，旦发夕死，夕发旦死。真头痛，头痛甚，脑尽痛，手足寒至节，死不治。 \n《痹论》帝曰∶痹，其时有死者，或疼久者，或易已者，其故何也？岐伯曰∶其入脏 \n者死，其留连筋骨间者疼久，其留皮肤间者易已。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《热论篇》曰∶三阴三阳，五脏六腑皆受病，营卫不行，五脏不通，则死矣。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《六元正纪大论》曰∶大积大聚，其可犯也，衰其大半而止，过者死。 \n《诊要经终论》曰∶凡刺胸腹者，必避五脏。中心者环死，中脾者五日死，中肾者七日 \n死，中肺者五日死，中膈者皆为伤中，其病虽愈，不过一岁死。 \n《刺禁论》曰∶脏有要害，不可不察，肝生于左，肺藏于右，心部于表，肾治于里，脾 \n为之使，胃为之市。膈盲之上，中有父母，七节之傍，中有小心，从之有福，逆之有咎。刺 \n中心，一日死，其动为噫。刺中肝，五日死，其动为语。刺中肾，六日死，其动为嚏。刺中 \n肺，三日死，其动为咳。刺中脾，十日死，其动为吞。刺中胆，一日半死，其动为呕。刺跗 \n上中大脉，血出不止死。刺面中溜脉，不幸为盲。刺头中脑户，入脑立死。刺阴股中大脉， \n血出不止死。刺臂太阴脉，出血多立死。 \n《小针解》曰∶取五脉者死，言病在中，气不足，但用针尽大泻其诸阴之脉也。取三阳 \n之脉者，唯言尽泻三阳之气，令病患 然不复也。夺阴者死，言取尺之五里五往者也 \n。夺阳者狂，正言也。所谓五脏之气已绝于内者，脉口气内绝不至，反取其外之病处与阳经 \n之合，有留针以致阳气，阳气至则内重竭，重竭则死矣。其死也无气以动，故静。所谓五脏 \n之气已绝于外者，脉口气外绝不至，反取其四末之输，有留针以致其阴气，阴气至则阳气反 \n入，入则逆，逆则死矣。其死也阴气有余，故躁。 \n《玉版篇》曰∶夫针之与五兵，其孰小乎？能杀生人，不能起死者也。帝曰∶愿卒闻之 \n。岐伯曰∶经隧者，五脏六腑之大络也，迎而夺之而已矣。帝曰∶上下有数乎？曰∶迎之五 \n里，中道而止，五至而已，五往而藏之气尽矣，故五五二十五而竭其输矣。此所谓夺其天气 \n者也。帝曰∶愿卒闻之。曰∶窥门而刺之者，死于家中；入门而刺之者，死于堂上。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《痈疽篇》《玉版篇》等义，俱详列外科。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《平人绝谷篇》帝曰∶愿闻人之不食，七日而死何也？伯高曰∶神者，水谷之精气也 \n。故肠胃之中，常留谷二斗，水一斗五升。故平人日再后，后二升半，一日中五升，七日五 \n七三斗五升，而留水谷尽矣。故平人不食饮七日而死者，水谷精气津液皆尽故也。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：《通评虚实论》帝曰∶乳子而病热，脉悬小者何如？岐伯曰∶手足温则生，寒则死。 \n帝曰∶乳子中风热，喘鸣肩息者，脉何如？岐伯曰∶喘鸣肩息者，脉实大也，缓则生，急则 \n死。 \n《论疾诊尺篇》曰∶婴儿病，其头毛皆逆上者，必死。 \n《热病篇》曰∶老人婴儿，热而腹满者死。 \n\n\n\n<目录>卷之三十七天集·杂证谟\\死生\n\n<篇名>经义\n\n属性：华元化曰∶不病而五行绝者死。不病而性变者死。不病而暴语妄者死。不病而暴不语者 \n死。不病而喘息者死。不病而强中者死。不病而暴目盲者死。不病而暴肿满者死。不病而大 \n便结者死。不病而暴无脉者死。不病而暴昏冒如醉者死。此内外先尽故也。逆者即死，顺者二年无有生者也。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\总论类\n\n<篇名>妇人九证（一）\n\n属性：妇人诸病，本与男子无异，而其有异者，则惟经水、胎产之属。故本门亦止列此九证， \n曰∶经脉类，胎孕类，产育类，产后类，带浊类，乳病类，子嗣类， 瘕类，前阴类。 \n凡此九者，乃其最切之病，不得不另详方论。此外杂证，但与男子相同者，自有各门论治之 \n法，故不以男女分而资赘于此。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\总论类\n\n<篇名>论难易（二）\n\n属性：谚云∶宁治十男子，莫治一妇人。此谓妇人之病不易治也。何也？不知妇人之病，本与 \n男子同，而妇人之情，则与男子异。盖以妇人幽居多郁，常无所伸，阴性偏拗，每不可解， \n加之慈恋爱憎，嫉妒忧恚，罔知义命，每多怨尤，或有怀不能畅遂，或有病不可告人，或信 \n师巫，或畏药饵，故染着坚牢，根深蒂固，而治之有不易耳，此其情之使然也。然尚有人事 \n之难，如寇宗 引黄帝之论曰∶凡治病察其形气色泽，形气相得，谓之可治；色泽以浮，谓 \n之易已；形气相失，色夭不泽，谓之难治。又曰∶诊病之道，观人勇怯、骨肉、皮肤，能知 \n其虚实，以为诊法。故曰∶治之要极，无失色脉，此治之大则也。今富贵之家，居奥室之中 \n，处帷幔之内，复有以绵帕蒙其手者，既不能行望色之神，又不能尽切脉之巧。使脉有弗合 \n，未免多问，问之觉繁，必谓医学不精，往往并药不信，不知问亦非易，其有善问者，正非 \n医之善者不能也。望闻问切，欲于四者去其三，吾恐神医不神矣。世之通患，若此最多，此 \n妇人之所以不易也。故凡医家病家，皆当以此为意。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>经脉之本（三）\n\n属性：《上古天真论》曰∶女子二七，天癸至，任脉通，太冲脉盛，月事以时下，故有子。盖 \n天癸者，言后天之阴气，阴气足而月事通，是即所为月经也。正以女体属阴，其气应月，月 \n以三旬而一盈，经以三旬而一至，月月如期，经常不变，故谓之月经，又谓之月信。夫经者 \n，常也。一有不调，则失其常度而诸病见矣。然经本阴血，何脏无之，惟脏腑之血皆归冲脉 \n，而冲为五脏六腑之血海，故经言太冲脉盛，则月事以时下，此可见冲脉为月经之本也。然 \n血气之化，由于水谷，水谷盛则血气亦盛，水谷衰则血气亦衰，而水谷之海，又在阳明。考 \n之《痿论》曰∶阳明者，五脏六腑之海，主润宗筋，宗筋主束骨而利机关也。冲脉者，经脉 \n之海也，主渗灌溪谷，与阳明合于宗筋。阴阳总宗筋之会，会于气街，而阳明为之长。是以 \n男精女血，皆由前阴而降，此可见冲脉之血，又总由阳明水谷之所化，而阳明胃气又为冲脉 \n之本也。故月经之本，所重在冲脉，所重在胃气，所重在心脾生化之源耳。其他如七情六淫 \n，饮食起居之失宜者，无非皆心脾胃气之贼。何者当顾，何者当去，学人于此，当知所从矣。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>经脉诸脏病因（四）\n\n属性：女人以血为主，血王则经调，而子嗣、身体之盛衰，无不肇端于此。故治妇人之病，当 \n以经血为先。而血之所主，在古方书皆言心主血，肝藏血，脾统血，故凡伤心、伤脾、伤肝 \n者，均能为经脉之病。又曰∶肾为阴中之阴，肾主闭藏；肝为阴中之阳，肝主疏泄。二藏俱 \n有相火，其系上属于心，故心火一动，则相火翕然从之，多致血不静而妄行，此固一说。然 \n相火动而妄行者有之，由火之盛也。若中气脱陷及门户不固而妄行者亦有之，此由脾肾之虚 \n，不得尽言为火也。再如气道逆而不行者有之，由肝之滞也。若精血败而不行者亦有之，此 \n由真阴之枯竭。其证极多，不得误以为滞也。是固心脾肝肾四脏之病，而独于肺脏多不言及 \n，不知血之行与不行，无不由气。如《经脉别论》曰∶饮入于胃，游溢精气，下输于脾；脾 \n气散精，上归于肺；通调水道，下输膀胱，水精四布，五经并行，合于四时五行阴阳，揆度 \n以为常也。此言由胃达脾，由脾达肺，而后传布诸经。故血脱者当益气，气滞者当调气，气 \n主于肺，其义可知。是皆诸经之当辨者如此。然其微甚本末，则犹有当辨者。盖其病之肇端 \n，则或由思虑，或由郁怒，或以积劳，或以六淫、饮食，多起于心肺肝脾四脏，及其甚也， \n则四脏相移，必归脾肾。盖阳分日亏，则饮食日减，而脾气胃气竭矣；阴分日亏，则精血日 \n涸，而冲任肾气竭矣。故予曰∶阳邪之至，害必归阴；五脏之伤，穷必及肾。此源流之必然 \n，即治疗之要着。故凡治经脉之病，或其未甚，则宜解初病，而先其所因；若其已剧，则必 \n计所归，而专当顾本。甚至脾肾大伤，泉源日涸，由色淡而短少，由短少而继绝，此其枯竭 \n已甚也。昧者无知，犹云积血，而通之破之，祸不旋踵矣。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>经不调（五）\n\n属性：经血为水谷之精气，和调于五脏，洒陈于六腑，乃能入于脉也。凡其源源而来，生化于 \n脾，总统于心，藏受于肝，宣布于肺，施泄于肾，以灌溉一身，在男子则化而为精，妇人则 \n上为乳汁，下归血海而为经脉。但使精气无损，情志调和，饮食得宜，则阳生阴长，而百脉 \n充实，又何不调之有？苟不知慎，则七情之伤为甚，而劳倦次之。又或为欲不谨，强弱相陵 \n，以致冲任不守者，亦复不少。此外则外感内伤，或医药误谬，但伤营气，无不有以致之。 \n凡人有衰弱多病，不耐寒暑，不胜劳役，虽先天禀弱者常有之，然有以气血方长，而纵情亏 \n损，或精血未满，而早为斫丧，致伤生化之源，则终身受害。此未病之先，所当深察而调之 \n者也。若欲调其既病，则惟虚实阴阳四者为要。丹溪曰∶先期而至者，血热也；后期而至者 \n，血虚也。王子亨曰∶阳太过则先期而至，阴不及则后时而来。其有乍多乍少，断绝不行， \n崩漏不止，皆由阴阳盛衰所致，是固不调之大略也。然先期而至，虽曰有火，若虚而挟火， \n则所重在虚，当以养营安血为主。矧亦有无火而先期者，则或补中气，或固命门，皆不宜过 \n用寒凉也。后期而至者，本属血虚，然亦有血热而燥瘀者，不得不为清补，有血逆而留滞者 \n，不得不为疏利。总之，调经之法，但欲得其和平，在详察其脉证耳。若形气脉气俱有余， \n方可用清用利。然虚者极多，实者极少，故调经之要，贵在补脾胃以资血之源，养肾气以安 \n血之室。知斯二者，则尽善矣。若营气本虚，而不知培养，则未有不日枯而竭者，不可不察 \n也。凡经行之际，大忌寒凉等药，饮食亦然。 \n初虞世曰∶经以月至，有常也。其来过与不及，皆谓之病。若荣血亏损，不能滋养百骸 \n，则发落面黄，羸瘦燥热。燥气盛则金受邪，金受邪则为咳为嗽，为肺痈，为肺痿必矣。但 \n助胃壮气，则荣血生而经自行。若果怒气逆，经闭不行，当用行气破血之剂。 \n《褚氏遗书·精血篇》曰∶男子精未通而御女以通其精，则五体有不满之处，异日有难 \n状之疾。阴已痿而思色以降其精，则精不出而内败，小便涩而为淋。精已耗而复竭之，则大 \n小便牵痛，愈痛则愈便，愈便则愈痛。女人天癸既至，逾十年无男子合则不调，未逾十年， \n思男子合亦不调。不调则旧血不出，新血误行，或渍而入骨，或变而为肿，后虽合而难子， \n合多则沥枯虚人，产众则血枯杀人。观其精血，思过半矣。 \n《产宝方序论》曰∶妇人以血为基本，苟能谨于调护，则血气宣行，其神自清，月水如 \n期，血凝成孕。若脾胃虚弱，不能饮食，营卫不足，月经不行，肌肤黄燥，面无光泽，寒热 \n腹痛，难于子息，或带下崩漏，血不流行，则成瘕证。 \n薛立斋曰∶经云∶二阳之病发心脾，有不得隐曲，为女子不月。故心脾平和，则百骸、 \n五脏皆润泽，而经候如常。苟或心脾受伤，则血无所养，亦无所统，而月经不调矣。是故调经 \n者，当理心脾为主。丹溪先生亦曰∶先期而至者，血热也；后期而至者，血虚也。窃谓先期 \n而至者，有因脾经血燥，有因脾经郁火，有因肝经怒火，有因血分有热，有因劳役动火。过 \n期而至者，有因脾经血虚，有因肝经血虚，有因气虚血弱。主治之法，脾经血燥者，加味逍 \n遥散；脾经郁滞者，归脾汤；肝经怒火者，加味小柴胡汤；血分有热者，加味四物汤；劳役 \n动火者，补中益气汤。其过期而至者，若脾经血虚，宜人参养营汤；肝经血少，宜六味地黄 \n丸；气虚血弱，宜八珍汤。盖血生于脾，故云脾统血。凡血病当用苦甘之剂，以助其阳气而 \n生阴血，俱属不足也。大凡肝脾血燥，四物汤为主；肝脾血弱，补中益气汤为主；肝脾郁结 \n，归脾汤为主；肝经怒火，加味逍遥散为主。 \n又曰∶胃者，卫之源；脾者，荣之本。荣出中焦，卫出上焦。卫不足，益之必以辛；荣 \n不足，补之必以甘，甘辛相合，脾胃健而荣卫生，是以气血俱旺也。或因劳心，虚火妄动， \n月经错行，宜安心补血泻火，此东垣先生治法也。 \n又曰∶人之少有老态，不耐寒暑，不胜劳役，四时迭病，皆因气血方长而劳心亏损，或 \n精血未满而早年斫丧。故其见证，难以名状。若左尺脉虚弱，或细数，是左肾之真阴不足也 \n，用六味丸；右尺脉迟软，或沉细而数欲绝，是命门之相火不足也，用八味丸；至于两尺微 \n弱，是阴阳俱虚，用十补丸。此皆滋其化源也，不可轻用黄柏、知母之类。设或六淫外侵而 \n见证，亦因其气内虚，而外邪溱集耳，尤宜用前药。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>经不调（五）\n\n属性：加味八珍汤（妇九四 补虚调经） 调味养营汤（妇九五 退热调经） 《金匮》胶艾汤（ \n妇九三 劳伤经血不止） 《良方》当归散（妇九六 妄行不止） 四物二连汤（妇百十三 血 \n虚内热） 补肝散（妇九二 虚弱不调） 益阴肾气丸（补一二三 血虚不调） 丹参散（妇九七 \n调经止血） 琥珀散（妇百二 逐瘀通经） 白芷散（妇一二六 固经） 《良方》黄龙汤（妇 \n八五 经后外感） 《良方》人参汤（妇七七 补虚调经） 十全大补汤（补二十 温补气血） \n六物煎（新因二十 虚补最妙） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>血热经早（六）\n\n属性：凡血热者，多有先期而至，然必察其阴气之虚实。若形色多赤，或紫而浓，或去多，其 \n脉洪滑，其脏气、饮食喜冷畏热，皆火之类也。 \n治血热有火者，宜清化饮主之。若火之甚者，如抽薪饮之类亦可暂用，但不可以假火作 \n真火，以虚火作实火也。大都热则善流而愆期不止者，如续断、地榆、丹参、茜根、栀子之 \n属皆可用。若微火阴虚而经多早者，治宜滋阴清火，用保阴煎之类主之。所谓经早者，当以 \n每月大概论。所谓血热者，当以通身脏象论。勿以素多不调，而偶见先期者为早；勿以脉证 \n无火，而单以经早者为热。若脉证无火，而经早不及期者，乃其心脾气虚，不能固摄而然， \n宜大营煎、大补丸煎，或五福饮加杜仲、五味子之类主之。此辈极多，若作火治，必误之矣 \n。若一月二三至，或半月、或旬日而至者，此血气败乱之证，当因其寒热而调治之，不得以 \n经早者并论。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>血热经早（六）\n\n属性：《良方》续继汤（妇二二） 四物二连汤（妇百十三） 二黄散（妇二十） 一母丸（妇三七） \n《良方》当归散（妇九六） 延年益嗣丹（妇一三五） 《奇效》四物汤（妇百十一） 子芩散（妇一二二） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>血热经迟（七）\n\n属性：血热者经期常早，此营血流利及未甚亏者多有之。其有阴火内烁，血本热而亦每过期者 \n，此水亏血少，燥涩而然治宜清火滋阴，以加味四物汤、加减一阴煎、滋阴八味丸之类主之。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>血寒经迟（八）\n\n属性：凡血寒者，经必后期而至。然血何以寒？亦惟阳气不足，则寒从中生，而生化失期，是 \n即所谓寒也。至若阴寒由外而入，生冷由内而伤，或至血逆，或为疼痛，是又寒滞之证，非 \n血寒经迟之谓也，当详辨之。 \n凡阳气不足，血寒经迟者，色多不鲜，或色见沉黑，或涩滞而少，其脉或微、或细，或 \n沉迟弦涩，其脏气形气必恶寒喜暖。凡此者，皆无火之证，治宜温养血气，以大营煎、理阴 \n煎之类加减主之。大约寒则多滞，宜加姜、桂、吴茱萸、荜茇之类，甚者须加附子。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>血寒经迟（八）\n\n属性：五物煎（新因三） 乌鸡煎丸（妇一四二） 增损四物汤（妇百十） 四神散（妇七五） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>血虚经乱（九）\n\n属性：凡女人血虚者，或迟或早，经多不调，此当察脏气，审阴阳，详参形证脉色，辨而治之 \n，庶无误也。盖血虚之候，或色淡，或涩少，或过期不至，或行后反痛，痛则喜暖喜按，或 \n经后则困惫难支，腰膝如折，或脉息则微弱弦涩，或饮食素少，或形色薄弱。凡经有不调， \n而值此不足之证，皆不可妄行克削及寒凉等剂，再伤脾肾以伐生气，则惟有日甚矣。凡肝脾 \n血虚，微滞微痛者，宜四物汤主之，或加肉桂，或加黄芩，随寒热而用之，自无不可。三阴 \n亏弱，无热无寒，平脏者，宜小营煎、五福饮、六物煎之类主之，此常人最宜之剂。或八珍 \n汤、十全大补汤之类，皆宜择用。三阴亏弱兼阳虚者，宜大营煎、理阴煎之类主之。忧思过 \n度，心脾受伤者，七福饮、归脾汤之类主之。脾土不健，饮食减少，宜燥宜温者，温胃饮、 \n理中汤之类主之。脾土虚陷，不能统摄营气，而为漏为频者，宜五福饮、归脾汤、寿脾煎、 \n秘元煎，或四君子加芎归主之。肝虚不能藏血，或多惊惕，或多小腹急痛，宜三阴煎、补肝 \n散之类主之。若阴血虚，水不制火，而邪火盛者，或为夜热盗汗，或为烦渴生痰，是即劳损 \n之渐，速宜调治，用一、二、三、四、五阴等煎，择宜治之，否则恐成血枯也。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>肾虚经乱（十）\n\n属性：妇人因情欲房室，以致经脉不调者，其病皆在肾经，此证最多，所当辨而治之。 \n凡欲念不遂，沉思积郁，心脾气结，致伤冲任之源，而肾气日消，轻则或早或迟，重则 \n渐成枯闭，此宜兼治心脾肾，以逍遥饮、秘元煎之类主之。若或欲火炽盛，以致真阴日溃者 \n，宜保阴煎、滋阴八味丸之类主之。若房室纵肆不慎者，必伤冲任之流，而肾气不守，治须 \n扃固命门，宜固阴煎、秘元煎之类主之。若左肾真阴不足，而经脉不调者，宜左归饮、左归 \n丸、六味地黄丸之类主之。若右肾真阳不足，而经有不调者，宜右归饮、右归丸、八味地黄 \n丸之类主之。若思郁不解致病者，非得情舒愿遂，多难取效；房室不慎致病者，使非勇于节 \n欲，亦难全恃药饵也。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>经期腹痛（十一）\n\n属性：经行腹痛，证有虚实。实者，或因寒滞，或因血滞，或因气滞，或因热滞；虚者，有因 \n血虚，有因气虚。然实痛者，多痛于未行之前，经通而痛自减；虚痛者，于既行之后，血去 \n而痛未止，或血去而痛益甚。大都可按可揉者为虚，拒按拒揉者为实。有滞无滞，于此可察 \n。但实中有虚，虚中亦有实，此当于形气禀质，兼而辨之，当以意察，言不能悉也。 \n凡妇人经期有气逆作痛，全滞而不虚者，须顺其气，宜调经饮主之，甚者如排气饮之类 \n亦可用。若血瘀不行，全滞无虚者，但破其血，宜通瘀煎主之。若气血俱滞者，宜失笑散主 \n之。若寒滞于经，或因外寒所逆，或素日不慎寒凉，以致凝结不行，则留聚为痛而无虚者， \n须去其寒，宜调经饮加姜、桂、吴茱萸之类主之，或和胃饮亦可酌用。若血热血燥，以致滞 \n涩不行而作痛者，宜加味四物汤，或用保阴煎去续断加减主之。以上五证，但察其有滞无虚 \n，方是真实；若或兼虚，弗得任行克伐。 \n凡妇人经行作痛，挟虚者多，全实者少，即如以可按拒按及经前经后辨虚实，固其大法 \n也。然有气血本虚，而血未得行者，亦每拒按，故于经前亦常有此证，此以气虚血滞，无力 \n流通而然。但察其形证脉息，凡涉虚弱不足，而经滞作痛者，惟用决津煎、五物煎加减主之 \n，其效如神，或用四神散之类亦可。若痛在经后者，多由血虚，当用大小营煎，随宜加减治 \n之，或四物、八珍俱可用，然必察其寒热虚实以为佐使，自无不效。其有余滞未行者，惟决 \n津煎为妙。凡妇人但遇经期则必作痛，或食则呕吐，肢体困倦，或兼寒热者，是必素禀气血 \n不足，止宜八珍汤、大营煎之类。若虚而寒甚者，宜理阴煎，渐加培补，久必自愈。有因带 \n浊多而虚痛者，亦宜大、小营煎，随其寒热，加佐使主之。 \n立斋曰∶前证若风寒伤脾者，六君加炮姜；思虑伤血者，四物加参术；思虑伤气者，归 \n脾加柴栀；郁怒伤血者，归脾、逍遥兼服。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>经期腹痛（十一）\n\n属性：温经汤（妇百三 寒痛） 交加散（妇百 结聚作痛） 醋附丸（妇百七 行滞止痛） 牛膝 \n散（妇九九 通经止痛） 姜黄散（妇百一 逐瘀止痛） 当归没药丸（妇百六 血瘀作痛） 玄 \n胡当归散（妇九八 血逆作痛） 琥珀丸（妇一三四） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>崩淋经漏不止（十二）\n\n属性：崩漏不止，经乱之甚者也。盖乱则或前或后，漏则不时妄行，由漏而淋，由淋而崩，总 \n因血病，而但以其微甚耳。《阴阳别论》曰∶阴虚阳搏谓之崩。《百病始生篇》曰∶阳络伤 \n则血外溢，阴络伤则血内溢。故凡阳搏必属阴虚，络伤必致血溢。知斯二者，而崩淋之义及 \n治疗之法，思过半矣。惟是阴虚之说，则但伤营气，无匪阴虚而五脏之阴皆能受病，故神伤 \n则血无所主，病在心也；气伤则血无所从，病在肺也；意伤则不能统血摄血，病在脾也；魂 \n伤则不能蓄血藏血，病在肝也；志伤则不能固闭真阴，病在肾也。所以五脏皆有阴虚，五脏 \n皆有阳搏。故病阴虚者，单以脏气受伤，血因之而失守也；病阳搏者，兼以火居阴分，血得 \n热而妄行也。凡治此之法，宜审脏气，宜察阴阳。无火者，求其脏而培之补之；有火者，察 \n其经而清之养之。此不易之良法也。然有火者不得不清，但元气既虚，极多假热，设或不明 \n真假，而误用寒凉，必复伤脾胃，生气日见殆矣。先贤有云∶凡下血证，须用四君子辈以收 \n功。又云∶若大吐血后，毋以脉诊，当急用独参汤救之。厥旨深矣。故凡见血脱等证，必当 \n用甘药先补脾胃，以益发生之气。盖甘能生血，甘能养营，但使脾胃气强，则阳生阴长，而 \n血自归经矣，故曰脾统血治崩淋经漏之法∶若阴虚血热妄行者，宜保阴煎、加减一阴煎； \n若火盛迫血妄行而无虚证者，宜徙薪饮、黄芩散加续断、丹参；若血热兼滑者，宜保阴煎、 \n槐榆散、生地黄汤；若肝经怒火动血者，加味四物汤；若肝经怒火动血，逆气未散者，化肝 \n煎，或保阴煎加减主之；若血有滞，逆而妄行者，四物汤、丹参散；若营气不足，血不能调 \n而妄行者，五福饮、四物汤、四君子汤、八珍汤，择宜用之；若脾气虚陷，不能收摄而脱血 \n者，寿脾煎、归脾汤、四君子加芎、归，再甚者，举元煎；若脾肾虚寒，兼呕兼溏泄而畏寒 \n者，理阴煎、五君子煎、理中汤。若阳气大虚脱陷者，四维散；若脾肾阴气不固者，固阴煎 \n、五阴煎、秘元煎；若肝胆气虚，不能藏血者，必多惊恐畏怯，宜五福饮、七福饮、八珍汤 \n；兼阳虚者，仍加姜、桂；若去血过多，血脱气竭者，当速用独参汤提握其气，以防脱绝， \n或用当归补血汤；若崩淋既久，血滑不禁，宜涩宜固者，龙骨散、如圣散、七灰散之类，同 \n人参兼用之。凡血淋治法，大约如前。但其秽臭脉滑者多火，宜从清凉；若腥臭清寒脉细者 \n多寒，必须温补。其或久病则精去无穷，尾闾易竭，非大加培补不可，惟固阴煎，及十全大 \n补汤之类为宜。 \n一、崩淋之病，有暴崩者，有久崩者。暴崩者，其来骤，其治亦易；久崩者，其患深， \n其治亦难。且凡血因崩去，热必渐少，少而不止，病则为淋。此等证候，未有不由忧思郁怒 \n，先损脾胃，次及冲任而然者。崩淋既久，真阴日亏，多致寒热咳嗽，脉见弦数或豁大等证 \n。此乃元气亏损、阴虚假热之脉，尤当用参、地、归、术甘温之属，以峻培本源，庶可望生 \n。但得胃气未败，受补可救；若不能受补，而日事清凉，以苟延目前，则终非吉兆也。 \n一、崩淋病，治有五脏之分，然有可分者，有不可分者。可分者，如心肺居于膈上，二 \n阳脏也；肝脾肾居于膈下，三阴脏也治阳者宜治其气，治阴者宜治其精，此可分之谓也。 \n然五脏相移，精气相错，此又其不可分者也。即如病本于心，君火受伤，必移困于脾土，故 \n治脾即所以治心也。病本于肺，治节失职，必残及于肾水，故治肾即所以治肺也。脾为中州 \n之官，水谷所司，饷道不资，必五路俱病，不究其母，则必非治脾良策。肝为将军之官，郁 \n怒是病，胜则伐脾，败则自困，不知强弱，则攻补不无倒施。不独此也，且五脏五气，无不 \n相涉，故五脏中皆有神气，皆有肺气，皆有胃气，皆有肝气，皆有肾气，而其中之或此或彼 \n，为利为害，各有互相倚伏之妙。故必悟藏气之大本，其强弱何在？死生之大权，其缓急何 \n在精气之大要，其消长何在？攻补之大法，其先后何在？斯足称慧然之明哲。若谓心以枣仁、 \n远志，肺以桔梗、麦冬，脾以白术、甘草，肝以青皮、芍药，肾以独活、玄参之类，是不过 \n肤毛之见，又安知性命之道也。诸证皆然，不止崩淋者若此。 \n一、妇人于四旬外，经期将断之年，多有渐见阻隔，经期不至者。当此之际，最宜防察 \n。若果气血和平，素无他疾，此固渐止而然，无足虑也。若素多忧郁不调之患，而见此过期 \n阻隔，便有崩决之兆。若隔之浅者，其崩尚轻；隔之久者，其崩必甚。此因隔而崩者也。当 \n预服四物、八珍之类以调之，否则恐其郁久而决，则为患滋大也。若其既崩之后，则当辨其 \n有火无火。有火者，因火逼血，宜保阴煎主之。无火者，因隔而决，或其有滞，当去其故而 \n养其新，宜调经饮先以理之，然后各因其宜，可养则养，用小营煎；可固则固，用固阴煎之 \n类主之。 \n王叔和曰∶五崩何等？曰∶白崩者，形如涕；赤崩者，形如绛津；黄崩者，形如烂瓜； \n青崩者，形如蓝色；黑崩者，形如 血也。 \n立斋曰∶前证治法固脾胃亏损不能摄血归源者，用六君加芎、归、柴胡。若因肝经之火 \n而血下行，用奇效四物汤，或四物加柴、栀、苓、术。若肝经风热而血妄行，用加味逍遥散 \n，或小柴胡加栀、芍、丹皮。若怒动肝火而血沸腾，亦用前药。若脾经郁结而血不归经，用 \n归脾加柴、栀、丹皮。若悲伤胞络而血下崩，用四君加柴、栀、升麻。 \n附按∶大尹王天成之内久患崩，自服四物凉血之剂，或作或彻。因怒发热，其血不止， \n服前药不应，乃主降火，更加胁腹大痛，手足俱冷。余曰∶此脾胃虚寒所致。先用附子理中 \n汤，热退痛止；又用《济生》归脾汤、补中益气汤，崩血顿愈。若泥痛无补法，则误矣。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>崩淋经漏不止（十二）\n\n属性：一方∶治风热血崩，用荆芥穗灯火烧焦为末，每服一二钱，童便调服。 \n一方∶治血崩，用陈槐花一两，百草霜半两，为末，每服一二钱，烧红秤锤淬酒服。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>崩淋经漏不止（十二）\n\n属性：增损四物汤（妇百十 虚不固摄） 一味防风散（妇百十五 肝经风热血崩） 防风黄芩汤 \n（妇一二三 风热血崩） 柏叶散（妇一二一 虚弱久崩） 棕灰散（和二一五 固涩崩漏） 龙 \n脑鸡苏丸（和三七二 虚火崩淋下血） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>杀血心痛（十三）\n\n属性：陈临川《良方》云∶妇人血崩而心痛甚，名曰杀血心痛，由心脾血虚也。若小产去血过 \n多，而心痛甚者亦然，用乌贼鱼骨炒为末，醋汤调下；失血散亦效。 \n立斋曰∶前证若阴血耗散，用乌贼丸收敛之；若瘀血不散，用失笑散行散之；若心血虚 \n弱，用芎归汤补养之；若郁结伤血，用归脾汤调补之。 \n附按∶一妇人血崩兼心痛三年矣，诸药不应，每痛甚，虚证悉具，面色痿黄。余曰∶心 \n主血，盖由去血过多，心无所养，以致作痛，宜用十全大补汤，参术倍之。三十余剂稍愈， \n百余剂全愈。 \n愚谓杀血心痛，既由血去过多而心痛甚，明属心无所养，但当专用甘温以养营气，如十 \n全大补汤、大营煎、小营煎、五福饮之类为宜。若失笑散者，惟气滞血逆而用以行之、散之 \n则可，必不可以治血虚也。再如乌贼丸，乃《内经·腹中论》用治血枯者，亦恐于血虚心痛 \n未必即效，用者审之。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>热入血室（十四）\n\n属性：妇人伤寒，或劳役，或怒气，发热适遇经行，以致热入血室，或血不止，或血不行，令 \n人昼则明了安静，夜则谵语如见鬼状者是也。若热因外邪，由表而入者，宜一柴胡饮，或三 \n柴胡饮，或四柴胡饮，或《良方》黄龙汤加生地，酌而用之。若或怒或劳，火由内生，其人 \n多汗而无表证者，宜保阴煎、清化饮、当归六黄汤之类加减主之。若病虽渐愈，但元气素弱 \n，而热有未退，血未止者，宜补阴益气煎，或补中益气汤。若脾气素弱，宜归脾汤；血气俱 \n弱者，宜十全大补汤，庶无误矣。若血热多滞者，宜小柴胡汤加丹皮、红花、当归。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>辨血色（十五）\n\n属性：凡血色有辨，固可以察虚实，亦可以察寒热。若血浓而多者，血之盛也；色淡而少者， \n血之衰也。此固大概之易知者也。至于紫黑之辨，其证有如冰炭，而人多不解，误亦甚矣。 \n盖紫与黑相近，今人但见紫色之血，不分虚实，便谓内热之甚。不知紫赤鲜红，浓而成片成 \n条者，是皆新血妄行，多由内热；紫而兼黑，或散或薄，沉黑色败者，多以真气内损，必属 \n虚寒。由此而甚，则或如屋漏水，或如腐败之宿血，是皆紫黑之变象也。此肝脾大损，阳气 \n大陷之证，当速用甘温，如理阴煎、理中汤、归脾汤、四味回阳饮、补中益气汤之类，单救 \n脾土，则陷者举，脱者固，元气渐复，病无不愈。若尽以紫色作热证，则无不随药而毙矣。 \n凡肠 、便血之属，无不皆然，学人于此，最有不可忽者。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>血枯经闭（十六）\n\n属性：《评热病论》曰∶月事不来者，胞脉闭也。胞脉者，属心而络于胞中，今气上迫肺，心 \n气不得下通，故月事不来也。 \n《阴阳别论》曰∶二阳之病发心脾，有不得隐曲，女子不月。其传为风消，其传为息贲 \n者，死不治。 \n《邪气脏腑病形篇》曰∶肾脉微涩，为不月。 \n血枯之与血隔，本自不同。盖隔者，阻隔也；枯者，枯竭也。阻隔者，因邪气之隔滞， \n血有所逆也；枯竭者，因冲任之亏败，源断其流也。凡妇女病损，至旬月半载之后，则未有 \n不闭经者。正因阴竭，所以血枯，枯之为义，无血而然。故或以羸弱，或以困倦，或以咳嗽 \n，或以夜热，或以食饮减少，或以亡血失血，及一切无胀无痛，无阻无隔，而经有久不至者 \n，即无非血枯经闭之候。欲其不枯，无如养营；欲以通之，无如充之。但使雪消则春水自来 \n，血盈则经脉自至，源泉混混，又孰有能阻之者？奈何今之为治者，不论有滞无滞，多兼开 \n导之药，其有甚者，则专以桃仁、红花之类，通利为事，岂知血滞者可通，血枯者不可通也 \n。血既枯矣，而复通之，则枯者愈枯，其与榨干汁者何异？为不知枯字之义耳，为害不小， \n无或蹈此弊也。此之治法，当与前血虚肾虚二条，参而用之。 \n寇宗 曰∶夫人之生，以血气为本。人之病，未有不先伤其血气者。若室女童男，积想 \n在心，思虑过度，多致劳损，男子则神色消散，女子则月水先闭。盖忧愁思虑则伤心，而血 \n逆气竭，神色先散，月水先闭。且心病则不能养脾，故不嗜食；脾虚则金亏，故发嗽；肾水 \n绝则木气不荣，而四肢干痿，故多怒，鬓发焦，筋骨痿。若五脏传遍，则必至于死。此一种 \n，于劳中最难治。盖病起于五脏之中，无有已期，药力不可及也。若或自能改易心志，然后 \n用药扶接，如此则可得九死一生。举此为例，其余诸方，可按脉与证而治之。 \n张氏云∶室女月水久不行，切不可用青蒿等凉药。医家多以为室女血热，故以凉药解之 \n，殊不知血得热则行，冷则凝，《养生必用方》言之甚详，此说大有理，不可不知。若经候 \n微少，渐渐不通，手足骨肉烦疼，日渐羸瘦，渐生潮热，其脉微数，此由阴虚血弱，阳往乘 \n之，少水不能减盛火，火逼水涸，耗亡津液治当养血益阴，慎毋以毒药通之，宜用柏子仁 \n丸、泽兰汤。 \n立斋曰∶夫经水，阴血也，属冲任二脉，主上为乳汁，下为月水。其为患，有因脾胃虚 \n，不能生血而不行者，调而补之；有因脾郁伤血，耗损而不行者，解而补之；有因胃火，血 \n消烁而不行者，清而补之；有因劳伤心，血少而不行者，静而补之；有因怒伤肝，血少而不 \n行者，和而补之；有因肾水亏，不能生肝血而闭者，补脾肺；有因肺气虚，不能行血而闭者 \n，补脾胃。经曰∶损其肺者益其气，损其心者调其荣卫，损其脾者调其饮食，适其寒温，损 \n其肝者缓其中，损其肾者益其精。审而治之，庶无误矣。五谷入胃，化以为血，以荣四末， \n内养五脏六腑。若服苦寒之剂，复伤胃气，必致不起。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>血枯经闭（十六）\n\n属性：通经散（攻四五） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\经脉类\n\n<篇名>经脉类论列总方（十七）\n\n属性：四君子汤（补一） 五君子煎（新热六） 六君子汤（补五） 四物汤（补八） 八珍汤（补 \n十九） 十全大补汤（补二十） 归脾汤（补三二） 小营煎（新补十五） 加味四物汤（补九） \n寿脾煎（新热十六） 大营煎（新补十四） 补中益气汤（补三十） 理阴煎（新热三） 理中汤 \n（热一） 附子理中汤（热二） 保阴煎（新寒一） 五福饮（新补六） 补阴益气煎（新补十六） \n五物煎（新因三） 七福饮（新补七） 人参养营汤（补二一） 六物煎（新因二十） 五阴等 \n煎（新补八起至三十止） 加减一阴煎（新补九） 举元煎（新补十七） 秘元煎（新固一） 四味 \n回阳饮（新热一） 固阴煎（新固二） 逍遥散（补九二） 加味逍遥散（补九三） 左归饮（新补 \n二） 右归饮（新补三） 当归补血汤（补四四） 左归丸（新补四） 右归丸（新补五） 当归六 \n黄汤（寒六五） 六味丸（补百二十） 八味丸（补一二一） 滋阴八味丸（新寒十七） 独参汤（ \n补三五） 十补丸（热一七三） 奇效四物汤（妇百十一） 温胃饮（新热五） 和胃饮（新和五） \n《良方》黄龙汤（妇八五） 一柴胡饮（新散一） 三柴胡饮（新散三） 加味小柴胡汤（散二 \n十） 四柴胡饮（新散四） 小柴胡汤（散十九） 生地黄汤（固五七） 补肝散（妇九二） 化肝 \n煎（新寒十） 调经饮（新因四） 决津煎（新因二） 通瘀煎（新因五） 丹参散（妇九七） 芎归 \n汤（妇四一） 如圣散（妇百十七） 失笑散（妇百四） 四维散（新热十二） 四神散（妇七五） \n排气饮（新和六） 抽薪饮（新寒三） 徙薪饮（新寒四） 清化饮（新因十三） 黄芩散（妇一二 \n二） 槐榆散（妇百十八） 龙骨散（妇百十六） 七灰散（妇百十九附绵花子方） 乌贼丸（妇百 \n九） 柏子仁丸（妇百八） 泽兰汤（妇百五） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>胎脉（十八）\n\n属性：《平人气象论》曰∶妇人手少阴脉动甚者，任子也。《阴阳别论》曰∶阴搏阳别，谓之 \n有子。《腹中论》曰∶何以知怀子之且生也？曰∶身有病而无邪脉也。《脉经》曰∶尺中之 \n脉，按之不绝，法妊娠也。滑伯仁曰∶三部脉浮沉正等，无他病而不月者，妊也。 \n凡妇人怀孕者，其血留气聚，胞宫内实，故脉必滑数倍常，此当然也。然有中年受胎， \n及血气羸弱之妇，则脉见细小不数者亦有之，但于微弱之中，亦必有隐隐滑动之象，此正阴 \n搏阳别之谓，是即妊娠之脉，有可辨也。又胎孕之脉数，劳损之脉亦数，大有相似。然损脉 \n之数，多兼弦涩，胎孕之数，必兼和滑。此当于几微中，辨其邪气胃气之异，而再审以证， \n自有显然可见者。 \n凡辨男女之法，自古及今，无不以阴阳二字为纲领。然言多矛盾，悉属疑似。兹余以坎 \n离之象定之，庶得其要。盖坎为天一之卦，坎中满，阳在内也；离为地二之卦，离中虚，阴 \n在内也。得坎象者为男，得离象者为女。所以男脉多沉实，沉实者，中满之象；女脉多浮虚 \n，浮虚者，中虚之象。无论人之老少强弱，脉之部位大小，但因象察象，无不如响之应，然 \n尤于两尺为最也，足称捷法。 \n《脉诀》云∶欲产之妇脉离经，沉细而滑也同名，夜半觉痛应分诞，来日日午定知生。 \n《质疑》谓离经之脉，即歇至者是也。在须臾却非病。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>胎候（十九）\n\n属性：巫方氏《颅囟经》云∶一月为胞胎，精血凝也；二月为胎，形始成胚也；三月阳神为三 \n魂；四月阴灵为七魄；五月五形分五脏也；六月六律定六腑也；七月睛开窍，通光明也；八 \n月元神具，降真灵也；九月宫室罗布，以定生人也；十月受气足，万象成也。 \n《五脏论》有耆婆论曰∶一月如珠露，二月如桃花，三月男女分，四月形象具，五月筋 \n骨成，六月毛发生，七月游其魂，男能动左手，八月游其魄，儿能动右手，九月三转身，十 \n月受气足。 \n孙真人曰∶凡儿在胎，一月胚，二月胎，三月有血脉，四月形体成，五月能动，六月诸 \n骨具，七月毛发生，八月脏腑具，九月谷入胃，十月百神备则生矣。生后六十日，瞳子成， \n能咳笑应和人；百五十日，任脉成，能自反复；百八十日，髋骨成，能独坐；二百一十日， \n掌骨成，能扶伏；三百日，髌骨成，能行也。若不能根据期者，必有不平之处。 \n《巢氏病源论》曰∶妊娠一月名胎胚，足厥阴脉养之；二月名始膏，足少阳脉养之；三 \n月名始胎，手心主脉养之。当此之时，血不流行，形象始化，未有定仪，因感而变。欲子端 \n正庄严，常口谈正言，身行正事；欲子美好，宜佩白玉；欲子贤能，宜看诗书，是谓外象而 \n内感者也。四月始成其血脉，手少阳脉养之；五月始成其气，足太阴脉养之；六月始成其筋 \n，足阳明脉养之；七月始成其骨，手太阴脉养之；八月始成肤革，手阳明脉养之；九月始成 \n毛发，足少阴脉养之；十月五脏、六腑、关节、人神皆备，此其大略也。 \n陈临川曰∶尝试推巢氏所论云妊娠脉养之理，若足厥阴，肝脉也；足少阳，胆脉也。为 \n一脏一腑，表里之经，余皆如此。且四时之令，必始于春木，故十二经之养，始于肝胆，所 \n以养胎在一月二月。手心主，心胞络脉也；手少阳，三焦脉也，属火而夏旺，所以养胎在三 \n月四月。手少阴、手太阳，乃心脉也，以君主之官，无为而尊也。足太阴，脾脉也；足阳明 \n，胃脉也。属土而旺长夏，所以养胎在五月六月。手太阴，肺脉也；手阳明，大肠脉也。属 \n金而旺秋，所以养胎在七月八月。足少阴，肾脉也。属水而旺冬，所以养胎在九月。又况母 \n之肾脏系于胎，是母之真气，子之所赖也。至十月，儿于母腹之中，受足诸脏气脉所养，然 \n后待时而生。此论诚有至理，世更有明之者，亦未有过于巢氏之论矣。余因述其说。 \n一、胎有男女之辨。《易》曰∶干道成男，坤道成女。《颅囟经》曰∶三阳所会则生男 \n，三阴所会则生女。葛仙翁曰∶男从父气，女从母气。《圣济经》曰∶天之德，地之气，阴 \n阳之至和，流薄于一体，因气而左动则属阳，阳资之则成男；因气而右动则属阴，阴资之则 \n成女。是以胎有男女，则成有迟速；体有阴阳，则怀有向背。故男动在三月，阳性早也；女 \n动在五月，阴性迟也。女胎背母而怀，故母子腹软；男胎面母而怀，故母之腹硬。此皆 \n得理之谈，所当察也。至若褚氏以精血之先后言男女，《道藏经》以一日、三日、五日得者 \n为男等说，总属亿度渺茫，非有确见也。余不敢遵信，故别有微论，列子嗣类。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>安胎（二十）\n\n属性：凡妊娠胎气不安者，证本非一，治亦不同。盖胎气不安，必有所因，或虚或实，或寒或 \n热，皆能为胎气之病，去其所病，便是安胎之法。故安胎之方不可执，亦不可泥其月数，但 \n当随证随经，因其病而药之，乃为至善。若谓白术、黄芩乃安胎之圣药，执而用之，鲜不误 \n矣。 \n一、胎气有寒而不安者，其证或吞酸吐酸，或呕恶胀满，或喜热畏凉，或下寒泄泻，或 \n脉多沉细，或绝无火证，而胎有不安者，皆属阳虚寒证，但温其中而胎自安矣。宜用温胃饮 \n、理阴煎之类加减主之。亦当以平素之脏气，察其何如，酌而用之。 \n一、胎气有热而不安者，其证必多烦热，或渴或躁，或上下不清，或漏血、溺赤，或六 \n脉滑数等证。宜凉胎饮、保阴煎之类主之。若但热无虚者，如枳壳汤、一母丸、黄芩散之类 \n，皆可择用，清其火而胎自安矣。 \n一、胎气有虚而不安者，最费调停。然有先天虚者，有后天虚者，胎元攸系，尽在于此 \n。先天虚者，由于禀赋，当随其阴阳之偏，渐加培补，万毋欲速，以期保全。后天虚者，由 \n于人事，凡色欲劳倦，饮食七情之类，皆能伤及胎气，治此者，当察其所致之由，因病而调 \n，仍加戒慎可也。然总之不离于血气之虚，皆当以胎元饮为主。若心脾气虚于上者，宜逍遥 \n饮、归脾汤、寿脾煎之类主之。若肝肾不足于下者，宜左归饮、右归饮、固阴煎主之。若气 \n血俱虚者，宜五福饮、八珍汤、十全大补汤之类主之。若脾肾气虚而兼带浊者，宜秘元煎、 \n菟丝煎之类主之。若多呕恶者，当随前证前方，各加二陈汤之类以和之。凡治虚证，贵在随 \n机应变，诚有不可以凿执言者。 \n一、胎气有实滞气滞，凡为恶阻，为胀满而不安者，惟其素本不虚，而或多郁滞者乃有 \n之，但察其所由而开之导之，诸治实者固无难也。呕吐不止者，二陈汤加枳壳、砂仁主之， \n或用人参橘皮汤亦妙。食滞胀满不安者，小和中饮加减主之。肝气滞逆，胀满不安者，解肝 \n煎主之。怒动肝气兼火者，化肝煎主之。脾肺气滞，上攻作痛者，紫苏饮主之。气滞兼痰者 \n，四七汤、二陈汤加当归主之。气滞兼火，为胀为烦者，枳壳汤、束胎丸之类主之。 \n一、王节斋曰∶调理妊妇，在于清热养血，白术补脾为安胎君药，条实黄芩为安胎圣药 \n，清热故也，暑月宜加用之。此一说者，虽若有理，而实有大病，不可不辨也。夫孕之胎气 \n，必随母之脏气，大都阴虚者多热气，阳虚者多寒气，寒之则寒，热之则热者，是为平气。 \n今以十人言之，则寒者居其三，热者居其三，平者居其四，此大较也。若谓受胎之后，必增 \n内热，自与常人不同，则何以治恶阻者，必用二陈、六君、生姜、半夏之属而后效，其果增 \n热否乎？故治热宜黄芩，寒则不宜也。非惟寒者不宜，即平气者亦不宜。盖凡今之胎妇，气 \n实者少，气虚者多。气虚则阳虚，而再用黄芩，有即受其损而病者，有用时虽或未觉，而阴 \n损胎元，暗残母气，以致产妇羸困，或儿多脾病者，多由乎此。奈今人不能察理，但以圣药 \n二字，认为胎家必用之药，无论人之阴阳强弱，凡属安胎，无不用之，其害盖不少矣。至若 \n白术，虽善安胎，然或用不得善，则其性燥而气闭，故凡阴虚者非可独用，气滞者亦当权宜 \n。是以用药之难，当如盘珠，有不可胶柱而鼓瑟也。 \n立斋曰∶妊娠若元气不实，发热倦怠，或胎气不安，用当归散。因气恼，加枳壳；胸膈 \n痞闷，再加苏梗；或作痛，加柴胡。若饮食不甘，或欲呕吐，用六君加紫苏、枳壳。若恶阻 \n呕逆，头眩体倦，用参橘散；未应，用六君子汤。若恶阻呕吐，不食烦闷，亦用参橘散之类 \n。若顿仆胎动，腹痛下血，用胶艾汤；未应，用八珍加胶、艾。若顿仆、毒药，腰痛短气， \n用阿胶散；未应，煎送知母丸。若顿仆胎伤，下血腹痛，用佛手散；未应，用八珍送知母丸 \n。若心惊胆怯，烦闷不安，名子烦，用竹叶汤。未应，血虚佐以四物，气虚佐以四君。若下 \n血不止，名胎漏，血虚用二黄散，血去多用八珍汤。未应，用补中益气汤。若因事而动，下 \n血，用枳壳汤加生、熟地黄；未应，或作痛，更加当归。血不止，八珍加胶艾。若不时作痛 \n，或小腹重坠，名胎痛，用地黄当归汤；未应，加参、术、陈皮。或因脾气虚，用四君加归 \n、地；中气虚，用补中益气汤。若面目虚浮，肢体如水气，名子肿，用《全生》白术散；未 \n应，用六君子汤。下部肿甚，用补中益气倍加茯苓。或因饮食失宜，呕吐泄泻，此是脾胃亏 \n损，用六君子汤。若足指发肿，渐至腿膝，喘闷不安，或足指缝出水，名水气，用天仙藤散 \n；脾胃虚弱，兼以四君子；未应，用补中益气，兼以逍遥散。若胎气上攻，心腹胀满作痛， \n名子悬，用紫苏饮。饮食不甘，兼四君子；内热晡热，兼逍遥散。若小便涩少，或成淋沥， \n名子淋，用安营散；不应，兼八珍汤。腿足转筋，而小便不利，急用八味丸，缓则不救。若 \n项强筋挛，语涩痰盛，名子痫，用羚羊角散。或饮食停滞，腹胀呕吐，此是脾胃虚弱，而不 \n能消化，用六君子汤；不应，用平胃散加参、苓。或胎作胀，或胀作痛，此是脾胃气虚，不 \n能承载，用安胎饮加升麻、白术；不应，用补中益气汤。或脐腹作胀，或小便淋闭，此是脾 \n胃气虚，胎压尿胞，用四物加二陈、参、术，空心服后探吐，药出气定，又服又吐，数次必 \n安。或因劳役所伤，或食煎妙，小便带血，此是血得热而流于胞中，宜清膀胱，用逍遥散。 \n或遗尿不禁，或为频数，此是肝火血热，用加味逍遥散。若胸满腹胀，小便不通，遍身浮肿 \n，名胎水不利，用鲤鱼汤；脾胃虚，佐以四君子。病名同而形证异，形证异而病名同，聊见 \n本方。凡用见证之药不应，当分月经治之。 \n徐东皋曰∶胎有不安而腰疼腹痛，甚则至于下坠者，未必不由气血虚，无所营养而使之 \n然也。夫胎之在腹，如果之在枝，枝枯则果落，固理之自然。妇人性偏恣欲，火动于中，亦 \n能致胎不安而有堕者，大抵不外乎属虚属火二者之间，清热养血之治尽之矣。此外有二因动 \n胎者，又不可不知也。有因母病动胎者，但疗母病则胎自稳；有因触伤动胎者，当以安胎药 \n二三剂而胎自安。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>安胎（二十）\n\n属性：茯苓丸（妇三九 温胃安胎） 黄 汤（妇九 气虚胎动） 七味阿胶散（妇八 胎动腹痛） \n太山磐石散（妇三） 《千金》保孕丸（妇三六） 《良方》白术散（妇十一 胎热） 三味白 \n术汤（妇十二 胎热心痛） 益母地黄汤（妇十七 跌坠腹痛） 钩藤散（妇十 胎动腹痛） 醋 \n附丸（妇百七 胎滞不安） 独圣散（妇十八 顺气安胎） 探胎饮（妇十五） 肾着汤（热一二 \n九妊娠脚肿） 当归黄 汤（妇九八 妊娠不利） 滑胎枳壳散（妇二四 瘦胎） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>恶阻（二一）\n\n属性：妊娠之妇，每多恶心呕吐，胀满不食，《巢氏病源》谓之恶阻。此证惟胃气弱而兼滞者 \n多有之，或嗜酸择食，或肢体困倦，或烦闷胀满，皆其候也。然亦有虚实不同，所当辨而治 \n之。 \n凡恶阻多由胃虚气滞，然亦有素本不虚，而忽受胎妊，则冲任上壅，气不下行，故为呕 \n逆等证；及三月余而呕吐渐止者，何也？盖胎元渐大，则脏气仅供胎气，故无暇上逆矣。凡 \n治此者，宜以半夏茯苓汤、人参橘皮汤之类，随宜调理，使之渐安，必俟及期，方得帖然也 \n。若中脘多痰者，用二陈汤加枳壳，或用半夏茯苓汤。若饮食停滞作胀者，宜小和中饮加减 \n主之。若气逆作胀者，宜半夏茯苓汤加枳壳、苏梗、香附。若脾胃气虚者，宜五味异功散、 \n六君子汤、人参橘皮汤之类主之。若胃虚兼寒多呕者，宜六味异功煎、温胃饮之类主之。若 \n肝肾阳虚作呕者，宜理阴煎主之。 \n立斋曰∶半夏乃健脾气、化痰滞之主药也。脾胃虚弱而呕吐，或痰涎壅滞，饮食少思， \n胎不安，必用茯苓半夏汤，倍加白术，以半夏、白术、茯苓、陈皮、砂仁善能安胎气、健脾 \n胃，予常用，验矣。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>恶阻（二一）\n\n属性：四味白术散（妇十三 胃虚吐水） 茯苓丸（妇三九 养胃温胃，痞闷，恶食） 竹茹汤（ \n妇三三 清痰止呕） 乌附汤（妇三五 和气养胃） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>胎气上逼（二二）\n\n属性：妊娠将理失宜，或七情郁怒，以致气逆，多有上逼之证。若气逆气实而胀逼者，宜解肝 \n煎。若胃寒气实而逼者，宜和胃饮。若胃火兼滞者，宜枳壳汤。若脾虚兼滞者，宜紫苏饮。 \n如脾虚而气不行者，宜四君子汤，甚者八珍汤。若脾气虚而兼寒者，宜五君子煎。若脾肾虚 \n寒不行者，宜理阴煎。若脾肾气虚兼火者，宜逍遥散，或加黄芩、枳壳、砂仁。若胎死腹中 \n，冷气上逼，呕恶面青者，治如后胎动欲堕条。 \n一方治胎气上逼，热痛下血，或烦闷困笃，用葱二十茎，水浓煮饮之，胎未死即安，胎 \n已死即下。未效再服。若胎动烦躁，唇口青黑，手足厥冷，须用当归汤。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>胎漏（二三）\n\n属性：妊妇经血不固者，谓之胎漏。而胎漏之由，有因胎气者，有因病气者。而胎气之由，亦 \n有二焉。余尝诊一妇人，脉见滑数，而别无风热等病，问其经脉则如常不断，而但较前略少 \n耳。余曰∶此必受妊者也。因胎小血盛有余而然。后于三月之外，经脉方止，果产一男。故 \n胎妊之妇多有此类。今常见怀胎七八个月而生子者，人但以血止为度，谓之不足月，然其受 \n胎于未止之前，至此而足而实，人所不知也。第此等胎气，亦有阴阳盛衰之辨。如母气壮盛 \n，荫胎有余而血之溢者，其血虽漏而生子仍不弱，此阴之强也，不必治之；若父气薄弱，胎 \n有不能全受而血之漏者，乃以精血俱亏，而生子必萎小，此阳之衰也，而亦人所不知也。凡 \n此皆先天之由。若无可以为力者，然栽培根本，岂果无斡旋之道乎？第见有于无之目及转强 \n于弱之手，为不易得，是乌可以寻常语也。至若因病而漏者，亦不过因病治之而已耳。 \n妊娠血热而漏者，保阴煎、清化饮择而用之。怒动肝火漏血者，保阴煎，甚者化肝煎主 \n之。脾虚不能摄血者，寿脾煎、四君子之类主之。脾虚血热气滞者，四圣散主之。脾肾兼虚 \n者，五阴煎主之。三焦气血俱虚者，五福饮、七福饮之类主之。劳倦伤而动血者，寿脾煎、 \n归脾汤主之。偶因伤触动血者，五福饮、安胎散主之。冲任气虚，不能约制，血滑易动者， \n固阴煎、秘元煎主之。 \n立斋曰∶前证若因气热，用防风黄芩丸。若因血热，用加味逍遥散。若因血虚，用二黄 \n散。若因血去太多，用八珍汤，未应，补中益气汤。若因肝火，用柴胡清肝散。若因脾火， \n用加味归脾汤。若因事下血作痛，用八珍汤，加阿胶、熟艾。若因脾胃虚弱，用补中益气汤 \n加五味子。若因脾胃虚陷，用前汤，倍用升麻、柴胡。若晡热内热，宜用逍遥散。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>胎漏（二三）\n\n属性：安胎寄生汤（妇十九 下血腰痛） 当归芍药汤（妇十六 急痛去血） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>妊娠卒然下血（二四）\n\n属性：妊娠忽然下血，其证有四∶或因火热迫血则妄行；或因郁怒气逆则动血；或因损触胎气 \n，胞宫受伤而下血；或因脾肾气陷，命门不固而脱血。凡此皆动血之最者也。不速为调理， \n则必致堕胎矣。然治此者，必先察其血去之多少，及于血去之后，尤当察其邪之微甚。如火 \n犹未清，仍当清火；气犹未顺，仍当顺气。若因邪而动血，血去而营虚，则速当专顾元气以 \n防脱陷。此中或当治标，或当救本，或当兼标本而调理之。倘不知先后缓急，将恐治标未已 \n，而救本无暇也。当详察之。 \n若火盛迫血妄行者，当察其火之微甚。火之微者，凉胎饮；稍甚者，徙薪饮；再甚者， \n保阴煎、子芩散。若肝经有风热而血下者，宜防风黄芩丸。若怒气伤肝，气逆血动而暴至者 \n，宜保阴煎。若气有未顺而胀满者，四七汤、二陈汤，或加芎、归之类。若兼肝火者，宜化 \n肝煎。若触损胎气，胞宫受伤而血下者，宜安胎散、胶艾汤。去血多者，倍加人参。若从高 \n坠下，伤动胎气而下血者，宜益母地黄汤、安胎散。若因惊气虚而陷者，仍加人参。若脾胃 \n素弱，或偶因伤脾下血者，宜寿脾煎、归脾汤。或中气下陷者，补中益气汤。若血虚微热， \n漏血尿血者，续断汤。以上诸动血证，若去血未多，血无所积，胎未至伤而不止者，宜凉则 \n凉，宜补则补，惟以安之固之为主治。若血已离位，蓄积胞宫，为胀为痛，而余血未出者， \n欲与留之，有不可得，欲去其血而不伤营气，则惟四物汤大加当归为最宜也。若察其胎气已 \n动，势有难留，则五物煎、决津煎皆切要之药。 \n一方∶治顿仆胎动，用川芎末二钱，酒下二三服，胎生即安，胎死即下。 \n又方∶治同前，用砂仁和皮炒为末，每服二钱，米饮下，腹热即安。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>胎动欲堕（二五）\n\n属性：妊娠胎气伤动者，凡跌扑、怒气、虚弱、劳倦、药食误犯、房室不慎，皆能致之。若因 \n母病而胎动，但治其母；若因胎动而母病，但安其胎。轻者转动不安，或微见血，察其不甚 \n，速宜安之，用前安胎及卒然下血等法。若腹痛血多，腰酸下坠，势有难留者，无如决 \n津煎、五物煎，助其血而落之，最为妥当。若其势甚而舌青面赤，胀满呕恶，或冷气上逼者 \n，儿已死矣。若面青吐沫舌赤，是母死也。若面舌唇吻俱青，口中沫出，是母子俱死也。若 \n胎已死，当速去其胎以救其母。气血虚者，惟用决津煎最妙。如不应而胀痛上逼，热不容缓 \n者，急用平胃散一两，酒水各半煎，投朴硝五钱，热服之；或用朴硝一两，以童便调服，则 \n逐而下矣。下后随证调补之。如无胀急，则但用决津煎加朴硝，则死胎自下。 \n一、凡气血衰弱，无以滋养其胎，或母有弱病，度其终不能成者，莫若下之，以免他患 \n，宜桂心散，或用下胎短剧方。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>数堕胎（二六）\n\n属性：夫胎以阳生阴长，气行血随，营卫调和，则及期而产。若或滋养之机少有间断，则源流 \n不继而胎不固矣。譬之种植者，津液一有不到，则枝枯而果落，藤萎而花坠。《故五常政大"}, {"n": 21, "text": "卷二十一\n\n论》曰∶根于中者，命曰神机，神去则机息。根于外者，命曰气立，气止则化绝。正此谓也 \n。凡妊娠之数见堕胎者，必以气脉亏损而然。而亏损之由，有禀质之素弱者，有年力之衰残 \n者，有忧怒劳苦而困其精力者，有色欲不慎而盗损其生气者。此外如跌扑、饮食之类，皆能 \n伤其气脉，气脉有伤而胎可无恙者，非先天之最完固者不能，而常人则未之有也。且胎怀十 \n月，经养各有所主，所以屡见小产堕胎者，多在三个月及五月七月之间，而下次之堕必如期 \n复然。正以先次伤此一经，而再值此经，则遇阙不能过矣。况妇人肾以系胞，而腰为肾之府 \n，故胎妊之妇最虑腰痛，痛甚则坠，不可不防。故凡畏堕胎者，必当察此所伤之由，而切为 \n戒慎。凡治堕胎者，必当察此养胎之源，而预培其损，保胎之法无出于此。若待临期，恐无 \n及也。凡胎孕不固，无非气血损伤之病。盖气虚则提摄不固，血虚则灌溉不周，所以多致小 \n产。故善保胎者，必当专顾血虚，宜以胎元饮为主而加减用之，其次则芍药芎归汤，再次则 \n泰山磐石散，或《千金》保孕丸，皆有夺造化之功，所当酌用者也。又凡胎热者血易动，血 \n动者胎不安，故堕于内热而虚者亦常有之。若脾气虚而血热者，宜四圣散；肝肾虚而血热者 \n，宜凉胎饮；肝脾虚而血热者，宜固胎煎。又立斋法∶治血虚血热，数堕胎者，于调补之外 \n，时值初夏，教以浓煎白术汤下黄芩末二钱，与数十帖，得保而生，亦可法也。此外，凡有 \n他证而胎不安者，当于安胎条中酌而治之。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>胎不长（二七）\n\n属性：妊娠胎气本乎血气。胎不长者，亦惟血气之不足耳。故于受胎之后而漏血不止者有之， \n血不归胎也；妇人中年血气衰败者有之，泉源日涸也；妇人多脾胃病者有之，仓廪薄则化源 \n亏而冲任穷也；妇人多郁怒者有之，肝气逆则血有不调而胎失所养也。或以血气寒而不长者 \n，阳气衰则生气少也。或以血热而不长者，火邪盛则真阴损也。凡诸病此者，则宜补宜固， \n宜温宜清，但因其病而随机应之，则或以及期，或以过月，胎气渐充，自无不长。惟是年迈 \n血衰而然者，数在天矣，有非可以人力为也。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>鬼胎（二八）\n\n属性：妇人有鬼胎之说，岂虚无之鬼气，果能袭人胞宫而遂得成形者乎？此不过由本妇之气质 \n，盖或以邪思蓄注，血随气结而不散，或以冲任滞逆，脉道壅瘀而不行，是皆内因之病，而 \n必非外来之邪，盖即血 气瘕之类耳，当即以 瘕之法治之。详见本条。此外如狐 \n魅异类之遇者，则实有所受而又非鬼胎之谓，亦当于 瘕类求法下之。又凡鬼胎之病， \n必以血气不足而兼凝滞者多有之，但见经候不调而预为调补，则必无是病。若其既病，则亦 \n当以调补元气为主，而继以去积之药乃可也。然用补之外，而欲于补中兼行者，无如决津煎 \n。欲去其滞而不至猛峻者，无如通瘀煎。既加调补而欲直攻其病者，则夺命丹、回生丹皆可 \n酌用，或以当归、红花煎浓汤，送赤金豆亦妙。 \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>妊娠药禁（二九）\n\n属性：斑水蛭及虻虫，乌头附子配天雄，野葛水银并巴豆，牛膝薏苡与蜈蚣，棱莪代 \n赭芫花麝，大戟蛇蜕黄雌雄，牙硝芒硝牡丹桂，槐花牵牛皂角同，半夏南星与通草，瞿麦干 \n姜桃仁通， 砂干漆蟹甲爪，地胆茅根莫用好。（出《便产须知》） \n\n\n\n<目录>卷之三十八人集·妇人规（上）\\胎孕类\n\n<篇名>妊娠寡欲（三十）\n\n属性：妊娠之妇，大宜寡欲，其在妇人多所不知，其在男子而亦多有不知者，近乎愚矣。凡胎 \n元之强弱，产育之难易，及产后崩淋经脉之病，无不悉由乎此。其为故也，盖以胎神巩固之 \n日，极宜保护宫城，使不知慎而多动欲火，盗泄阴精，则藩篱由不固而伤，血气由不聚而乱 \n，子女由元亏而夭，而阴分之病亦无不由此而百出矣。此妇人之最宜慎者，知者不可不察。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>滑胎（三十二）\n\n属性：妊娠滑胎之法，惟欲其坐草之期易而且速，而难易之由，则在血之盈虚，不在药之滑利 \n。盖血多则润而产必易，血亏则涩而产必难，故于未产之前，但宜以培养气血为主，而预为 \n之地，如四物汤、滑胎煎、五福饮、小营煎、八珍汤之类，即皆滑胎之要药。若不知此而过 \n用滑利等物，或产期未近，无火无滞而妄用清火行气，沉降苦寒等药，必皆暗残营气，走泄 \n真阴，多致血亏气陷，反为临期大害。若果肥盛气实者，则紫苏饮、保生无忧散、滑胎枳壳 \n散之类，皆可择用。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>催生（三三）\n\n属性：凡妊娠胎元完足，弥月而产，熟落有期，非可催也。所谓催生者，亦不过助其血气而利 \n导之耳。直待临期，乃可用脱花煎或滑胎煎，随证加减主之。或经日久产，母困倦难生，俱 \n宜服滑胎煎，以助其气血，令儿速生。其有气虚无力，艰于传送者，必用独参汤，随多随少 \n接济其力，皆为催生要法。若期未至而妄用行气导血等剂，以为催生，亦犹摘方苞之萼，揠 \n宋人之苗耳。 \n一、临盆将产，腹痛已甚，凡催生之药，无如脱花煎，少用肉桂五七分为最稳最妙。若 \n气虚无力者，加人参二三钱；虚甚者，任意加用之。 \n一、催生若水血下多，子道干涩难出者，宜用滑利之物，如猪脂油、蜜、酥油、葱白、 \n葵子、牛乳、滑石、榆白皮之类以润之，亦济急之法也。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>催生（三三）\n\n属性：达生散（妇四十） 生化汤（妇四二） 加味芎归汤（妇四四 难产） 《良方》当归汤（妇 \n五滑胎催生） 经验滑石散（妇五二 胎干难产） 佛手散（妇四一） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>稳婆（三四）\n\n属性：产妇临盆，必须听其自然，弗宜催逼，安其神志，勿使惊慌，直待花熟蒂圆，自当落矣 \n。所以凡用稳婆，必须择老成忠浓者，预先嘱之，及至临盆，务令从容镇静，不得用法催逼 \n。余尝见有稳婆忙冗性急者，恐顾此失彼，因而勉强试汤，分之掐之，逼之使下，多致头身 \n未顺而手足先出，或横或倒，为害不小。若未有紧阵，不可令其动手，切记！切记！又或有生 \n息不顺，及双胎未下之类，但宜稳密安慰，不可使产母闻知，恐惊则气散，愈难生下。又尝 \n见有奸诡之妇，故为哼讶之声，或轻事重报，以显己能，以图酬谢，因致产妇惊疑，害尤非 \n细，极当慎也。 \n立斋《医按》载一稳婆云∶止有一女，于分娩时，适当巡街侍御行牌，取我视其内室分 \n娩，女为此惊吓，未产而死。后见侍御，更以威颜吩咐。迨视产母，胎虽顺而头偏在一边， \n此时若以手入推正，可保顺生。因畏其威，不敢施手，但回禀云∶此是天生天化，非人力所 \n能。因是子母俱不能救。由此观之，可见产时当用静镇自然，而一毫惊恐疑畏有不可使混于其间者。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>产要（三五）\n\n属性：凡孕妇临月，忽然腹痛，或作或止，或一二日，或三五日，胎水少来，但腹痛不密者， \n名曰弄胎，非当产也。又有一月前，或半月前，忽然腹痛如欲产而不产者，名曰试月，亦非 \n产也。凡此腹痛，无论胎水来与不来，俱不妨事，但当宽心候时可也。若果欲生，则痛极连 \n腰，乃将产也。盖肾系于腰，胞系于肾故耳。又试捏产母手中指本节，跳动即当产也。此时 \n儿逼产门，谷道挺迸，水血俱下，方可坐草试汤，瓜熟蒂悬，此乃正产之候也。 \n一、产妇腹痛未甚，且须宽心行动，以便儿身舒转。如腰腹痛甚，有产之兆，即当正身 \n仰卧，或起坐舒伸，务宜安静从容，待儿转身向下，其产必顺而且易。最不宜预为惊扰入手 \n，以致产妇气怯，胞破浆干，使儿转身不易，则必有难产之患。 \n一、产妇初觉欲生，便须惜力调养，不可用力妄施，恐致临产乏力。若儿方转身而用力 \n太早，则多致横逆，须待顺而临门，一逼自下。若时候未到，用力徒然。 \n一、临产房中，不宜多人喧嚷惊慌，宜闭户，静以待生。 \n一、将产时，宜食稠软白粥，勿令饥渴以乏气力，亦不宜食硬冷难化之物，恐产时乏力 \n，以致脾虚不能消化，则产后有伤食之病。 \n一、产妇产室，当使温凉得宜。若产在春夏，宜避阳邪，风是也；产在秋冬，宜避阴邪 \n，寒是也。故于盛暑之时，亦不可冲风取凉，以犯外邪；又不宜热甚，致令产母头疼面赤； \n亦不宜人众，若热气熏蒸，亦致前患。其或有热极烦渴而血晕血溢者，亦可少与凉水，暂以 \n解之，然亦不可多用。若冬末春初，余寒尚盛，产室不可无火，务令下体和暖，衣被亦当温 \n浓，庶不为寒气所侵，可免胎寒血滞难产之患。且产后胎元既落，气血俱去，乘虚感邪，此 \n时极易，故不可不慎。 \n一、凡富贵之家过于安逸者，每多气血壅滞，常致胎元不能转动。此于未产之先，亦须 \n常为运动，庶使气血流畅，胎易转则产亦易矣。是所当预为留意者。 \n一、妊娠将产，不可詹卜问神，如巫觋之徒哄吓谋利，妄言凶险，祷神祗保，产妇闻之 \n，致生疑惧。夫忧虑则气结滞而不顺，多至难产，所宜戒也。 \n一、产时胞浆未下，但只稳守无妨。若胞浆破后，一二时辰不生，即当服催生等药，如 \n脱花煎、滑胎煎，或益母丸之类。盖浆乃养儿之生，浆干不产，必其胎元无力，愈迟则愈干 \n，力必愈乏，所以速宜催之。 \n一、产妇与酒，不可多而致醉。凡产前醉，则乏力而四肢不用；产后酒多，恐引入血分 \n四肢，致后日有动血，及四肢无力，髓骨酸痛之患。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>六逆产（三六）\n\n属性：一、横生者，以儿方转身，产母用力逼之太早，故致儿身未顺而先露手臂。但令母安然 \n仰卧，稳婆以手徐推儿臂下体，令其正直，复以中指摸其肩，弗使脐带攀系即生。 \n二、倒生者，因儿未及转身，产母努力，故令儿先露足。令母正卧，以手徐推足入，良 \n久仍推儿身，徐俟转正近门即生。 \n三、偏生者，因儿未顺生路，产母努力，逼儿头偏一边，虽若露顶，实额角也，亦照前 \n法推正即生。若儿顶后骨偏拄谷道傍，以手从外后傍轻轻托正即生。 \n四、碍产者，儿身虽顺，门路虽正，但不能下，乃因胎转时脐带绊肩而然。令产母仰卧 \n，以手轻推儿向上，乃用中指按儿两肩，理顺脐带即生。 \n五、坐产者，因儿将产，其母疲倦，久坐椅褥，抵其生路而然。须用手巾一条拴系高处 \n，令产母以手攀之，轻轻屈足舒伸以开生路，儿即顺生。 \n六、盘肠产者，临产母肠先出，子产而肠未收，故曰盘肠产。古法以醋、水各半盏，默 \n然产母面背则收。一法以蓖麻子四十九粒，研烂，涂母头顶，待肠收上，急洗去。 \n俗以水 面背惊之而肠亦收，但恐惊则气散，反致他疾，戒之。 \n一方∶治横逆产难，令产母仰卧，以小针刺儿手脚心三五次，用盐擦之，手脚即缩上， \n转身即生。 \n一方∶治盘肠产，以半夏为末，用少许搐鼻中，肠自上。 \n又方∶用大纸捻以麻油润渗，点着吹灭，以烟熏产妇鼻中，肠即上。 \n又方∶肠出，盛以洁净漆器，浓煎黄 汤浸之，肠即上。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>胞破产难（三七）\n\n属性：凡产妇胎未顺而胞先破者，其因有二∶盖一有母质薄弱，胞衣不固，因儿转动，随触而 \n破者，此气血之虚也；一有儿身未转，以坐草太早，用力太过，而胞先破者，此举动之伤也 \n。若胞破久而水血干，产路涩则儿难下，宜急用大料四物汤，或五物煎、脱花煎、滑胎煎、 \n五福饮、当归汤之类，助其气血，并浓煎葱汤熏洗产户，使其暖而气达，则自当顺下。若持 \n久力乏，血已耗涸，则甚危矣。当用八珍汤料一斤，益母草四两，水数碗煎熟，不时饮之， \n亦有得生者。或以黄 、芎、归数斤，以大釜煎，药气氤氲满室，使产母口鼻俱受其气，亦 \n良法也。大抵产难之证，多患于郁闷、安佚、富贵之家，治法虽云胎前清气，产后补血，然 \n不可拘泥。若脾胃不健，气血不充，必当预为调补；不然，临产必多患难。 \n一、产难经日不下，别无危证者，宜用脱花煎催之，极妥极妙。 \n一医宿客店，治店妇临产数日不生，下体俱冷，无药甚窘，令取椒、橙叶、茱萸，共煎 \n汤一盆，令产妇以小凳坐盆内熏洗，良久，小腹皆暖，气温血行，遂产。 \n一方∶以紫苏煎汤熏洗。大抵遇严寒时月，产久伤冷，气血必凝，此熏洗之法，亦要法 \n也。外以淋汤，内以羊肉汤，必效。 \n一方∶令产妇以自己发梢含于口中，令其恶心作呕，即下。亦治胞衣不出。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>胞衣不出（三八）\n\n属性：胞衣不出，有以气血疲弱，不能传送而停阁不出者。其证但见无力，而别无痛胀，治当 \n补气助血，宜速用决津煎，或滑胎煎、保生无忧散、《局方》黑神散之类主之。有以恶露流 \n入胞中，胀滞不出者。盖儿既脱，胞带必下坠，故胞在腹中，形如仰叶，仰则盛聚血水而胀 \n碍难出。惟老成稳婆多有识者，但以手指顶其胞底，以使血散，或以指摸上口，攀开一角， \n使恶露倾泻，则腹空自落矣。又一法，以本妇头发，搅入喉中，使之作呕，则气升血散，胞 \n软亦自落矣。凡胎胞不出者多死，授以此法，甚效。若血渗胞中，停蓄既久，而为胀为痛， \n或喘或急，则非逐血破血不可也，宜速用夺命丹，或用失笑散，以热酒调服，使血散胀消， \n其衣自下。若气血兼虚者，亦惟决津煎为善。 \n一方∶用蓖麻子仁一两，研烂贴母右足心，衣下速洗去，缓则肠亦出。如肠不收，以此 \n膏涂脑顶，则肠自入。 \n一方∶用红花一两，酒煮浓汁服。 \n一法∶用产妇鞋底炙热，熨小腹上下，即出。 \n一方∶用皂角刺烧为末，每服一钱，温酒调服。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>胞衣不出（三八）\n\n属性：牛膝散（妇四九 胎衣不下，腹胀） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>气脱血晕（三九）\n\n属性：产时胎胞既下，气血俱去，忽尔眼黑头眩，神昏口噤，昏不知人，古人多云恶露乘虚上 \n攻，故致血晕，不知此证有二∶曰血晕，曰气脱也。若以气脱作血晕，而用辛香逐血化痰等 \n剂，则立刻毙矣，不可不慎也。 \n一、气脱证∶产时血既大行，则血去气亦去，多致昏晕不省，微虚者少顷即苏，大虚者 \n脱竭即死。但察其面白眼闭，口开手冷，六脉细微之甚，是即气脱证也。速用人参一二两， \n急煎浓汤，徐徐灌之，但得下咽，即可救活；若少迟延，则无及矣。余尝救此数人，无不随 \n手而愈，此最要法也。又尝见有禁参而毙者，云新产后不可用参，用参则补住恶血，必致为 \n害，即劝之亦不肯用，直待毙而后悔者亦数人矣。又有云产后必过七日方可用参，此等愚昧 \n讹传，不知始自何人，误人不浅，万万不可信也。 \n一、血晕之证，本由气虚，所以一时昏晕，然血壅痰盛者亦或有之。如果形气脉气俱有 \n余，胸腹胀痛上冲，此血逆证也，宜失笑散。若痰盛气粗，宜二陈汤。如无胀痛气粗之类， \n悉属气虚，宜大剂芎归汤、八珍汤之类主之。 \n一、猝时昏晕，药有未及，宜烧秤锤令赤，用器盛至床前，以醋沃之，或以醋涂口鼻， \n令酸气入鼻，收神即醒。或以破旧漆器，或用干漆烧烟熏之，使鼻受其气皆可。但此法惟轻 \n而暴晕者所宜，若气虚之甚而昏厥者，非用大补之剂，终无益也。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>儿初生\n\n属性：（初诞法详小儿门，四十） \n凡婴儿初生，当随手包裹，切不可为风寒所侵。盖儿在腹中，遮护最密，及其初脱胞胎 \n，肌肤脆嫩，极易感邪。若在夏令，自所无虑，但觉稍寒，即须慎之。尝见儿生未久，多有 \n惊风发热抽搐等病者，率由乎此。 \n一、小儿初生，天气微凉即大忌洗沐，恐腠理不密，元气发泄，而外邪乘之也。凡产母 \n分娩艰难，劳伤胎气，多有儿虽脱胞而乏力垂危，或已死者，切不可便断脐带，当急用大纸 \n捻蘸香油，于脐带上往来烧断之，取其阳气以续胎元，俄顷，儿得啼声，即已活矣，且可免 \n胃寒泄泻之病。凡见此者，若以刀断脐带，则子母皆多难保。此出《立斋医按》。 \n一、凡烧带之法，惟素多阳虚及产时气脱者，最宜用之以助阳气。若母气阳强，或儿声 \n洪亮者，皆不宜用，恐火从脐入，日后致生热毒，则反为害不小。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>子死腹中（四一）\n\n属性：凡子死腹中者，多以触伤，或犯禁忌，或以胎气薄弱不成而殒，或以胞破血干，持久困 \n败，但察产母腹胀舌黑者，其子已死。若非产期而觉腹中阴冷重坠，或为呕恶，或秽气上冲 \n，而舌见青黑者，皆子死之证。宜速用下死胎方下之。下后察其虚实，随加调补自愈。若唇 \n舌面色俱青，则母子皆危之兆也。 \n补遗方∶治胎死腹中。用红花以酒煮汁，饮二三碗即下。 \n新法下胎方∶用当归一两，浓朴三钱，陈皮二钱，入酒、水各一碗，煎至一碗，加朴硝 \n三五钱，再煎十余沸，去 热服，死胎自下。或止用脱花煎更妙。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>子死腹中（四一）\n\n属性：回生丹（妇六六） 下死胎方（妇五九） 桂香散（妇五五） 琥珀丸（妇一三四） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>产门不开不闭子宫不收（四二）\n\n属性：交骨不开，产门不闭，无非阴气不足，阴不足则气不达，所以不开。不开则产必艰难， \n宜加味芎归汤，补而开之，大有奇效。或十全大补汤亦可。 \n产门不闭，由阴气大虚，不能收摄；或由阴火下流而然。故或为阴挺突出，或为肿胀， \n或为淋涩不禁。若气血俱虚者，宜十全大补汤加五味子，补而敛之。或痛而觉热者，宜加味 \n逍遥散。若忧思伤脾血热者，加味归脾汤。若暴怒伤肝动火者，龙胆泻肝汤。 \n子宫不收而外坠者，宜补中益气汤加醋炒芍药，饮而举之。或外以黄 煎汤熏洗亦妙。 \n或以硫黄汤熏洗，硫黄散敷之。 \n一方∶治产后子宫不敛，用荆芥、藿香、椿根白皮煎汤熏洗，神效。 \n一方∶产后子肠不收，外用枳壳、诃子、五倍子、白矾煎汤熏洗。若不收，再灸顶心百 \n会穴数壮即上。 \n一方∶子宫脱出，用蓖麻仁十四枚，研烂涂顶心，入即洗去。 \n一方∶治产后阴脱，用绢袋盛炒热蛇床子熨之，亦治阴痛。又法∶用蛇床子五两，乌梅 \n十四个，煎水，日洗五六次。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>小产（四三）\n\n属性：小产之证，有轻重，有远近，有禀赋，有人事。由禀赋者，多以虚弱。由人事者，多以 \n损伤。凡正产者，出于熟落之自然；小产者，由于损折之勉强，此小产之所以不可忽也。若 \n其年力已衰，产育已多，欲其再振且固，自所难能。凡见此者，但得保其母气，则为善矣。 \n若少年不慎，以致小产，此则最宜调理，否则下次临期仍然复坠，以致二次三次，终难子嗣 \n，系不小矣。凡此安之之法，见前数堕胎条中。既产调理之法，亦与大产相似。详后产后条 \n中，俱当按而用之。 \n一、凡妇人年及中衰，胎元无力，则常有胎不能长，及多小产昏晕之患，此气血衰败而 \n然。血气既衰，则凡于小产之后，多有胎既落而复又下坠。如更有一胎欲产者，此非胎也， \n乃因气虚而胞宫随胎下陷也。产母不知，必至惊慌，此无足虑，但以寿脾煎，或八珍、十全 \n大补、芎归补中汤之类主之，则自安矣。 \n又∶凡小产有远近，其在二月三月为之近，五月六月为之远。新受而产者其势轻，怀久 \n而产者其势重，此皆人之所知也。至若犹有近者，则随孕随产矣。凡今艰嗣之家，犯此者十 \n居五六。其为故也，总由纵欲而然。第自来人所不知，亦所不信。兹谨以笔代灯，用指迷者 \n，倘济后人，实深愿也，请详言之。尽胎元始肇，一月如珠露；二月如桃花；三月四月而后 \n，血脉形体具∶五月六月而后，筋骨毛发生。方其初受，亦不过一滴之玄津耳。此其橐 正 \n无根据，根 尚无地，巩之则固，决之则流。故凡受胎之后，极宜节欲以防泛溢。而少年 \n纵情，罔知忌惮，虽胎固欲轻者，保全亦多，其有兼人之勇者，或恃强而不败，或既败而复 \n战。当此时也，主方欲静，客不肯休，无奈狂徒敲门撞户，顾彼水性热肠，有不启扉而从， \n随流而逝者乎？斯时也，落花与粉蝶齐飞，火枣共交梨并逸，合污同流，已莫知其昨日孕而 \n今日产矣。朔日孕而望日产矣，随孕随产，本无形迹。盖明产者胎已成形，小产必觉；暗产 \n者胎仍以水，直溜何知？故凡今之行院家多无大产，以小产之多也。娶娼妓者多少子息，以 \n其子宫滑而惯于小产也。今尝见艰嗣求方者，问其阳事，则曰能战；问其功夫，则曰尽通； \n问其意况，则怨叹曰∶人皆有子我独无。亦岂知人之明产，而尔之暗产耶？此外如受胎三月 \n五月而每有堕者，虽衰薄之妇常有之。然必由纵欲不节，致伤母气而堕者为尤多也。故凡恃 \n强过勇者多无子，以强弱之自相残也；纵肆不节者多不育，以盗损胎元之气也。岂悉由妇人 \n之罪哉？欲求我方者，当以此篇先读之，则传方之思，已过半矣。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>小产（四三）\n\n属性：人参黄 汤（妇四八 小产气虚血不止） 当归川芎汤（妇四三 小产瘀血痛） 殿胞煎（ \n新因十 小产后腹痛） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>下胎断产（四四）\n\n属性：下胎断产本非仁者之事，然有妇人临产艰危，或病甚不胜产育者，则下胎断产之法有不 \n得已，亦不可废者也。至若水银、虻虫、水蛭、斑蝥之属，不惟伤胎，且伤母矣，用者不可 \n造次。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>下胎断产（四四）\n\n属性：《千金》去胎方（妇六一） 下胎短剧方（妇五六） 扶羸短剧方（妇五八） 《广济》下胎 \n方（妇五七） 《良方》桂心散（妇五四） \n一方∶不拘生胎死胎，用蓖麻仁二个，巴豆一个，麝香一分，研贴脐中并足心即下。月 \n一粒，温酒吞下。 \n又云∶下生胎，用蓖麻子一个。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>下胎断产（四四）\n\n属性：断产短剧方（妇六八） 《千金》断产方（妇又六七） 丹溪断子法（妇六九） 断产灸法（ \n妇六七） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产育类\n\n<篇名>产育类论列总方（四五）\n\n属性：四物汤（补八） 八珍汤（补十九） 十全大补汤（补二十） 五福饮（新补六） 五物煎（新 \n因三） 补中益气汤（补三十） 当归汤（妇五） 小营煎（新补十五） 保生无忧散（妇四七） \n羊肉汤（妇七一） 脱生煎（新因十一） 加味逍遥散（补九三） 寿脾煎（新热十六） 决津煎（ \n新因二） 加味归脾汤（补三三） 滑胎煎（新因九） 益母丸（妇六四） 滑胎枳壳散（妇二四） \n紫苏饮（妇二八） 夺命丹（妇六五） 加味芎归汤（妇四四） 失笑散（妇百四） 芎归补中汤 \n（妇四六） 龙胆泻肝汤（寒六二） 硫黄汤（妇六三、六二） 《局方》黑神散（妇五十） 芎归 \n汤（妇四一） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>论产后当大补气血（四六）\n\n属性：产后病治，尝见丹溪云∶产后当大补气血，即有杂证，以末治之，一切病多是血虚，皆 \n不可发表。此其意谓血气随胎而去，必属大虚，故无论诸证，皆当以大补为先，其他皆属可 \n缓。余于初年，诚然佩服，及执而用之，则每为所困，经者数次，始悟其言虽有理，而未免 \n言之过也。即今产科所宗，无非此法。余目睹其误，及亲为解救者，盖不少矣。故敢剖析于 \n后，实有所见，不得不言，非存心自 ，故毁先贤。若然，则徒为笑骂之招耳。宾虽至愚， \n必不为也。观者其深察此意。 \n凡产后气血俱去，诚多虚证，然有虚者，有不虚者，有全实者。凡此三者，但当随证随 \n人，辨其虚实，以常法治疗，不得执有成心，概行大补以致助邪，此辨之不可不真也。 \n一、产后虚证，无非随人元气，必素弱之人多有之，或于产后血气俱去而更弱者亦有之 \n。此当因人察脉，因脉察证。若脉气、形气、病气俱不足，此当以全虚治之。若形气不足， \n病气有余，或兼火邪，或兼外邪，或以饮食停滞，是亦虚中有实，不得不详审而治。此中委 \n曲，未能言尽，惟明者悟之。 \n一、产后不虚证，盖或其素日无病，或以年少当时，或以素耐辛苦贫劳之质，此辈本无 \n不足，及其一旦受孕，乃于无病腹中参入此物，故致血气壅塞，为胀为呕，是皆添设有余之 \n病。及其既产，始见通快，所留得去，仍复故吾。常人之产，此类极多，果何虚之有？然或 \n以内伤，或以外感，产后之病，难保必无，倘有所犯，去之即愈；若概行大补，果能堪否？ \n即临盆带去血气，未免暂见耗损，然以壅滞之余，不过皆护胎随从之物，去者当去，生者旋 \n生，不出数日，必已来复，此生化自然之理，何至是产皆虚也。凡治此类，但当因证用治。 \n若执云产后必当大补气血，则实实之病，必所不免，而轻者必甚，甚者必危矣。由此观之， \n则立言者固不易，而用言者又岂易哉。 \n一、产后全实证，有如外感风寒，头痛身热，便实中满，脉紧数洪大有力者，此表邪之 \n实证也。又火之盛者，必热渴躁烦，或便结腹胀，口鼻舌焦黑，酷喜冷冻饮料，眼眵，尿管痛赤 \n，脉见洪滑，此内热之实证也。又郁怒动肝，胸胁胀痛，大便不利，脉弦而滑，此气逆之实 \n证也。又恶露未尽，瘀血上冲，心腹胀满，疼痛拒按，大便难而小便利，此血逆之实证也。 \n又凡富贵之家，保护太过，或过用人参、 、术，以致气壅；或过用糖、酒、炭火，以致内 \n热；或产本不虚，而妄用大补之药，以致增病，此调摄之实证也。又或因产过食，恐其劳困 \n，固令勉强，以致停蓄不散，此内伤之实证也。以上诸证，姑举要者以见其概。然既有表邪 \n则不得不解，既有火邪则不得不清，既有内伤停滞则不得不开通消导。且人有强弱，产有虚 \n实，病有真假，治有逆从，固不可以同日语也。观《六元正纪大论》曰∶妇人重身，毒之何 \n如？曰∶有故无殒，亦无殒也。此自经常不易之大法，亦何庸赘辨之若此。第因丹溪之言， \n人多偏执，故不得不详尽其说，以解后人之惑也。诸虚实治法详具后条。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>论产后三禁（四七）\n\n属性：观《病机机要》云∶治胎产之病，当从厥阴证论之。宜无犯胃气及上二焦，是为三禁， \n谓不可汗，不可下，不可利小便。发其汗，则同伤寒下早之证；利大便，则脉数而伤脾；利 \n小便，则内亡津液，胃中枯燥。但使不犯三禁，则营卫自和，而寒热自止矣。凡用治之法， \n如发渴则白虎，气弱则黄 ，血痛则当归，腹痛则芍药。大抵产病，天行从加减柴胡，杂证 \n从增损四物，宜察脉证而用之。详此说虽为产育之大法，然病变不同，倘有是证，则不得不 \n用是药，所谓有病则病受之也。第此经常之法，固不可不知，而应变之权，亦不可执一也。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后腹痛（四八）\n\n属性：产后腹痛，最当辨察虚实。血有留瘀而痛者，实痛也；无血而痛者，虚痛也。大都痛而 \n且胀，或上冲胸胁，或拒按而手不可近者，皆实痛也，宜行之散之。若无胀满，或喜揉按， \n或喜热熨，或得食稍缓者，皆属虚痛，不可妄用推逐等剂。 \n凡新产之后，多有儿枕腹痛者，摸之亦有块，按之亦微拒手，故古方谓之儿枕，皆指为 \n胞中之宿血，此大不然。夫胎胞俱去，血亦岂能独留？盖子宫蓄子既久，忽尔相离，血海陡 \n虚，所以作痛。胞门受伤，必致壅肿，所以亦若有块，而实非真块。肿既未消，所以亦颇拒 \n按。治此者，但宜安养其脏，不久即愈，惟殿胞煎为最妙，其次则四神散、五物煎皆极佳者 \n。若误认为瘀，而妄用桃仁、红花、玄胡、青皮之属，反损脏气，必增虚病。 \n一、有母体本虚而血少者，即于产时亦无多血，此辈尤非血滞。若有疼痛，只宜治以前 \n法，或以大、小营煎、黄雌鸡汤主之。 \n一、凡新产之后，其有阳气虚弱而寒从中生，或寒由外入，以致心腹作痛，呕吐不食， \n四肢厥冷者，宜九蜜煎、大严蜜汤，或理阴煎主之。 \n一、产当寒月，以致寒气入腹，脐下胀痛，手不可近者，宜羊肉汤主之。若气实寒甚者 \n，宜蟠葱散。 \n一、产后恶露不尽，留滞作痛者，亦常有之。然此与虚痛者不同，必其由渐而甚，或大 \n小便不行，或小腹硬实作胀，痛极不可近手，或自下上冲心腹，或痛极牙关紧急，有此 \n实证，当速去其血。近上者，宜失笑散；近下者，宜通瘀煎、夺命丹、回生丹。如或未效， \n当用决津煎为善。 \n一、产后有脾虚、肾虚而为腹痛者，此不由产而由脏气之不足。若脾气虚寒，为呕吐， \n为食少，而兼腹痛者，宜五君子煎、六君子汤、温胃饮之类主之。若肾气虚寒，为泻为痢， \n而兼腹痛者，宜胃关煎、理阴煎之类主之。 \n一、产后有饮食停滞及气逆作痛，亦当因其类而消去之，如排气饮、大和中饮之类，皆 \n可酌用。 \n仲景曰∶产后腹中 痛，当归生姜羊肉汤主之。并治腹中寒疝，虚劳不足。 \n立斋曰∶前证若因气滞，用延胡索散。若因外寒，用五积散。若因怒气，用四物加木香 \n、柴胡。若因血虚，用四物、参、术、炮姜。若因阳气虚弱，用四君、当归、炮姜。若因脾 \n虚血弱，用六君、当归、炮姜。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后发热（四九）\n\n属性：产后发热，有风寒外感而热者，有邪火内盛而热者，有水亏阴虚而热者，有因产劳倦虚 \n烦而热者，有去血过多头晕闷乱烦热者。诸证不同，治当辨察。 \n一、产后有外感发热者，盖临盆之际，多有露体用力，无暇他顾，此时或遇寒邪，则乘 \n虚而入，感之最易。若见头疼身痛，憎寒发热，或腰背拘急，脉见紧数，即产后外感证也。 \n然此等外感，不过随感随病，自与正伤寒宿感者不同，故略加解散即自痊。可勿谓新产之后 \n不宜表散，但当酌其虚实而用得其宜耳。凡产后感邪，气不甚虚者，宜三柴胡饮。若气虚脾 \n弱而感者，宜四柴胡、五柴胡饮。若肝脾肾三阴不足而感者，宜补阴益气煎。若虚寒之甚者 \n，宜理阴煎。若产妇强壮气实而感者，宜正柴胡饮。若兼内火盛而外邪不解者，宜一柴胡饮 \n。若风寒俱感，表里俱滞者，宜五积散。 \n一、产后有火证发热者，但外感之热多在表，火证之热多在里。此必以调摄太过，或时 \n令热甚，或强以酒，或误用参、术、姜、桂大补之药，或过用炭火，或窗牖太密，人气太盛 \n，或气体本实而过于动作。凡属太过，皆能生火。火盛于内，多见潮热内热，烦渴喜冷，或 \n头痛多汗，便实尿赤，及血热妄行，但无表证，脉见缓滑不紧而发热者，便是火证，宜清化 \n饮、保阴煎之类主之。若本元不虚，或火之甚而势之急者，即徙薪饮、抽薪饮亦所常用，不 \n必疑也。 \n一、产后有阴虚发热者，必素禀脾肾不足，及产后气血俱虚，故多有之。其证则倏忽往 \n来，时作时止，或昼或夜，进退不常，或精神困倦，怔忡恍惚，但察其外无表证，而脉见弦 \n数，或浮弦豁大，或微细无力。其来也渐，非若他证之暴至者，是即阴虚之候，治当专补真 \n阴，宜小营煎、三阴煎、五阴煎之类，随宜主之。若阴虚兼火而微热者，宜一阴煎。若阴虚 \n兼火之甚而大热者，宜加减一阴煎。若阴虚火盛，热而多汗者，宜当归六黄汤。若阴中之阳 \n虚，火不归源而热者，宜大营煎、理阴煎、右归饮之类主之。若血虚阳不附阴，烦热作渴者 \n，宜人参当归汤。若气血俱虚，发热烦躁，面赤作渴，宜八珍汤、十全大补汤。若热甚而脉 \n微者，宜急加桂、附，或认为火，则祸在反掌。 \n一、产后有去血过多发热者，其证必烦渴短气，头痛头晕，闷乱内热，是亦阴虚之属， \n宜人参当归汤主之。 \n立斋曰∶大凡元气虚弱而发热者，皆内真寒而外假热也。但用六君或补中益气加炮姜温 \n补脾气，诸证自退。若四肢畏冷，急加附子。凡新产阴血暴伤，阳无所附而外热，宜用四物 \n、炮姜，补阴以配阳。若因误服寒凉克伐之剂而外热，此为寒气格阳于外，宜用四君子加姜 \n、桂；如不应，急加附子。若或肌肤发热，面目赤色，烦渴引饮，此血脱发躁，宜用当归补 \n血汤。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后乍寒乍热（五十）\n\n属性：产后乍寒乍热，总由血气虚损，阴阳不和而然。若阳胜则乍热，阴胜则乍寒。凡阴胜而 \n寒多者，宜增损四物汤、理阴煎。若阳胜而热多者，宜四物汤、三阴煎。若阳气陷入阴中而 \n乍寒乍热者，宜补中益气汤、补阴益气煎。若阴阳俱虚而寒热者，宜八珍汤、十全大补汤。 \n若败血不散，流入阴中而作寒热者，宜决津煎、殿胞煎。若血实气壅者，宜夺命丹。陈无择 \n曰∶败血流闭诸阴则寒，流闭诸阳则热，宜五积散。若有外感者，宜从前产后发热调治。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>蓐劳（五一）\n\n属性：蓐，草荐也。产妇坐草艰难，以致过劳心力，故曰蓐劳，此即产后劳倦也。其证则或为 \n寒热如疟，或头疼自汗，或眩晕昏沉，或百节疼痛，或倦怠喘促，饮食不甘，形体虚羸之类 \n，皆其候也，悉当以培补元气为主。若初产后蓐劳困倦，惟猪腰汤为妙，或用黄雌鸡汤、白 \n茯苓散。若蓐劳虚汗不止，宜母鸡汤。若兼脏寒者，宜羊肉汤。若气血俱虚者，宜五福饮、 \n十全大补汤。若兼外邪发热者，宜补阴益气煎、补中益气汤。若兼外邪发热而中寒背恶寒者 \n，宜理阴煎，详加减法治之。若兼阳虚内寒者，宜五君子煎，或理阴煎。若阳盛阴虚兼内热 \n者，宜五福饮加芍药、黄芩、地骨皮之类，随宜用之。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后喘促（五二）\n\n属性：产后喘急有二，乃一以阴虚之极，一以寒邪在肺。盖产后既以大虚，焉得气实而喘？若 \n肺无寒邪而见喘促者，此以血去阴虚，孤阳无主，故气穷短促而浮脱于上，此实肝肾不接， \n无根将脱之兆，最为危候。经曰∶肝苦急，急食甘以缓之，正此类也。惟贞元饮为治此之神 \n剂。若气虚兼寒者，宜大补丸煎，或理阴煎。若风寒外感，邪气入肺而喘急者，此必气粗胸 \n胀，或多咳嗽，自与气短似喘上下不接者不同，治当以疏散兼补为主，宜金水六君煎，或六 \n君子汤。若单以寒邪入肺，气实气壅而本无虚者，宜六安煎，或二陈汤加苏叶之类主之。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后喘促（五二）\n\n属性：二母散（妇八六 血热喘嗽） 二物参苏饮（妇八四 瘀血入肺喘嗽） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后恶露不止（五三）\n\n属性：产后恶露不止，若因血热者，宜保阴煎、清化饮。有伤冲任之络而不止者，宜固阴煎加 \n减用之。若肝脾气虚，不能收摄而血不止者，宜寿脾煎，或补中益气汤。若气血俱虚而淡血 \n津津不已者，宜大补丸煎，或十全大补汤。若怒火伤肝而血不藏者，宜加味四物汤。若风热 \n在肝而血下泄者，宜一味防风散。 \n一、止血方∶用蒲黄二两，水煎，顿服。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后恶露不止（五三）\n\n属性：人参当归汤（妇百十四） 佛手散（妇四一 血多烦晕） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后发痉（五四）\n\n属性：产后发痉，乃阴血大亏证也。其证则腰背反张，戴眼直视，或四肢强劲，身体抽搐。在 \n伤寒家虽有刚痉、柔痉之辨，然总之则无非血燥血枯之病，而实惟足太阳与少阴主之。盖膀 \n胱与肾为表里，肾主精血，而太阳之脉络于头目项背，所以为病若此。若其所致之由，则凡 \n如伤寒误为大汗以亡液，大下以亡阴，或溃疡、脓血、大泄之后，乃有此证。故在产后，亦 \n惟去血过多，或大汗大泻而然，其为元气亏极、血液枯败也可知。凡遇此证，速当察其阴阳 \n，大补气血，用大补丸煎，或理阴煎，及十全大补汤之类，庶保其生。若认为风痰，而用发 \n散消导等剂，则死无丸矣。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后大便秘涩（五五）\n\n属性：产后大便秘涩，以其失血亡阴，津液不足而然，宜济川煎加减主之，及后立斋法俱妙。 \n立斋曰∶前证若计其日期，饮食已多，即用药通之，祸在反掌之间矣。必待其腹满觉胀 \n，欲去不能者，此乃结在大肠，宜用猪胆汁润之。若服苦寒疏通，反伤中气，通而不止，或 \n成他证。若去血过多，用十全大补汤。血虚火燥，用加味四物汤。气血俱虚，用八珍汤。虽 \n数日不通，饮食如常，腹中如故，仍用八珍加桃仁、杏仁治之。若泥其日期饮食之多而通之，则误矣。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后杂证方（五六）\n\n属性：《良方》黄龙汤（妇八五 产后外感） 《良方》交加散（妇百 产后中风） 海藏愈风汤 \n（和二一七 失血筋急搐搦） 交加散（和二五二 产后类风不省人事） 七珍汤（妇七九 产 \n后不语） 补脬饮（妇八一 产后脬破淋沥） 《良方》人参汤（妇七七 产后诸虚） 麻黄根 \n汤（妇八三 产后虚汗） 趁痛散（妇八十 产后发热 骨节疼痛） 加味小柴胡汤（散二十 乳母肝火发热） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\产后类\n\n<篇名>产后类论列总方（五七）\n\n属性：四君子汤（补一） 五君子煎（新热六） 金水六君煎（新和一） 六君子汤（补五） 大补丸 \n煎（新补一） 十全大补汤（补二十） 四物汤（补八） 五物煎（新因三） 补中益气汤（补三十） \n大营煎（新补十四） 小营煎（新补十五） 补阴益气煎（新补十六） 五福饮（新补六） 八珍 \n汤（补十九） 当归六黄汤（寒六五） 温胃饮（新热五） 胃关煎（新热九） 加味四物汤（补九） \n寿脾煎（新热十六） 理阴煎（新热三） 增损四物汤（妇百十） 三阴煎（新补十一） 一阴煎 \n（新补八） 加减一阴煎（新补九） 五阴煎（新补十三） 贞元饮（新补十九） 人参当归汤（妇 \n百十四） 保阴煎（新寒一） 固阴煎（新因二） 一味防风散（妇百十五） 右归饮（新补三） \n蟠葱散（热百十） 当归补血汤（补四四） 羊肉汤（妇七十、七一） 猪腰汤（妇七四） 黄雌鸡 \n汤（妇七二） 母鸡汤（妇七三） 决津煎（新因二） 殿胞煎（新因十） 通瘀煎（新因五） 济川 \n煎（新补二一） 清化饮（新因十三） 失笑散（妇百四） 夺命丹（妇六五） 四神散（妇七五） \n二陈汤（和一） 六安煎（新和二） 五积散（散三九） 抽新饮（新寒三） 徙薪饮（新寒四） 延 \n胡索散（妇九八） 白茯苓散（妇七八） 正柴胡饮（新散六） 一柴胡饮（新散一） 三柴胡饮（ \n新散三） 四柴胡饮（新散四） 五柴胡饮（新散五） 九蜜煎（新因十二） 大岩蜜汤（妇七六） \n回生丹（妇六六） 排气饮（新和六） 大和中饮（新和七） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\带浊遗淋类\n\n<篇名>带下（五八）\n\n属性：凡妇人淋带，虽分微甚，而实为同类，盖带其微而淋其甚者也。总由命门不固，而不固 \n之病，其因有六∶盖一以心旌之摇之也。心旌摇则命门应，命门应则失其所守，此由于不遂 \n者也。一以多欲之滑之也，情欲无度，纵肆不节，则精道滑而命门不禁，此由于太遂者也。 \n一以房室之逆之也。凡男女相临，迟速有异，此际权由男子，而妇人情兴多致中道而止，止 \n则逆，逆则为浊为淋，此由于遂而不遂，乃女子之最多而最不肯言者也。以上三证，凡带浊 \n之由乎此者，十居八九，而三者之治，必得各清其源，庶可取效。然源未必清，而且旋触旋 \n发，故药饵之功，必不能与情窦争胜，此带浊之所以不易治也。此三者之外，则尚有湿热下 \n流者，有虚寒不固者，有脾肾亏陷而不能收摄者，当各因其证而治之。 \n一、心旌摇，心火不静而带下者，先当清火，宜朱砂安神丸、清心莲子饮、《直指》固 \n精丸之类主之。若无邪火而但见心虚带下者，宜秘丸煎、人参丸、心虚白浊歌、茯兔丸之类。 \n一、欲事过度、滑泄不固而带下者，宜秘丸煎、寿脾煎、固阴煎、苓术菟丝丸、《济生 \n》固精丸、锁精丸、金锁思仙丹之类主之。 \n一、人事不畅，精道逆而为浊为带者，初宜六味地黄汤，或威喜丸之属以利之；久不止 \n者，宜固阴煎、苓术菟丝丸之属以固之。 \n一、湿热下流而为带浊，脉必滑数，色见红赤，证有烦渴而多热者，宜保阴煎、加味逍 \n遥散，或经验猪肚丸亦佳。若热甚兼淋而赤者，宜龙胆泻肝汤。 \n一、元气虚弱而带下者，宜寿脾煎、固阴煎、菟丝煎、七福饮、十全大补汤、九龙丸之 \n属。若阳气虚寒，脉见微涩，色白清冷，腹痛多寒者，宜加姜附，或用家韭子丸。 \n一、脾肾气虚下陷而多带者，宜用寿脾煎、固阴煎、归脾汤、补中益气汤之属。 \n立斋曰∶前证或因六淫七情，或因醉饱房劳，或因膏粱浓味，或服燥剂所伤，或亏损阳 \n气下陷，或湿痰下注蕴积而成，故言带也。凡此皆当壮脾胃、升阳气为主，佐以各经见证之 \n药。若色青者属肝，用小柴胡加山栀；或湿热壅滞，小便赤涩，龙胆泻肝汤。色赤者属心， \n用小柴胡加黄连、山栀、当归；思虑过伤，用妙香散等药。色白者属肺，用补中益气加山栀 \n。色黄者属脾，用六君子加山栀、柴胡；不应，归脾汤。色黑者属肾，用六味地黄丸。若气 \n血俱虚，八珍汤。阳气陷下，补中益气汤。湿痰下注，前汤加茯苓、半夏、苍术、黄柏。气 \n虚痰饮下注，四七汤送肾气丸。不可拘肥人多痰，瘦人多火，而以燥湿泻火之药轻治之也。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\带浊遗淋类\n\n<篇名>带下（五八）\n\n属性：醋附丸（妇百七 气滞带浊，腹中急痛） 金樱膏（补百 虚劳带浊） 克应丸（妇一二八 \n虚滑带浊） 固元丹（固三一 赤白带） 白芷散（妇一二六 下元虚滑） 益母丸（妇六四 \n带浊诸病） 白芍药散（妇一二七 带浊疼痛） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\带浊遗淋类\n\n<篇名>白浊遗淋（五九）\n\n属性：淫浊与带下之不同者，盖白带出于胞宫，精之余也；淫浊出于膀胱，水之浊也。虽膀胱 \n与肾为表里，故带浊之源，无非皆出于阴分，然带由脾肾之虚滑者多，淫浊由膀胱之湿热者 \n多，此其所以有辨也。若淫浊初起而见热涩者，宜大厘清饮。若初起无火而但有窒塞者，宜 \n小厘清饮，或五苓散。若肝经怒火下流，宜加味逍遥散。若肝火盛而见痛涩者，宜龙胆泻肝 \n汤。若服寒凉利药太过，以致下焦虚寒不固者，宜萆 厘清饮。若元气虚寒下陷者，宜寿脾 \n煎、补中益气汤。若脾湿下流者，宜归脾汤、六君子汤。若久而不愈，肝肾虚滑下陷者，宜 \n寿脾煎、秘丸煎、家韭子丸。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\带浊遗淋类\n\n<篇名>白浊遗淋（五九）\n\n属性：滑石散（妇一二九 热淋） 牛膝膏（和三四六 死血作淋） 三味牛膝汤（寒一二六 血 \n热淋痛） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\带浊遗淋类\n\n<篇名>妇人梦与鬼交（六十）\n\n属性：人禀五行正气以生，气正则正，气邪则邪，气强则神旺，气衰则鬼生，如《刺法论》曰 \n∶神失守位，则邪鬼外干，即此类也。然妇人之梦与邪交，其证有二∶一则由欲念邪思，牵 \n扰意志而为梦者，此鬼生于心，而无所外干也；一则由禀赋非纯，邪得以入，故妖魅敢于相 \n犯，此邪之自外至者亦有之矣。病因有内外，则证亦有不同。病由内生者，外无形迹，不过 \n于梦寐间常有所遇，以致遗失，及为恍惚带浊等证，亦如男子之梦遗，其机一也，但在女子 \n多不肯言耳。至若外有邪犯者，其证则异。或言笑不常，如有对晤，或喜幽寂，不欲见人； \n或无故悲泣，而面色不变；或面带桃花，其脉息则乍疏乍数，三五不调，或伏沉，或促结， \n或弦细，或代易不常，是皆妖邪之候。凡此二者，若失于调理，久之不愈，则精血日败，真 \n阴日损，乃致潮热发热，神疲体倦，饮食日减，经水日枯，肌肉消削，渐成劳损，脉见紧数 \n，多致不救矣。凡治此者，所因虽有不同，而伤精败血，其病则一。故凡病生于心者，当先 \n以静心为主，然后因其病而药之，神动者安其神、定其志；精滑者固其精、养其阴，尤当以 \n培补脾肾，要约门户，以助生气为主。若为妖魅所侵，则内当调补正气，如归神汤之类；外 \n宜速灸鬼哭穴以驱邪气，则自当渐愈。其穴以两手大指相并缚定，用艾炷于爪甲角骑缝灸之 \n，务令两甲连肉四处着火方效，或七壮，或二七壮。两足大指，亦名足鬼眼。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\带浊遗淋类\n\n<篇名>带浊类论列总方（六一）\n\n属性：人参丸（补百五） 八珍汤（补十九） 朱砂安神丸（寒一四二） 归脾汤（补三二） 六君子 \n汤（补五） 清心莲子饮（寒三二） 妙香散（固十五、十六） 九龙丸（固四二） 十全大补汤（ \n补二十） 寿脾煎（新热十六） 秘丸煎（新固一） 加味逍遥散（补九三） 菟丝煎（新固三） \n固阴煎（新固二） 心虚白浊歌（补百一） 威喜丸（固四五） 茯菟丸（固三八） 补中益气汤（ \n补三十） 锁金丸（固二六） 保阴煎（新寒一） 《济生》固精丸（固二九） 四七汤（和九七） \n五苓散（和一八二） 金锁思仙丹（固十九） 归神汤（妇一二五） 肾气丸（补一二一） 六味 \n地黄汤（补百二十） 七福饮（新补七） 家韭子丸（固三四） 小厘清饮（新和十） 《直指》固 \n精丸（固三十） 小柴胡汤（散十九） 大厘清饮（新寒五） 苓术菟丝丸（新固五） 萆 厘清饮 \n（热一六五） 经验猪肚丸（固四十） 龙胆泻肝汤（寒六三） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\乳病类\n\n<篇名>乳少（六二）\n\n属性：妇人乳汁，乃冲任气血所化，故下则为经，上则为乳。若产后乳迟乳少者，由气血之不 \n足，而犹或无乳者，其为冲任之虚弱无疑也。治当补化源而兼通利，宜猪蹄汤。若乳将至而 \n未得通畅者，宜涌泉散。 \n产妇乳汁不来，其原有二∶盖一因气血不足，故乳汁不来，宜用猪蹄汤，是即虚者补之 \n也。一因肥胖妇人痰气壅盛，乳滞不来者，宜用漏芦汤之类，是壅者行之也。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\乳病类\n\n<篇名>乳出（六三）\n\n属性：产后乳自出，乃阳明胃气之不固，当分有火无火而治之。无火而泄不止，由气虚也，宜 \n八珍汤、十全大补汤。若阳明血热而溢者，宜保阴煎，或四君子汤加栀子。若肝经怒火上冲 \n，乳胀而溢者，宜加减一阴煎。若乳多胀痛而溢者，宜温帛熨而散之。若未产而乳自出者， \n以胎元薄弱，滋溉不全而然，谓之乳泣，生子多不育。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\乳病类\n\n<篇名>吹乳妒乳（六四）\n\n属性：产后吹乳，因儿饮乳，为口气所吹，致令乳汁不通，壅结肿痛，不急治之，多成痈肿。 \n速服栝蒌散，外以南星末敷之，更以手揉散之。势甚者，惟连翘金贝煎最妙。 \n产后妒乳，因无儿饮乳，或儿未能饮，余乳蓄结作胀，或妇人血气方盛，乳房作胀，以 \n致肿痛，憎寒发热，不吮通之，必致成痈。若肿不消，用麦芽二三两炒熟，水煎服，立消。 \n一方∶用陈皮一两，甘草一钱，水煎服。 \n一方∶治吹乳、乳痈肿痛，用萱草根擂酒服之，以滓罨患处。 \n《袖珍方》用猪牙皂角去皮，蜜炙为末，酒服一钱。又诗云∶妇人吹奶法如何？皂角烧 \n灰蛤粉和，热酒一杯调八字，管教时刻笑呵呵。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\乳病类\n\n<篇名>乳痈乳岩（六五）\n\n属性：肿痛势甚，热毒有余者，宜以连翘金贝煎先治之，甚妙。 \n立斋法曰∶妇人乳痈，属胆胃二腑热毒，气血壅滞，故初起肿痛发于肌表，肉色 \n赤，其人表热发热，或发寒热，或憎寒头痛，烦渴引冷，用人参败毒散、神效栝蒌散、加味 \n逍遥散治之，肿自消散。若至数日之间，脓成溃窍，稠脓涌出，脓尽自愈。若气血虚弱，或 \n误用败毒，久不收敛，脓清脉大则难治。乳岩属肝脾二脏郁怒，气血亏损，故初起小核结于 \n乳内，肉色如故，其人内热夜热，五心发热，肢体倦瘦，月经不调，用加味逍遥散、加味归 \n脾汤、神效栝蒌散，多自消散。若积久渐大，□岩色赤出水，内溃深洞为难疗，但用 \n前归脾汤等药可延岁月。若误用攻伐，危殆迫矣。大凡乳证，若因恚怒，宜疏肝清热。 痛 \n寒热，宜发表散邪。 肿痛甚，宜清肝消毒，并隔蒜灸。不作脓或脓不溃，补气血为主。不 \n收敛或脓稀，补脾胃为主。脓出反痛，或发寒热，补气血为主。或晡热内热，补血为主。若 \n饮食少思，或作呕吐，补胃为主。饮食难化，或作泄泻，补脾为主。劳碌肿痛，补气血为主 \n。怒气肿痛，养肝血为主。儿口所吹，须吮通揉散，成痈治以前法。潮热暮热，亦主前药。 \n大抵男子多由房劳耗伤肝肾，妇人郁怒亏损肝脾，治者审之。世有孕妇患此，名曰内吹。然 \n其所致之因则一，惟用药不可犯其胎耳。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\乳病类\n\n<篇名>乳病论列总方（六六）\n\n属性：猪蹄汤（妇八七） 涌泉散（妇八八） 漏芦汤（妇九十） 八珍汤（补十九） 四君子汤（补 \n一） 十全大补汤（补二十） 保阴煎（新寒一） 归脾汤（补三二） 加味归脾汤（补三三） 栝 \n蒌散（妇九一） 神效栝蒌散（外一八一） 加味逍遥散（补九三） 加减一阴煎（新补九） 人参 \n败毒散（散三六） 连翘金贝煎（新因三一） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：（总论，共十二段，六七） \n天地 ，万物化醇，男女构精，万物化生，此造化自然之理也。亦无思无 \n为之道也。故有人道即有夫妇，有夫妇即有子嗣，又何有乏嗣之说？然天有不生之时，地有 \n不毛之域，则人不能无乏嗣之流矣。然则生者自生，乏者当乏，而求嗣之说，又何为也？果 \n可求耶？果不可求耶？则其中亦自有说，亦自有法矣。所谓说者，非为不生不毛者而说也，亦 \n非为少壮强盛者而说也。盖不生不毛者，出于先天之禀赋，非可以人力为也。少壮强盛者， \n出于妙合之自然，不必识，不必知也。惟是能子弗子者，无后难堪，本非天付，衰老无儿者 \n，精力日去，岂比少年，此所以有挽回之人力，则有说而有法矣。虽法之垂诸古者已不为少 \n，然以余觉之，则若有未尽其妙蕴者焉。因而胪列其法，曰天时，曰地利，曰人事，曰药食 \n，曰疾病，总五类二十四条。但凡其一，便足败乃公事矣。宾于晚年得子，率鉴乎此，凡苦 \n于是者，惟察之信之，则祚胤之猷，或非渺小，故命之曰《宜麟》策。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：凡交会下种之时，古云宜择吉日良时，天德月德，及干支旺相，当避丙丁之说，顾以仓 \n猝之顷，亦安得择而后行，似属迂远，不足凭也。然惟天日睛明，光风霁月，时和气爽，及 \n情思清宁，精神闲裕之况，则随行随止，不待择而人人可办，于斯得子，非惟少疾，而必且 \n聪慧贤明，胎元禀赋，实基于此。至有不知避忌者，犯天地之晦冥，则受愚蠢迷蒙之气；犯 \n日月星辰之薄蚀，则受残缺刑克之气；犯雷霆风雨之惨暴，则受狠恶惊狂之气；犯不阴不阳 \n、倏热倏寒之变幻，则受奸险诡诈之气。故气盈则盈，乘之则多寿；气缩则缩，犯之则多夭 \n。顾人生六合之内，凡生长壮老已，何非受气于生成？而知愚贤不肖，又孰非禀质于天地？此 \n感兆元始之大本，苟思造命而赞化育，则当以此为首务。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：干道成男，坤道成女，此固生成之至道，然亦何以见之，亦何以用之？盖乾坤不用，用 \n在坎离，坎离之用，阴阳而已。夫离本居阳，何以为女？以阳之中而阴之初也。坎本居阴， \n何以为男？以阴之中而阳之初也。盖中者盛于上，盛者必渐消；初者生于下，生者必渐长。 \n故阳生于坎，从左而渐升，升则为阳而就明；阴生于离，从右而渐降，降则为阴而就晦，此 \n即阴阳之用也。而千变万化，莫不由之。由之推展，则凡冬至夏至，一岁之阴阳也；子东午 \n西，一日之阴阳也；有节有中，月令之阴阳也；或明或晦，时气之阴阳也；节前节后，消长 \n之阴阳也；月光潮汛，盈虚之阴阳也。再以及人，则老夫女妻，阴若胜矣，有颠之倒之之妙 \n；彼强此弱，阳亦在也，有操之纵之之权，顾无往而非阴阳之用也。知之而从阳避阴，则干 \n道成男；不知而背阳向阴，则坤道成女矣。明眼人其鉴而悟之，笔有难于尽意也。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：地利关于子嗣，非不重也。有阴宅之宜子孙者，常见螽斯之多；有阳宅之宜子嗣者，惟 \n生气天乙方为最吉。然吉地吉人，每多不期而会，所谓有德斯有人，有人斯有土，此其所致 \n之由，自非偶然。故曰必先有心地，而后有阴地，信非诬也。第其理深义邃，有非一言可悉 \n。然宗枝攸系，诚有不可不知者。此外如寝室交会之所，亦最当知宜忌。凡神前庙社之侧， \n井灶冢柩之傍，及日月火光照临，沉阴危险之地，但觉神魂不安之处，皆不可犯。倘有不谨 \n，则夭枉生理残障，飞灾横祸，及不忠不孝之流，从而出矣。验如影响，可不慎哉。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：欲绵瓜瓞，当求基址。盖种植者，必先择地，砂砾之场，安望稻黍；求子者，必先求母 \n，薄福之妇，安望熊罴？倘欲为子嗣之谋，而不先谋基址，计非得也。然而基址之说，隐微 \n叵测，察亦诚难，姑举其显而易者十余条，以见其概云耳。大都妇人之质，贵静而贱动，贵 \n重而贱轻，贵浓而贱薄，贵苍而贱嫩。故凡唇短嘴小者不堪，此子处之部位也。耳小轮薄者 \n不堪，此肾气之外候也。声细而不振者不堪，此丹田之气本也。形体薄弱者不堪，此藏蓄之 \n宫城也。饮食纤细者不堪，此仓廪血海之源也。发焦齿豁者不堪，肝亏血而肾亏精也。睛露 \n臀削者不堪，藏不藏而后无后也。颜色娇艳者不堪，与其华者去其实也。肉肥胜骨者不堪， \n子宫隘而肾气 也。袅娜柔脆，筋不束骨者不堪，肝肾亏而根干不坚也。山根唇口多青气者 \n不堪，阳不胜阴，必多肝脾之滞逆也。脉见紧数弦涩者不堪，必真阴亏弱，经候不调而生气 \n杳然者也。此外，如虎头熊项，横面竖眉，及声如豺野狼之质，必多刑克不吉，远之为宜。又 \n若刚狠阴恶，奸险克薄之气，尤为种类源流，子孙命脉所系，乌可近之？虽曰尧亦有丹朱， \n舜亦有瞽瞍，然二气相合，未必非一优一劣之所致。倘使阴阳有序，种址俱宜，而稼穑有不 \n登者，未之有也。唯一有偏胜，则偏象见矣。是种之不可不择者有如此。不然，则麟趾之诗 \n，果亦何为而作者耶？余因人艰嗣之苦，复见人有不如无之苦。故愿天常生好人，所以并虑及之。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：阴阳之道，合则聚，不合则离；合则成，不合则败。天道人事莫不由之，而尤于斯道为 \n最。合与不合，机有十焉，使能得之，权在我矣。 \n一曰阖辟，乃妇人之动机也。气静则阖，气动则辟，动缘气至，如长鲸之饮川，如巨觥 \n之无滴。斯时也，吸以自然，莫知其入，故未有辟而不受者，未有受而不孕者。但此机在瞬 \n息之间，若未辟而投，失之太早；辟已而投，失之太迟。当此之际，自别有影响情状可以默 \n会，不可以言得也。惟有心人能觉之，带雨施云，鲜不谷矣。 \n二曰迟速，乃男女之合机也。迟宜得迟，速宜见速，但阴阳情质禀有不齐，固者迟，不 \n固者速。迟者嫌速，则犹饥待食，及咽不能；速者畏迟，则犹醉添杯，欲吐不得，迟速不侔 \n，不相投矣。以迟遇疾，宜出奇由迳，勿逞先声；以疾遇迟，宜静以自持，挑而后战，能反 \n其机，适逢其会矣。 \n三曰强弱，乃男女之畏机也。阳强阴弱则畏如蜂虿，避如戈矛；阳弱阴强，则闻风而靡 \n，望尘而北，强弱相凌，而道同意合者鲜矣。然抚弱有道，必居仁由义，务得其心；克强固 \n难，非聚精会神，安夺其魄？此所以强有不足畏，弱有不足虞者，亦在乎为之者之何如耳。 \n四曰远近，乃男女之会机也。或以长材排闼，唐突非堪，或以偷觑跽门，敢窥堂室，欲 \n拒者不能，欲吞者不得，睽隔如斯，其能 乎？然敛迹在形，致远在气，敛迹在一时， \n养气非顷刻，使不有教养之夙谋，恐终无刚劲之锐气，又安能直透重围，而使鸠居鹊巢也。 \n五曰盈虚，乃男女之生机也。胃有盈虚，饱则盈而饥则虚也。肾有盈虚，蓄则盈而泄则 \n虚也。盛衰由之，成败亦由之，不知所用，则得其FS 而失其常耳。 \n六曰劳逸，乃男女之气机也。劳者气散而怯，逸者气聚而坚，既可为破敌之兵机，亦可 \n为种植之农具，动得其宜，胜者多矣。 \n七曰怀抱，乃男女之情机也。情投则合，情悖则离。喜乐从阳，故多阳者多喜；郁怒从 \n阴，故多阴者多怒。多阳者多生气，多阴者多杀气。生杀之气，即孕育贤愚之机也。莫知所 \n从，又胡为而然乎。 \n八曰暗产，乃男子之失机也。勿谓我强，何虞子嗣；勿谓年壮，纵亦何妨。不知过者失 \n佳期，强者无酸味，而且随得随失，犹所莫知，自一而再，自再而三，则亦如斯而已矣。前 \n有小产论，所当并察之。 \n九曰童稚，乃女子之时机也。方苞方萼，生气未舒，甫童甫笄，天癸未裕，曾见有未实 \n之粒可为种否？未足之蚕可为茧否？强费心力而年衰者能待乎？其亦不知机也矣。 \n十曰二火，乃男女之阳机也。夫君火在心，心其君主也；相火在肾，肾其根本也。然二 \n火相因，无声不应，故心宜静，不静则火由欲动，而自心挑肾。先心后肾者，以阳烁阴，出 \n乎勉强，勉强则气从乎降，而丹田失守，已失元阳之本色。肾宜足，肾足则阳从地起，而由 \n肾及心。先肾后心者，以水济火，本乎自然，自然则气主乎升，而百脉齐到，斯诚化育之真 \n机。然伶薄之夫每从勉强，故多犯虚劳，讵云子嗣？朴浓之子，常由自然，故品物咸亨，奚 \n虑后人？知机君子，其务阳道之真机乎。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：无故置外家，大非美事。凡诸反目败乱多有由之，可已则已，是亦齐家之一要务也。其若 \n年迈妻衰，无后为大，则势有不得不置者。然置之易而蓄之难，使蓄不有法，则有蓄之名， \n无蓄之实，亦仍与不蓄等耳。而蓄之之法，有情况焉，有寝室焉。以情况言之，则主母见外家 \n，大都非出乐从，所以或多嗔怒，或多骂詈，或因事责其起居，或假借加以声色，是皆常情 \n之所必至者。而不知产育由于血气，血气由于情怀，情怀不畅，则冲任不充，冲任不充，则 \n胎孕不受，虽云置外家，果何益与？凡蓄外家之不可过严者以此。再以寝室言之，则宜静宜远， \n宜少近耳目者为妙。盖私构之顷，锐宜男子，受宜女人，其锐其受，皆由乎气。当此时也， \n专则气聚而直前，怯则气馁而不摄，此受与不受之机也。然勇怯之由，其权在心。盖心之所 \n至，气必至焉。心有疑惧，心不至矣。心有不至，气亦不至矣。倘临期惊有所闻，则气在耳 \n而不及器矣。疑有所见，则气在目而不及器矣。或忿或畏，则气结在心而不至器矣。气有不 \n至，则如石投水，而水则无知也。且如两阵交锋，最嫌奸细之侦伺，一心无二，何堪谗间以 \n相离。闺思兵机，本无二致，凡外家室之不可不静而远者以此。虽然，此不过为锦囊无奈者设 \n，倘有高明贤淑，因吾言而三省，惟宗祧之是虑，不惟不妒，而且相怜，则愈近愈慰，而远 \n之之说，岂近人情？又若有恭谨良人，小心奉治，则求容已幸，又安敢有远而敬之之念。其 \n然其然，吾未如之何也已。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：种子之方，本无定轨，因人而药，各有所宜。故凡寒者宜温，热者宜凉，滑者宜涩，虚 \n者宜补，去其所偏，则阴阳和而生化着矣。今人不知此理，而但知传方，岂宜于彼者亦宜于 \n此耶？且或见一人偶中，而不论宜否，而遍传其神，竞相制服，又岂知张三之帽，非李四所 \n可戴也。今录十方于后，择宜用之，庶获济矣。 \n一、妇人血气俱虚，经脉不调，不受孕者，惟毓麟珠随宜加减用之为最妙；其次，则八 \n珍益母丸亦佳。若脏寒气滞之甚者，用续嗣降生丹亦妙。 \n一、男子脏气平和而惟精血不足者，宜还少丹、全鹿丸、无比山药丸。若右肾阳气不足 \n者，宜右归丸，或毓麟珠俱妙。若阳痿精衰，虚寒年迈艰嗣者，必宜赞育丹。若阳盛阴虚， \n左肾精气不足者，宜左归丸，或延年益嗣丹。若火盛水亏，多内热者，宜大补阴丸。此外， \n如河车种玉丸、乌鸡丸、黑锡丹之类，皆可酌用。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：凡男女胎孕所由，总在血气。若血气和平，壮盛者无不孕育，亦育无不长。其有不能孕 \n者，无非气血薄弱，育而不长者，无非根本不固。即如诸病相加，无非伤损血气。如果邪逆 \n未除，但当以煎剂略为拨正；拨正之后，则必以调服气血为主，斯为万全之策。所以凡用种 \n子丸散，切不可杂以散风消导，及败血苦寒峻利等药。盖凡宜久服而加以此类，则久而增气 \n，未有不反伤气血，而难于孕者也。再若香附一物，自王好古曰∶乃妇人之仙药，多服亦能 \n走气。而后世不言走气，但相传曰∶香附为妇人之要药。由是但治妇人，则不论虚实，无弗 \n用之。不知香附气香味辛性燥，惟开郁散气、行血导滞，乃其所长。若气虚用之，大能泄气 \n；血虚用之，大能耗血。如古方之女金丹，又四制香附丸之类，惟气实血滞者用之为宜。凡 \n今妇人十有九虚，顾可以要药二字而一概用之乎？用之不当，则渐耗渐弱，而胎元之气必反 \n将杳然矣。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：凡饮食之类，则人之脏气各有所宜，似不必过为拘执，惟酒多者为不宜。盖胎种先天之 \n气，极宜清楚，极宜充实，而酒性淫热，非惟乱性，亦且乱精。精为酒乱，则湿热其半，真 \n精其半耳。精不充实则胎元不固，精多湿热，则他日痘疹、惊风、脾败之类，率已受造于此 \n矣。故凡欲择期布种者，必宜先有所慎，与其多饮，不如少饮，与其少饮，犹不如不饮，此 \n亦胎元之一大机也。欲为子嗣之计者，其毋以此为后着。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：疾病之关于胎孕者，男子则在精，女人则在血，无非不足而然。凡男子之不足，则有精 \n滑、精清、精冷者，及临事不坚，或流而不射者，或梦遗频数，或便浊淋涩者。或好色以致 \n阴虚，阴虚则腰肾痛惫；或好男风以致阳极，阳极则亢而亡阴；或过于强固，强固则胜败不 \n洽；或素患阴疝，阴疝则肝肾乖离。此外，则或以阳衰，阳衰则多寒；或以阴虚，阴虚则多 \n热。若此者，是皆男子之病，不得盖诿之妇人也。倘知其由而宜治则治之，宜反则反之，必 \n先其在我而后及妇人，则事无不济矣。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>宜麟策\n\n属性：妇人所重在血，血能构精，胎孕乃成。欲察其病，惟于经候见之。欲治其病，惟于阴分 \n调之。盖经即血也，血即阴也，阴以应月，故月月如期，此其常也。及其为病，则有或先或 \n后者，有一月两至者，有两月一至者，有枯绝不通者，有频来不止者，有先痛而后行者，有 \n先行而后痛者，有淡色、黑色、紫色者，有瘀而为条为片者，有精血不充而化作白带、白浊 \n者，有子宫虚冷而阳气不能生化者，有血中伏热而阴气不能凝成者，有血症气痞，子脏 \n不收，月水不通者。凡此皆真阴之病也。真阴既病，则阴血不足者不能育胎，阴气不足者不 \n能摄胎。凡此摄育之权，总在命门，正以命门为冲任之血海，而胎以血为主，血不自生，而 \n又以气为主，是皆真阴之谓也。所以凡补命门，则或气或血，皆可谓之补阴，而补阴之法， \n即培根固本之道也。凡自壮至老，乃人人之所不可缺者，而矧以先天后天之肇基，又将舍是 \n而何求乎？是以调经种子之法，亦惟以填补命门，顾惜阳气为之主。然精血之都在命门，而 \n精血之源又在二阳心脾之间。盖心主血，养心则血生；脾胃主饮食，健脾胃则气布。二者胥 \n和，则气畅血行，此情志饮食又当先经脉而为之计者，亦无非补阴之源也。使不知本末先后 \n，而妄为之治，则又乌足以言调经种子之法。（以上宜麟策终） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>盈虚吟（六八）\n\n属性：谁识雌雄在坎离，玄关消息有真机。坎虚离实云非是，坎实离虚亦是非。天以至刚方得 \n体，地缘无日乃成泥。三生同有金丹在，试问仙翁知不知？ \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>辨古（六九）\n\n属性：种子之法，古人言之不少，而余谓其若未尽善者，盖亦有疑而云然。谨并列而辨之，亦 \n以备达者之裁正。 \n一、《广嗣诀》云∶三十时辰两日半，二十八九君须算，落红满地是佳期，金水过时徒 \n霍乱，霍乱之时枉费功，树头树底觅残红，但解开花能结子，何愁丹桂不成丛。按∶此言妇 \n人经期方止，其时子宫正开，便是布种之时，过此佳期，则子宫闭而不受胎矣。然有十日半 \n月及二十日之后受胎者，又何为其然也。又一哲妇曰∶若根据此说，则凡有不端者，便于后半 \n月为之，自可无他虑矣。善哉言也，此言果可信否？ \n一、《道藏经》曰∶妇人月信止后一日、三日、五日合者，干道成男；二日、四日、六 \n日合者，坤道成女。按∶此以单数属阳，故成男；偶数属阴，故成女。果若然，则谁不知之 \n，得子何难也？总未必然。 \n一、《褚氏遗书》云∶男女之合，二情交畅。若阴血先至，阳精后冲，血开裹精，精入 \n为骨而男形成矣；阳精先至，阴血后参，精开裹血，血入为本而女形成矣。按此一说，余初 \n见之，甚若有味有理，及久察之，则大有不然。盖相合之顷，岂堪动血，惟既结之后，则精 \n以肇基，血以滋育而胎渐成也。即或以血字改为精字，曰阴精先至，似无不可。然常见初笄 \n女子，有一合而即孕者，彼于此时，畏避无暇，何云精泄？但其情动则气至，气至则阴辟， \n阴辟则吸受，吸受则无不成孕，此自然之正理也。若褚氏之说，似穿凿矣。 \n一、东垣曰∶经水断后一二日，血海始净，精胜其血，感者成男；四五日后，血脉已旺 \n，精不胜血，感者成女。按∶此说亦非确论。今见多生女者，每加功于月经初净而必不免于 \n女者，岂亦其血胜而然乎。 \n一、丹溪曰∶阴阳交构，胎孕乃凝，所藏之处，名曰子宫，一系在下，上有两岐，中分 \n为二，形如合钵，一达于左，一达于右。精胜其血，则阳为之主，受气于左子宫而男形成； \n精不胜血，则阴为之主，受气于右子宫而女形成。按∶此乃与《圣济经》左动成男，右动成 \n女之说同。第以子粒验之，无不皆有两瓣，故在男子亦有二丸，而子宫之义谅亦如此，信非 \n谬也。惟左受成男、右受成女之说，则成非事后莫测其然。即复有左射右射之法，第恐阴中 \n阖辟，自有其机，即欲左未必左，欲右未必右。而阴阳相胜之理，则在天时人事之间，似仍 \n别有一道，虽知此说，终无益也。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>述古（七十）\n\n属性：《褚氏遗书》曰∶建平孝王妃姬皆丽无子，择民家未笄女子入御，又无子，问曰∶求男 \n有道乎？澄对曰∶合男女必当其年，男虽十六而精通，必三十而娶；女虽十四而天癸至，必 \n二十而嫁。皆欲阴阳完实，然后交而孕，孕而育，育而子坚壮强寿。今未笄之女，天癸始至 \n，已近男色，阴气早泄，未完而伤，未实而动，是以交而不孕，孕而不育，而子脆不寿，此 \n王之所以无子也。然妇人有所产皆女者，有所产皆男者，大王诚能访求多男妇人至宫府，有 \n男之道也。王曰∶善。未再期生六男。夫老阳遇少阴，老阴遇少阳，亦有子之道也。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\子嗣类\n\n<篇名>子嗣类论列总方（七一）\n\n属性：毓麟珠（新因十四） 左归丸（新补四） 右归丸（新补五） 赞育丹（新因又十四） 还少丹 \n（补一三五） 全鹿丸（补一二七） 无比山药丸（补一三六） 延年益嗣丹（妇一三五） 大补阴 \n丸（寒一五七） 八珍益母丸（妇一三八） 续嗣降生丹（妇一三六） 女金丹（妇一三三） 四制 \n香附丸（妇一三二） 河车种玉丸（妇一三七） 乌鸡丸四方（妇一三九后） 黑锡丹（热一八九） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\瘕类\n\n<篇名>论证（七二）\n\n属性：瘕之病，即积聚之别名。《内经》止有积聚疝瘕，并无证字之名，此后世之所增 \n设者。盖 者征也；瘕者，假也。征者成形而坚硬不移者是也，假者无形而可聚可散者 \n是也。成形者，或由血结，谓之血 ，或由食结，谓之食 。无形者惟在气分，气 \n滞则聚而见形，气行则散而无迹。此 瘕之辨也。然又有痛者，有不痛者。痛者联于气 \n血，所以有知，气血行则愈，故痛者易治；不痛者不通气血，别结窠囊，药食难及，故不痛 \n者难治，此又治之有辨也。其他如肺之积曰息奔，心之积曰伏梁，脾之积曰痞气，肝之积曰 \n肥气，肾之积曰奔豚，以至后世有曰 癖、曰痞块之属，亦不过以形见之处有不同，故名亦 \n因之而异耳。总之非在气分，则在血分。知斯二者，则 瘕二字已尽之矣。但血 \n气瘕，各有虚实，而宜攻宜补，当审之真而用之确也。诸经义另详积聚门，所当参阅。 \n《骨空论》曰∶任脉为病，男子内结七疝，女子带下瘕聚。张子和曰∶遗溺闭癃，阴痿 \n脬痹，精滑白淫，皆男子之疝也。若血涸、月事不行，行后小腹有块，或时动移，前阴突出 \n，后阴痔核，皆女子之疝也。但女子不谓之疝，而谓之瘕。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\瘕类\n\n<篇名>血症（七三）\n\n属性：瘀血留滞作症，惟妇人有之。其证则或由经期，或由产后，凡内伤生冷，或外受风 \n寒，或恚怒伤肝，气逆而血留，或忧思伤脾，气虚而血滞，或积劳积弱，气弱而不行，总由 \n血动之时，余血未净，而一有所逆，则留滞日积而渐以成症矣。然血必由气，气行则血 \n行。故凡欲治血，则或攻或补，皆当以调气为先。罗谦甫曰∶养正邪自除。必先调养，使营 \n卫充实。若不消散，方可议下。但除之不以渐，则必有颠覆之害。若不守禁忌，纵嗜欲，其 \n有不丧身者鲜矣。 \n一、血瘀作痛，或成形不散，在脐腹之下。若暂见停蓄而根盘未固者，只宜五物煎，或 \n决津煎加减主之，则血无不去，痛无不止，足称神剂。 \n一、妇人形气病气俱实，或腹胀，或痛甚，而新有所逆，但欲行滞止痛者，宜通瘀煎、 \n失笑散、玄胡当归散、加减四物汤之类，疏之导之，气通滞去，痛必自愈。若稍久且坚而欲 \n消之磨之，宜三棱煎、万病丸之类主之。 \n一、形气强壮而瘀血不行，或大病结闭，或腹胀痛甚，有非下不可者，宜《良方》桃仁 \n承气汤下之最捷，或用夺命丹、桃仁煎、穿山甲散、赤金豆之类皆可。然下须详慎，非有大 \n实不得已之证，不宜妄用。 \n一、养正之法，当察阴阳上下，病之久新，及邪正强弱之势。其有停瘀虽甚而元气困弱 \n者，不可攻。病久而弱，积难摇动者，不可攻。凡此之类，皆当专固根本，以俟其渐磨渐愈 \n，乃为良策。如郁结伤脾者，宜用归脾汤、逍遥饮、寿脾煎。脾胃虚寒者，宜温胃饮、养中 \n煎、六君子汤。肝肾虚寒者，宜大营煎、暖肝煎、理阴煎，或《良方》交加散亦可。脾肾虚 \n寒，大便泄泻或不实者，宜胃关煎、理阴煎。病久脾肾气滞而小腹痛胀者，宜八味地黄丸。 \n肝火不清，血热而滞者，宜加味逍遥散。以上诸证，凡虚中带滞者，不妨于前药中各加行气 \n导滞之品，此在用者之圆活也。 \n一、妇人久 宿痞，脾肾必亏，邪正相搏，牢固不动，气联子脏则不孕，气联冲任 \n则月水不通。内治之法宜如前，外以阿魏膏贴之，仍用熨痞方，或用琥珀膏亦可。然必须切 \n慎七情及六淫、饮食起居，而不时随证调理，庶乎可愈。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\瘕类\n\n<篇名>食（七四）\n\n属性：凡饮食留聚而为 痞者，或以生冷，或以风寒，或以忿怒气逆，或以劳倦饥馁，而 \n饮食叠进不用消化，则积而成 矣。然胃气强者必不致留聚饮食，而饮食之不能化者， \n必由脾肾气弱而然。所以治此者，宜酌虚实而为攻补，庶乎得效也。诸治法详积聚门，宜参 \n而用之。 \n立斋曰∶前证若形气虚弱，须先调补脾胃为主，而佐以消导。若形气充实，当先疏导为 \n主，而佐以补脾胃。若气壅血滞而不行者，宜用乌药散，散而行之。若脾气虚而血不行者， \n宜用四君、芎、归，补而行之。若脾气郁而血不行者，宜用归脾汤，解而行之。若肝肾血燥 \n而不行者，宜用加味逍遥散，清而行之。大抵食积痞块之证，皆以邪气盛则实，真气夺则虚 \n，但当养正辟邪，而积自除矣。虽曰坚者削之，客者除之，若胃气未虚，或可少用。若病久 \n虚乏者，不宜轻用。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\瘕类\n\n<篇名>气瘕（七五）\n\n属性：瘕者，假也。所谓假者，谓其形虽若 ，而原无根窠，非若 痞之坚顽有形者 \n也。盖有形者，或因血积，或因食积，积有定形，所不可移易者也。无形者，病在气分，气 \n逆则甚，气散则缓，聚散无根者也。惟其无根，故能大能小，或左或右。或近胁肋而如臂如"}, {"n": 22, "text": "卷二十二\n\n指，则谓之 癖；或下脐腹而为胀为急，则谓之疝瘕。《难经》曰∶病有积聚，何以别之？ \n然，积者阴气也，阴沉而伏。聚者阳气也，阳浮而动。故积者五脏之所生，聚者六腑之所成 \n也。然则 由于积，积在阴分而有渊薮，故攻之非易；瘕由于聚，聚在阳分而犹乌合。 \n故散之非难，此 瘕之辨有如此。惟散之之法，最有因通因塞之妙用，而人多莫之知也 \n。 \n一、凡病在气分，而无停蓄形积者，皆不可下。盖凡用下者，可除有形，而不可以除无 \n形。若气因形滞者，去其积则气亦顺，自无不可。若全在无形气分，即下亦不去，而适足以 \n败正气也，宜切识之。 \n一、散气之法，止在行气，盖气行则散也。但行气之法，大有权宜。如气实则壅滞，宜 \n破而行之；气闭则留蓄，宜利而行之；气热则干涸，宜寒而行之；气寒则凝结，宜温而行之 \n。此散气治瘕之大法也。然瘕聚之证，使果气强力健，则流行不息，又何瘕聚之有？惟正气 \n不行，而后邪气得聚。经曰∶邪之所凑，其气必虚。故凡为此病，必气虚者多，虚不知补， \n则正气不行，正气不行，则邪气不散，安望其有瘳乎？但实者有据，故显而易见，虚每似实 \n，故隐而难知，此所以当辨其真也。 \n一、破气行气之剂，凡气实气壅之甚而为胀为痛者，宜排气饮、木香顺气散、木香调气 \n散、四磨汤、诸七气汤之类主之。若血中之气滞而为瘀为痛者，宜失笑散、通瘀煎、调经饮 \n，甚者《良方》奇命丹。疝瘕气聚者，荔香散，甚者天台乌药散。气结膀胱，小水不利者， \n小厘清饮、四苓散、五苓散。气结大肠，干秘不行者，搜风顺气丸、麻仁丸。水亏血虚而秘 \n滞者，济川煎；肝气逆而为聚者，解肝煎，兼火者，化肝煎。气聚兼热，火郁不行者，抽薪 \n饮、大厘清饮。寒滞不行，气结胀聚者，抑扶煎、和胃饮、丁香茯苓汤。三焦壅滞，气道不 \n清而中满肿胀者，廓清饮。痰饮水气停蓄胸胁，而为吞酸呕逆者，苓术二陈煎、六安煎、和 \n胃饮、括痰丸之类主之。以上诸法，惟气实瘕聚者宜之，凡元气不足者，皆不可用。 \n一、补气以行气之剂，如圣愈汤、参归汤、七福饮，皆能调心气之虚滞。五味异功散、 \n参术汤，能理心脾之气虚不行。独参汤、参附汤，能助肺以行五脏之治节。若脾胃气虚而滞 \n者，惟六君子汤、归脾汤为宜。脾胃虚寒而滞者，必温胃饮、理中汤、五君子煎最佳。若虚 \n在脾肾阴分，气有不行而或为痰饮，或为胀满，或为呕吐腹痛等证，非理阴煎不可。若虚在 \n血中之气而为滞为痛，微则四物汤，甚则五物煎、决津煎、大营煎方可。若肝肾寒滞，小腹 \n气逆而痛者，必暖肝煎以温之。若脾肾气虚，门户不要而为滞为痛者，必胃关煎以固之。若 \n元气下陷，滞而不升者，宜补中益气汤、举元煎以举之。若元气大虚，气化不行而滞者，必 \n五福饮、十全大补汤、大补丸煎，或六味回阳饮以培补之。以上皆补气行气之法也。亦不过 \n为之筌蹄云耳。而此中之用，诚有未可以言悉者。然常人之情，犹为气之滞者，惟破之散之 \n为宜；而反云补之，必不然也。不知客之强者，以主之弱；邪之胜者，惟正之虚。凡今人之 \n病虚者最多，而用补者最少，治与病违，而欲以药济人，盖亦罕矣。即余以多虚少实，谆谆 \n为言，而人亦未信，姑以人事喻之，其或可晓然乎。夫人之虚实，亦犹人之贫富。气实者若 \n富翁，气虚者若贫士，今人于千百中，而富者其几？舍富之外，尽贫人矣。其多其少，即此 \n类也。又有华其貌而罄其室者，人多难测，亦此类也。但贫人之情，可益不可损，增一分犹 \n然未足，削一分其窘何堪？使以潜消暗剥之术，而加之贫寒窘乏之士，阴移人祚而人不之觉 \n，亦甚堪怜矣。此道以仁为术，其可不以此为心乎？嗟乎！人生以气为主，得气则生，失气则 \n死。夫知者知人之命，不知者知人之病。若强不知以为知，而徒资便给，以人命为尝试者， \n则其概可知矣。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\瘕类\n\n<篇名>瘕类论列总方（七六）\n\n属性：四君子汤（补一） 五君子煎（新热六） 六君子汤（补五） 四物汤（补八） 五物煎（新因 \n三） 五味异功散（补四） 五福饮（新补六） 七福饮（新补七） 十全大补汤（补二十） 圣愈 \n汤（补九十） 大补丸煎（新补一） 补中益气汤（补三十） 参术汤（补四十） 参归汤（补三八） \n六味回阳饮（新热二） 参附汤（补三七） 独参汤（补三五） 六味地黄丸（补百二十） 举丸 \n煎（新补十七） 大营煎（新补十四） 八味地黄丸（补一二一） 寿脾煎（新热十六） 逍遥饮（ \n新因一） 加味逍遥散（补九三） 归脾汤（补三二） 养中煎（新热四） 苓术二陈煎（新和四） \n温胃饮（新热五） 胃关煎（新热九） 丁香茯苓汤（热六三） 理中汤（热一） 理阴煎（新热 \n三） 天台乌药散（和三二九） 暖肝煎（新热十五） 和胃饮（新和五） 木香调气散（和四四） \n解肝煎（新和十一） 化肝煎（新寒十） 木香顺气散（和四三） 排气饮（新和六） 抑扶煎（ \n新热十一） 搜风顺气丸（和三四三） 乌药散（和七四） 六安煎（新和二） 桃仁承气汤（攻四 \n）四磨汤（和五二） 廓清饮（新和十三） 大厘清饮（新和五） 抽薪饮（新寒三） 济川煎（新 \n补二一） 小厘清饮（新和十） 七气汤（和四七） 调经饮（新因四） 《良方》交加散（妇百） \n决津煎（新因二） 通瘀煎（新因五） 加减四物汤（妇百十二） 失笑散（妇百四） 五苓散（ \n和一八二） 玄胡当归散（妇九八） 三棱丸（攻三七、六十） 荔香散（新因二八） 四苓散（和 \n一八七） 夺命丹（妇六五） 括痰丸（新和十九） 穿山甲散（攻四十） 桃仁煎（攻三九） 赤 \n金豆（新攻二） 麻仁丸（攻九二） 万病丸（妇一四三） 熨痞方（攻八八） 琥珀膏（外三一七） 阿魏膏（外三一二） \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\前阴类\n\n<篇名>阴挺（七七）\n\n属性：妇人阴中突出如菌如芝，或挺出数寸，谓之阴挺。此或因胞络伤损，或因分娩过劳，或 \n因郁热下坠，或因气虚下脱，大都此证当以升补元气、固涩真阴为主。如阴虚滑脱者，宜固 \n阴煎、秘元煎。气虚陷下者，补中益气汤、十全大补汤。因分娩过劳气陷者，寿脾煎、归脾 \n汤。郁热下坠者，龙胆泻肝汤、加味逍遥散。 \n\\x水杨汤\\x 治妇人阴中生物痒痛，牵引腰腹，多由房事太过，或因淫欲不遂，或因非理所 \n为，以致阴户有伤，名曰阴挺。 \n金毛狗脊 五倍子 枯矾 鱼腥草 水杨根 黄连（各一两） \n上为末。分四剂，用有嘴瓦罐煎汤，外预以竹筒去节，接罐嘴，引热气熏入阴中，或透 \n挺上。俟汤温，仍用洗沃之。仍服治挺诸药。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\前阴类\n\n<篇名>阴肿（七八）\n\n属性：妇人阴肿，大都即阴挺之类。然挺者多虚，肿者多热。如气陷而热者，升而清之，宜清 \n化饮，如柴胡、防风之属。气闭而热者，利而清之，宜大厘清饮、徒薪饮。肝肾阴虚而热者 \n，加味逍遥散。气虚气陷而肿者，补中益气汤。因产伤阴户而肿者，不必治肿，但调气血， \n气血和而肿自退。或由损伤气滞，无关元气而肿者，但以百草汤熏洗之为妙。 \n一方∶治阴中肿痛。用枳壳半斤，切，炒，乘热以帛裹熨之，以消其外；仍用少许乘热 \n裹纳阴中，冷即易之，不三次愈。 \n一方∶用小麦、朴硝、白矾、五倍子、葱白煎汤浸洗。 \n\\x甘菊汤\\x 治阴户肿。用甘菊苗叶不拘多少，捣烂，以百沸汤淋汁熏浸洗之。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\前阴类\n\n<篇名>阴疮（七九）\n\n属性：妇人阴中生疮，多由湿热下注，或七情郁火，或纵情敷药，中于热毒。其外证则或有阴 \n中挺出如蛇头者，谓之阴挺；如菌者，谓之阴菌；或如鸡冠，或生虫湿痒，或内溃肿烂疼痛 \n，常流毒水。其内证则或为体倦内热，经候不调，或为饮食不甘，晡热发热，或为小腹痞胀 \n，腰胁不利，或为小水淋沥，赤白带下。凡治此之法，若肿痛内外俱溃者，宜芍药蒺藜煎为 \n最佳，或四物汤加栀子、丹皮、胆草、荆芥，或用加味逍遥散。若湿痒者，宜芍药蒺藜煎， \n或归脾汤加柴、栀、丹皮。淋涩者，宜龙胆泻肝汤加白术、丹皮。淋涩而火盛痛胀者，宜大 \n厘清饮，或抽薪饮。肿而坠毒者，补中益气汤加山栀、丹皮。可洗者用百草煎。可敷者宜螵 \n蛸散、完疮散。 \n\\x蛇蜕散\\x 治妇人阴疮。先以荆芥、蛇床子汤熏洗，挹干敷药。 \n蛇蜕（一条烧存性） 枯矾 黄丹 蓄 本（各一两） 硫黄 荆芥穗 蛇床子（各五钱） \n上为细末，香油调搽，湿则干掺。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\前阴类\n\n<篇名>阴痒（八十）\n\n属性：妇人阴痒者，必有阴虫，微则痒，甚则痛，或为脓水淋沥，多由湿热所化，名曰 \n。内宜清肝火，以龙胆泻肝汤，及加味逍遥散主之；外宜桃仁研膏，和雄黄末，或同难肝纳 \n阴中，以制其虫。然无如银朱烟搽鸡肝以纳之，尤妙。 \n\\x椒茱汤\\x 治妇人阴痒不可忍，惟以热汤泡洗，有不能住手者。 \n花椒 吴茱萸 蛇床子（各一两） 藜芦（半两） 陈茶（一撮） 炒盐（二两） \n以水五升煎汤，乘热熏洗。 \n杏仁膏 治妇人阴痒不可忍。 \n杏仁（烧存性） 麝香（少许） \n上为末。用旧帛裹之，缚定火上炙热，纳阴中。 \n\\x椿根皮汤\\x 治阴痒突出。 \n臭椿皮 荆芥穗 藿香（等分） \n上锉。煎汤熏洗，即痒止而入。 \n一方∶治疳虫下蚀下部。用蒲黄、水银研匀敷入，外以鹤虱草煎汤熏洗。 \n炙肝散∶治妇人阴痒虫蚀。用牛肝或猪肝，切三寸长，大如钱，炙熟纳阴中，引虫出尽即愈。 \n一方∶治阴中虫痒。捣桃叶，绵裹纳阴中，日易三四次。 \n一方∶治阴痒。用蛇床子一两，白矾五钱，煎汤淋洗。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\前阴类\n\n<篇名>阴冷（八一）\n\n属性：妇人阴冷，有寒证，有热证。寒由阳虚，真寒证也；热由湿热，假寒证也。假寒者必有 \n热证，如小便涩数黄赤，大便燥结，烦渴之类是也；真寒者，小便清利，阳虚畏寒者是也。 \n真寒者，宜补其阳，如理阴煎、十补丸、加减续嗣降生丹；假寒者，当清其火，宜龙胆泻肝 \n汤、加味逍遥散。肝肾虚寒者，宜暖肝煎、镇阴煎、大营煎。脾胃虚寒者，宜理中汤、理阴 \n煎、寿脾煎之类主之。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\前阴类\n\n<篇名>交接出血而痛（八二）\n\n属性：凡妇人交接即出血者，多由阴气薄弱，肾元不固，或阴分有火而然。若脾虚气陷不能摄 \n血者，宜补中益气汤，或补阴益气煎。若脾肾虚弱阴气不固者，宜寿脾煎、归脾汤。若肝肾 \n阴虚不守者，宜固阴煎。若阴火动血者，宜保阴煎。 \n\n\n\n<目录>卷之三十九人集·妇人规（下）\\前阴类\n\n<篇名>前阴类论列总方（八三）\n\n属性：固阴煎（新固二） 保阴煎（新寒一） 补中益气汤（补三十） 理阴煎（新热三） 理中汤（热一） \n补阴益气煎（新补十六） 归脾汤（补三二） 寿脾煎（新热十六） 加味精逍遥散（补九三） 四物汤（补八） \n秘元煎（新固一） 续嗣降生丹（妇一三六） 清化饮（新因十三） 大营煎（新补十四） 芍药蒺藜煎（新因三五） 大营煎（新补十四） 暖肝煎（新热十五） 镇阴煎（新热十三） 十补丸（热一七三） 徒薪饮（新寒四） \n大厘清饮（新寒五） 百草煎（新因三七） 螵蛸散（新因三八） 银朱烟（新因五三） 抽薪饮（新寒三） 完 \n疮散（新因五九） \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：小儿之病，古人谓之哑科，以其言语不能通，病情不易测。故曰∶宁治十男子，莫治一妇人； \n宁治十妇人，莫治一小儿。此甚言小儿之难也。然以余较之，则三者之中，又为小儿为最易。何以 \n见之？盖小儿之病非外感风寒，则内伤饮食，以至惊风吐泻，及寒热疳痫之类，不过数种，且其脏 \n气清灵，随拨随应，但能确得其本而撮取之，则一药可愈，非若男妇损伤，积痼痴顽者之比，余故 \n谓其易也。第人谓其难，谓其难辨也；余谓其易，谓其易治也，设或辨之不真，则诚然难矣。然辨 \n之之法，亦不过辨其表里、寒热、虚实，六者洞然，又何难治之有？故凡外感者，必有表证而无里 \n证，如发热、头痛、拘急、无汗，或因风搐搦之类是也；内伤者，止有里证而无表证，如吐泻、腹 \n痛、胀满、惊疳、积聚之类是也；热者必有热证，如热渴、躁烦、秘结、痈疡之类是也；寒者必有 \n寒证，如清冷吐泻，无热无烦，恶心喜热者是也，凡此四者，即表里寒热之证，极易辨也。然于四 \n者之中，尤惟虚实二字最为紧要，盖有形色之虚实，有声音之虚实，有脉息之虚实，如体质强盛与 \n柔弱者有异也，形色红赤与青白者有异也，声音雄壮与短怯者有异也，脉息滑实与虚细者有异也， \n故必内察其脉候，外观其形气，中审其病情，参此数者而精察之，又何虚实之难辨哉。必其果有实 \n邪，果有火证，则不得不为治标，然治标之法，宜精简轻锐，适当其可，及病则已，毫毋犯其正气，斯为高手 \n但见虚象，便不可妄行攻击，任意消 \n耗。若见之不真，不可谓姑去其邪，谅亦无害，不知小儿以柔嫩之体，气血未坚，脏腑甚脆，略受 \n伤残，萎谢极易，一剂之谬尚不能堪，而况其甚乎。矧以方生之气，不思培植而但知剥削，近则为 \n目下之害，远则遗终身之羸，良可叹也。凡此者，实求本之道，诚幼科最要之肯綮，虽言之若无奇 \n异，而何知者之茫然也。故余于篇端，首以为言，然非有察察之见者，固不足以语此，此其所以不 \n易也。 \n阴阳应象大论曰∶善诊者，察色按脉，先别阴阳。审清浊而知部分，视喘息、听声音而知所苦 \n，观权衡规矩而知病所主。按此论虽通言诊法之要，然尤于小儿为最切也。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：小儿初生，饮食未开，胃气未动，是诚清虚之腑，此时开口调变，极须得宜。保婴诸书皆云分 \n娩之时，口含血块，啼声一出，随即咽下，而毒伏于命门，因致他日发为惊风、发热、痘疹等证。 \n此说固似有理，然婴儿通体无非血气所结，而此亦血气之余，何以毒遽如是？即使咽之，亦必从便 \n而出，何以独留为害？无足凭也。惟是形体初成，固当为之清除。其法于未啼时，用软帛裹指，挖 \n去口中之血，乃用后法，并拭去口中秽恶，以清脏腑。此亦初诞之要法，不可无也。 \n开口法∶凡小儿初诞，宜以甘草细切少许，用沸汤泡汁，以淡为妙，不宜太甜，乃用软帛蘸汁 \n，遍拭口中，去其秽浊。随用胡桃肉去皮嚼极烂，以稀绢或薄纱包如小枣，内儿口中，使吮其汁， \n非独和中，且能养脏，最佳法也。若母气素寒，小儿清弱者，只以淡姜汤拭口，最能去胃寒，通神 \n明，并可免吐泻之患。此法最妙，人所未知也。拭后仍用核桃法如前。一法以牛黄半分，同朱砂研 \n匀，蜜调如前，与吮为佳，极能辟痰邪，去秽恶，除热安神。然必母气多热，小儿肥盛者可用，清 \n弱者不宜用。一、古法拭口多有用黄连者，不知黄连大寒大苦，而小儿以胃气为主，安得初生即可 \n以苦劣之气相犯，致损胃气，则他日变呕变泻，由此而起矣，大非所宜。一、 \n古法多用朱砂开口者，按陈文中曰∶小儿初生，便服朱砂、轻粉、白蜜、黄连，本欲下胎毒，不知 \n此皆伤脾败阳之药，轻粉下痰损心，朱砂下涎损神，儿实者服之软弱，弱者服之易伤，反致变生诸 \n病，是固不可不察也。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：巢氏曰∶小儿初生，肌肤未实，宜用旧絮护其背，不可太暖，更宜数见风日，则血气刚强，肌 \n肉致密，若藏于重帏密室，或浓衣过暖，则筋骨软脆，不任风寒，多易致病。衣服当随寒热加减， \n但令背暖为佳，亦勿令出汗，恐表虚风邪易伤。乳哺亦不宜过饱，陈氏所谓忍三分寒，吃七分饱， \n频揉肚，少洗澡，要肚暖头凉心胸凉，皆至论也。又须令乳母预慎六淫七情，浓味炙爆，则乳汁清 \n宁，儿不致疾。否则阴阳偏胜，血气沸腾，乳汁败坏，必生诸病。若屡用药饵，则脏腑阴损，多 \n变败证，可不慎欤。大抵保婴之法，未病则调和乳母，既病则审治婴儿，亦必兼治其母为善。 \n小儿饮食有任意偏好者，无不致病，所谓爽口味多终作疾也，极宜慎之。尝见王隐君曰∶余幼 \n时酷嗜甘饴，忽一日见饴中有蚯蚓伸头而出，自此不敢食饴，至长始知长上为之。此可为节戒之妙 \n法。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：初生儿以手捻其头，摸其颐颔，不作声者为无病。总有病，以手指探其口，虽发声而从容咂指 \n者其病轻，若即发声不咂指而色或青红兼紫者，此落地受寒之甚也，其病重，须急辨其形色虚实而 \n治之。苦牙关紧闭不纳乳，或硬而不软，其病极重也，此惊邪入足太阳经及足阳明经而然，须急治 \n之，庶可平复。 \n一、初生儿肥胖色嫩日觉好看者，此其根本不坚，甚非佳兆，且亦最易感邪。凡邪入腑者，近 \n在第二三日见之，其证吐乳、夜啼发哭、腹鸣，皆胎惊之证，然犹浅而易治。若邪之入脏者，远在 \n六七日见之，此脐风、噤风、撮口风之候，其病深而难医。若大声口噤，舌大痰壅者不治，盖五六日间病传心肺脾 \n三经也。此风气甚 \n盛而无所泄，故形见于喉口于关声音也。其面额青紫黑色者不治，爪甲青黑者不治，脐青黑者亦不 \n治。凡父母肥者不可生肥儿，父母瘦者亦不可生肥儿。生而肥胖，必当以药敛之，使其肥肉坚实， \n面转微黄之色则吉，不然则凶。生儿怯弱，必须以药扶助之。若七日之内，肌肉顿肥，则必病矣。 \n过此以往渐肥者，不足虑也。治肥之法，宜清痰湿，解胎毒，预防其风气，亦不可过用峻厉以伤脾 \n气。又当看小儿元气浓薄，浓者十无一失，薄者十无一生。然其中有死者，有不死者，则以病之所 \n生，有真伪也。凡怯弱者，宜专培脾肾为主。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：看小儿法，以听声为先，察色为次。凡声音清亮者生，有回音者生；涩者病，散而无出声者不 \n寿。忽然大声而无病者，须细看其身，恐有疮毒，即须治之。脐带中无血者生，脐带银白色者生。 \n短带紫胀者，于断带之后捻去紫血，可保无虞。额皮宽者寿。卵缝通达黑色者寿，初生下如水泡之 \n状者险。面转微黄之色者吉。生下粉白花色者，必主脐风而死。生下皮宽肉瘦，五六日顿肥者，亦 \n必有脐风之患。生下皮肉不光者死。泣不出声者死。泣而无泪者死。舌如猪肝者死。口角上有紫色 \n如虾须者死。发粗长者生，细软不放者死。阴物不起者死。阴囊不收者死，白者死，赤者死。无粪 \n门者死。臀肉不生者死。股肉不生者不寿。面无彩色者夭。脐带短大紫色者夭。生下浑身银白色者 \n夭。生下有齿者大凶，致伤父母，不然必伤自身。生下来裹即撒尿者，杀父母，荡家财，在世一生 \n劳苦。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：凡小儿形体既具，经脉已全，所以初脱胞胎，便有脉息可辨，故通评虚实论曰∶乳子病热，脉 \n悬小者，手足温则生，寒则死。乳子病风热，喘鸣肩息者，脉实大也。缓则生，急则死。此轩岐之 \n诊小儿，未尝不重在脉， \n亦未尝不兼证为言也。自《水镜诀》及《全幼心鉴》等书，乃有三岁以上当察虎口，寅卯辰、风气 \n命三关之说。其中之可取者，惟曰∶脉从寅关起，不至卯关者易治，苦连卯关者难治，若寅侵卯、 \n卯侵过辰者，十不救一。只此数语，乃于危急之际，亦可用辨吉凶。至若紫为风，红为伤寒，青为 \n惊，白为疳、及青是四足惊，赤是水惊，黑是人惊，黄是雷惊之类，岂此一线之色，果能辨悉如此 \n，最属无稽，乌足凭也。即今幼科所尚，无不以此为科套，全不知脉而信口胡猜，试问其心，果亦 \n有的确之见否？茫然无掳而欲以人子为尝试，良可叹也。故凡诊小儿，既其言语不通，尤当以脉为 \n主，而参以形色声音，则万无一失矣。然小儿之脉，非比大人之多端，但察其强弱缓急四者之脉， \n是即小儿之肯綮。盖强弱可以见虚实，缓急可以见邪正，四者既明，则无论诸证，但随其病以合其 \n脉，而参此四者之因，则左右逢源，所遇皆道矣。再加以声色之辨，更自的确无疑，又何遁情之 \n有，此最活最妙之心法也。苦单以一脉凿言一病，则一病亦能兼诸脉，其中真假疑似，未免胶柱， \n实有难于确据者。然法不可废，最所当察，故择其得理者，并附于左，亦可以见其概。 \n钱仲阳曰∶小儿之脉，气不和则弦急，伤食则沉缓，虚惊则促急，风则浮，冷则沉细，脉乱者 \n不治。 \n薛氏曰∶凡看脉，先定浮沉、迟数，阴阳、冷热。沉迟为阴，浮数为阳。浮主风，沉迟主虚冷 \n，实主有热，紧主癫痫，洪主热盛，沉缓主虚泻，微迟有积有虫，迟涩主胃脘不和，沉主乳食难化 \n，沉细主乳食停滞。紧弦主腹中热痛，牢实主大便秘，沉而数者骨中有热，弦长是肝膈有风，紧数 \n乃惊风为患，四肢掣颤，浮洪乃胃口有热，沉紧主腹痛有寒，虚濡者有气，又主慢惊，芤主大便利 \n血。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：声由气发，气实则声壮，气虚则声怯，故欲察气之虚实者，莫先乎声音。如《内经》诸篇有曰∶ \n言而微，终日乃复言者，此夺气也。有曰∶气海有余者，气满胸中， 息面赤；气海不足，则气少 \n不足以言。有曰∶心气虚则悲，实则笑不休。有曰∶手少阴虚则不能言。有曰∶内夺而厥，则为喑 \n俳，此肾虚也。华元化曰∶阳候 \n多语，阴证无声。多语者易治，无声者难荣。凡此皆声音虚实之辨，故彼圣人者，闻声知情，无所 \n不达，此声音之学，所以不可忽也。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：脉要精微论曰∶夫精明五色者，气之华也。赤欲如白裹朱，不欲如赭；白欲如鹅羽，不欲如盐 \n；青欲如苍璧之泽，不欲如蓝；黄欲如罗裹雄黄，不欲如黄土；黑欲如重漆色，不欲如地苍。五色 \n精微象见矣，其寿不久也。 \n玉版论要篇曰∶色夭面脱不治，百日尽已。色见上下左右，各在其要，上为逆，下为从，女子 \n右为逆，左为从，男子左为逆，右为从。 \n五色篇曰∶官五色奈何？曰∶青黑为痛，黄赤为热，白为寒，是谓五官。又曰∶以色言病之间 \n甚奈何？曰∶其色粗以明，沉夭者为甚，其色上行者病益甚，其色下行如云彻散者病方已。 \n经脉篇曰∶凡诊络脉，脉色青则寒且痛，赤则有热。胃中寒，手鱼之络多青矣。胃中有热，鱼 \n际络赤。其暴黑者，留久痹也。其有赤有黑有青者，寒热气也。其青短者，少气也。 \n凡察色之法，大都青白者少热气，病主阴邪；黄赤者多热气，病主阳盛。青主风气，主肝邪， \n主脾胃虚寒，主心腹疼痛，主暴惊伤心胆之气，主惊风，当察兼色以分急慢。白主气虚，甚则气脱 \n，主无火，主脾肺不足。白兼青者主慢惊，主大小肠泄泻。赤主火，主痰热，主伤寒热证，主烦渴 \n，主急惊躁扰，主闭桔，主阳邪喘促，主痈疡痘疹。黑属水，主阴寒，主厥逆，主痛极。沉黑主危 \n笃。黄主积聚，主痞块，主脾病，主胀满，主脾疳。黄兼白者主脾寒脾弱，主气虚神怯。黄兼青者 \n主脾虚泄泻，主慢脾风。黄兼赤者主疳热。两颧鲜红，或作或止者，谓之面戴阳，乃真阴虚弱，此 \n非阳证也，不得以热赤同论。 \n钱氏曰∶左颊为肝，右颊为肺，额上为心，鼻上为脾，下颏为肾，随证施治之。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：小儿气血未充，而一生盛衰之基，全在幼时，此饮食之宜调，而药饵尤当慎也。今举世幼科既 \n不知此大本，又无的确明见，而惟苟完目前。故凡遇一病，则无论虚实寒热，但用海底兜法，而悉 \n以散风、消食、清痰、降火、行滞、利水之剂，总不出二十余味，一套混用，谬称稳当，何其诞也 \n。夫有是病而用是药，则病受之矣，无是病而用是药，则元气受之矣，小儿元气几何，能无阴受其 \n损而变生不测耶？此当今幼科之大病，而医之不可轻任者，正以此也。又见有爱子者，因其清黄瘦 \n弱，每以为虑，而询之庸流，则不云痰火，必六食积，动以肥儿丸、保和丸之类，使之常服。不知 \n肥儿丸以苦寒之品，最败元阳，保和丸以消耗之物，极损胃气，谓其肥儿也，而适足以瘦儿，谓其 \n保和也，而适足以违和耳。即如抱龙丸之类，亦不宜轻易屡用。余尝见一富翁之子，每多痰气，或 \n时惊叫，凡遇疾作，辄用此丸，一投即愈，彼时以为神丹，如此者不啻十余次。及其长也，则一 \n无所知，凝然一痴物而已，岂非暗损元神所致那。凡此克伐之剂，所以最当慎用，故必有真正火证 \n、疳热，乃宜肥儿丸及寒凉等剂；真正贪积、胀满，乃宜保和丸及消导等剂；真正痰火喘急，乃宜 \n抱龙丸及化痰等剂，即用此者，亦不过中病即止，非可过也。若无此实邪可据，而诸见出入之病， \n则多由亏损元气，悉当加意培补，方是保赤之主。倘不知此而徒以肥儿、保和等名，乃欲藉为保障 \n，不知小儿之元气无多，病已伤之，而医复伐之，其有不萎败者鲜矣。此外，如大黄、芒硝、黑丑 \n、芫花、大戟、三棱、篷术之类，若作必不得已，皆不可轻易投也。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：凡小儿之病，本不易察，但其为病之源，多有所因，故凡临证者，必须察父母先天之气，而母 \n气为尤切。 \n如母多火者，子必有火病；母多寒者，子必有寒病；母之脾肾不足者，子亦如之。凡骨软行迟，齿 \n迟语迟，囟门开大，疳热脾泄之类，多有由于母气者。虽父母之气俱有所禀，但母气之应在近，父 \n气之应在远。或以一强一弱而偏得一人之气者，是皆不可不察。至若稍长而FS 纵欲，或调摄失宜而 \n自为病者，此又当察其所由，辨而治之。如果先天不足，而培以后天，亦可致寿、虽曰先天俱盛， \n而或父母多欲，或抚养失宜，则病变百端，虽强亦夭。 \n此中几圆理微，贵在知常知变也。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：初生小儿撮口脐风者，因胎中受热，或初生不慎，为风寒所侵，遂致聚唇撮口，眼闭口噤，啼 \n声如雅，或声不能出，成舌上如粟，或口吐白沫，或喉痰潮响，或气息喘急，甚者舌强面青，腹胀 \n青筋，吊肠牵痛。百日内病甚者多不治。脐风者，以断脐之后，为水湿风邪所侵，因致腹胀脐肿， \n四肢柔直，啼不吮乳，甚则发搐。若脐边青黑，手拳口噤者，是为内搐，不可治。凡治此之法，痰 \n盛者当先治痰，火盛者当先清火，若无火无痰者，专当温补脾胃。凡断脐不盈尺，多患此者。齿龈 \n有泡如粟，以绵裹指，蘸温水擦破，口即开，不用药。七日内患此有，百无一生。脐风果因浴拭外 \n伤皮肤者，用绵灰或枯矾末掺之即愈。若因剪脐短少，或因束缚不紧或因牵动，风入脐中，或因铁 \n器断脐，冷气传于脾络，以致前证者，口内有小泡，急掐破去其毒水，以艾灸脐中，亦有得生者。 \n治法多端，无如灸法。苦因乳母肝脾郁怒，或饮食生冷辛热，致儿为患者，当治其母。 \n钱氏云∶撮口因浴后拭脐，风邪所入而作，用益黄散补之。 \n陈无择云∶视其牙龈有泡，擦破之。口既开，用真白僵蚕略烘为末，蜜调涂口内。 \n《保婴集》云∶小儿百日脐风马于，当作胎毒，泻足阳明之火，用针挑破，以桑树白汁涂之。 \n田氏治噤风，用天南星为末，加片脑少许，以指蘸姜汁擦于龈，立开。或用牛黄，以竹沥调服 \n一字，随以 \n猪乳滴于口中。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：惊风之要领有二，一曰实证，一曰虚证而尽之矣。盖急惊者，阳证也，实证也。乃肝邪有余而 \n风生热，热生痰，痰热客于心膈间，则风火相搏，故其形证急暴而痰火壮热者，是为急惊。此当先 \n治其标，后治其本。慢惊者，阴证也，虚证也。此脾肺俱虚，肝邪无制，因而海脾生风，无阳之证 \n也。故其形气病气俱不足者，是为慢惊，此当专顾脾肾以救元气。虽二者俱名惊风，而虚实之有不 \n同，所以急慢之名亦异。凡治此者，不可罔顾其名以思其义。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：小儿惊风，肝病也，亦脾肾心肺病也。盖小儿之真阴未足，柔不济刚，故肝邪易动，肝邪动则 \n木能生火，火能生风，风热相搏则血虚，血虚则筋急，筋急则为掉眩反张、搐搦强直之类，皆肝木 \n之本病也。至其相移，木邪侮土则脾病，而为痰，为吐泻；木盛金衰则肺病，而为喘促，为短气； \n木火上炎则心病，而为惊叫，为烦热；木火伤阴则肾病，而为水涸，为血燥、为干渴，为汗不出， \n为搐，为 ，此五脏惊风之大概也。 \n治此之法有要存焉，盖一日风，二日火，三日痰，四日阳虚，五日阴虚，但能察此缓急则尽之 \n矣。所谓风者，以其强直掉眩皆属肝木，风木同气，故云惊风，而实作外感之证。今人不明此义， \n但为治风必须用散，不知外来之风可散，而血燥之风不可散也。故凡如防风、荆芥、羌活、独活、 \n细辛、干葛、柴胡、紫苏、薄荷之类，使果有外邪发热无汗等证，乃可暂用，如无外邪，则最所当 \n忌，此用散之不可不慎也。 \n所谓痰火者，痰凝则气闭，火盛则阴亏，此实邪之病本也。若痰因火动，则治火为先，火以痰 \n留，则去痰为主。火之甚者，宜龙胆草、山栀子、黄连、黄柏、石膏、大黄之属；火之微者，宜黄 \n芩、知舟、玄参、石斛、 \n地骨皮、木通、天麻之属。痰之甚者，宜牛黄、胆星、天竺黄、南星、半夏、白芥子之属；痰之微 \n者，宜陈皮、前胡、海石、贝母、天花粉之属。此外，如朱砂之色赤体重，故能入心镇惊，内孕水 \n银，故善透经络，坠痰降火。雄黄之气味雄悍，故能破结开滞，直达横行。冰片、麝香，乃开窍之 \n要药；琥珀、青黛，亦清利之佐助而已。又如僵蚕、全蝎、蝉蜕之属，皆云治风，在僵蚕味咸而 \n辛，大能开痰涎、破结气，用佐痰药，善去肝脾之邪，邪去则肝平，是即治风之谓也。全蝎生于东 \n北，色青属木，故善走厥阴，加以盐味咸而降痰，是亦同气之属，故云治风，较之僵蚕，此其次矣 \n。蝉蜕性味俱薄，不过取其清虚轻蜕之义，非有实济不足恃也。凡惊风之实邪，惟痰火为最，而风 \n则次之，治实之法，止于是矣。然邪实者易制，主败者必危。盖阳虚则阴邪不散而元气不复；阴虚 \n则营气不行，而精血何来？所以惊风之重，重在虚证，不虚不重，不竭不危，此元精元气相为并立 \n，有不容偏置者也。故治虚之法，当辨阴阳，阳虚者宜燥宜刚，阴虚者宜温宜润。然善用阳者，气 \n中自有水；善用阴者，水中自有气，造化相须之妙，既有不可混，又有不可离者如此。设有谓此非 \n小儿之药，此非惊风之药者，岂惊风之病不属阴阳，而小儿之体不由血气乎？若夫人者，开口便可 \n见心，又乌足与论乾坤合一之道。诸补之法具详如下。 \n一、惊风反张，强直转筋等病，在经筋篇曰∶足少阴之筋病，足下转筋及所过而结者皆痛。病在 \n此者，主痫螈及痉。在外者不能俯，在内者不能仰，故阳病者腰反折不能俯，阴病者不能仰。又曰 \n经筋之病，寒则反折筋急，热则筋弛纵不收，阴痿不用。阳急则反折，阴急则俯不伸。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：急惊之候，壮热痰壅，窜视反张，搐搦颤动，于关紧急，口中气热，颊赤唇红，饮冷便结，脉 \n浮洪数。此肝邪风热，阳盛阴虚证也。治此之法，当察缓急，凡邪盛者，不得不先治其标。若痰甚 \n喘急者，宜抱龙丸、琥珀散、清膈煎、梅花饮之类主之。火盛而烦热者，宜凉惊丸、抑青丸，或黄 \n连安神丸、牛黄散，及山栀、黄连、 \n龙胆草之属。火盛燥热而大便秘结者，宜泻表丸，或以为汤煎服之，或利惊丸亦可。若外感风寒， \n身热为惊者，当解其表，宜抑肝散倍加柴胡，或参苏饮、五积散、星苏散之类，择而用之。若表邪 \n未解而内亦热者，宜钱氏黄龙汤。若惊气渐退而以未清者，宜安神镇惊丸。凡以上者，皆急则治标 \n之法，但得痰火稍退，即当调补血气，如后附薛氏之法，或参用慢惊诸治以防虚败，此幼科最要之 \n法。前哲有云∶小儿易为虚实，攻伐之药，中病即止，不可过剂，诚至言也。大抵此证多属肝胆脾 \n肾阴虚血燥，风火相搏而然，苦罔顾真阴，过用祛风化痰之药，则脾益虚，血益燥，邪气绵延，必 \n成慢惊矣。此中阴虚之义，皆人所不知，当阅小儿补肾论，始见其详。论载第二卷二五。 \n东垣曰∶急惊者，风木旺也。风木属肝，肝邪盛必传克于脾。欲治其肝，当先实脾后泻风木。 \n楼全善曰∶急惊属木火土实。木实则搐而有力，及目上视，动札频睫；土实则身热面赤，而不 \n吐泻，偃睡合睛。治法宜凉宜泻，而用凉惊利惊等丸。亦有因惊而发者，以致于关紧急，壮热等证 \n，此内有实热，外挟风邪，当截风定搐。若痰热尚盛，宜微下之。痰热既泄，急宜调养胃气。搐定 \n而痰热少退，即宜调补脾气。 \n薛氏曰∶此肝经血虚，火动生风。盖风生则阴血愈散，阴火愈炽；火动则肺金愈亏，肝邪愈盛 \n。宜滋肝血，养脾气。若屡服祛风化痰，泻火辛散之剂，便宜认作脾虚血损，急补脾土。若风火相 \n搏，发热抽搐，目 筋挛，痰盛者，用四物、钩藤钩以生肝血，清肝火，用四君子加当归以补脾土、 \n生肺金。若肝经血燥，发热惊搐，目 筋挛，痰盛者，用六味丸以滋肾水，四君子加芍药以补脾土 \n。若肺金克肝木，用地黄丸以益肝血，加芍药、木香以平肺金。若屡用惊药而脾胃虚寒者，须用六 \n君子汤以补脾士，丁香、木香以培阳气。若脾土虚寒，肾水反来侮土，而致中寒腹痛，吐泻少食等 \n证者，用益黄散以补脾土而泻水，庶几不致慢惊矣。但治小儿，当审察虚实，凡证属有余者，病气 \n也，不足者，元气也，故有余当认为不足，思患预防，斯少失矣。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：慢惊之候，多由吐泻，因致气微神缓，昏睡露睛，痰鸣气促，惊跳搐搦，或乍发乍静，或身凉 \n身热，或肢体逆冷，或眉唇青赤，面色淡白，但其脉迟缓，或见细数，此脾虚生风，无阳证也。小 \n儿慢惊之病，多因病后，或以吐泻，或因误用药饵，损伤脾胃所致。然亦有小儿脾胃素弱，或受风 \n寒，则不必病后，及娱药者亦有之，总属脾肾虚寒之证。治慢惊之法，但当速培元气，即有风痰之 \n类，皆作实邪，不得妄行消散，再伤阳气，则必致不救。凡脾土微虚，微泻而内不寒者，可平补之 \n，宜六神散、四君子汤，或五味异功散。脾肾俱虚而脏平无寒者，宜五福饮，且阴血生于脾土，又 \n宜四君子加当归、枣仁。脾气阳虚微寒者，宜温胃饮、理中汤、五君子煎。脾气虚寒多痰者，宜六 \n君子汤，或金水六君煎。脾肾阴阳俱虚而寒者，惟理阴煎为最妙。脾肾虚寒之甚，或吐泻不止者， \n宜附子理阴煎，再甚者宜六味回阳饮，或四味回阳饮，量儿大小与之。脾肾虚寒泄泻不止者，宜胃 \n关煎。 \n薛氏曰∶《保婴集》云∶急惊屡发屡用攻泻，则脾损阴消而变为慢惊者多矣。当补脾养血，佐 \n以安心、清肺、制木之药，最为切当。窃谓前证多因脾胃亏损，肝木所胜，外虚热而内真寒也。但 \n用五味异功散加当归，佐以钩藤饮，以补脾土，平肝木，亦多得效。如不应，用六君加炮姜、木香 \n，温补脾土。更不应，急加附子以回阳。若用逐风、驱痰之药，反促其危也。愚按附子温中回阳， \n为慢惊之圣药也，如元气未脱，用之无有不效，气脱甚者，急宜炮用之。 \n《保婴撮要》曰∶凡元气亏损而至昏愦者，急灸百会穴，若待下痰不愈而后灸之，则元气脱散 \n而不救矣。此乃脏腑传变已极，总归虚处，惟脾受之，无风可逐，无惊可疗，因脾虚不能摄涎，故 \n津液妄泛而似痰者，但当以温补脾胃为主。若不审其因，泛用祛风化痰之剂，则脾气益伤，阴血益 \n损，病邪益甚而危矣。 \n楼全善曰∶木虚则搐而无力，火虚则身寒，口中气冷，土虚则吐泻，睡而露睛，治宜温补脾胃 \n，用六君子 \n汤、五味异功散之类。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：小儿忽被大惊，最伤心胆之气。口问篇曰∶大惊卒恐则气血分离，阴阳破散，经络厥绝，脉道 \n不通。阴阳相逆，经脉空虚，血气不次，乃失其常，此《内经》概言受惊之病有如此。矧小儿血气 \n尢非大人之比，若受大惊，则其神气失散，溃乱不堪，尚何实邪之有。斯时也，收复止气犹恐不暇 \n，顾可复为清散耶？即如朱砂、琥珀之类，不过取其镇重之意，亦作救本之法。今幼科诸书皆以大 \n惊之证，例作急惊论治，误亦甚矣。不知急惊、慢惊，一以风热，一以脾肾之虚，皆不必由惊而得 \n。而此以惊恐致困者，本心胆受伤，神气陡离之病，所因不同，所病亦异，胡可以同日语也。 \n治大惊气散之病，当以收复神气为主，宜《秘旨》安神丸、七福饮、茯神汤、团参散、独参汤 \n之类，加金银等物煎服之。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：小儿惊啼，证本与惊风不同，亦与大惊卒恐者有异。盖小儿肝气未充，胆气最怯，凡耳闻骤声 \n，目视骤色，虽非大惊卒恐，亦能怖其神魂。醒时受怖，寐则惊惕，或振动不宁，或忽尔啼叫，皆 \n神怯不安之证。总宜安神养气为主，如独参汤、团参散、七福饮、《秘旨》安神丸之类，皆其所宜 \n。若微烦热者，宜生脉散。热甚者，宜朱砂安神丸，或导赤散。惊哭多泪，忽啼忽止者是惊惕。啼 \n叫无泪，声长不扬者是腹痛。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：搐，抽搐也，是即惊风之属，但暴而甚者，谓之惊风，微而缓者，谓之发搐。发搐不治，则渐 \n成惊风矣。 \n虽钱氏等书，皆以时候之气，分五脏之证为论治，然病变不测，有难以时气拘者，是不若察见在之 \n形证，因脏腑之虚实，随宜施治者之为得也。总之，小儿之实证无他，惟东方之实及中央之滞耳。 \n盖东方木实则生火生风，而为热为惊；中央土实则生湿生滞，而为痰为积。知斯二者，则知所以治 \n实矣。若小儿之虚证，则五脏皆有之，如心虚则惊惕不安，肺虚则气促多汗，脾虚则为呕吐、为暴 \n泄、为不食、为痞满倦卧、为牙紧流涎、为手足牵动，肝虚则为筋急血燥、为抽搐劲强、为斜视目 \n瞪，肾虚则为二便不禁、为津液枯槁、为声不出、为戴眼、为肢体厥逆、为火不归源。知此五者， \n则知所以治虚矣。然此虚实之证，固亦多有疑似者，但以形色、声音、脉息参而察之，则无有不了 \n然者。诸治责之法，当从急惊，治虚之法，当从慢惊，及如后夜啼诸治法，已尽其蕴，当并察之。 \n总之，诺言实者，乃邪气之实，非元气之实也。故治此者，切不可伤及元气。若病已久，尤当专顾 \n脾肾，则根本完固，诸无不愈矣。 \n钱仲阳曰∶惊痫发搐，男左视无声，右视有声，女右视无声，左视有声，此相胜也。盖左为肝 \n部，右为肺部，金木相胜故耳。若握拳拇指在内，女为顺；拇指在外，男为顺，顺则易治，逆则难 \n治。 \n薛氏曰∶寅卯辰时搐而发热作渴，饮冷便结，属肝胆经虚热，用柴芍参苓散；作渴引饮，自汗 \n盗汗，属肝胆经血虚，用地黄丸；口吻流涎，属肝木克脾土，用六君子汤。巳午未时发搐，若兼作 \n渴饮水，属风火相搏，以地黄丸补肝，导赤散、凉惊丸治心。若作渴饮汤，体倦不乳，土虚而木王 \n也，用地黄丸以补肾，六君五汤以补脾。申酉戌时微搐而喘，目微斜，身似热，睡而露睛，大便淡 \n黄，属脾肺虚热，用异功散；若手足逆冷，或喘泻不食，属脾肺虚寒，用六君、炮姜、木香；久病 \n而元气虚者，用六君子、六吠丸二药主之。亥子丑时微搐身热，目睛紧斜，吐泻不乳，厥冷多睡， \n属寒水侮土，用益黄散；未应，用六君、姜、桂。伤风发搐，口中气热，呵欠，手足动者，名假搐 \n，用大青膏发散风邪。伤风发搐，口气不热，肢体倦怠，用异功散补脾土，钩藤饮清肝木。若因风 \n邪内郁，发热而变诸证者，当理肺金，清风邪。若外邪既解而内证未除，当理肺补脾。若 \n停食发搐，呕吐乳食者，宜用消食丸。若伤食后发搐，身热困睡，呕吐不思乳会者，当先定搐，后 \n用白饼子下之。若食既散而前证仍作，或变他证者，脾土伤而肝木乘之也，用六君子加钩藤钩以健 \n脾平肝。若肺经亏损而致惊搐等证者，当补脾肺以平肝心，则惊搐自止矣。如手足冷汗，搐眉搐肚 \n，日夜不止，名真搐，当用人参汤、川鸟、全蝎等药，平其胃气。百日内发搐，真者内生风，二、 \n三次必死；假者外生风，虽频发不死。百日内搐，亦有因乳母七情浓味所致者，当兼治其母，而以 \n固胃为先，不可迳治其儿也。苦涎入心脾则不能言，用凉心、镇惊、下痰之药。逆搐者不治。若吐 \n泻后变证者亦不治。大凡发搐，因风者则面青目赤，因惊则叫呼搐搦，因食则嗳吐气闷，脾肺虚则 \n生粘痰，喉间作锯声。此乃心火不能生脾土，脾土不能生肺金，以致肺不能主气，脾不能摄涎，故 \n涎气泛上而喉中作声耳。若用祛风治痰之剂，则气散阴消而促其危矣。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：小儿夜啼不安，接《保婴》等书云∶夜啼有二，曰脾寒，曰心热也。夜属阴，阴胜则脾脏之寒 \n愈盛，脾为至阴，喜温而恶寒，寒则腹中作痛，故曲腰而啼，其候面青，手腹俱冷，不思乳食是也 \n，亦曰胎寒，宜钩藤饮。寒甚者，理中丸。若曲腰啼叫，哭而无泪者，多系腹痛，宜木香散，或用 \n温胃饮加木香。若脾肾寒甚而兼带作痛者，宜陈氏十二味异功散。苦过用乳食，停滞作痛，邪实无 \n虚而啼者，宜保和丸、和胃饮加减主之。甚者宜消食丸。若阴盛阳衰，心气不足，至夜则神有不安 \n而啼叫者，宜四君子汤、五味异功散，或七福饮《秘旨》安神丸。若面青手冷，阳气虚寒，心神惊 \n怯而啼者，宜五君子煎，或六味异功煎。甚者宜七福饮加炮干姜、肉桂。若兼泄泻不乳，脾肾虚弱 \n也，宜六神散。甚者，养中煎、胃关煎。若兼吐泻少食，脾胃虚寒也，宜五君子煎、温胃饮，或六 \n味异功煎加炮木香。若大便不化，食少腹胀，脾气虚弱也，宜五味异功散，或五君子煎加木香。若 \n面色白，黑睛少，至夜分阴中阳虚而啼者，此肝肾之不足也，宜六味丸、八味丸、理阴煎。若见灯 \n见火愈啼者，心热也。心属火，见火则烦热内生，两阳相搏，故仰身而啼，其证面赤手腹俱暖，口 \n中气热是也。火 \n之微者，宜生脉散、导赤散；火之甚者，宜朱砂安神丸、人参黄连散。苦肝胆热甚，木火相搏者， \n宜柴胡清肝散。大都此证，或因吐泻，内亡津液，或禀赋肾阴不足，不能滋养肝木，或乳母恚怒， \n肝火侮金，当用六君子汤补脾土以生肺金，地黄丸壮肾水以滋肝木。若乳母郁闷而致者，用加味归 \n脾汤。乳母暴怒者，加味小柴胡汤。乳母心肝热搏者，柴胡清肝散。若因惊夜啼者，宜从前惊啼论 \n治。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：小儿发热证，其最要者有四∶一则外感发热，二则疮毒发热，三则痘疹发热，四则疳积发热。 \n凡此四者之外，如饮食、惊风、阴虚、变蒸之类，虽亦有之，然各有其说，均当详辨。 \n一、发热当辨虚实，如实则面亦气粗，口燥唇疮作渴，喜冷冻饮料水，大小便难，或掀衣露体，烦 \n啼暴叫，声洪脉强，伸体而卧，睡不露睛，手足指热，皆为实证。实以邪气有余，或可散邪，或宜 \n清火。虚则面色青白，气怯神倦，恍惚软弱，口鼻微冷，不喜寒凉，饮汤安静，泄泻多尿，呕恶惊 \n惕，上盛下泄，抱腹喜按，乍凉乍温，夜则虚汗，卧则露睛，屈体而卧，手足指冷，脉息缓弱，皆 \n为虚证。虚以正气不足，最宜调补，或兼解邪，虽有发热外证，必不可妄用寒凉，及任意消散克伐 \n等剂。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：凡小儿无故发热，多由外感风寒。若寒邪在表未解者，必有发热头痛，成身痛无汗，或鼻塞流 \n涕，畏寒拘急，脉见紧数者是也。凡暴感者，极易解散，一汗可愈。但察其气血平和，别无实热等 \n证，或但倦怠昏睡者，则但以四柴胡饮，或五柴胡饮为主，酌儿大小而增减其剂。此法先固其中， \n次解其表，庶元气无伤，而邪且易散，最为稳当极妙之法。有云小儿何虚，乃堪此补，及又有补住 \n邪气之说，皆寸光昧理之谈，不可信也。若胃气微见虚寒者，宜五君子煎加柴胡，或以理阴煎加减 \n用之最妙，元气颇强而能食者，宜正柴胡饮。兼内热火盛 \n而外邪未解者，宜一柴胡饮，或钱氏黄龙汤。壮热火盛往来寒热者，宜柴芩煎。寒气盛者，宜二柴 \n胡饮。寒邪盛而中气微虚者，宜五积散。伤寒见风，身热兼嗽而中气不虚者，宜柴陈煎。若中气不 \n足而兼热兼嗽者，宜金水六君煎。冬受寒邪，至春夏而发热者，是为小儿正伤寒，但取效稍迟，然 \n治法不能外此。 \n新按∶余之仲儿，生于乙卯五月，于本年初秋，忽尔感寒发热，脉微紧。然素知其脏气属阴， \n不敢清解，遂与芎、苏、羌、芷、细辛、生姜之属，冀散其寒，一剂下咽，不惟热不退而反大泻作 \n，连二日泻不止而喘继之，愈泻则愈喘。斯时也，将谓其寒气盛耶，何以用温药而反泻？将谓其火 \n刑金耶，岂以清泻连日而尚堪寒凉？将谓其表邪之未除耶，则何以不利于疏散？束手无策，疑惧已 \n甚，且见其表里俱剧，大喘垂危，又岂浅易之剂所能挽回？因沉思良久，渐有所得，乃用人参二钱 \n，生姜五片，煎汁半盏，然未敢骤进，恐再加喘，必致不救。因用茶匙挑与二、三匙，即怀之而旋 \n走室中，徐察其呼吸之进退，然喘虽未减，而亦不见其增甚，乃又与三、四匙，少顷，则觉其鼻息 \n似乎少舒，遂放胆与以半小钟，更觉有应，自午及酉，完此一剂。适一医至，急呼曰∶误矣，误矣 \n！焉有大喘如此而尚可用参者？速宜以抱龙丸解之。余诺之而不听。乃复以人参二钱五分，如前煎 \n汤，自酉至子尽其剂，剂完而气息遂平， 大睡，泻亦止而热亦退矣。此所以知其然者，观其因 \n泻反喘，岂非中虚？设有实邪，自当喘随泻减，是可辨也。向使误听彼医，易以清利，中气一脱， \n即当置之死地，必仍咎余之误用参也。孰是孰非，何从辨哉。余因纪此，以见温中散寒之功，其妙 \n有如此者。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：凡小儿偶然发热者，率由寒热不调，衣被单薄，柔弱肌腠，最易相感，感则热矣。余之治此， \n不必用药，但于其熟睡之顷，夏以单被，冬以绵被，蒙头松盖，勿壅其鼻，但以稍暖为度，使其鼻 \n息出入皆此暖气，少顷则微汗津津，务令上下 稍透，则表里通达而热自退矣。若冬月衣被寒凉， \n汗不易出，则轻搂着身，赤体相 \n贴，而上覆其面，则无有不汗出者。此余近年养儿至妙之法，百发百中者也。若寒邪甚者，两三微 \n汗之，无有不愈。然此法惟行于寅卯之际，则汗易出而效尤速。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：一、小儿发热，若热随汗退者，即外感证也。其有取汗至再而热不遏者，必痈毒、痘疹之候，俟 \n其形见，当于本门求法治之。若是疮毒，但当辨其阴证阳证，阳证宜清火解毒，阴证宜托里助阳。 \n方治详具外科。若汗出热不退，别无痈肿而耳后红筋灿然，及眼如包泪，或手指尖冷，脉紧数者， \n必是痘疹，方治详具痘疹门。 \n一、小儿饮食内伤，本无发热之证，盖饮食伤脏，则为胀为痛，为吐为泻，本非肌表之病，焉 \n得发热。故调经论曰∶邪之生于阳者，得之风雨寒暑，生于阴者，得之饮食居处、阴阳喜怒。此自 \n不易之理也。今人但见小儿发热，则多言伤食而妄行消导，谬亦甚矣。其或饮食内伤，风寒外感， \n表里兼病而发热者，亦常有之。然此当察其食之有停无停，酌而治之，亦非可混行消耗。盖恐内本 \n无滞而妄加克伐，则亏损中气，以致外邪难解，则病必滋甚。 \n一、小儿疳积发热，此诚饮食内伤所致，然必成痞成疳，阳明郁积既久，所以内外俱热，是非 \n暴伤饮食者之比，亦非肌表发热者之比，方治详具疳积条。 \n一、小儿有阴虚发热之证，及变蒸发热之说。凡阴虚发热者，此即小儿劳损证也，亦名为童子 \n劳，此当于虚损门求法治之。至若变蒸之说，则辨在本条，并当详察。 \n钱仲阳曰∶潮热者，时间发热，过时即退，来日根据时而发，此欲发惊也。壮热者，常热不已， \n甚则发惊痫也。风热者，身热而口中气热，乃风邪外感也。温热者，肢体微热，热不已则发惊搐。 \n壮热恶风寒，为元气不充，表之虚热也。壮热不恶风寒，为外邪所客，表之实热也。壮热饮杨，为 \n津液短少，里之虚热也。壮热饮水，为内火销烁，里之实热也。脉尺寸俱满为重实。尺寸俱弱为重虚。 \n脉洪大，或缓而滑，或数而鼓，此热盛拒阴， \n虽形证似寒，实非寒也。热而脉数，按之不鼓，此寒盛格阳，虽形证似热，实非热也。发热恶热， \n大渴不止，烦躁肌热，不欲近衣，其脉洪大，按之无力，或兼目痛鼻干者，此血虚发热也，当补其 \n血。如不能食而热，自汗出者，气虚也，当补其气。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：内热与外热不同，内热以五内之火，热由内生，病在阴分，故内热者宜清凉，不宜升散，升散 \n则内火愈炽，火空则发也，外热以肤腠之邪，风寒外袭，病在阳分，故外热者宜解散，不宜清降， \n清降则表热愈留，外内合邪也。此外热内热之治，其不同者有如此。欲分内外之辨，则外热者，其 \n至必骤；内热者，其来必绥。但察其绝无表证，而热在脏腑、七窍、三焦、二阴、筋骨、肌肉之间 \n者，皆是内热之证。但内热之证，亦有虚实，实者宜从正治，虚者当从反治，反正之间，有冰炭之 \n异，非可混也。 \n凡实热之在内者，古法治分五脏，宜从正治。心热者，宜泻心汤、导赤散、安神丸。肝热者， \n泻青丸、柴胡饮子、龙胆汤。脾热者，泻黄散。肺热者，轻则泻白散、地骨皮散，重则凉膈散。肾 \n热者，滋肾丸、滋阴八味丸。实热则宜疏下，虚热则宜调补。肢体热，轻则惺惺散，重则人参羌活 \n散。大便秘者，二黄犀角散、四顺清凉饮。余热不退者，地骨皮散。大小便血者，保阴煎。血热妄 \n行者，清化饮。三焦火盛、上下热甚者，抽薪饮。小水热痛者，大厘清饮。阳明内热，烦渴头痛， \n二便秘结者，玉泉散。阳明火盛，兼少阴水亏者，玉女煎。凡元气虚而为热者，必真阴不足，皆假 \n热证也，宜从反治。心脾肺气虚假热者，五君子煎、人参理中汤。五脏气血俱虚假热者，五福饮。 \n肝肾真阴不足假热者，轻则六味地黄汤，甚则理阴煎。肝肾血虚假热者，大营煎五物煎。肝肾阴虚 \n，上热下寒，则阳无所附而格阳为热者，六味回阳饮，或八味地黄汤。肝经血虚生风而热者，四物 \n加天麻、钩藤钩。汗后血虚而热甚者，六神散加粳米。汗后气虚而恶寒发热者，补中益气汤。汗后 \n阴虚，阳无所附而热者，四物汤加参、 。汗后阳虚，阴无所附而热者，四君子加芎、归。久从温 \n补而潮热不退，脉 \n见滑大者，五福饮加地骨皮，或加知母。凡婴儿诸热有因别证而作者，当从所重者而治之。若乳下 \n婴儿，当兼治其母以调之。 \n\n\n\n<目录>卷之四十谟集\\小儿则（上）\n\n<篇名>总论（一）\n\n属性：四君子汤（补一） 五君子煎（新热六） \n五味异功散（补四） 六君子汤（补五） \n团参散（小十） 六味异功煎（新热七） \n四物汤（补八） 五物煎（新因三） \n金水六君煎（新和一） 五福饮（新补六） \n理中汤（热一） 人参理中汤（热一） \n七福饮（新补七） 温胃饮（新热五） \n四味回阳饮（新热一） 胃关煎（新热九） \n理阴煎（新热二） 六味回阳饮（新热二） \n独参汤（补三五） 生脉散（补五六） \n六味地黄丸（补百二十） 养中煎（新热四） \n茯神汤（小六十） 八味地黄丸（补一二一） \n大营煎（新补十四） 滋肾丸（寒一六三） \n滋阴八味丸（新寒十七） 保阴煎（新寒一） \n清化饮（新因十三） 补中益气汤（补三十） \n益黄散（和十九） 六神散（小五一） \n加味归脾汤（补三三） 小柴胡汤（散十九） \n柴胡饮子（小三十） 柴胡清肝散（寒五九） \n一柴胡饮（新散一） 二柴胡饮（新散二） \n人参黄连散（小十七） 四柴胡饮（新散四） \n五柴胡饮（新散五） 二黄犀角散（小二九） \n正柴胡饮（新散六） 柴芩煎（新散十） \n钱氏黄龙汤（小二五） 柴陈煎（新散九） \n五积散（散三九） 四顺清凉饮（攻二五） \n星苏散（小二四） 参苏饮（散三四） \n朱砂安神丸（寒一四二） 惺惺散（小二三） \n钩藤饮（小六六） 黄连安神丸（寒一四二） \n泻白散（寒四二） 泻黄散（寒五七） \n《秘旨》安神丸（小七一） 泻心汤（寒二七） \n抑肝散（小六七） 安神镇惊丸（小七六） \n泻青丸（寒一五一） 抑青丸（小九八） \n东垣凉膈散（痘八三） 抽薪饮（新寒三） \n龙胆汤（小八二） 大厘清饮（新寒五） \n玉泉散（新寒十五） 玉女煎（新寒十二） \n地骨皮散（小三一） 导赤散（寒一二二） \n大青膏（小六八） 消食丸（小三七） \n清膈煎（新寒九） 和胃饮（新和五） \n利惊丸（小九七） 凉惊丸（小九六） \n抱龙丸（小八五） 琥珀散（小八一） \n牛黄散（小二七） 备用方 \n梅花饮（小八三） 白饼子（小三九） \n肥儿丸（小百十一） 保和丸（小三五） \n木香散（痘二一） 陈氏十二味异功散（痘二二） \n人参羌活散（小二六） \n具列小儿方中，所当详阅。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>吐泻（二十六）\n\n属性：小儿吐泻证，虚寒者居其八九，实热者十中一二。但察其脉证无火，面色清白，气息平缓，肢 \n体清凉，或神气疲倦，则悉是虚寒之证，不得妄用凉药，古人云∶脾虚则呕，胃虚则吐者是也。盖 \n饮食入胃，不能运化而吐者，此脾气虚弱，所以不能运也。寒凉入胃，恶心而吐者，此中焦阳气受 \n伤，所以不能化也。若邪在中焦，则止于呕吐，若连及下焦，则并为泻矣。故在中上二焦者，宜治 \n脾胃，连及下焦者，宜调脾肾。若非实热火邪，而妄用寒凉消伐者，无有不死。 \n一、小儿虚寒呕吐，凡无故吐泻，察其无火者，必生冷寒气伤胃所致，今小儿所病，大约皆是 \n此证，宜养中煎，或温胃饮为主治，其次则五君子煎、理中汤、冬术煎。若兼血虚燥渴者，宜五君 \n子加当归。若兼脾肾虚寒，或多痰涎，或兼喘促，宜理阴煎；甚者，人参、附子、理阴煎为最妙， \n勿谓呕吐不宜熟地也。若脾气无寒，或偶有所触，虽吐而不甚者，宜五味异功散。若脾中寒滞，气 \n有不顺而呕吐者，宜藿香安胃散。若上焦不清，多痰兼滞者，宜六君子汤，或更加砂仁、炮姜、木 \n香。 \n一、小儿伤食呕吐，若误会不宜之物，或停积滞浊以致吐者，必胸膈胀满，或肚腹作痛，此其 \n中必有余邪，宜和胃饮、益黄散。若但有食滞而胃不寒者，宜大和中饮、小和中饮。若食滞兼痰而 \n吐者，宜二陈汤、六安煎苓术二陈煎。若饮食虽滞，而因脾虚不能运化者，此其所重在脾气，不在 \n饮食，止宜养中煎、温胃饮，或理阴煎、圣术煎之类，以培其本，不可因饮食之故，而直行消伐也 \n。 \n一、小儿胃热呕吐者，其证最少，盖内热者多不致吐，即亦有之，其必多食炙爆甘甜之物，以 \n致滞积胃口，或夏间冒暑，及脏气素热者乃有之。凡治热证，必须详辨的确，勿得以假热作真热也 \n。凡胃火内热呕吐者，察其证必烦热，作渴喜冷，察其脉息必洪大滑数。火之甚者，宜泻黄散、玉 \n泉散、或竹叶石膏汤。若有痰食之滞兼火作吐者，宜二陈汤加石膏、黄连、山栀，或加山楂、麦芽 \n之类。若脾胃虚弱而兼火者，宜人参安胃散，或橘皮竹茹汤。若胃火呕吐作渴者，宜竹茹汤。若夏 \n月胃热，阳暑伤胃者，必烦热大渴，吐泻并作，宜五味香薷饮，或十味香薷饮，或竹茹汤，或橘皮 \n竹茹汤。若内热之甚者，宜益元散、玉泉散主之。然暑有阴阳之辨，若因天气暑热，过用生冷，以 \n致伤胃而为吐泻者，此属阴暑，则宜暖胃温中，如前虚寒治法，或用五苓散亦妙，凡本条之药绝不 \n可用。 \n薛氏曰∶凡暑令吐泻，手足发热，作渴饮冷者，属阳证，宜清凉之剂。若手足并冷，作渴饮汤 \n者，属阴证，宜温补之剂。故病有属阴者，误用寒凉之药，死后手足青黯，甚则遍身皆然，于此可 \n验。 \n一、小儿吐泻并作者，本属内伤，然有因寒气自外而入，内犯脏气而然者；有因生冷不慎，致伤 \n胃气而然者；有因中气本弱，饮食失宜而然者。邪伤阳分则为吐，邪伤阴分则为泻，若吐泻并作， \n则阴阳俱伤之证也。此当察其有滞无滞，详辨其虚实而治之。若吐泻初起，邪滞未清者，必有胸腹 \n胀闷实滞等证，此宜先用和胃饮、苓术二陈煎之类，以清上焦之气。若吐泻初起，腹胀腹痛而拒按 \n者，宜先用胃苓汤，或五苓散加干姜、木香之类，以分下焦之清。若上无胀滞，或所吐既多而呕恶 \n不已，此其上焦岂尚有物？但察其形气困倦，总惟胃虚而然。若虚寒不甚者，宜五味异功散。然无 \n寒不作吐，故惟五君子煎、六味异功煎，及养中煎、温胃饮之类，皆最宜也。若下腹虽痛而可按可 \n揉，或腹寒喜熨，或所泻既多而泄仍不止，此其下焦必空虚已极，惟脾肾虚寒不能固摄而然，非胃 \n关煎不可；其稍轻者，或用四君子加肉豆蔻、补骨脂、丁香之属；若虚中兼滞者，或助胃膏亦可酌 \n用。其或果由胃火，则火逆于上，热蓄于下，亦能为吐为泻，然必有火证火脉者，方是其证，乃宜 \n大小厘清饮，或用香连丸，或如前胃热呕吐条参而治之。然此证最少，不得轻易混用。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>吐泻新按\n\n属性：余季子于丁巳正月生于燕邸，及白露时甫及半周，余见新凉日至，虞 褥之薄，恐为寒气所侵 \n，每切嘱眷属保护之，而眷属不以为意，及数日后，果至吐泻大作，余即用温胃和脾之药，不效。 \n随用理中等剂，亦不效。三日后，加人参三钱，及姜、桂、吴茱、内豆蔻之类，亦不效。至四五日 \n，则随乳随吐，吐其半而泻其半，腹中毫无所留矣。余不得已，乃用人参五、六钱，制附子、姜、 \n桂等各一、二钱，下咽即吐，一滴不存，而所下之乳则白洁无气，仍犹乳也。斯时也，其形气之危 \n，已万无生理矣。余含泪静坐书室，默测其故，且度其寒气犯胃而吐泻不止，若舍参、姜、桂、附 \n、之属，尚何术焉？伎已止此，窘莫甚矣。思之思之，忽于夜半而生意起，谓其胃虚已极，但药之 \n气味略有不投，则胃不能受，随拒而出，矧附子味咸，亦能致呕，必其故也。因自度气味，酌其所 \n宜，似必得甘辣可口之药，庶乎胃气可安，尚有生意。乃用胡椒三钱，捣碎，加煨姜一两，用水二 \n钟，煎至八分，另盛听用。又用人参二两，亦用水二钟，煎至一钟，另盛听用。用此二者，取其气 \n味之甘辛纯正也。乃用茶匙挑合二者，以配其味，凡用参汤之十，加椒姜扬之一，其味微甘而辣， \n正得可口之宜。遂温置热汤中，徐徐挑而与之，陆续渐进，经一时许，皆咽而不吐，竟得获效，自 \n后乳药皆安，但泻仍未止也。此自四鼓服起，至午未间，已尽二两之参矣。参尽后，忽尔躁扰呻吟 \n，烦剧之甚，家人皆怨，谓以婴儿娇嫩，脏腑何堪此等热药。是必烧断肚肠也，相与抱泣。余虽疑 \n之而不为乱，仍宁神熟思之，意此药自四鼓至此，若果药有难堪，何于午前相安，而此时遽变若此 \n？其必数日不食，胃气新复，而仓廪空虚，饥甚则然也。傍有预备之粥，取以示之，则张皇欲得， \n其状甚急，乃与一小盏，辄鲸吞虎嗜，又望其余，遂复与半碗，犹然不足，又与半惋，遂寂然安卧 \n矣。至次日，复加制附，始得为止全愈。呜呼！此儿之重生，固有天命，然原其所致之因，则人之 \n脏气皆系于背，褥薄夜寒，则寒从背俞而入，内干于脏，中必深矣，原其所治之法，则用药虽当， \n而气味不投无以相入，求效难矣。及其内饥发躁，使非神悟其机，倘妄用清凉，一解则全功尽弃， \n害可言哉。 \n故余笔此，以见病原之轻重，气味之相关，及延医之活变有如此关系者。虽然，此特以己之儿 \n，故可信心救疗如是，设以他人之子，有同是病者，于用参数钱之时，见其未效，不知药未及病， \n必且烦言吠起，谤其误治，改用苦寒，无不即死，而仍归罪于用参者，此时黑白将焉辨之？故再赘 \n其详，用以广人之闻见云。 \n都FS 钱旭阳长郎，年及两周，季夏间以生果伤脾，因致先泻后痢。旭阳善医，知其不过伤于 \n生冷，乃与参、术、姜、桂、温脾等药，泻痢不愈，而渐至唇口生疮。乃谋之余，曰∶此儿明为生 \n冷所伤，今不利温药，将奈之何？余曰∶此因泻伤阴，兼之幸辣遽入，而虚火上炎耳，非易以附子 \n，不能使火归原也。因用二剂，而唇口疮痛，咽肿倍甚，外见于头面之间，而病更剧矣。又谋之余 \n曰∶用药不投如此，岂真因湿生热耶？余诊之曰∶上之脉息，下之所出，皆作真热，本属阳虚。今 \n热之不效，虽属可疑，然究其所归，寒之则死，必无疑也。意者，药犹未及耳。旭阳曰∶尚有一证 \n似属真寒，今其所用汤饮，必欲极滚极热者，余等不能入口，而彼则安然吞之，即其喉口肿痛如此 \n，所罔顾也，岂其证乎？余曰∶是矣，是矣。遂复增附子一钱五分，及姜、桂、肉果、人参、熟地 \n之属，其泻渐止，泻止而喉口等证，不一日而全收矣。疑似之间，难辨如此，使非有确持之见，万 \n无一生矣。余自经此以来，渐至不惑，后有数儿，证治大同者，俱得保全。亿，此不惑之道，其要 \n何居？在知本之所在耳，临证者可无慎哉！ \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>吐泻新按\n\n属性：薛氏治一小儿，每饮食失节，或外惊所忤，即吐泻发搐，服镇惊化痰等药而愈。后发搐益甚， \n饮食不进，虽参术之剂，到口即呕。余用白术和土炒黄，用米泔煎数沸，不时灌半匙，仍呕。次日灌之，微呕。再 \n日灌之， \n欲呕。此后每服二三匙，渐加至半杯，不呕，乃浓煎服而愈 \n一、小儿泻而大便热赤，小便涩少，此热蕴于内也。先以四苓散加炒黄连一剂，其热顿退。又 \n用七味白术散去木香二剂，热渴顿止。后以四君、升麻调理而痊。 \n一、小儿九岁，会炙爆之物，作泻饮冷，诸药不应，肌体消瘦，饮食少思。余用黄连一两，酒 \n拌炒焦为末，入人参末四两，粥丸小豆大，每服四五十丸，不拘时，白汤下，服讫渐愈。又用五味 \n异功散加升麻，服月余而瘥。后不戒浓味，患疳积，消瘦少食，发热作渴，用大芦苍丸为主，以四 \n味肥儿丸为佐，疳证渐退。却以四味肥儿丸为主，以五味异功散为佐而痊。后又不禁浓味，作泻饮 \n冷，仍服肥儿丸、异功散而瘥。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>霍乱吐泻（二十七）\n\n属性：小儿霍乱吐泻者，必以寒凉伤胃，或时气阴湿，或饮食失宜，皆能致之。然此与前吐泻并行者 \n，稍有不同。盖霍乱者，暴而甚；吐泻者，徐而缓。霍乱者，伤在一时，吐泻者，其伤以渐，此其 \n所以有异也。若暴疾霍乱而胃口未清，胸腹仍满者，宜先用和胃饮，苓术二陈煎，或大、小和中饮 \n，或小厘清饮，或神香散之类主之。俟胃口稍平，即宜五味异功散，或温胃饮、五苓散之类调补之 \n。若霍乱初起便觉神疲气倦，而胃口别无胀滞者，此其胃气已伤，即宜温补，如养中煎、温胃饮之 \n类，不得概行清利也。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>论泻痢粪尿色（二十八）\n\n属性：古人有以小儿泻痢粪黄酸臭者，皆作胃热论治，此大误也。盖饮食入胃，化而为粪，则无有不 \n黄，无有不臭者，岂得以黄色而酸臭者为热乎？今以大人之粪验之，则凡胃强粪实者，其色必深黄 \n而老苍，方是全阳正色。若纯黄不苍而粪有嫩色，则胃中火力便有不到之处，再若淡黄则近白矣。近白之色则半黄之色也，粪色半黄则 \n谷食半化之色也，粪气酸腥则谷食半化之气也，谷食半化，则胃中火力盛衰可知也。若必待粪青粪 \n白，气味不臭，然后为寒，则觉之迟矣。故但以粪色之浅深，粪气之微甚，便可别胃气阳和之成色 \n，智者见于未然，而况于显然乎。余故曰∶古人以粪黄酸臭为火者，大误也。再若小水之色，凡大 \n便泻痢者，清浊既不分，小水必不利，小水不利，其色必变，即清者亦常有之，然黄者十居八九。 \n此因泻亡阴，阴亡则气不化，气不化则水涸。水涸则色黄不清，此自然之理也。使非有淋热痛涩之 \n证，而但以黄色便作火治者，亦大误也。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>吐乳（二十九）\n\n属性：小儿吐乳，虽有寒热之不同，然寒者多而热者少，虚者多而实者少，总山胃弱而然。但察其形 \n色脉证之阴阳，则虚实寒热自有可辨，热者宜加微清，寒者必须温补。乳子之药，不必多用，但择 \n其要者二、三、四味，可尽其妙，如参姜饮、五味异功散之类，则其要也。苦儿小乳多，满而溢者 \n，亦是常事，乳行则止不必治也。若乳母有疾，因及其子，或有别证者，又当兼治其母，宜从薛氏 \n之法如下。 \n薛氏曰∶前证若小儿自受惊，或乳母恚怒，致儿吐泻青色者，宜用异功散。若母食浓味而乳热 \n者，用东垣清胃散。母饮酒而乳热者，用葛花解酲汤，子服一、二匙。若饮烧酒而乳热，或子母身 \n赤，或昏愦，服冷米醋三、五杯，多亦无妨，儿服一、二匙。若母停滞生冷而乳冷者，母服人参养 \n胃汤，子服调中丸。若母停滞而变热乳者，母服大安丸，子服五味异功散。若母郁怒伤肝脾而乳热 \n者，用归脾汤、逍遥散。若母脾虚血弱而乳热者，用六君子加芍、归。若母气血虚而乳热者，子母 \n俱服八珍汤。若母劳后发热而乳热者，子母俱服补中益气汤。苦因怒动肝火而乳热者，用五味异功 \n散加柴胡、山栀。若吐痰涎及白绿水者，木乘脾土，虚寒证也，用六君子加柴胡、木香。大凡吐乳 \n泻青色者属惊，法当平肝补脾。吐泻青白色者属寒，法当温补脾土。前诸证，若手足指热者属实， \n手足指冷者属虚，此亦验法也。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>五疳证（三十）\n\n属性：钱仲阳曰∶小儿诸疳，皆因病后脾胃亏损，或用药过伤，不能传化乳食，内亡津液，虚火妄动 \n，或乳母六淫七情，饮食起居失宜，致儿为患。凡疳在内者，目肿腹胀，泻痢青白，体渐瘦弱；疳 \n在外者，鼻下赤烂，频揉鼻耳，或肢体生疮。大抵其证虽多，要不出于五脏，而五脏之疳不同，当 \n各分辨治之。肝疳者，一名筋疳，亦名风疳。其证白膜遮睛，或泻血而瘦，宜用地黄丸以生肾。心 \n疳者，面黄颊赤，身体壮热，宜用朱砂安神丸以治心，异功散以补脾。脾疳者，一名肥疳，体黄瘦 \n削，皮肤干涩而有疮疥，腹大嗜土，宜用四味肥儿丸以治疳，五味异功散以生土，或用益黄散。肺 \n疳者，一名气疳，喘嗽气促，口鼻生疮，宜用人参清肺汤以治肺，益气汤以生金。肾疳者，一名骨 \n疳，肢体瘦削，遍生疮疥，喜卧湿地，用地黄丸。鼻疮用兰香散。诸疮用白粉散。若患潮热，当先 \n补肝，后泻心，若妄以硝黄等药利之，则成疳。若患癖，当消磨，若误以巴豆、硼砂下之，或伤寒 \n误下，皆能成疳。其初病者为热疳，用黄连丸。久病者为冷疳，用木香丸。冷热相兼者，用如圣丸 \n。津液短少者，用七味白术散。凡此皆因大病，脾胃亏损，内亡津液所致，当固脾胃为主，而早为 \n施治，则不变败证也。 \n杨氏曰∶无辜疳者，脑后项边有核如弹丸，按之转动，软而不疼，其内有虫，不速针出，则内 \n食脏腑，肢体痈疽，便利脓血，壮热羸瘦，头露骨高，宜用大芜荑汤、蟾蜍丸。丁奚者，手足极细 \n，项小骨高，尻削体痿，腹大脐突，号哭胸陷，宜用肥儿丸、大芦荟丸。哺露者，虚热往来，头骨 \n分开，翻会吐虫，烦渴呕哕，宜用肥儿丸、大芦荟丸。走马疳者，于齿蚀烂。盖齿属肾，肾虚受热 \n，痰火上炎，致口臭齿黑，甚则龈烂牙宣。宜敷雄黄散，服蟾蜍丸。若作渴泻痢肿胀、劳瘵等证， \n当详参方论而治之。盖疳者，干也，因脾胃津液干涸，而患在小儿为五疳，在大人为五劳，总宜以 \n调补胃气为主。 \n又，杨氏曰∶又有疳伤者，五脏虫疳也，其名甚多，姑举其要。虫疳者，其虫如丝，出于头项 \n腹背之间。黄白赤者可治，青黑者难治。蛔疳者，皱眉多啼，呕吐青沫，腹中作痛，肚胀青筋，唇 \n口紫黑，头摇齿痒。脊 \n疳者，身热赢黄，烦渴下利，拍背有声，脊骨如锯齿，十指皆疮，频啮指甲。脑疳者，头皮光急， \n满头并疮，脑热如火，发结如穗，遍身多汗，腮肿囟高。疳渴者，日则烦渴，饮水不食，夜则渴止 \n。疳泻者，毛焦唇白，额上青纹，肚胀肠鸣，泻下糟粕。疳利者，停积宿滞，水谷不聚，泻下恶物 \n。疳肿者，虚中有积，肚腹紧胀，脾复受湿，则头面手足虚浮。疳劳者，潮热往来，五心烦热，盗 \n汗骨蒸，嗽喘枯悴，渴泻饮水，肚硬如石，面色如银。大抵其证虽多，要不出于五脏，总宜以五脏 \n之法治之。 \n景岳曰∶按杨氏云∶疳者，干也，在小儿为五疳，在大人为五劳。然既云为干，又云为劳，岂 \n非精血败竭之证乎？察前诸法，俱从热治，多用清凉，虽此证真热者固多，而元气既败，则假热者 \n尤多也。即前所用，亦有地黄丸、异功散、益黄散、益气汤之类，恐此数方有不足以尽之。其或血 \n气俱损，有非大补不可者；阴虚假热，脾败肾亏，又有非温补不可者。贵在临证酌宜，仍当以虚损 \n治劳之法参用，庶得尽善。 \n薛氏曰∶按疳证或以哺食太早，或嗜食甘肥，或服峻厉之药，重亡津液，虚火炽盛，或因禀赋 \n，或乳母浓味七情致之，各当调治其内。若口舌蚀烂，身体壮热，腮唇赤色，或作肿痛，腹膈烦闷 \n，或掌热咽干，作渴饮，水，便赤盗汗，啮齿虚惊，此心经内外疳也，宜安神丸之类主之。若鼻外 \n生疮，眼目赤烂，肢体似癣，两耳前后、项侧、缺盆、两腋结核，或小腹、内股、玉茎、阴囊、睾 \n丸肿溃，小便不调，或出白津，或咬指甲，摇头侧目，白膜遮睛，羞明畏日，肚大青筋，口干下血 \n，此肝经内外疳也，用地黄、芦荟二丸主之。若头不生发，或生疮痂，或发成穗，或人中口吻赤烂 \n，腹痛吐逆，乳食不化，口干嗜土、泻下酸臭，小便白浊，或合目昏睡，恶闻木音，此脾经内外疳 \n也，用肥儿丸主之。若鼻外生疮，咽喉不利，颈肿齿痛，咳嗽寒热，皮肤皱错，欠伸少气，鼻痒出 \n涕，衄血目黄，小便频数，此肺经内外疳也，用地黄清肺饮主之。若脑热吐痰，手足逆冷，寒热往 \n来，滑泄肚痛，口臭作渴，齿龈溃烂，爪黑面黧，身耳生疮，或耳出水，或食自发，此肾经内外疳 \n也，用地黄丸主之。凡疳热上攻，或痘毒上升，为患甚速，名为走马疳，急敷雄黄散、搽牙散、马 \n鸣散、择而用之，服蟾蜍丸。轻则于龈腐烂，唇吻肿痛，可治；甚则牙龈蚀落，腮颊透烂，不治。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>盗汗（三十一）\n\n属性：小儿元气未充，腠理不密，所以极易汗出，故凡饮食过热，或衣被过暖，皆能致汗。东垣诸公 \n云∶此是小儿常事，不必治之。然汗之根本，由于营气；汗之启闭，由于卫气。若小儿多汗者，终 \n是卫虚，所以不固。汗出既多，未免营卫血气愈有所损，而衰羸之渐，未必不由乎此，此所以不可 \n不治也。大都治汗之法，当以益气为主，但使阳气外固，则阴液内藏，而汗自止矣。 \n一、治法∶凡小儿无故常多盗汗，或自汗者，宜以团参散为主，或参苓散、四君子汤、五味异 \n功散，或白术散之类，俱可择用。若其甚者，宜三阴煎、人参养营汤，或十全大补汤。若心经有火 \n而见烦渴者，宜生脉散、一阴煎。若肝脾火盛，内热熏蒸，血热而汗出者，脉必洪滑，证多烦热， \n宜当归六黄汤，或加减一阴煎。若阳明实热，汗出大渴者，宜仲景竹叶石膏汤。若因病后，或大 \n吐大泻之后，或误用克伐之药，以致气虚气脱而大汗亡阳者，速宜用参附汤、六味回阳饮，或 附 \n汤之类，庶可挽回也。大都汗多亡阳者，多致角弓反张，项强戴眼等证，此太阳、少阴二经精血 \n耗散，阴虚血燥而然，速宜用大营煎、人参养营汤，或十全大补汤之类，方可解救。若作风治，万 \n无一生矣。前汗证门有详论详法，所当参阅。余之儿辈，有于襁褓中多盗汗者，但以人参一钱，泡 \n汤与服，当夜即止。久不服参，必又汗出，再服再止，其效如神。凡养儿者，亦可以此为常法。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>腹胀腹痛（三十二）\n\n属性：小儿腹胀腹痛，多因食积，或寒凉伤脾而然。《内经》曰∶病痛者阴也。又曰∶痛者，寒气多 \n也，有寒故痛也。束垣曰∶寒胀多，热胀少，皆主于脾胃。故凡小儿肚腹或胀或痛，虽曰多由积滞 \n，然脾胃不虚，则运化以时，何致作胀？是胀必由于虚也。若胃气无伤而腹中和暖，则必无留滞作 \n痛，是痛多由乎寒也。故治痛治胀者，必当以健脾暖胃为主。若无火证，不得妄用凉药。若无拒按 \n坚实等证，不得妄用攻药。 \n一、治法∶凡小儿肚腹膨胀，或时常作痛，黄瘦，常用调理之法，惟芍药枳实丸加减用之为宜， \n且善止腹痛。或大健脾丸、杨氏启脾丸、和中丸之类，皆可酌用。若偶尔伤脾，气促困倦，外见腹 \n胀而内不胀者，此脾气虚也，宜五味异功散，或六味异功煎。若脾胃阳气不足，虚寒作胀，或畏寒 \n，或手足冷，或兼呕泻者，宜五君子煎、养中煎、温胃饮、六君子汤，或调中丸。若兼脾肾阳虚， \n或水泛为痰，成喘促、痛胀、泄泻，宜理阴煎加减主之。若脾胃气虚而痛滞吐泻者，宜六味异功煎 \n，或六君子汤加木香，或调中汤。若胃口偶有留滞，大痛而胀者，宜排气饮，或益黄散。若宿食偶"}, {"n": 23, "text": "卷二十三\n\n有不消而暂为胀满者，宜大、小和中饮，或保和丸、消食丸。若有坚积停滞，胀痛拒按，形气俱实 \n者，宜赤金豆、白饼子、紫霜丸之类攻下之。凡诸未尽，当于腹痛肿胀二门，参酌为治。 \n余初年在京，治一五岁邻女，适经药铺，见有晒晾巴豆，其父误以为松仁，以一粒与食之，嚼 \n而味辣，即忙吐出，而已半粒下咽矣。少顷，大泻十余次，泻后次日，即致肚腹通身悉皆肿胀，绝 \n口不食，因求治于余。或谓宜黄连、绿豆以解毒；或谓宜四苓、五皮以利水。余曰∶大攻之后，岂 \n非大虚之证乎？能再堪苦寒以败脾否？大泻之后，又尚有何水之可利？遂单用独参汤及温胃饮以培 \n脾气，不数剂而复元如初。夫既以大泻，而何以反胀若是？因此一证，乃知大虚大寒而致成肿胀者 \n，类多如此。（新按） \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>痞块（三十三）\n\n属性：小儿多有痞块者，总由口腹无节，见食必啖，食上加食，脾胃化之不及，则胃络所出之道，未 \n免渐有留滞，留滞不已，则日以益大，因成痞矣。或以感寒发热之后，胃气未清，此时最宜择食节 \n食，若不知慎，则食以邪留，最易成痞，此实人所不知也。第痞块既成，必在肠胃之外，膜膈之间 \n，故作可以消伐之剂推逐而去者。若但知攻痞，则胃气益弱，运化失权，不惟不能消痞，且致脾土 \n亏损，则痞邪益横而变百出矣。故治此者，当酌其缓急，专以调补胃气为主，外则用膏用灸，以拔 \n其结络之根，庶为万全之策。 \n一、凡调理脾胃之法，若痞邪未甚，宜芍药枳实丸加减用之为善，或大健脾丸及杨氏启脾丸，皆 \n可择用。若脾胃气虚，食少体瘦，宜五味异功散。若脾胃虚寒者，宜调中丸、温胃饮、五君子煎。 \n若兼胃脘停积，食滞作胀者，宜保和丸、消食丸，或大、小和中饮。苦胀急坚实，形气尚强，不得 \n不泻者，宜赤金豆、白饼子。若痞久成热，致动阳明之火，而牙口溃烂成疳者，宜芦荟丸、胡黄连 \n丸或蟾蜍丸。此外，如贴痞膏及炙治之法，俱详载积聚门。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>癫痫（三十四）\n\n属性：钱仲阳曰∶小儿发痫，因血气未充，神气未实，或为风邪所伤，或为惊怪所触，亦有因妊娠时 \n七情惊怖所致。若眼直目牵，口噤涎流，肚膨发搐，项背反张，腰脊强劲，形如死状，终日不醒， \n则为 矣。凡治五痫，皆随脏治之，每脏各有一兽之形，通用五色丸为主，仍参以各经之药。发而 \n重者死，病甚者亦死，如面赤目瞪，吐舌啮唇，心烦气短，其声如羊者曰心痫。血虚者用养心汤； \n发热饮冷为实热，用虎睛丸；发热饮汤为虚热，用辰砂妙香丸。面青唇青，两眼上窜，手足挛掣反 \n折，其声如犬者曰肝滴。肝之虚者，用地黄丸；抽搐有力为实邪，用柴胡清肝散；大便不通，用泻 \n青丸。面黑目振，吐涎沫，形体如尸，其声如猪者曰肾痫，用地黄丸、紫河车丸之类。肾无泻法， \n故径从虚治之。面如枯骨，目白反视，惊跳反折，摇头吐沫，其声如鸡者曰肺痫。 \n肺气虚者，用补肺散∶面色萎黄者，土不能生也，用五味异功散；面色亦者，阴火上冲于肺也 \n，用地黄丸。面色萎黄，目直腹满，自利，四肢不收，其声如牛者曰脾痫，用五味异功散；若面青 \n泻利，饮食少思，用六君子加木香、柴胡。若发热抽掣仰卧，面色光泽，脉浮者，病在腑，为阳证 \n，易治；身冷不搐覆卧，面色黯黑，脉沉者，病在脏，为阴证，难治。凡有此证，先宜看耳后高骨 \n间，若有青脉纹，先抓破出血，可免其患。此皆元气不足之证也，须以紫河车丸为主，而以补药佐 \n之。设若泛行克伐，复伤元气，则必不时举发，久而变危，多致不救。又有惊痫、风痫、食痫三种 \n。治惊痫，宜比金丸、茯神丸、钱氏养心汤、辰砂妙香散、清神汤、虎睛 \n丸之类主之。风痫用钱氏牛黄丸、消风丸、星苏散之类主之。食痫用妙圣丹主之。 \n薛立斋曰∶妊娠若遇惊恐，则必内应于胎，故一月足厥阴脉养，惊则肝有病；二月足少阳脉养 \n，惊则胆受病；三月手少阴脉养，惊则心受病；四月名为离经；五月足太阴脉养，惊则脾受病；六 \n月足阳明脉养，惊则胃受病；七月手太阴脉养，惊则肺受病；八月手阳明脉养，惊则大肠受病；九 \n月足少阴脉养，惊则肾受病。是脏腑纳气于丹田，自肝至肾，十经滋养而生，此则胎中所致也。若 \n既生之后，或惊怪所触，或乳哺失节，或乳母饮食起居，六淫七情，脏气不平，亦致是证。须察见 \n证属于何经，更别阴阳，以调补脾胃为主，否则不时举发，甚至不救。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>癫痫（三十四）\n\n属性：薛氏治一小儿，患前证，吐痰困倦，半饷而苏，诸药不效，年至十三而频发。用肥浓紫河车生 \n研烂，入人参、当归末，捣丸，桐子大，每服三五十丸，日进三五服，乳化下。一月渐愈。又佐以 \n八珍汤全愈。 \n又一儿七岁发惊痫，令其恣饮人乳后，发渐疏而轻。至十四复发，用乳不效，亦用河车丸数具 \n而愈，常用加减八味丸而安。后至二十三岁复发而手足厥冷，仍用前法，佐以八味丸、十全大补汤 \n而痊。 \n又治数小儿，皆以补中益气汤、六君子汤、六味、八味等丸，相间用之，皆得全愈。 \n癫痫诸经义及大人证治诸法，俱详载癫狂门，所当参阅。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>溺白（三十五）\n\n属性：小儿便如米泔，或溺停少顷变作泔浊者，此脾胃湿热也。凡饮食不节者多有此证，然亦有气虚 \n下陷而然者。若脉证兼火者，当清利，宜导赤散，或四味肥儿丸。若饮食过伤兼胀滞者，宜保和丸 \n、大安丸。若形气不足， \n或黄瘦，或呕泄者，宜五味异功散，或四君子汤，或补中益气汤。若肝肾火盛，移热膀胱者，必兼 \n痛涩烦热，宜七味龙胆泻肝汤。若脾胃本虚而复兼湿热者，宜四君子汤加炒黄连。若止见溺白而别 \n无烦热脉证，则但节其生冷水果及甘甜等物，不久自愈。切不可因其溺白，而过用芩、连、栀子之 \n类，多致伤脾而反生吐泻等证，渐至羸败者，是皆误冶之害也，不可不察。 \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>变蒸（三十六）\n\n属性：巢氏云∶小儿变蒸者，以长血气也。变者上气，蒸者体热。钱仲阳曰∶变者，易也。小儿在母 \n腹中，乃生骨气，五脏六腑成而未全。自生之后，即长骨脉、脏腑之神志，自内而长，自下而上。 \n故以生之日后三十二日一变蒸，即觉情志有异于前，何也？长生意志脏腑故也。何谓三十二日长骨 \n添精神？盖人有三百六十五骨节，以应天数，内除手足中四十五碎骨外，共有三百二十数，自下生 \n骨，一日十段而上之，十日百段，而三十二日计三百二十段为一遍，亦曰一蒸。凡一周遍，乃生虚 \n热诸病，如是十周，则小蒸毕也。故初三十二日一变，生肾志；六十四日二变一蒸，生膀胱；九十 \n六日三变，生心喜；一百二十八日四变二蒸，生小肠；一百六十日五变，生肝哭；一百九十二日六 \n变三蒸，生胆；二百二十四日七变，生肺声；二百五十六日八变四蒸，生大肠；二百八十八日九变 \n，生脾；三百二十日十变五蒸，生胃，此所谓小蒸毕也。又手厥阴经为脏，手少阳经三焦为腑， \n此一脏一腑俱无状，故不变不蒸也。太仓云∶气入四肢，长碎骨，于十变后六十四日为一大蒸，计 \n三百八十四日，又六十四日为二大蒸，计四百四十八日，又六十四日为三大蒸，计五百一十二日， \n至五百七十六日变蒸既毕，儿乃成人也。变者，生五脏也；蒸者，养六腑也。每经一变一蒸，情态 \n即异，轻则发热微汗，其状似惊；重则壮热，脉乱而数，或汗或吐，或烦啼躁渴。轻者五日解，重 \n者七八日解，其候与伤寒相似。其治法，平和者微表之，实热微利之，用紫霜丸、黑散子、柴胡散 \n。有寒无热，并吐泻不乳多啼者，当归散、调气散主之。 \n薛立斋曰∶《全婴方论》云∶变蒸者，以长气血也。变者上气，蒸者发热也。轻则体热虚惊， \n耳冷微汗， \n唇生白泡，三日可愈。重则寒热脉乱，腹痛啼叫，不能乳食，食即吐 五日方愈。古方以黑散子、 \n紫霜丸主之。窃谓此证，小儿所不免者，虽勿药可也，况前药乃属峻厉，非惟脏腑不能胜，抑且反 \n伤气血，慎之，慎之！余尝见一小儿，至二变发热有痰，投以抱龙丸一粒，卒至不救，观此可验 \n矣。若不热不惊，略无证候而暗变者，盖受胎气壮实故也。 \n景岳曰∶小儿变蒸之说，古所无也，至西晋王叔和始一言之，继自隋、唐巢氏以来，则日相 \n传演，其说益繁。然以余观之，则似有未必然者，何也？盖儿胎月足离怀，气质虽未成实，而脏腑 \n已皆完备。及既生之后，凡长养之机，则如月如苗，一息不容有间，百骸齐到，自当时异而日不同 \n，岂复有此先彼后，如一变生肾，二变生膀胱，及每变必三十二日之理乎？又如小儿之病与不病， \n余所见所治者，盖亦不少，凡属违和，则不因外感必以内伤，初未闻有无因而病者，岂真变蒸之谓 \n耶？又见保护得宜，而自生至长，毫无疾痛者不少，抑又何也？虽有暗变之说，终亦不能信然。余 \n恐临证者有执迷之误，故道其愚昧若此，及如前薛氏之戒，皆不可不察也。明达者以为然否？ \n\n\n\n<目录>卷之四十一谟集\\小儿则（下）\n\n<篇名>小儿下论列方（三十七）\n\n属性：理中汤（热一） 理中丸（同上） 十全大补汤（补二十） 养中煎（新热四） 温胃饮（新热五） 六味地 \n黄丸（补百二十） 理阴煎（新热三） 胃关煎（新热九） 八味地黄丸（补一二一） 四君子汤（补一） 五君 \n子煎（新热六） 加减八味丸（补一二二） 六君子煎（补五） 归脾汤（补三二） 补中益气汤（补三十） 八珍汤（补十九） 白术散（和三十） 人参养营汤（补二一） 生脉散（补五六） 逍遥散（补九二） 人参养胃汤（小四一） 参姜饮（新热八） 团参散（小三五） 人参安胃散（小四二） 益黄散（和十九） 大营煎（新补十四） 三阴煎（新补十一） 加减一阴煎（新补九） 五味异功散（补四） 参苓散（补五三） 安神丸（寒一四三） 当归六黄汤（寒六四） 茯神汤（小六十） 清神汤（小六一） 六味异功煎（新热七） 虚晴丸（小百一） 调牛汤（小二） 调中丸（小三） 六味回阳散（新热二） 调中丸（小三） 和中丸（和八七 八八） 保和丸（小三五） 六安煎（新和二） 参术二陈煎（新和四） 芍药枳术丸（新和十六） 二陈汤（和一） 大健脾丸（和八五） 大安丸（小三六） 启脾丸（和八六） 和胃饮（新和五） 排气饮（新和六） 大和中饮（新和七） 小和中饮（新和八） 竹茹汤（和一二一） 地黄清肺饮（小六九） 五苓散（和一八二） 泻黄散（寒五七） 钱氏养心汤（小五九） 四苓散（和一八七） 胃苓汤（和百九十） 朱砂安神丸（寒一四二） 益元散（寒百十二） 小厘清饮（新和 \n十） 辰砂妙香散（固十五） 兰香散（小百十） 玉泉散（新寒十五） 东垣清胃散（寒五四） 柴胡散（小二一） 赤散（寒一二二） 葛花解酲汤（和一二四） 星苏散（小二四） 香连丸（寒百十三） 五物香薷饮（和百七十） 比金丸（小百） 消风丸（小百四） 十味香薷饮（和一七一） 妙圣丹（小百五） 紫河车丸（小百九） 橘皮竹茹汤（和一二二） 消食丸（小三七） 胡黄连丸（小一二二） 藿香安胃散（热七） 黄连丸（小一三一） 如圣丸（小二六） 竹叶石膏汤（寒五） 紫霜丸（小百三十） 木香丸（小百二十） 龙胆泻肝汤（寒六三） 白饼子（小三九） 地龙丸（小八五） 钱氏牛黄丸（小九二） 黑散子（未收） 赤金豆（新攻二） 四味肥皂丸（小百十一） 马鸣散（痘一三八） 大芦荟丸（小百十五） 大芜荑汤（小百八） 搽牙散（痘一三五） 白粉散（外一九六） 圣术煎（新热二五） 雄黄散（痘一三三） 神香散（新和二十） 助胃膏（小六） \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>述原（一）\n\n属性：景岳子曰∶痘之与疹，原非一种，虽痘之变态多证，而疹之收敛稍易，然疹之甚者，其势凶危 \n，亦不减于痘，最为可畏，盖疹毒痘毒，本无异也。第古人重痘而忽疹，多不详及，使后人无所宗 \n法，余实怅之。自得罗田万氏之刻，见其理透法精，鄙念斯慰。今悉从其训，备述于此，虽其中稍 \n有裁订，亦不过正其疑似，详具未详耳。使此后患疹者，幸获迷津之指南，亦以见万氏之功为不少 \n矣。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>名义（二）\n\n属性：疹者，痘之末疾，惟二经受证，脾与肺也，内应于手足太阴，外合于皮毛肌肉，是皆天地间 \n戾不正之气，故曰疹也。然其名目有异，在苏松曰沙子，在浙江曰醋子在江右湖广曰麻，在山陕曰 \n肤疮、曰糠疮、曰赤疮，在北直曰疹子。名虽不同，其证则一。但疹在痘前者，痘后必复疹，惟痘 \n后出疹者，方为结局。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹逆顺（三）\n\n属性：万氏曰∶疹以春夏为顺，秋冬为逆，以其出于脾肺二经，一遇风寒，势必难出，且多变证，故 \n于秋冬为不宜耳。夫天行不正之气，致为人之疡疹，然古人于痘疹二字，始终归重于痘，并不分别 \n疹为何物，岂可以二证归于一证耶？想当时重痘不重疹，故尔略之，致使后人不得心法，因而害事 \n者，往往有之。今以吾家四代传流，以及今日心得之法，开载于后，用此应病，定不差矣。敢有毫 \n厘隐匿，天其鉴之。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹脉（四）\n\n属性：凡出疹，自热起至收完，但看右手一指，脉洪大有力，虽有别证，亦不为害，此定存亡之要法 \n也。 \n景岳曰∶按此即阳证得阳脉之义，若细软无力，则阳证得阴脉矣，一元气既弱，安能胜此邪毒 \n？是即安危之基也。故凡诊得阴脉者，印当识为阴证而速救元神，宜用伤寒温补托法，参酌治之。 \n若执以麻疹为阳毒而概用清寒，则必不免矣。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹证（五）\n\n属性：疹虽非痘之比，然亦由胎毒蕴于脾肺，故发于皮毛肌肉之间，但一时传染，大小相似，则未有 \n不由天行疠气而发者。此其源虽内发，而证多属表，故其内为胎毒，则与痘证同，外有表邪，则与 \n伤寒类。其为毒也，总由君相二火，燔灼太阴，而脾肺受之。故其为证，则有咳嗽喷嚏，面肿腮赤 \n，目胞浮肿，眼泪汪汪，鼻流清涕，呵欠闷顿，乍凉乍热，手足稍冷，夜卧惊悸，或恶心呕哕，或 \n以手掐面日唇鼻者，是即出疹之候，便宜用解毒散邪等药，不使留停于中，庶无他患。且凡是疹证 \n，必其面亦、中指冷而多嗽，又必大热五六日，而后见红点遍身，此其所以与痘与伤寒有异也。 \n一、痘欲尽发而不留，疹欲尽出则无病。邪气郁遏则留而不去，正气损伤则困而不伸。毒归五脏 \n，变有四证，归脾则泄泻不止，归心则烦热不退而发惊，归肺则咳嗽血出，归肾则牙龈烂而疳蚀。 \n程氏曰∶麻疹初出，类伤风寒，头疼咳嗽，热甚，目赤颊红。一二日内即出者轻，必须解表， \n忌见风寒、荤腥浓味，如犯之，恐生痰涎，变为惊搐，必致危矣。如初起吐泻交作者顺，干呕霍乱 \n者逆，欲出不出者危亡立至。 \n徐氏曰∶痘自里而出于脏故重，疹自表而出于腑故轻。 \n景岳曰∶痘疹之属有四肿，曰痘，曰疹，曰麻，曰斑也。痘则陆续渐出，自小而大，或稀或密 \n，部位颗粒有辨也。疹则一齐发出，大者如苏子，次者如芥子，小者如蚕子，而成粒成片者是也。 \n麻则最细而碎，如蚊迹模糊者是也。斑则无粒，惟成片，红紫如云如锦者是也。大都疹与麻斑同类 \n，即发斑伤寒之属，而痘则本非其类也。盖痘毒本于肝肾，出自中下二焦，是以终始不妨于食，而 \n全赖水谷为主，所以能会则吉，不能食则凶。故治痘者，不可罔顾脾胃。麻疹之毒，则由表邪不解 \n而内犯太阴阳明，病在上中二焦，所以多不能食，故治麻疹者，但宜解散火邪，邪散则自能食矣。 \n是痘疹之治，当各有所重者如此。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹期（六）\n\n属性：出疹之候，初热一日至次日鸡鸣时，其热即止，止存五心微热，渐见咳嗽鼻流清涕，或腹中作 \n痛，饮食渐减，到申酉之间，其热复来。如此者四日，用手满接发际处甚热，其面上热少减二三分 \n，咳嗽连声，面燥腮赤，眼中多泪，喷嚏频发，或忽然鼻中出血。至五日，其热不分昼夜。六日早 \n时，其疹出在两颊下，细细红点，至午时，两手背并腰下及浑昏，密密俱有红点。七日普遍掀发， \n其鼻中清涕不流，喷嚏亦不行，七日晚，两颊颜色渐淡。此验出疹之要法。 \n凡疹热六日而出，一定之规也。若医人无识，用药太早，耗散元气，及至出时，变害多矣。或嗽而变喘， \n或出一二日即隐，或作大泻，或合目而喘，此医人用药不当之害也。吾家治法，定不在五日内用药 \n，必待见疹，方用徐徐升表。然用药亦有次第，凡一剂必作十余次饮之，况疹在皮肤之间，苦作一 \n次服，则药性催之太急，每致谵语烦躁，故当慎之。 \n景岳曰∶按此万氏之法，谓医人用药太早，恐致耗散元气，故必待见点而后施治，及作一次 \n服，恐药性催之太急，皆惟恐无益而反以致害，此固其心得之法也。然以愚见，则医有高下，药有 \n宜否，但使见有确真，发无不当，则于未出之前，或解或补，必有得预防之力，以潜消其毒者；既 \n出之后，亦必有善调之方，而不致催急者，此在善与不善，或不嫌早与不早也。尝见庸流之误治者 \n多，是诚不服药为中医也。此万氏之说所以不可不遵。 \n凡疹热五六日必出矣，医人用药见不能散，父母见药不效，医人见热嗽不能除，或以别证治之 \n，主家又或更医，此世之所以误者多矣。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>麻疹初热（七）\n\n属性：麻疹发热之初，与伤寒相似，惟疹子则面颊赤，咳嗽喷嚏，鼻流清涕，目中有泪，呵欠喜睡， \n或吐泻，或手掐眉目，面赤为异耳。但见此候，即是疹子，便宜谨避风寒，戒荤腥浓味。古法用升 \n麻葛根汤以表散毒邪，余制透邪煎代之更佳，或柴归饮亦妙。但使皮肤通畅，腠理开豁，则疹毒易 \n出，不可作伤寒，妄加汗下也。妄汗则增热而为衄血咳血，为口疮咽痛，为目赤肿，为烦躁干渴， \n为大小便不通。妄下则里虚，为滑泄，为滞下。经曰∶必先岁气，母伐天和。言不可妄汗妄下也。 \n凡疹初热疑似之间，切不可轻易用药。总有他证，必待五日，腮下见疹，方可用升表之剂。嗽 \n多、连打嚏喷，鼻流清涕，或流鼻血，饮食减少，好饮凉水，只宜调理饮食，戒面食荤腥。 \n一、疹子初发热时，未见出现，咳嗽百十余声不已，上气喘急，面目胞肿，时卧时起，此火毒内 \n蒸，肺叶焦举，宜甘桔汤合白虎汤加牛蒡子、薄荷主之。如疹出之时，咳嗽口干，心烦者，此毒在 \n心肺，发未尽也，泻白散加天花、连翘、玄参、黄连主之。 \n一、疹子欲出未出之时，宜早为发散以解其毒，则无余患。若不预解，使之尽出，多致毒蓄于中 \n，或为壮热，日久枯瘁，或成惊痫，成为泻痢，或为咳血喘促，或作疳蚀而死。此虽一时戾气之染 \n，然未有不由于人事之未尽也。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹出没（八）\n\n属性：一、疹子出没，常以六时为准。假如子后出，午后即收，午后出，子后即收，乃阳生阴成，阴 \n生阳成，造化自然之数也。凡此旋出旋收者轻。若一出连绵三四日不收者，乃阳毒太甚，宜大青汤 \n，或用荆芥、牛蒡子、甘草、玄参、石膏、桔梗主之。若逡巡不出者，乃风寒外束，皮肤闭密也， \n宜荆防败毒散主之。 \n一、疹已出而复没者，乃风寒所逼而然，若不早治，毒必内攻，以致痒 而死。急用升麻汤加 \n荆芥、牛蒡子、甘草热服，则疹必复出而安矣。 \n一、发热六七日以后，明是疹子却不见出，此必皮肤坚浓，腠理闭密，或为风寒所袭，或曾有 \n吐泻，皆能伏也。急用托里散表之剂，如麻黄汤去杏仁，加蝉蜕、升麻，外用胡荽酒之类。如一向 \n未更衣者，必毒甚于内，伏而不出《局方》凉膈散加牛蒡子主之。 \n一、疹子只怕不能得出，若出尽则毒便解。故治疹者，于发热之时，当察时令寒暄，酌而治之 \n。如时证大寒，以桂枝葛根汤，或麻黄汤发之。时证大热，以升麻葛根汤，或合人参白虎汤发之。 \n不寒不热，以荆防败毒 \n散发之。如兼疫疠之气，以人参败毒散发之。如尽一剂，不出，再作本汤服之，外用胡荽酒，又以 \n苎麻蘸酒遍身戛之，务令亟出。如三四作更不出，加腹中胀痛，气喘昏闷，则死证也。 \n景岳曰∶按此万氏之法，极得随时制宜之善，已尽发表之义矣。然发表之义，亦最不易，即如 \n营卫不足而疹有不能出者，其证甚多，若徒知发之，而不知滋之，则营卫有弱者，非惟不能发，而 \n且恐穷其源矣。此其或在脾胃，或在血气，必得其神，庶乎有济。如伤寒三表之法，实亦有关于此 \n。 \n一、疹毒出尽，则邪气解散，正气自然和平。如发热烦闷，或呕吐，或泄泻，此毒邪壅遏，尚 \n未出尽也。烦热者，黄连解毒汤。呕泄者，柴胡橘皮汤。并外用胡荽酒，及苎麻戛法如前。待疹子 \n出尽，则烦热自去，呕吐自止矣。 \n一、疹有既收而余毒未尽，至三日之外又复发出，或至五六次不已者，此因发热之时，不避风 \n寒，致令邪气郁于肌肉之间，留连不散，虽曾解散，终属未畅耳。若兼杂证，亦当随证治之。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹形色（九）\n\n属性：凡看麻疹初出之法，多于耳后、项上、腰腿，先见其顶尖而不长，其形小而匀净者吉也。若色 \n见通红，则疹发于心，红者，火之正色也。若疹色淡白者，心血不足也，养血化斑汤主之，或四物 \n汤加防风。色大红焰或微紫者，血热也，或出太甚者，并宜大青汤主之，或四物汤去川芎加柴胡、 \n黄芩，干葛、红花、牛蒡子、连翘，凉血滋阴而热自除，所谓养阴退阳之义，亦五死一生之证也。 \n若黑色者，则热毒尤甚，而十死一生之证，此尤不可不明察之而混为施治也。 \n凡疹初出色赤者，毒盛之势也。但大便调，咳嗽多，右手一指脉轻重取皆有力，虽势重不碍， \n但当随证调理。若嗽少，右手一指脉无力，虽三日后收，其浑身疹疮变为紫色，壅结于皮肤之间， \n若用解利之药，其色渐 \n转红色，嗽多流涕，颇思饮食者生，若投二三剂难变者难疗也。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹涕（十）\n\n属性：凡疹出至二三日，必两鼻俱干。待收完，看毒瓦斯轻者，清涕即来，就思饮食，此不必服药。若 \n清涕来迟，不思饮食者，须要清肺解毒，必俟清涕出，方可不用药。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹吉凶（十一）\n\n属性：或热或退，五六日而后出者轻。 \n透发三日而渐没者轻。 \n淡红滋润，头面匀净而多者轻。 \n头面不出者重。 \n红紫黯燥者重。 \n咽喉肿痛不食者重。 \n冒风没早者重。 \n移热大肠变痢者重。 \n黑黯干枯，一出即没者不治。 \n鼻扇口张，目无神者不治。 \n鼻清，粪黑者不治。气喘，心前吸者不治。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>总论治法（十二）\n\n属性：一、疹喜清凉而恶湿，痘喜温暖而恶凉，此固其大法也，然亦当有得其宜者。如疹子初出，亦须 \n和暖则易出，所以发苗之初，只要发出得尽，则疹毒便解，非若痘之苗而秀，秀而实，而后毒解也 \n。痘子成熟之时，若太温热，则反溃烂不收，是痘之后亦喜清凉也。故治痘疹者，无过热，无过寒， \n必温凉适宜，使阴阳和平，是为得之。 \n一、痘宜内实，可用补剂；疹忌内实，只惟解散，惟初热发表时略相似耳。既出之后，痘宜补气 \n以生血，疹宜补阴以制阳。何也？盖疹热甚则阴分受其熬煎，而血多虚耗，阴津被克，故治以清火 \n滋阴为主，而不可少动其气，若燥悍之剂，首尾皆深忌也。世知痘证所系之重。而不知疹之杀人尤 \n甚，方书多忽而不备，良可太息也矣。 \n一、斑疹之毒，皆出于火。《内经》曰∶赫曦之纪，其病疮疡。故或遇二火司天，或司运之岁， \n肺金受制，感而发者居多。轻则如蚊迹之状，或垒肿于皮肤间，名曰瘾疹。重者如朱点红晕，或片 \n片如锦纹，名曰斑疹。大抵色赤者吉，色黑者凶。其证似伤寒发热，凡三四日而出，七八日而靥也 \n。凡此之类，皆属邪热，治之之法，惟辛凉解利而已。即若吐泻，亦断不可用温补也。如豆蔻、干 \n姜之类，切勿轻用。而初发之时，尤不可大汗，只宜升麻、葛根、透邪煎之属，微表之耳。故用宜 \n斟酌，有不可一概取必也。 \n一、标出不红，现而发热转甚，或头痛身痛烦躁者，升麻汤，或透邪煎。 \n一、色赤稠密，身痛烦躁者，升麻汤加紫草、连翘。 \n一、寒热并作，头痛背强者，升麻汤加羌活、防风、连翘。 \n一、头项面肿，升麻汤加牛蒡子、荆芥。若脉强火盛热渴者，宜清降其火，以白虎汤加减用之 \n。 \n一、自汗烦渴，气壅脉数者，化斑汤。 \n一、身热烦渴，泄泻者，柴苓汤，或四苓散。如夏月，益元散。 \n一、热甚，小便赤涩，谵语惊恐者，导赤散、四苓散加辰砂。夏月，益元散加辰砂。 \n一、咳嗽甚者，二母散、麦门冬汤、清肺汤。 \n一、喘者，小柴胡汤去人参加五味子。 \n一、热甚鼻衄，或便血溺血热甚者，黄连解毒汤。血甚者，犀角地黄汤。 \n一、伤食呕吐，六君子汤加藿香、干葛，或减去人参。热甚呕吐者，解毒汤。小便不利而呕吐 \n者，四苓散。一二日不通者，导赤散。 \n一、大便秘结，发热身痛者，大柴胡汤。腹胀气喘者，前胡枳壳汤。 \n一、咽喉不利，甘桔汤。兼风热咳嗽者，加防风。 \n一、寒热往来似疟，小柴胡汤，如兼咳嗽去人参。 \n一、靥后身热不除者，升麻汤，或去升麻加黄芩、黄连各酒炒用。 \n一、下痢赤白腹痛者，黄芩芍药汤，或加枳壳，身热腹痛者，解毒汤。 \n一、余毒未尽，变生痈疽疮疖者，升麻汤加防风、荆芥、牛蒡子。 \n景岳曰∶按以上万氏治疹诸条，皆极详妥，然其中惟泻痢气喘二证则最多疑似。盖二证之由疹 \n毒，固当如其治矣。然有不因疹毒者，如俗医但见是疹，无不概用寒凉，不知有可凉者，有不可凉 \n者。其有脾气本弱而过用寒药，或以误会生冷致伤脾胃而为泄泻者，亦多有之。此一证也，虽曰由 \n疹而发，而实非疹毒之病矣。但察其别无热证热脉，而兼之色白气馁者，便须速救脾气，急从温补 \n，宜温胃饮、五君子煎、胃关煎之类主之。若执谓疹毒不可温，则无不危矣。此医之当知本也。又 \n如气喘一证，大有虚实。盖十喘九虚，若察其本非火证， \n又非外邪，而或以大泻，或以大汗而致喘者，必皆气脱之候，此非六气煎，或贞元饮必不可也。凡 \n此二者，皆不可不加细察，而或者以气促作气喘，则万万大误矣。又痘疮总论中，有因人因证之辨 \n，与此麻疹实同一理，所当参阅。故不可以麻疹之邪，悉认为实火，而不知虚火之为害也。 \n徐东皋曰∶痘难疹易之说，此俗谈耳。其有胃气原弱，所感入深，又或因泻利而发有不快，或 \n发之未透而随现随隐，久之邪气渐入于胃，必泻泄不已，出而复出，加之喘促，则必危矣。凡若此 \n者，又岂可以易言哉。所以但有出疹，若见虚弱，急当先补脾胃；其有欲出不出，急当托里发表以 \n助之。且首尾供不可泻，一如痘证同也。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹禁忌（十三）\n\n属性：凡疹疮发表之后，红影出于肌肤，切戒风寒生冷。如一犯之，则皮肤闭密，毒瓦斯壅滞，遂变浑 \n身青紫，而毒反内攻，烦躁腹痛，气喘闷乱，诸证作矣。欲出不出，危亡立至，医家病家皆不可不 \n慎。 \n一、疹疮之证，全在调治，禁忌如鸡鱼炙爆，盐醋五辛之类，直过七七之后方可食之，惟宜食 \n淡，不可纵口，致生他疾也。若误会鸡鱼，则终身皮肤粟起如鸡皮之状。或遇天行出疹之时，又令 \n重出；误食猪肉，则每岁凡遇出疹之月，多有下利；误食盐醋，致令咳嗽，则每岁出疹之月，必多 \n咳嗽；误食五辛之物，则不时多生惊热，此痘疹之家皆所当慎也。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹发热（十四）\n\n属性：疮疹非热不出。凡疹子欲出，必遍身发热或烦躁，或头眩，或身体拘急。及既出则身便凉，诸 \n证悉解，此一层疹子随即收者，极轻者也。如疹子既出而热甚不减，此毒盛者也，宜大青汤解其毒 \n。便涩者，宜黄连解 \n毒汤合白虎汤，或大连翘饮解其里。大便不通者，《局方》凉膈散加牛蒡子主之。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹喘嗽（十五）\n\n属性：凡疹证多嗽，此顿出顿入之势也。但有疹毒，须假嗽多而散，故疹后旬日之内，尚宜有嗽，切 \n不可见嗽多而治嗽也，宜慎之。疹证属肺与脾胃，肺受火邪则嗽多，嗽多则顿出头面并及四肢；大 \n肠受火邪，则上连脾胃而为泄泻。若早泻则嗽必减而变为喘，盖喘嗽二者皆属于肺。然嗽实喘虚， \n得嗽者出，得喘者入，入则合眼多痰，胸满腹胀，色白而毒不尽出，证则危矣。此疹之宜嗽不宜喘 \n，而最不宜于泄泻也。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹吐泻（十六）\n\n属性：凡疹子初起，发热吐利，纯是热证，不可作寒论。此乃火邪内逼上焦则多吐，下焦则多利，中 \n焦则吐利并作。自利者，宜黄芩汤。吐利者，宜黄芩汤加半夏二钱、生姜三片。自利里急后重，宜 \n黄连解毒汤合益元散。 \n凡疹出一二日，或三四日，忽然大泻，嗽多者，用升表之药，加以分利治之。苦泻而兼喘，复 \n见闷乱摇头者凶。 \n一、麻疹现后，大便下脓血，或因泄泻而变成脓血者，或径自利者，但看疮疹出多而色红又多嗽 \n者，只宜表疹。俟其收后，方宜解毒，兼治其痢。 \n一、疹子初起，最忌泄泻，然亦有始终泄泻而不妨者，禀之强弱异也。苦因泻嗽减而变为喘者则 \n危矣，详前喘嗽条。 \n一、身热烦渴泄泻者，柴苓汤、四苓散。如热甚或夏月，益元散。 \n一、疹后作痢、亦有看手咬指甲，撕口唇皮，及咬人等证，当以解毒分利药治之。若所下稠涎， \n红白相兼者，务要用解毒之药。若昼夜由三、五十次，渐减至二、三次，成渐多嗽，右手一指脉渐 \n起，清涕复来者，方 \n可望生。若痢变煤色，或现房漏色，或如青菜色，肛门如筒，喘促音哑，饮食不进，午后腮红，皆 \n不治。 \n景岳曰∶自古方书，凡发挥未尽，及用治未当者，间亦有之，而惟于泄泻一证则尤其为最。何 \n也？盖古人以池泻为热者什九，故多用河间黄芩芍药汤为主治，而不知凡属泄泻，最多脾肾虚寒也 \n。即如出疹一证，虽有由疹毒而泻者，然果系实热，多不作泻，但致泻者，卒由脾胃之弱。若但知 \n清火解毒，则脾必日败，而渐现房漏、青菜色，及气促、绝食不治之证矣。病而至此，岂犹热耶？ \n总属误耳。故凡治泄泻者，即虽是疹，亦必察其有无热邪。如无热证热脉，即当于痘疮泄泻条求法 \n治之，庶最危者犹可望其生也。故余于诸法之外，而独言其要者有如此。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹饮食（十七）\n\n属性：凡出疹者，多有五六日不饮食，此胃为邪气所侵，亦为邪气所养，故不食亦不妨。切不可着意 \n治之，只宜治疹，疹疮出尽，毒瓦斯渐解，即思饮食。尤不可与面食，虽用粥饮，每次只可少与，候 \n气清神爽，身全不热，渐渐加添，但宜少而频也。 \n凡出疹之先，平昔过用面食者，或正出时吃面食者，成胃气渐开即思面食而用早者，因动胃火 \n，以致清涕不来，身体作热，两眼看手，咬指抠鼻，撕口唇皮，及撕眼札毛者，此皆疹后食复之病 \n也，当清肺解毒，加消导之剂治之。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹饮水（十八）\n\n属性：凡患疹之人，不拘大小，自起至收，必皆喜饮凉水。此不必禁，但宜少不宜多，宜顿不宜顿， \n则毒瓦斯随之渐解。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹渴（十九）\n\n属性：凡疹子渴喜饮水，纯是火邪，肺焦胃干，心火内亢故也。初热发渴者，升麻葛根汤加天花粉、 \n麦门冬；渴甚者，人参白虎汤合黄连解毒汤主之。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹汗衄（二十）\n\n属性：凡疹子发热，或自汗，或鼻衄者，不须止之，此亦散越之义。汗者，毒从汗散；衄者，毒从衄 \n解，但不可太过。如汗太多，人参白虎汤，或合黄连解毒汤；衄太多者，玄参地黄汤。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹躁妄狂乱（二十一）\n\n属性：凡疹有初热而见烦扰谵妄狂乱者，宜升麻葛根汤调辰砂益元散主之。 \n一、疹收之后，余热未尽，日夜烦躁，谵语狂乱者，辰砂益元散用灯心汤调下，或四苓散加灯草 \n、黄连、黄芩，调水飞朱砂五分主之。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹咽痛（二十二）\n\n属性：痘疹咽痛亦是常候，乃火毒上熏而然也，勿以喉痹同论，妄用针刺。盖此非喉痹痈肿，原无恶 \n血可去也。痘疹喉病，只是咽干作痛，宜廿桔汤加牛蒡子，或射干鼠粘子汤，细细咽之，更以玉钥 \n匙吹之。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹唇口疮（二十三）\n\n属性：凡出疹之先，或有胃火，及出疹之后，余毒不散，此热毒收于牙龈上下，故并唇口生疮。遇有 \n此证，每日 \n用温米泔水洗十余吹，急用解毒之药治之。若或失治，多变走马疳也。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹腹痛（二十四）\n\n属性：凡疹初热一日至五六日之间，多有腹痛之证。此大肠之火郁于皮窍之中，故作腹痛。俱不可认 \n作伤食，用消导之药，或以手揉，俱能致害。但解疹毒，毒散则腹痛自止，最宜慎之。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>疹后诸证（二十五）\n\n属性：凡疹后余毒未尽，随当解之。若停留日久不解，则必致喘嗽，或喉中痰响，或为四肢冷痹，或 \n目无光彩，面色青白，或鼻孔如烟筒，或嗽声不出。若右手一指脉轻取散乱，重按全无，则成难治 \n之证矣。 \n一、疹子收后身有微热者，此虚热也，不须治之，待血气和畅，其热自退。苦热势太甚，或日 \n久不减，宜用柴胡麦门冬散；甚则黄连解毒汤，或合人参白虎汤。 \n一、疹后热不退，而发枯毛竖，肉消骨立，渐渐羸瘦，为骨蒸劳瘵之证者，宜万氏柴胡四物汤 \n主之，或芦荟肥儿丸加当归、连翘治之。迟则变证，为睡则露睛，口鼻气冷，手足厥逆，遂成慢脾 \n风螈 ，不治之证矣。 \n一、疹后热不除忽作搐者，不可以急惊风同论，宜导赤散加人参、麦门冬，送七味安神丸。小便 \n清者可治，短少者难治。如见多痰，或用抱龙丸，或以四物汤加麦门冬、枣仁、淡竹叶、甘草、龙 \n胆草、黄连、茯苓、辰砂、石菖蒲之类治之，或以此药为末，用蒸饼、猪心血为丸服亦可。 \n一、疹退后多有咳嗽之证。若微嗽不已者，此余毒未尽也，用清肺饮加生甘草、牛蒡子主之。 \n苦嗽甚气逆，发而不已者，此肺中伏火，金虚叶焦也，宜清肺饮，或清肺汤合人参白虎汤、六一散 \n之类主之。若身热顿嗽，甚至饮食俱呛出，或咳出血，皆热毒乘肺而然，宜多用门冬清肺汤，或加 \n连翘，或清金降火汤主之。若咳甚而面浮目肿，胸高喘急，血退场门鼻，面色青赤，昏躁摇头者，死 \n证也。又有肺气本虚，为毒所逼而发喘不已，但 \n无嗽血呛会等证者，宜用清肺饮倍加人参治之。不可拘于肺热之说，而纯用清肺解毒之药也。 \n一、疹后余热未尽，或热甚而失血者，四物汤加茵陈、木通、犀角以利小便，使热气下行则愈。 \n若血在上者去川芍。 \n一、疹后余毒入胃，久而不散，以致牙龈黑烂，肉腐血出，臭气冲人者，名为走马疳，用马鸣 \n散主之；甚者急用人中白、芦荟、使君子、龙胆草、黄连、五灵脂，浸蒸饼为丸，滚水服之，以清 \n胃火。若面颊浮肿，环口青黑，齿脱唇崩鼻坏者，死证也。 \n一、疹退之后，饮食如常，动止如故，乃卒然心腹绞痛，遍身汗出如水者，此因元气虚弱，失 \n于补养，外虽无病，里实虚损，偶然为恶气所中，谓之中恶。此朝发夕死之证。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>附麻疹（二十六）\n\n属性：痘之外有疹，疹子外又有麻疹。麻疹者，亦疹之类，即斑疹也。但正疹则热至五六日而后一齐 \n涌出，出皆粒粒成疮，非若麻疹之皮红成片也。且麻疹之出，则不拘三四日，以火照之，遍身涂朱 \n之状，此将出之兆。出则细碎，皮红成片，如蚊蚤之迹者，即麻疹也。亦或有六日始出，出而又没 \n，没而又出，不过一周时许。世俗谓一日三出，三日九出，后方齐出透彻。然亦有不拘者，只三日 \n间，从面至胸背手足，虽随出随没，然只要出透，以遢身红润者为美。重者遍身膨胀，眼亦封闭。 \n色有赤白微黄不同，只要红活，最嫌黑陷，及面目胸腹稠密，缠锁咽喉者为逆，发不出而喘者即死 \n。所谓麻者，以遍身细碎如麻，无有空处故也。然又有遍身但红而绝无斑点者，是又谓之火丹，亦 \n其类也。故痘家有夹疹、夹麻、夹丹等证，总皆热毒所致，俱当详辨也。 \n一、麻疹初起，呵欠发热，恶寒咳嗽，嚏喷流涕，宜升麻葛根汤加苏叶、葱白以解肌，切忌大汗 \n。若潮热甚者，加芩、连、地骨皮。谵语者，调辰砂益元散。咳嗽加麻黄、杏仁、麦门冬、石膏。 \n咳甚热甚者，用凉膈散加桔梗、地骨皮。泄泻者，宜四苓散。便红合犀角地黄汤。吐血衄血，用犀 \n角地黄汤加山栀。小便赤加木通。 \n寒热似疟，小柴胡汤。 \n一、麻疹已出，烦躁作渴者，解毒汤合白虎汤。喘而便闭者，前胡根壳汤加五味子。便秘甚者 \n，小承气汤。谵语溺闭者，导赤散。小便如泔者，四苓散加车前、木通。谵语如狂者，解毒汤调辰 \n砂益元散。大小便血者，犀角地黄汤合解毒汤。吐血衄血，解毒汤加炒山栀、童便。泄泻，解毒汤 \n或四苓散。喘兼泄泻，溺赤涩者，柴苓汤。烦热大渴作泻者，白虎汤加苍术、猪苓。热盛干呕者， \n解毒汤。伤食呕吐，四君子汤。夏月因热作呕，四苓散加人参。 \n一、麻证初起，及已出已没，一切杂证俱与痘疹大同，但始终药宜清凉。虽曰麻喜清凉，痘喜 \n温暖，不易常道，然虚则补，实则泻，寒则温，热则凉，方是医家玄妙。故治麻亦有血虚而用四物 \n汤，气虚而用四君子汤，伤冷则温中、理中之药，皆当因证而用也。 \n一、麻证收后，余毒内改，凡寻衣摸床，谵言妄语，神昏志乱者死。如热轻而余毒未除，必先 \n见诸气色，若有所见，须预防之，始终以升麻葛根汤为主，或四味消毒饮，或六味消毒饮、解毒汤 \n，随证选用，仍忌鱼腥葱蒜等物。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>水痘（二十七）\n\n属性：凡出水痘，先十数点，一日后，其顶尖上有水泡；二日三日，又出渐多；四日浑身作痒，疮头 \n皆破，微加壮热即收矣。但有此疾，须忌发物，七八日乃痊。 \n一、水痘亦有类伤寒之状，身热二三日而出者，或咳嗽面赤，眼光如水，或喷嚏，或流涕，但 \n与正痘不同，易出亦易靥，治以清热解毒为主。 \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>麻疹论列方（二十八）\n\n属性：四君子汤（补一） 五君子煎（新热六） 六君子汤（补五） 四物汤（补八） 六气煎（新因二一） 人参 \n败毒散（散三六） 化斑汤（寒三） 白虎汤（寒二） 大柴胡汤（攻七） 小柴胡汤（散十九） 甘桔汤（因一 \n七五） 解毒汤（痘五一） 黄连解毒汤（寒一） 麻黄汤（散一） 升麻汤（痘一三九） 升麻葛根汤（散三十） \n透邪煎（新因二三） 托里散（痘四） 《局方》凉膈散（攻十九） 柴归饮（新因十五） 清肺饮（痘八七） 清 \n肺汤（痘一四五） 柴胡橘皮汤（痘二九） 仲景黄苓汤（寒百五） 二母散（痘百五十） 射干鼠粘子汤（痘七 \n七） 麦门冬汤（痘一四二） 导赤散（寒一二二） 万氏柴胡四物汤（痘一四三） 四苓散（和一八七） 柴苓 \n汤（和一九二） 养血化班汤（痘十八） 小承气汤（攻二） 益元散（寒百十二） 门冬清肺汤（痘一四七） 大 \n清汤（痘一五三） 泻白散（寒四二） 清金降火汤（痘一四九） 柴胡麦门冬散（痘二四） 贞元饮（新补十九） \n柴胡麦门冬散（痘二四） 胃关煎（新热九） 大连翘饮（寒七八） 玄参地黄汤（痘八六） 七味安神丸（小七 \n二） 玉钥匙（因一九三） 马鸣散（痘一三八） 胡荽酒（痘百十八） 四味消毒饮（痘四八） 犀角地黄汤（寒 \n七九） 芦荟肥儿丸（小百十四） 六味消毒饮（痘四九） 前胡枳壳汤（痘九四） 桂枝葛根汤（痘三七） 黄 \n芩芍药汤（寒百丸） \n\n\n\n<目录>卷之四十二谟集·痘疹诠\\麻疹（全）\n\n<篇名>备用方\n\n属性：具列痘疹方末，所当详阅。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>总论（一）\n\n属性：痘疮一证，俗曰天疮，原其所由，实由胎毒内藏，而复因时气外触，其毒乃发，故传染相似， \n是亦天行疫疠证也。但考之《内经》则止言疡胗，即今斑疹之属也。故自越人、仲景、元化、叔和 \n诸公皆无一言及痘，可见上古本无是证，而今则何以有之？愚谓近代之毒，必以醉酒五味造作太过， \n较古人之恬淡，相去远矣。或者未信余言，第观藜藿膏粱之家即有不同，今之北虏亦不出痘，原其 \n所由，实由是耳。岂果彼无胎毒耶？故凡多遭此害者，当以余言熟味之。 \n一、痘疮变纪百出，虚中有实，实中有虚，要非曲学偏见者可以窥其堂室，若目力心思一有不 \n到，则害不小矣。设或知证而不知形，则无以洞其外；知形而不知脉，则无以侧其内；知脉而不知 \n本，则无以探其源；知本而不知囚，则无以穷其其变；知因而不知药，则无以神其治。只此数事， \n今医果能全之否？设有不能而强以为能，则致害于人，获非于天，能无畏乎？故余十痘疹一门，留 \n心既久，积验已多，因搜采先哲之最精于此者，如文中陈氏，仲阳钱氏，立斋薛氏，罗田万氏，晨 \n峰程氏，东皋徐氏，改斋友氏，并其他杂录等书，有述其旧者，有发其未发者，有剖其疑似者，有 \n因涉历而吐其心得者，尽我愚衷，集而成帙。痘疹玄秘，似无出此。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>初辨痘证（二）\n\n属性：痘疹发热，大抵初时与伤寒相似。然伤寒之邪从表入里，故见各经之证，痘疹之毒则从里出表， \n故见五脏之证。如呵欠闷顿，肝证也；乍凉乍热，手足稍冷，多睡，脾证也；面燥腮赤，咳嗽喷嚏， \n肺证也；惊悸，心证也； 凉耳冷，肾证也。又观心窝有红色，耳后有红筋，目中含泪，成身热， \n手指皆热，惟中指独冷，乃知是痘证也，盒饭察其虚实，随证治之。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>初辨痘证（二）\n\n属性：五指稍头冷，惊来不可当。若逢中指热，必定是伤寒；中指独自冷，麻痘证相传。女右男分左， \n分明好细看。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>初辨痘证（二）\n\n属性：两耳红筋痘必轻，紫筋起处重沉沉，急须用药相攻治，十个难求三五生。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>初辨痘证（二）\n\n属性：凡初看痘法，以纸捻蘸油照其颗粒，次以手摸面颊，如红色随手转白，随白转红，谓之血活， \n生意在矣。若揩下不白，举之不红，是谓血枯，纵疏亦危。又看目睛神光，口唇舌尖，红活如常， \n无燥白之色，乃为吉兆，自可无忧。此观痘疹之大治。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>初辨痘证（二）\n\n属性：凡看痘之法，一见发热，即当先察其脉。盖凡痘疮将出者，未见形迹，必先发热，既见发热， \n脉必滑数。 \n但微见滑数有神而不失和缓之气者，其痘必轻而少；若滑数加倍而犹带和缓者，其痘必多而重，尚 \n亦无害；若滑数之甚，义兼弦躁，或芤急无神而全无和缓之气者，其痘必甚而危，故余于初熟时， \n便能断其吉凶，人多惊服而不知所窥在脉也。凡诊此之法，但全握小儿之手，而单以拇指诊之，亦 \n最易也。看疹之法，此为第一，而今医多不知之，亦以古人之未之及耳。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>初辨痘证（二）\n\n属性：凡痘疮紧小充实者，名曰珍珠痘，此则易壮易靥。高硕饱满者，名曰大痘，此则早壮而迟收。 \n四围起而中心陷者，名茱萸痘；平扁不突者，名曰蒸饼痘，此则有凶有吉，稀者轻，密者重。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>论脉（三）\n\n属性：痘自发热以至起胀，毒从内出，阳之候也，脉宜浮大而数，不宜沉细而迟。自灌脓收靥以后， \n毒已外解，阴之候也，脉宜和缓，不宜洪数。又曰∶痘疮之脉，中和为贵，不可过于躁疾，或见微 \n小。故曰∶脉静身凉者生，脉躁身热者死。又阳病得阴脉者死。大抵四时以胃气为本，胃气者，以 \n四时之脉而皆兼和缓，即胃气也。盖滑、数、浮、洪为太过，太过为实，实者邪气实也。弦、迟、 \n微、弱为不及，不及为虚，虚者正气虚也。设以太过不及之脉，而中无和缓之气，是皆死候之脉， \n故曰人无胃气则死。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>形色情性（四）\n\n属性：凡天行痘疹之时，有于未出之先，察其形色情性，可以预知吉凶也。一观其色∶如面颜红白明 \n润，与平日同而无变者吉，如忽见红赤而太娇，或 白而无彩，顿然改变异于平时者凶。又如额有青 \n纹，目有赤脉，口有 \n黑气，耳有尘痕者，皆大凶之兆。二观其形∶凡精神畅爽，动止便利，语言清亮者，无病而吉也； \n如精神衰弱，动止迟留，言语低微异如平时者凶。又原具寿相者吉。如有天相，则儿头破颅解，项 \n小脚细，声微目无精彩，或睛光露神，啼声断续，无喜无情而自语自笑，聪意太早，肉浮骨嫩者， \n皆不吉之兆。三观情性∶几未发热时；忽生喜心，若与父母爱恋不忍舍者，及闻见怪异言语妄诞者， \n皆凶兆也。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>日期（五）\n\n属性：痘疮大约之数，发热三日，报痘三日，起胀三日，灌脓三日，结靥三日，共十五日，乃大率常 \n数，此其正也。惟痘密毒甚者，常过其期；痘疏毒微者，常不及期，固有不可一例拘者。但得痘色 \n明润，根窠红活，饮食二便如常，又无表里杂证，虽迟数日不妨。设有当出不出，当起不起，当脓 \n不脓，当靥不靥者，须详察其证。或为元气虚弱，不能营运，则补其元气，成为杂证攻剥，不能通 \n灌，则去其杂证。又六日以前毒发未尽，有杂证者常也；六日以后，毒该尽出，杂证当除而不出者 \n为逆，须详辨而急治之。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>五脏证（六）\n\n属性：痘疹二证，古人有云∶痘自里而出于脏，其毒深，故久热而难出为重；疹自表而出于腑，其毒 \n浅，故暴热而易出为轻。余谓此说未必然也。盖痘疹皆出于脏腑，未有表里不相通者，但出于腑者 \n在痘亦轻，出于脏者在疹亦重。所以凡是疹子，必发热至五六日而后出，不可言易。且疹子多属肺 \n经，岂肺经非脏耶？ \n一、心经痘证，心主火，儿红赤烦渴，或上窜切牙者，心脏热也。心热者，导赤散。心虚者， \n人参、麦门冬、生地黄、当归之类。烦渴邪盛者，葛根解毒汤。脾经痘证，多有吐泻腹痛者，诀云∶ \n发热肚中痛，斑疮腹内攻。发多防未透，发少更防痈。可见疮疹腹痛乃为恶候，当察腹痛吐泻各条 \n治之。肺经痘证，凡发热之时，喘息气逆，喉中涎响，此肺经恶候也。盖毒火内蒸刑肺而然，当察 \n本条治之。肝经之痘，儿发热之初，多有惊 \n搐等证。盖痘毒多热，热则生风，风热相搏，故发惊搐。然有当速治者，有不必治者，详见本条。 \n肾经痘证，初发热时，便觉腰痛。盖肾与膀胱为表里，今毒由太阳传入少阴，所以腰痛。此其毒陷 \n阴分，最非佳兆，宜察本条治之。 \n一、毒归五脏，证有不同，当详辨也。毒归于心，则为斑疹，为惊悸，为壮热，为咽干，为痛， \n为渴，为汗，为丹瘤，为痈疡溃烂。毒归于肺，则为咳，为喘，为痒，为衄血，为疮，干燥皱揭， \n为肩臂痛。毒归于脾，则为吐，为泻，为肿，为胀，为腹痛，为唇疮破裂，为舌本强，为手足痛， \n为不食。毒归于肝，则为闷乱，为水 ，为目病。为卵肿，为干呕，为筋急拘挛，为吐蛔，为寒战 \n切牙。毒归于肾，为腰痛，为黑陷，为失音，为手足逆冷，为咽干痛，为饥不欲食，为多唾。毒归 \n于肠胃，为泄泻，为痢脓血，为腹鸣矢气，为大便不通。毒归于膀胱，为小腹满痛，为溺血，为遗 \n溺，为小水不通，为头顶肿痛，为反张，为目上视。以上五脏之证，举其概耳，凡诸证治，俱备杂 \n证各条之中，宜详究之。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>分气血（七）\n\n属性：一、气血各有所主。凡痘之终始，无非藉赖血气，但得血气充畅，则易出易收，血气不足，则 \n变证百出，故治痘者，必当先顾血气。然气属阳，无形者也；血属阴，有形者也。故无形之属，皆 \n气主之；有形之属，皆血主之。是以气主标，血主本；气主发，血主肥；气主形，血主色；气主橐 \n，血主根基。故气能起胀，以主乳郭；血能灌浆，以成饱满。至其为病，则凡为白，为陷，为灰 \n色，为不起发，为顶有孔，为出水，为痛，为痒，为浮肿，为豆壳，为不靥不落，为饥表不固，为 \n肤腠不通等证，皆气之为病也。又如为紫黑，为干枯，为无血，为无脓，为黑陷黑靥，为胛痛牙疳， \n为疔痈斑疹，为津液不达，为痘后余毒，皆血之为病也。此气血之分固有如是，然血无气不行，气 \n无血不止。气至而血不随，虽起发而灌必不周；血至而气不至，虽润浮而毒终不透。故治此者，有 \n不可不兼顾也。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>辨虚质寒热（八）\n\n属性：一、察痘之要，惟在虚实二字。盖实者，邪气实也，邪实者，宜清宜泻；虚者，血气虚也，血 \n气虚者，宜温宜补。且痘本胎毒，非藉元气不能达，非藉元气不能收。故凡欲解毒清火，亦须凭借 \n元气，使元气无力，则清亦不能清，解亦不能解，设有不支，尚能堪此清解不？此痘疮之终始，皆 \n当斟酌元气为主。 \n一、痘疮表实里虚者，必易出难靥；表虚里实者，必难出易靥；若表里之气俱充实，其疮必 \n易出易靥。故儿自始出以至十日之外，外则浑身壮热，内则饮食二便俱如常，此即表里俱实者也， \n其疮必光泽起发，且易收易靥也。 \n一、表里各有虚实。凡表虚者，或恶寒，成身不大热，或寒热往来，四肢厥冷，或面青色白， \n多汗恶风，或怠惰嗜卧，或痘色灰白、顶陷不起、发不光泽，或色嫩皮薄痒 ，或如水泡、摸不碍 \n手，或根窠不红，或倒靥不能结痂，脉必浮细而弱，是皆表虚之证，治宜温补阳分。里虚者，凡 \n痘疮已出未出之间，有为吐泻呕恶，或喜热饮食，或为少食、不思饮食，或食亦不化，或为二便清 \n利，为溏泻，为不渴，为气促声微，为神昏多睡，为腹膨嗳气，为吞酸，为脉弱无力，是皆里虚之 \n证，治宜温补阴分。表实者，为身体壮热无汗，为面赤唇紫、头疼身痛、眼红鼻塞、皮焦肤赤、手 \n足热甚，为痘色红紫， 肿疼痛，为皮浓而硬，为痈肿斑疔，为脉浮洪滑大，是皆表实之证，治宜 \n清解表邪。里实者，为二便秘结，胸膈胀满，为唇燥咽干、口疮舌黑，为大渴咳嗽、痰涎喘粗， \n为烦躁惊狂、声高谵语，为脉沉数洪滑，是皆里实之证，治宜清解里邪。 \n张翼之曰∶吐泻少食为里虚，陷伏倒靥灰白为表虚，二者俱见，为表里俱虚，用异功散救之， \n甚至桂、附、灵砂亦可用。若能食便秘而陷伏倒靥者为里实，轻则射干鼠粘子汤，重则前胡枳壳汤。 \n下痢多血能食者为里实，若实其里则结痈毒。红活绽突为表实，若补其表则溃烂不结痂。 \n一、痘疮表里皆有寒热，热则阳证，寒则阴证，寒则血气凝涩而不章，热则血气淖泽而不敛。 \n然热证多 \n实，最忌 、术、桂、附及诸热燥之物，若元气虚弱者，即有热证，总不可执为实热。寒证多虚， \n最忌芩、连、栀、檗及诸苦寒之物，虽形体强盛，但见虚脉虚证，总不可认作有余。 \n表寒者，不起发，不红活，根窠淡白，身凉痒 ，倒陷干枯，皆肌表无阳之证，治宜补阳温表。 \n里寒者，为吐泻，为呕恶，为腹胀，为腹痛，为吞酸，为不欲食，为寒战切牙，气寒喜暖，为 \n二便清利、完谷不化，皆脏腑无阳之证，治宜温中补阳。 \n表热者，为肌肤大热，根窠红紫、顶赤发斑，头面红肿，紫黑焦枯，痈肿疔毒甚，皆火在肌表 \n之证，治宜散邪解毒。 \n里执者，为烦躁狂言，口干大渴，咽肿喉痛，内热自汗，小便赤涩，大便秘结，衄血溺血，皆 \n火在脏腑之证，治宜清热解毒。虚实寒热等证，虽表里之分，各有如此，然表之虚实，表之寒热， \n孰不由中气之所使，故惟善治中气，则未有表不和调者也，是即必求其本之道。 \n一、纯阴无阳之证，凡痘疮发热，手足却宜和暖，若手足厥冷，必其人曾有吐泻，脾脏气虚也。 \n脾主四肢所以冷为恶候，即有外证，亦不可单用发散，反损脾胃之气。此当温中兼表，宜黄 建中 \n汤，或六气煎、五物煎加防风、羌活、生姜、荆芥之类，以补养脾胃血气，而助痘疹之成就也。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>部位吉凶（九）\n\n属性：一、五脏之属，皆见于于面，故但察部位，可知吉凶。盖人之面部，左颊为肝，右颊为肺，额 \n上为心，颏下为肾，鼻为脾土。又目为肝之窍，鼻为肺之窍，口为脾之窍，耳为肾之窍，舌为心之 \n苗。若痘疹未出之先，但得面中诸部明润者吉，燥暗者凶。又山根为命宫，年寿为疾厄宫，此二宫 \n红黄光明者吉，青黑昏暗者凶。 \n三阳之脉皆会于面，正额为太阳脉之所会，唇颏为阳明脉之所居，两耳前后为少阳脉之所过。 \n痘为阳毒， \n故随阳气而先见于面。惟阳明经乃胃与大肠，积陈受腐，血气俱多之处，故痘疹初发，但于本经口 \n鼻两旁，人中上下，腮颏年寿之间先出现者为吉。如太阳经则水火交战之处，少阳经则木火相并之 \n乡，若于其位先现者凶。凡起浆收靥亦皆如是。 \n一、遍身部位皆有所辨，如头为诸阳聚会之处，两颐两颊为五脏精华之腑，咽为水谷之道路， \n喉为呼吸之关门，胸腹乃诸阳受气之海，为心肺之所居，脊背乃诸阳之统会，为十二经藏气之所系， \n儿此五处稀少者吉。若头额多者，谓之蒙头。颈项多者，谓之锁项。胸前多者，谓之瞒胸。蒙头则 \n阳毒亢，真阴竭。锁项则出入废，气化绝。瞒胸则心腹近，神失守。两颊两颐多至成片，或如涂朱 \n，则肝盛克脾。凡此者，至八九日间，多见滑泄泻青，或不能食，最为险候，故皆不宜多也。惟四 \n肢虽诸阳之本，然乃身所役使，卒伍卑贱之属，故虽多亦不至害。凡起发成浆收靥俱如此也。又心 \n窝手足心，谓之五心，痘俱多者必重。若头面、胸项、手足细碎稠密一样者，恐气血衰微，脾胃虚 \n弱，不能周流灌注，则无不危矣。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>痘形痘色吉凶（十）\n\n属性：万氏曰∶形乃气之充，色乃血之华，凡看痘者，舍此更无他法。是故形贵尖圆起发，若疮皮浓 \n硬而平 者凶。色贵光明润泽，根窠红活，而惨黯昏黑者凶。然形有起发而或致变者，由色不明润， \n根不红活故耳。若痘色光泽，根窠红活，虽平 亦为可治。然色以红活为贵，而犹有圈红、 红、 \n铺红之别。圈红者，一线淡红紧附于根下，而无败走之势，吉之兆也。 红者，血虽以附而脚跟血 \n色隐然不聚，险之兆也。铺红者，痘色与肉不分，平铺散漫，凶之兆也。以此察之，则死生可预决 \n矣。根窠者血之基，脓者血之成，故六日以前专看根窠，若无根窠，必不灌脓；六日以后专看脓色， \n若无脓，必不结痂，此必然之势也。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>吉证（十一）\n\n属性：一看口唇舌尖红活，无燥白之色者吉。 \n二看根窠红润圆活，地白分明者吉。 \n三看心窝额上稀少者，最为顺候。 \n四看痘顶出来，不焦不紫者吉。 \n五看颜色无黑陷，痘顶内暗而黄如苍蜡色，外润而黄如油色者吉。 \n一、凡看痘之法，须察部位，并察多寡。大抵痘少者毒少而吉，痘多者毒甚而凶。如上而头面， \n次而咽喉，前而胸腹，后而腰背，下而四肢，凡此五处，但得二三处稀少，而头面别无危证，即吉 \n候也。若五处通身皆密，即虽颗粒分明，恐气血不能周给，必难尽灌，或既灌而不能收，或既收而 \n不能脱，客强主弱而外盛内虚，小舟重载而力不胜任，鲜不覆矣。此多寡之宜察，勿谓虽多亦吉也。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>凶证（十二）\n\n属性：痘未出而声哑嗾喉者不治。已出五日内见者亦不治。 \n痘未壮而先抓破无气血者不治。 \n痰涎壅盛气急者不治。 \n痘未出已出而神昏气促，躁乱不宁者不治。 \n腹痛而泻脓血者不治。 \n肌肉黎黑如被杖者不治。 \n浆水米粒不入口，或饮食呛喉者不治。 \n眼中神光不明，珠色转绿转赤者不治。 \n闭目昏睡，舌卷囊缩者不治。 \n头温足冷，闷乱饮水者不治。 \n吐泻不止，药食不停不化，直下及肛门如竹筒者不治。 \n胃热发黄，身如橘色，下利者不治。 \n痘初出即青晦焦黑者不治。 \n密如蚕种，全不起发，平片花搭者不治。 \n痘疮痒 ，寒战不止者不治。 \n旧有疮疡走漏气血，而敷药不效者不治。故曰∶不怕五心有痘，只怕原疮泄漏。原疮即是未痘 \n之先有疮，泄去脓血，最为凶也。若果五心稀少，而饮食如常者，亦不妨事。 \n痘后伤风伤食，肌肉瘦脱者不治。 \n上除此之外，虽有杂证险证，及痘之稠密，但略有润泽兴起之意，须仗医之高妙，患家之心托 \n弗惑，细心调理，自有可收全功者。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>怪痘形证（十三）\n\n属性：怪痘者，乃逆痘中之尤甚者，形证不一，不可不辨。 \n一、痘初出时，面胸手足已见红点，却不起发，不成脓浆，随即收敛，若加气促声哑闷乱者即 \n死，此名内陷证也。此证若无烦喘闷乱等候者，名曰试痘。过五七日后，必复发热而痘出者，其痘 \n必重。 \n一、痘疮初出，如蚊蚤所咬，三日后反不见者，名反关痘，五日死。 \n一、痘子出现，三两成丛，根脚坚硬成块者，此名痘母，六七日死。 \n一、痘子将出，身上有红肿结硬处，似瘤非瘤，似痈非痈者，亦名痘母，三五日死。以上二证， \n俱宜真人解毒汤救之。 \n一、痘初出便成血泡，或水泡，随即破坏者，此名烂痘，二三日死。 \n一、痘出后，遍身都是空壳不作脓水者，此名空痘，八九日死。 \n一、痘当出现起发之时，中有干黑者，此名鬼痘，宜用胭脂水涂之，勿使蔓延。若不能急治， \n则乍起乍 ，当靥不靥，或多作番次而出，绵延日久而死。 \n一、痘出起发之时，中有痛甚如刀剜，叫哭不停者，此名痘疔，五六日死。 \n一、痘当起发之时，枯燥不润， 伏不起，皮肤皱揭者，此名干痘，五六日加烦满喘急而死。 \n一、痘于起发之时，皮嫩易破，摸之温手者，此名温痘，六七日痒 而死。 \n一、痘起发之时，疮色娇艳，皮薄光润，鲜红可爱者，此名嫩痘，八九日后不能成痂，必痒 \n而死。 \n一、痘于起发养浆之时，疮头有孔，浆水漏者，此名漏疮，五六日后痒 而死。 \n一、贼痘者，是诸痘未浆而此痘先熟也。又名假云泛。多在太阳、喉口、心胸等处，三日见者 \n六日死，四日见者七日死，五六日见者十一、二日必死也。 \n一、痘出虽稀，根窠全白无血色，三四日后虽亦起胀，然按之虚突，此亦名为贼痘，气血太虚， \n至灌浆时，必变成水泡，大如葡萄，皮薄若纸，抓破即死。 \n一、脓水将成之时，其疮自破，有孔而深者，此名倒陷。 \n一、将靥之时不能成痂，皮脱骨黑者，此亦名倒陷，俱不治。 \n一、痘于收靥之时不能成痂，皮肉溃烂，脓水淋漓者，此名痘癞，能食则生，不能食则死。凡 \n以上者，皆不治之证。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>死证日数歌（十四）\n\n属性：初出顶陷连肉红，过至九日一场空。又如血点带红紫，斑证只在六日中，发斑黑者在朝夕，斑 \n青顷刻去 \n匆匆。无脓痒 期二日，不冶腰疼及挺胸。报痕似痱如蚕种，舌卷囊缩命不充。紫泡刺出黑血者， \n饮食嗾喉证俱凶。难疗面肿痘不肿，青色黑陷及无脓，二便流利下肠垢，更加吐泻出蛔虫，头温足 \n冷好饮水，痘先惊后药难攻。气促泄泻渴不止，目无神者数当穷。声哑失音叫与哭，痘色纵好也 \n难终。有种气急亦难治，庶几灌好是伤风，见此宜服参苏饮，起死回生须见功。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>发热三朝辨吉凶（十五）\n\n属性：一、初发热时，身无大热，或热或退，神清气爽，唇鼻滋润，腰腹不疼，自始至终皆饮食如常， \n大便稠实，小便清利，而无杂证者吉，不必服药。 \n一、初热时，先发惊搐一二次而随止者，此痘出心经也，乃为吉兆，不必治之。若甚惊不止， \n日发三五次，或连日不止，痘出多而密者，乃凶兆也。 \n一、初发热时，吐泻不甚而随止者吉。 \n一、正发热时，或得大汗一身，汗随止而脉见稍平者吉。 \n一、初发热时，用红纸倏蘸麻油点照之，如心窝或遍身有成瑰红者，八九日后决死。 \n一、发热一日，即遍身齐出，或稠密如蚕种，摸之不碍手者决死。 \n一、发热时，腹中大痛，腰如被仗，乃至报痘而痛犹不止者决死。 \n一、发热时，头面上有一片红如胭脂者，八九日以后决死。 \n一、发热时，口鼻或大小便俱失血者快死。 \n一、发热时，妄见妄语，昏不知人者死。 \n一、发热时，腹胀而痛，大叫不止者死。 \n一、正发热三日之内，其热勿退而反烦躁闷乱，坐卧不安，此外虽清凉内却热也。若见手足冷， \n腹胀气喘 \n者即死。以上诸证，俱不必治。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>报痘三朝辨吉凶（十六）\n\n属性：一、见点之时，头面稀少，胸前背上皆无，根窠红润，顶突碍手，如珠光泽，此为上吉，不必 \n服药。 \n一、发热三日或四五日，热稍退，乃于口鼻、腮颐、地阁、颈项之间，或四肢，先放数点，大 \n小不一，淡红润色，痘与肉色红白分明者吉。 \n一、痘作二三次出，三日后手足心方才出齐，出齐后，头面胸背稀少，尖圆紧实，饮食二便如 \n常者吉。如无他证，不宜妄行用药。 \n一、痘之初出，三五相连者必密，单见者必稀。 \n一、痘疮上身多，下体少者吉，反是者险。 \n一、发热至五六日，痘应出不出，以灯照之，只在皮肤中有红点，但其色脉和平，别无逆证，忽 \n然眩冒大汗出者，毒瓦斯痘疮一齐从汗而出者，此名冒痘，再无壅遏之患，乃吉兆也。一、痘疮变化 \n莫测，有等身无大热，亦见报痘，但不灌脓结痂，或出而复没者，此名试痘，不可误作轻看。再过 \n数日，忽然大热，必然复出，宜审治之。 \n一、发热一日便出者凶。或一齐涌出，如蚕种密布者决死。 \n一、大热未退而见红点数粒，先见于太阳、额角、发际、天庭，或山根以上等处，此阳毒乘虚 \n上侵阳位也，大非吉兆。再加目红唇裂，痰鸣色紫，或白者尤甚，又或有三五粒聚于一块者，此名 \n铜钱痘，皆不吉之兆，急宜凉血解毒，以防其危。 \n一、痘疮初出紫色红片者，名紫云痘，四日死。 \n一、痘疮初出当顶红者，六七日死。盖痘欲淡红如线，附于根下，不欲当顶红也。 \n一、痘已出一遍，又出一遍，心腹疼痛不止，口气臭，色紫黑者决死。 \n一、痘疮皮薄，色白而光，根窠全无红色，或根带一点红，三五日后乃如绿豆样，此痘决不能 \n成脓，只成一胞清水，擦破即死。 \n一、色红带艳，皮肉尽红者，必不成脓，痒 而死。 \n一、报痘之时，全不起顶，有如汤泡及灯草火烧者，十余日后，必痒 而死。 \n一、报痘之时，有黑斑如痣状，或肌肉有成块黑者即死。 \n一、报痘时，若口鼻及耳有紫红色，或血出不止者决死。 \n一、报痘之时，应出不出，或起红斑如蚊迹者，六日后必死。 \n一、报痘之时，腰腹痛，或狂言烦躁、大渴、吐泻、不食者，俱不治。 \n一、报痘之后，痘已齐而身热不退，反甚者死。 \n一、痘齐之后，毒已外达，则内当安静，而反见烦躁闷乱，谵妄不止者，此邪气盛极，神机无 \n主也，必死。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>起发三朝辨吉凶（十七）\n\n属性：自报痘三朝之后，不疾不徐，先出者先起，后出者后起，大小分明不相连串，尖圆坚实，红活 \n肥满，面目渐肿，根据期灌浆，饮食二便如常，而无他证者，此表里无病，大吉之兆，不必服药。 \n一、痘虽起发，而色见灰白，肿如锡饼者，看其人脏气何如，如能食便调，无他证者吉；若不能 \n食，或吐 \n利，或瘙痒者凶。 \n一、痘起一分，则毒出一分，至五六日不尽起发，又色不红活者，大无生理。 \n一、起胀三日已足，痘皆满顶红紫者凶，面目肿甚者亦凶。 \n一、痘当起胀之时，遍身虽起而头面全然不起，或痘不胀而肉胀，头面皮肉红肿如瓠瓜之状， \n而痘反不起者决死。 \n一、起胀之时，遍身痘顶有眼如针孔，紫黑色者决死。 \n一、痘色干燥不润，惨黑不明，或灰白渐至倒陷，或发紫泡者皆死。 \n一、起胀时，凡腰腹大痛，或腹胀不能饮食，或气促神昏，或闷乱不宁，或泄泻烦渴，或唇白 \n痰鸣，或狂言妄语，啼哭呻吟，如见鬼神者皆死。 \n一、起胀时，吐利不止，乳食不化，或二便下血者死。 \n一、手足间见而复隐，起而后 ，或通身随胀随没，躁而发喘者死。 \n一、痘已起胀，内有六七粒细而成块，于中有一大痘扁阔歪斜者凶。 \n一、痘起紫色，刺出黑血如屋漏水者死。 \n一、痘于起发时，疮头便戴白浆者，不分何处，并非佳兆，不特唇口然也。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>灌脓三朝辨吉凶（十八）\n\n属性：一、痘自起发之后，小者渐大，平者渐高，陷者渐起，外带微红，内涵清浆，以至灌脓之时，却 \n要个个成脓，根脚红活，其形圆满光泽，此时毒化成浆，山绿色而渐变苍蜡，以手按之，其皮坚硬 \n，脓浆浓浊，约束完固，无少破损，饮食二便如常，此上吉候也，不必服药。 \n一、痘密者，自起至浆，渐至壮大，未有不相串者，虽相连属，只要根脚分明，陷者尽起，无 \n处不透，则 \n毒从浆化，脓成而毒自解，无伏留者矣，此亦吉候。 \n一、痘之初出，或顶平，或中心陷下，或白色，只要其人能食，二便如常，治无乖谬，以及灌 \n脓之时，陷者微起，平者微尖，淡白者红活，窠中血水尽化为脓，但得如此，毒已解矣。又表无痛 \n痒之证，里无吐泻之证，是表里俱无病也，如此者，坐待收靥，不可妄投汤剂。 \n一、灌脓时，红紫黑色，外剥声哑者死。 \n一、灌时纯是清水，皮薄而白如水泡者，三四日必抓破而死。 \n一、脓不能灌而干枯焦黑，或全无血水， 陷者即死。 \n一、头面肿大，疮尽搔破，臭不可近而足冷者决死。 \n一、灌脓之时，吐利不止，或二便下血，乳食不化，痘烂无脓者决死。 \n一、灌脓之时，二便不通，腹胀，肉黑发斑，谵妄气喘，或寒战切牙者决死。 \n一、回浆之时，渐当苍黑收敛，而反光嫩不敛者，此气血两虚，浆不能干，必发痒，搔破而死。 \n一、脓浆未成，忽然干收，或青紫焦黑者死。 \n一、忽然作痒，正面抓破，皮脱肉干者死。 \n一、诸痘有浆而天庭不起，或额上如沸汤浇破，臭连两颊，水去而干，似靥非靥者死。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>结靥三朝辨吉凶（十九）\n\n属性：一、痘至十日之外，血化毒解，脓必渐干，如苍蜡色，或如葡萄色，从口鼻两旁面部收起，以 \n至胸腹而下，然后额上与脚背一齐结靥而落，别无内证，饮食二便如常，或从手足心、手指尖或阴 \n上先收者，俱吉候也。 \n一、痘既苍蜡收靥而身有微热者，乃烧瘢之证，但饮食如常，供不必治。 \n一、痘当靥时，遍身臭烂，目无神气者决死。 \n一、当靥之时，遍身发痒。搔破无脓，皮卷如豆壳而干者死。 \n一、当靥之时，无脓而气急声哑，或手足颤掉，或寒战切牙，或腹胀痰响，或足冷过膝，或小 \n便少而大便频者，皆死。 \n一、当靥时，两脸干硬，按之如石者死。 \n一、痘至收靥，饮食不进，口中常如食物动而不止者决死。 \n一、面部胸腹未靥而脚先靥者危，阴胜阳也。 \n一、遍身俱靥，内遗数粒独不靥者，尚能杀人，如蛇之退皮，中有一节被伤，不能全退者终死。 \n其有靥至项下或至胸住定，而服药不效者亦死。 \n一、痘疮未该靥而卒然焦紫者死。 \n一、痘当靥时，遍身未见脓成，而口唇上下痘先黄熟者，毒瓦斯内攻于脾也，凶。 \n一、痘疮有脓结靥者则为吉证，若无脓收靥，则立见其危。 \n一、痘未收靥，而口唇腐烂及口白到舌者危。 \n一、收靥时，前后有红紫泡者不治。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>落痂后辨吉凶（二十）\n\n属性：一、痘疮收后，其痂先后自脱，痂浓落迟，离肉不粘者吉。 \n一、自食痘痂者，虽有他证不死。 \n一、疽痂虽落，而痘瘢雪白，略无血色者，气血脱尽也，若不急培元气，则过后必死。 \n一、痂落后，每发惊而神无所根据者，心气绝也，危。 \n一、痂落后，手足颤掉，切牙噤口，目闭腹胀，足冷过膝者不治。 \n一、原痘干燥，脓少不灌，虽结靥落痂而疤白者，或有余热不退者，虽过一月亦要死。 \n\n\n\n<目录>卷之四十三烈集·痘疹诠\\痘疮（上）\n\n<篇名>痘疮上论列方（二十一）\n\n属性：真人解毒汤（痘五二） \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>总论治法（二十二共十九条）\n\n属性：痘疮一证，顺者不必治，逆者不能治，所当治者，惟险证耳。何为险证？如根窠顺而部位险， \n部位顺而日期险，日期顺而多寡险，多寡顺而颜色险，颜色顺而饮食险，饮食顺而杂证险，杂证顺 \n而治疗险，治疗顺而触秽险。然犹有最险者，则在元气与邪气，邪气虽强，元气亦强者无害，只 \n恐元气一馁，邪气虽微者亦危。设或犯之而不为速治，则顺者不顺，而吉变为凶矣。凡此数者，皆 \n痘中之要领，所当详察详辨也。故凡欲治痘，必须先识死生，辨虚实，审寒热，明此六者，则尽之 \n矣。 \n一、治痘之要，惟邪气正气二者而已。凡邪气盛而无制者杀人，正气虚而不支者杀人，及其危 \n也，总归元气之败耳，使元气不尽，则未必至死。凡治此者，但知补泻二字，而用之无差，则尽善 \n矣。故补泻难容苟且，毫厘皆有权衡，必不可使药过于病，亦不可使药不及病。是以善用攻者，必 \n不致伐人元气，善用补者，必不致助人邪气，务使正气无损，而邪气得释，能执中和，斯为高手。 \n然执中之妙，当识因人因证之辨。盖人者，本也；证者，标也。证随人见，成败所由，故当以因人 \n为先，因证次之。若形气本实，则始终皆可治标；若形质原虚，则开手盒饭顾本。若谓用补太早， \n则补住邪气，此愚陋之见也。不知补中即能托毒，灌根即能发苗，万无补住之理。是以发源之初， \n最当着力，若不有初，鲜克有终矣。此可与智者言，不可与庸人道也。 \n一、治痘不宜迟。凡痘疹之有不同者，无过寒热虚实四证，大都寒则虚，热则实，虚寒则宜温 \n补，实热则宜清解。然其挽回之力，当于三五日前治之，过此则恐无及。若七日之后，毒发于外， \n外不足则外剥而死，若 \n毒发不尽，则又内传，内不足则内攻而死。故治痘有时，时之不可失也，有如此。倘初时不慎，则 \n后来之祸，从此伏矣。 \n一、解毒当知表里。所谓毒者，火毒也。所谓解毒者，求其所在而逐之也。盖痘疮之发，内则 \n本于淫火，外则成于风邪，内外相触，其毒乃发。故其发也，不甚于内则甚于外，甚于内者，以火 \n邪内盛而炽焰于外也；甚于外者，以寒邪外闭而郁火于内也。故但察其无汗外热而邪在表者，则当 \n疏之散之，使热邪从外而去，则毒亦从外而解矣。若察其多汗内热而邪在里者，则当清之利之，使 \n热邪从内而泄，则毒亦从内而解矣。其有内热既甚而表邪仍在者，则当表里相参，酌轻重而兼解之， \n则邪必皆散矣。若邪不在表，则必不可妄兼发散，以致表气愈虚，而痘必终败，其证则身有汗而外 \n不甚热者是也。若毒不在里，则必不可兼用寒凉，以致中寒脾败，而瑟必反陷，其证则口不渴而二便 \n不秘者是也。知斯五者，则蟹毒治实之法，无余蕴矣。此外有虚邪虚火等证，则当先酌元气，次察 \n邪气，无使失楫中流，顾本不及，则尤为切戒。凡云痘毒者，痘必自内而达外，但得出尽，则内无 \n毒，但得化尽，则外无毒，既出既化，而不使复陷，则毒尽去矣。故或宜散表，或宜托送，或宜清 \n解，或宜固中，而治法尽之矣。 \n一、补虚当辨阴阳。凡痘疮血气各有所属，已见则气血条中。然痘之所主，尤惟阴分为重，何 \n也？盖痘从形化，本乎精血，凡其见点起胀，灌浆结痂，无非精血所为，此虽曰气为之帅，而实血 \n为之主。且痘以阳邪，阳盛必伤阴，所以凡治痘者，最当重在阴分，宜滋润不宜刚燥。故曰∶补脾 \n不若补肾，养阴所以济阳，此秘法也。然血气本自互根，原不可分为两，如参、 、白术之类，虽 \n云气分之药，若用从血药，则何尝不补血？归、芎、地黄之类，虽云血分之药，若用从气药，则何 \n尝不补气。故凡见气虚者，以保元汤为主，而佐以归、地。血虚者，以四物汤为主，而佐以参、 。 \n盖气血本不相离，但主辅轻重，各有所宜，而用之当不，则明拙自有差耳。 \n一、治痘有要方，兹表而出之，以便择用。其有未尽，当于各条求之。 \n凡解表诸方，乃初热时所必用者，诸家皆以升麻葛根汤为首，程氏则用苏葛汤，似为更妥，余"}, {"n": 24, "text": "卷二十四\n\n则常用柴归饮以兼营卫，似为尤妥，此当随宜择用。营虚表不解者，五柴胡饮。阳气虚寒表不解者， \n柴葛桂枝汤。元气本壮而表不解者，疏邪饮，或加减参苏饮。寒气胜而表不解者，五积散，或麻 \n黄甘草汤。 \n凡清火解毒诸方，所以解实热也。如欲解毒清火而兼养气者，惟四味消毒饮为妙。鼠粘子汤亦 \n佳。热毒两盛而不化者，宜搜毒煎。烦热作渴，小水不利者，导赤散、六一散。血热赤斑，烦躁多 \n渴者，犀角散。热在阴分而失血者，玄参地黄汤。内热不清者，东垣凉膈散。二便供不利而火甚于 \n内者，通关散。热毒内蓄，小水不利，而为丹为痈者，大连翘饮。烦热多惊而神不安者，七味安神 \n丸。热毒内甚而狂妄者，退火丹。 \n凡表里兼解诸方。如内外俱有热邪者，宜柴葛煎，或柴胡麦门冬散。里邪甚而表邪微者，解毒 \n防风汤。表里俱有邪而元气兼虚者，实表解毒汤。表里俱实热者，双解散。 \n凡托里诸方，有宜专补元气者，有宜兼解毒者。如气血俱虚不起者，六物煎，或托里散。虚寒 \n不达，兼托兼表者，参 内托散，或十宣散。气分虚寒不透者，六气煎。气血俱虚，微热不起者， \n紫草快斑汤。 \n凡诸补剂，皆痘中元气根本，祛邪托毒者之所必赖，但见虚邪，必当以此诸方为主。气分不足 \n者，调元汤。气虚宜温者，保元汤，六气煎。气虚微热宜兼凉解者，参 四圣散。血虚者，四物汤， \n芎归汤。血分虚寒宜温者。五物煎。血虚血滞者，养血化斑汤。血虚血热宜兼解毒者，凉血养营煎。 \n气血俱虚者，六物煎、八珍汤、十全大补汤。气血虚寒，大宜温补者，无如九味异功煎、六味回阳 \n饮。即陈氏十一味木香散、十二味异功散，但虚寒而兼气滞者宜用之，欲赖补虚，大有不及。 \n凡攻下诸方，亦痘中所不可无，惟必不得已然后用之，勿得视以为常也。血虚秘结，大便不通 \n者，四顺清凉饮。里实多滞秘结者，前胡枳壳汤。表里俱实，大便不通者，柴胡饮子。血热便结毒 \n盛者，当归丸。 \n一、凡痘已出尽，内无不虚，盖随痘而为托送者，背元气也。使于此时，不知培补化源，则何 \n以灌浆？何以结痂？何以收靥？倘内虚无主，将恐毒母气复陷，无不危矣。若痘之稀疏者，气血之耗， \n犹为有限，若痘之多而 \n甚者，其气血内亏，必更甚矣。此不可不预为之防也。 \n一、平顺之痘，毒原不甚，既出之后，内本无邪，此辈原不必治。无奈父母爱子之切，且不识 \n病之轻重，故必延医诊视。既延医至，无不用药。既已用药，无匪寒凉。在彼立意不过，曰∶但解 \n其毒，自亦何妨？不知无热遭寒，何从消受？生阳一拔，胃气必伤，多致中寒泄泻，犹云协热下利， \n更益芩、连，最可恨也。又如痘疮初见发热，每多不审虚实，止云速当解毒，凡于十日之外，多有 \n泄泻而致毙者，皆此辈之杀之也。冤哉，冤哉！ \n余见者多矣，故笔诸此以为孟浪者戒。 \n一、痘在肌肉，阳明主之，故自出齐以后，最不宜吐泻，与其救治于倒陷之后，孰若保脾土于 \n未坏之先？ \n故凡生果茶水之类，皆宜慎用，而寒凉之药，尤不可不慎也。 \n一、治痘须辨其证，大部湿多则泡，血热则斑，气不足则顶陷，血不足则浆毒不附，里实大补 \n则生痈毒，表实大补则不结痂。里虚不补则内攻而陷，表虚不补则外剥而枯。但使周身气血活泼无 \n碍，则虽密亦不难治。故惟贵得中，勿使偏胜，则寒热虚实，自无太过不及之患，斯足云尽善矣。 \n一、秘传治痘之法，首尾当以四物汤为主，随证加减用之。惟肚腹不实者须远当归，但将全剂 \n通炒微焦，则用自无碍，且复有温中暖脾之妙。 \n一、首尾皆忌汗下，此先哲治痘之心法。盖妄汗者，必伤阳气，阳气伤则凡起发、灌浆、收靥 \n之力，皆失所赖，此表虚之为害也。妄下者，必伤阴气，阴气伤则凡脏腑化源，精神锁钥，饮食仓 \n廪，皆为所败。此里虚之为害也。然表虚者，犹赖里气完足可以充之，里虚则根本内溃，卫气亦从 \n而陷，无策可施矣。故古人深以汗下为戒，诚至要之旨也。然此以常道为言，非所以应变者设。遇 \n外感寒邪，腠理闭密，其出不快，其发不透者，若不用辛甘发散之剂以通达肌表，则痘有壅遏之患 \n矣。又若有大小便秘结，而毒有留伏不达者，不与苦寒泄利之药以疏通脏腑，则有胀满烦躁，焦紫 \n黑陷等患矣。故当察其虚实，审其常变，当汗则汗，当下则下，中病则已，无过其制。若无汗下之 \n证，则必不可妄用汗下，以贼人之命也。务得其宜，然后谓之明医，而福自有归矣。 \n万氏曰∶解其火毒，恐郁遏而干枯；养其血气，欲流行而舒畅。按此说诚善。然所谓火毒者， \n以实热为言，若火有虚实真假，则不得概认为火毒。 \n程氏曰∶痘疮出自六腑，先动阳分，而后归阴经，其本属阳，故多发热而阴血虚耗者多也。首 \n尾当滋阴补血为主，不可一毫动气，贵从缓治，所以白术、半夏之燥悍，升麻之提气上冲，皆不可 \n轻用也。且痘疮多有血热者，故宜用四物汤加芩、连之属，以养其阴而退其阳也。 \n程氏曰∶痘毒根于淫火，必因岁气传流而发，故多兼表证，则内外交攻。此时若不用轻扬之剂， \n祛风散邪，淡渗解毒之药，利便退热，则外邪内火何由得解？邪既不解，则痘何由得善？此治之不 \n容已也。然治之之法。必须审儿形色，察儿虚实，因证用药，庶几神效。世之医者多宗钱氏清凉解 \n毒之论，或按陈氏辛温发敬之方，主见不同，致误多矣。殊不知痘疹色灰白，不起发，根窠不红活， \n此皆虚寒，必宜陈氏方救之。荀非理明于心，无不眩惑。故必热则凉之，寒则温之，虚则补之，实 \n则泻之，何患乎疾之不愈耶。 \n程氏曰∶治痘之要，始出之前，宜开和解之门；既出之后，当塞走泄之路；落痂之后，清凉渐 \n进；毒去已尽，补益宜疏。 \n程氏曰∶凡治痘，前后须加木通，以泻热邪自小便中出，不使攻胃，令无变黑之证。七日之后， \n热退者，少用之。凡痘疮前后总有危证，万勿用天灵盖、脑、麝之属攻之。盖毒出一步，财内虚一 \n步，血气运一日，则内耗一日，岂可夏用辛香耗气之剂，虽侥幸偶中，后必有余害也。是可见王霸 \n之珠，相去远矣。 \n程氏曰∶凡妇人有孕而出痘者，以安胎为主。气虚者，保元汤。血虚者，四物汤，或加白术、 \n黄芩、砂仁、陈皮，必使胎气无损为主。 \n程氏曰∶桂岩郑先生云∶痘者象其形而名之也。愚谓不独象形而名，而治之之法，亦犹农家之 \n种豆也。豆之为物，上实则难出，土瘠则难长，故实者锄扰之，瘠者灌沃之，不实不瘠，惟顺其性， \n不使物害之而已，知此则可以语医矣。今人于痘初起，不察虚实寒热，或过用木香散、异功散之类， \n则以火济火，致变紫黑倒陷， \n痈毒吐衄者有之；或妄用芩、连、栀、檗寒凉之药，则大伤脾胃，为吐为泻，为寒战内陷者有之。 \n故凡治痘之法，六日之前，不宜温补，亦不宜妄用寒凉。师云∶凡解毒之内，略加温补，温补之中 \n，略加解毒，此不传不刻之秘诀也。若六日以后，毒已尽出于表，当温补而不温补者，脓不得壮而 \n痒寒战之患，必所不能兔矣。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>热证论治（二十三共十一条）\n\n属性：古云∶痘疹之病，皆由父母胎毒伏于命门相火之中，故每遇二火之令，或主客温热之气，即触 \n发而动，此痘疹属阳，固无疑矣。然阳毒阳邪，无热不成，亦无热不散，所以非热不能出现，非热 \n不能起发，非热不能化浆，非热不能干浆，此痘疮之终始，不能无热，亦不可无热也。但热贵其微， \n不宜其甚。盖热甚者毒必甚，而痘亦必重；热微者毒亦微，而痘出必轻；无热则不成不化，此热固 \n痘之常也，所以凡治痘疮，不可尽除其热，若必欲尽去之，则未有不成阴证而败者矣。 \n一、痘有三火，盖痘、疹二证，皆言为火者是矣。然轩岐之火义有三，曰太过，曰平气，曰不 \n及也。太过之火，是谓赫曦，炎烈之气也，其毒盛，治宜清解。平气之火，是谓升明，蕃茂之气也， \n其毒平，不必治之。不及之火，是谓伏明，屈伏之气也，其毒陷，治宜培补。此阴中有阳，阳中有 \n阴之大义，而亦痘疹万病之法旨，使不知此，尚敢云医。 \n一、治热当知微甚，及有毒无毒，斯无谬误。盖痘疹属阳，无不发热。若外虽发热，而内则不 \n渴，或饮食二便如常，此蒸痘之热耳，热虽在表而内则无病，万万不可妄治。其有热之甚者，痘毒 \n必甚，此不得不为调理，若甚于发热之初，必为之表散；若甚于见点之后，必为之清解。钱氏曰∶ \n热甚而大小便闭则利之。如果有热毒实邪，则不得骤用补阳之剂，致令毒瓦斯壅盛，则热终不退，反 \n为害矣。 \n一、假热非热，假寒非寒，见有不真，误治则死。如文中主温补，仲阳主凉泻，虽若各有所主， \n然无非因病而药，各有所宜，是以二者皆不可偏用。但得中和，斯为贵耳。余见近日幼科，多不知 \n陈氏之心法，但见痘 \n疮，则无论是虚是实，开口止知解毒，动手只是寒凉，百证千家，若同一辙，岂必尽皆实热乎？如 \n实热果真，白非凉泻不可，然必内外俱热，方是热证，内外俱实，方是实证。但其中有似实非实， \n似热非热者最多，此不可不察之真而审之确也。故凡见外证虽若实热，而内察则无，如口不甚渴， \n二便通利，或见微溏，或禀赋素弱，或脉息不强，或声色不振，或脏气多阴，或饮食不化，或胀满 \n呕恶，或吐蛔，或倦睡，或畏寒，或作痒，或多惊恐，或筋惕肉 之辈，虽见有热，此皆热在表而 \n不在里，总属无根之火，非真热证也。最忌寒凉。若垫而妄用，则必致败脾，无一免矣。 \n一、痘疮热甚者，毒之盛也，其痘必多；热微者毒亦微，其痘必少。痘既出而热不减者，痘必 \n日增，见点后而热渐退者，痘必疏矣。或有微热而痘反密，其内热必甚？而或见烦躁，或二便热 \n燥，此毒深热亦深也，宜清其内而兼解其表。或有热甚而痘反稀者，以外虽热而内则不热，此毒 \n浅热亦浅也。 \n一、痘疮初热之治法，详发热三朝治法条中。 \n一、治阳邪实热之法。表里挟邪俱热者，柴葛煎、连翘升麻汤。表热不解而里无热者，疏邪饮、 \n苏葛汤、柴归饮。表里俱热而邪实者，双解散。内热毒盛者，东垣凉膈散，或解毒防风汤。热毒炽 \n盛，痘疮紫赤，烦躁者，搜毒煎，或大连翘饮，或犀角地黄汤。阴虚血少，燥热神昏者，四物汤或 \n二阴煎。阴虚血热而大便不通者，四顺清凉饮。大便不通，实热内壅而胸膈胀闷者，前胡枳壳汤， \n或三黄丸。二便俱不利而实热内滞者，通关散。小水赤涩而邪热内蓄者，导赤散、六一散。心火盛 \n而惊搐多痰者，万氏牛黄清心丸，或七味安神丸。痘疮稠密，身热毒盛，养营退热解毒者，鼠粘子 \n汤、柴胡麦门冬散。 \n一、纯阳无阴之证，凡发热谵语，狂妄躁乱，大渴大烦，如见鬼祟，大便秘结，小便赤涩，六 \n脉滑数急疾，是皆火毒内炽之证，当用前法，酌而治之。 \n陈氏曰∶凡痘疹壮热，经曰不除，如无他证，只用六味柴胡麦门冬散治之。如不愈，服七味白 \n术散。凡身壮热，大便坚实，或口舌生疮，咽喉肿痛，皆疮毒未尽也，用射干鼠粘子汤。如不应， \n用七味人参白术散。 \n程氏曰∶痘疮前后，凡有烧热不退，并属血虚血热，只宜四物汤按证加减。渴加麦门冬、犀角 \n汁，嗽加栝蒌霜，有痰加贝母、橘红。切忌人参、白术、半夏之属，倘误用之，为害不小。盖痘疮 \n属阳，血多虚耗，今但滋阴补血，其热自退，此即养阴退阳之义也。 \n一、痘后余热发热证治，俱详痘后余毒条中。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>发热三朝治款（二十四）\n\n属性：痘疹一证，虽原于有生之初，然必因时气相触，内外挟邪而后作。凡痘之轻重，已兆于发热之 \n微甚，而吉凶于此亦可判矣。毒轻者易出易靥，固不必治；毒甚者险证百出，故不得不治。凡治此 \n者，于初热时，急宜用轻扬之剂，汗以散之，但使外感之邪，脏腑之毒，皆作秽汗，尽从毛窍中出 \n，则毒瓦斯已减其半，而重者可轻，危者可活矣。即如痘中一切变证，亦无非毒瓦斯欲出不能之所为， \n一经表散，则毒从汗去，而诸证亦必自退。然又当察表里之轻重，或宜解表，或宜清里，或宜托助 \n元气，孰者宜急，孰者宜缓，有不可执一也。故胡氏曰∶表热壅盛，非微汗则热不解，里热壅盛， \n非微利则里不解。失此不治，则毒瓦斯渐盛，而逆证随见矣。 \n一、散表之法，当知邪之浅深，毒之微甚。表邪甚者微散之，则表不能解，无益于事；表邪微 \n者妄汗之，则表气必虚，痘不起发，而反为大害。故惟以得中为贵，亦以微汗为贵，不可过伤卫气 \n也。其有大热不退，肌肤秘密，或气令寒凝之时，则不得不大为表散，一散未应，或至于再，必令 \n身热由汗而退，则毒瓦斯自解，可无患矣。此散之微甚，有权宜也。故凡是痘证，最畏内外之寒气， \n务使表里温暖，但得毛窍中常见津津润泽，亦犹庖人炊笼之法，但欲其松，则皮肤通畅，气无不达， \n痘必易出易收，无不善矣。 \n一、痘疮发热之候，宜乍热乍凉者为常。若遍身如火，昼夜不休，为失常也。此当察其表里， \n酌宜施治。 \n一、痘疮初见发热，若无虚寒等证，固不得骤用温补，以助火邪，恐致鼓扇痘毒，则反资大害。 \n若无实火大热等证，切不可因其发热，妄用寒凉，必致败脾泄泻，则为害尤甚。此时医之通弊也， \n大宜戒之。 \n一、既经表散之后，须谨避风寒，若使外邪再感，则皮毛闭塞，热毒必将复炽，汗而再汗，必 \n不能堪。又须切戒生冷水果，若误犯之，恐寒湿伤脾而为泄泻不食，则无不致害。 \n一、表散之剂，凡初见发热，状类伤寒，未知是痘非痘，即当先用汗散。此时欲散表邪，即当 \n兼调营气，宜以柴归饮为第一，惟大便不实者勿用之，以其性多润也，其次则苏葛汤，再次则升麻 \n葛根汤，或只用加减参苏饮亦佳。若冬月寒胜之时，或气体壮实，表不宜解者，须加麻黄，必要表 \n出一身臭汗为佳，但使热退身凉，苗则轻矣。若初发热，有恶寒身振如疟之状者，阳气虚也，宜柴 \n葛桂枝汤加黄 主之，痘出即愈。 \n一、清解之剂，用治表里而兼清兼散也。凡热之甚者毒必甚，若身常有汗而大热不退，或兼烦 \n躁热渴者，此其内火熏蒸而表里俱热也，须两解之，宜连翘升麻汤，或如圣汤。若身热烙手而目赤 \n口干，二便热秘，烦闷不安者，此表里俱实也，宜柴胡饮子，甚者大连翘饮、双解散，或调益元散 \n以利之。 \n一、表汗已透者，不得再汗，恐外亡阳而内伤气也。 \n一、发热之时，有腹痛胀满者，必外邪与毒瓦斯相并，未得外达而然，宜参苏饮加砂仁，温而散 \n之。 \n一、初热时，有惊搐谵语者，是为痘搐。微见而随止者不必治。若元气强壮而搐之甚者，宜羌 \n活散调制过朱砂以表之。若痰涎壅盛，喉内作声者，宜烈生姜汤，调化痰丸服之，或抱龙丸亦可。 \n一、此时渴欲茶水，只宜少与葱白汤，既可止渴，亦可疏表。 \n一、痘疮首尾皆畏泄泻，宜检本条速为治之，否则内溃脱陷之祸，不可胜言也。 \n徐氏曰∶凡解表之药，必在红点未见之前，如热之甚者，邪毒必甚，宜败毒散或参苏饮，调三 \n酥饼。 \n张冀之曰∶凡痘疮一见红点，便不可用升麻葛根汤，恐发得表虚也。程晨峰曰∶治痘者不可轻 \n用升麻，恐提气上冲，引动肺气也。按此二家之说，是皆治痘之大要，甚属有理，但其中亦有宜否之 \n辨。如阳气下陷，不能透达肌表者，则暂用升麻，固其所宜。又或虽见红点而表有热邪未解者，则 \n仍宜解散，亦不可缓。些二说者，虽不可坚执，实不可不知也。 \n吴东园曰∶初热时，只有二事，惟去邪扶正而已。邪热盛则去邪而正气自旺，正气衰则扶正而 \n邪热自退。正气盛而痘自发，热为痘用，则不为害矣。邪气退而正气不受烁，血脉充裕，则痘自泰 \n矣。须于此时看明，下手迟则无济于事矣。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>报痘三朝治款（二十五）\n\n属性：痘之形色初见，吉凶攸分，而寒热虚实亦已可辨，凡调摄挽回之力，惟在此时尤为紧要。且痘 \n出三日内，毒在半表半里之间，关系最重，故妄汗则成斑烂，妄下则成陷伏，寒凉过用必伤正气， \n燥热过用则助邪气，虚寒不补则陷伏痒 ，实热不解则变黑归肾，倘有一瘥，死生立判，医者于此， \n不可不为之慎。 \n一、痘疮见点后，身热稍退，别无内热等证，或色不甚红，顶不甚突者，便有虚象，虽在三五 \n日内，亦切不可用寒掠之药，恐伤脾胃，为害不小，须以保元汤，或六物煎之类为主，因证加减， \n以培养之。 \n一、痘疮必因热而出，因热而起，若热甚则血躁血枯，其出反难。故于未见点之先，必须察其 \n寒热，预为调理，若有热证，勿得过用辛热气分等药，恐助火邪，致滋多变。 \n一、此时最畏泄泻，宜按本条急治之。 \n一、见点太早者，有吉凶虚实之辨。凡发热一日，或才热便见，必血热毒盛之所致，其证多凶， \n但得痘稀而饮食如常，别无他证，则亦无害。若其形气本弱而痘现速者，此营热卫虚，不能约束于 \n外，故出现太骤，须兼实表，庶可免痒 溃烂之患，宜实表解毒汤主之。如发热一日便出而密者， \n其证最凶，其毒必甚，此证最忌温补，宜搜毒煎加柴胡主之，或羌活散加牛蒡子、紫草、蝉蜕，或 \n调保婴丹；热甚者，调退火丹或双解散急治之，可保一二。其有痘虽出早而色不红紫，热不甚者， \n此全属表虚之证，如保元汤、六物煎之类，亦所当用。 \n一、痘出不快者有数证，须审其有无外感内伤，而辨治其所病。如冬月严寒，或非时阴邪，外 \n闭寒胜而出迟者，宜五物煎加生姜、麻黄、细辛之类主之，或五积散亦佳。如夏月火热熏蒸，以致血热气虚，烦渴发躁而 \n出迟者，宜人参白虎汤加木通、干葛主之。有因时气不正，为风寒外邪所袭，以致皮腠闭密，发热 \n无汗而出迟者，其证必头痛鼻塞，四体拘急酸痛，宜疏邪饮、参苏饮、惺惺散之类主之。若本无诸 \n邪而出不快者，此气血内虚，不能驱毒托送，而留连于内，宜十宣散，或托里消毒散。若气分大虚 \n而出不快者，宜保元汤、六气煎。血分大虚者，宜五物煎，或六物煎加减主之。若内有所伤，气滞 \n而出不快者，宜匀气散、橘皮汤加减主之。头面出不快，当用川芎、荆芥、羌活、防风、天麻之类 \n为引使。胸腹出不快，当用 本、升麻、紫苏，及紫草木通汤。四肢出不快，当用桂枝、干葛、甘 \n草、连须、紫草、葱白，各加生姜为佐，连进二服，出自快矣。 \n一、痘不起发者，虽证有不同，然卒由血气内虚，不能托送者居多。此中或宜兼解散，或专补 \n元气，当辨而治之。凡出齐之后，或被风寒所闭，而发热头痛，陷伏不起者，宜羌活散、参苏饮， \n加内托等药治之。若红点初出，暗昧干燥不起发者凶，宜四物汤加紫草、红花、丁香、蝉蜕、官桂 \n，或调无价散，量儿大小与之。若便实内热，隐隐肌肉间不起发者，宜紫草饮子。若血分微热而毒 \n不能达者，宜托里消毒散。若气虚气陷不起者，保元汤，或蝉蜕膏加黄 。若血虚不起者，芎归汤 \n、四物汤。若血分虚寒不起者，五物煎。若气分虚寒不起者，保元汤、六气煎。若气血俱虚不起者 \n，六物煎、托里散。凡以上补助气血等剂，须加好酒、人乳、糯米，更妙。凡发痘之药，用本不同 \n，有以毒攻毒而发痘者，如用山甲、人牙、蟾酥、蝉蜕之属是也；有解毒清毒而发痘者，如草车、 \n红花、牛蒡子、犀角、木通、连翘、金银花之属是也；有升提气血而发痘者，如川芎、白芷、荆芥、 \n升麻、蔓荆子之属是也；有解散寒邪而发痘者，如麻黄、桂枝、柴胡、干葛、防风、紫苏、葱白之 \n属是也；有行气行滞以通壅塞而发痘者，如丁香、木香、陈皮、浓朴、山楂、大黄之属是也；有益 \n火回阳、健脾止泻而发痘者，如附子、肉桂、干姜、肉豆蔻之属是也。凡此者孰非托里起痘之法， \n然但可以此为佐，而必以血气为主，则在乎四君、四物、十全大补之类，庶乎随手而应，无不善矣 \n。 \n一、虚证见于报痘之时，即当速为培补，失此不治，必不能灌浆结痂，十日后必致不救。盖痘 \n疮实热者毒盛可畏，虚寒者内败可畏，但实热证显，虚寒证隐，人多误认，故为害反甚。且痘疮之 \n所赖者，惟饮食血气。 \n饮食之本在脾胃，血气之本在肝肾，但使脾胃气强，则滋灌有力，而无内虚陷伏之忧，气血充畅则 \n毒皆生化，而无表虚痒 之患。此其在气在血，或微或甚，所当早辨而治也。凡痘出灰白不红绽， \n或灰黑顶陷，或身无大热，皮嫩色光，溶溶如淫湿之状，或口不渴，饮食少，腹膨溏泄，二便清凉 \n，皆表里虚寒证也。若气虚者，宜调元汤、四君子汤。气虚微滞者，五味异功散。气虚宜温者，保 \n元汤、六气煎。脾气虚寒者，养中煎、温胃饮，或理中汤。血虚者，四物汤，血虚宜温者，五物煎 \n。气血俱虚者，六物煎、五福饮，或八珍汤。气血俱虚而寒者，十全大补汤。脾肾血气大虚大寒者 \n，九味异功煎、六味回阳饮。脾胃虚寒气滞者，陈氏十二味异功散。凡痘疮色灰白不起发者，气虚 \n也，候出齐，以保元汤和木通、川芎最稳。 \n一、火证热毒在见点之后，宜速为清解，若不早治，则日甚一日，必致不救。凡见点太赤，根 \n下皮色通红，此血热气有不能管束也，后必起发太骤，皮嫩易破，或痒 不可救，宜急清血分之热， \n用凉血养营煎，或鼠粘子汤，或用六味消毒饮加芍药治之；或四味消毒饮、益元散俱佳。凡痘疮已 \n现，毒泄则热当自解，若疮已出而壮热不减，此毒蕴于内，其势方张，其疮必密，宜解其毒，用柴 \n葛煎、或鼠粘子汤。凡见点之后，壮热不退，或三四点相连，色红带紫，或根窠焦色，红紫成片， \n或口唇热燥，烦渴喜冷，舌上有胎，或二便燥涩，此表里皆热，毒盛之重候，急须清热解毒。如表 \n热甚者，宜柴葛煎，里热甚者，宜搜毒煎加柴胡，或用六味消毒饮加酒芩、木通、栀子、黄连、山 \n楂、蝉蜕、归、芍、红花之类，或调退火丹加减用之。如热毒内甚而发惊狂谵语者，宜用紫草煎汤 \n磨犀角汁、调朱砂益元散，或退火丹解之。以上凡解毒之后，红紫退，二便调，能食不渴，此表里 \n皆清也，切勿再为解毒，须急以保元汤、四物汤、六物煎之类，调补气血以助灌浆收靥，否则恐变 \n痒而不能善其后矣。如痘疮内热之甚，大便硬结不通，大渴烦躁，腹胀满，脉见洪数而痘出不快 \n者，此热毒壅伏于内，须遍利之以祛其热毒，宜柴胡饮子，或三黄丸；甚则承气汤，或用猪胆导之。 \n然此惟热毒在里，痘形未见，不得已而微下之可也。若斑点隐隐见于皮肤中者，此已发越在表，乃 \n痘疮正发之时，切不可妄用下药。凡痘疮初出，但见红点稠密，急用缠豆藤烧存性，加制过朱砂， \n连进二三服，或用薄荷、牛莠子煎汤，调退火 \n丹服之，另用吴茱萸为末，以水调摊足心，引下热毒，亦可解散其势。 \n一、痘出变黑，乃危证也。盖痘疮乃血气滋灌，血足气充，则痘自红活；若热毒熏烁，则成焦 \n黑；若阳气不充，则成灰黑。且黑为水色，其亏在肾，以阴犯阳，最为恶候，当辨而治之。若热毒 \n凝聚，大便秘结，或烦躁热渴而为焦紫黑陷者，须通其便，先以解里之急，宜柴胡饮子，或当归丸。 \n得利后，宜即以紫草饮，或加味四圣散以化表之毒，仍用胭脂汁以涂之。若大便不结，别无大热等 \n证，而痘色黯黑者，总由脾虚不能制水，故见黑色，宜速用五物煎，或保元汤加紫草、红花服之， \n外点以四圣丹、胭脂汁。若渐见红活则吉，若更干黑则凶。《心鉴》云∶凡治黑痘，常用保元汤加 \n芎、桂补提其气，气旺则诸毒自散，黑者转黄，屡试屡验。 \n一、夹疹夹斑证，本非痘中吉兆，然亦有轻重之辨，宜酌而治之，外有本条，仍宜参阅。凡发 \n热二三日之间，痘形未见，忽然偏身发出红点一层，密如蚊蚤所咬者，决非痘也，此乃斑疹之属， \n多为风寒所遏，不能发越而斑先见也，宜疏邪饮，柴葛煎、或败毒散之属，微散而解之。但得身凉 \n，斑必自退，再越一日，痘出必轻矣。凡痘夹斑疹齐出者，亦宜辨其寒热，若表里俱热而邪不解者 \n，宜柴葛煎加减主之。若热邪不甚而表邪甚者，宜疏邪饮，或柴归饮加羌活、防风、干葛之类主之 \n，或败毒散亦可用。若痘夹红斑如锦纹者，宜凉血化毒汤加柴胡、黄芩、玄参、犀角之属主之。若 \n痘出夹斑夹疹而眼红唇裂者，表热也；烦躁大渴，妄言妄见者，里热也。表里俱热，最为凶证，若 \n不表里兼治，何由得解？宜双解散主之。若加闷乱气喘者必不治。 \n一、贼痘者，于出齐之后，其中有独红独赤独大，摸之皮软而不碍手者，此贼痘也。过三日之 \n外，必变成水泡，甚至紫黑泡，皆危证也，急用保元汤，或六气煎加紫草、红花、蝉蜕解之，或用 \n灯草、木遍煎汤，调下益元散，利去心经之热，而红自退。如已成水泡，宜用保元汤，倍加四苓散 \n利之，此秘法也，不然则遍身擦破，臭烂而死， \n一、病于未出之先，倘有湿疮脓水流注者，用附石末敷之，以防其漏气，或真正绿豆粉亦可。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>起发三朝治款（二十六）\n\n属性：痘疮放标之后，渐渐起胀，但肥胖一分，是胎毒发出一分，胖尽而毒出尽也。有不起者，或因 \n元气之弱，不能送毒，或有杂证阻滞，不能升发，皆痘前之失调理也。此时当速治之，否则后难为 \n矣。 \n一、痘宜渐发者吉，若一齐涌出，皮肉虚肿者，此表虚不能收摄，故奔溃而出，后必痒疡或成 \n溃烂，急宜人参固肌汤，或芎归汤。若血热者，宜凉血养营煎。虚甚者，宜六物煎。毒盛者，宜六 \n味消毒饮，或四味消毒饮出入用之。 \n一、痘不起发，或起而不透者，多由元气内虚，不能托送，故毒瓦斯留伏不出也。毒不尽出，则 \n变证莫测。凡见此者，速当救里以托其毒，然当察其气分血分，辨而治之。盖痘之壮突由乎气，肥 \n泽由乎血，气主 之，血主濡之也。若形虽壮而色见枯者，此气至而血不荣也，宜四物汤加人参、 \n麦门冬之类主之。若痘色红润而形平陷者，此血至而气不充也，宜保元汤，或六气煎加川芎主之。 \n若形色俱弱而不起发者，此气血俱不足也，宜六物煎加减主之，或保元汤、十全大补汤，调无价散 \n或独圣散与之。若冬春之间，为寒气所抑不能起发者，宜麻黄甘草汤加归、 ，或十宣散主之。若 \n夏秋火盛不起而烦渴秘结内热者，宜人参白虎汤。若痘疮起胀迟延不红活者，宜保元汤，或六物煎 \n加丁香、山楂、糯米、人乳、好酒主之，或用无价散，量儿大小以好酒调服。凡痘疮起发，通身皆 \n欲其透，惟四肢稍远难齐。若脾胃素强能食者勿虑，惟脾胃素弱食少者，四肢多有不透，以脾主四 \n肢，津液不能灌溉故也，宜以补脾为主，用快斑越婢汤加当归，或黄 建中汤加人参、防风。若因 \n误服凉药而致白 不起者，宜理中汤，或胃爱散。 \n一、痘虽起发，若灰白色或顶陷者，气虚也，切不可用寒凉之药，须六气煎加丁香、川芎、人 \n乳、好酒主 \n之，或保元汤倍加酒炒黄 、当归亦佳。 \n一、痘虽起发红活，若顶平色嫩，皮薄不能坚浓者，此气虚也，必恐变为痒 ，宜六气煎，或 \n六物煎加减主之，或十全大补汤、十宣散俱可择用。 \n一、地红血散不附者，保元汤加芍药、当归稍以收敛，归附气位。 \n一、根窠淡红，线晕枯燥者，血虚也，宜保元汤加当归、川芎、酒洗红花，再加山楂以行参、 \n之滞，少加木香以行气而血自活也。 \n一、痘虽起发而干枯无水，或青紫黯色，不久必变黑陷，乃血虚之甚也，宜四物汤加人参、麦 \n门冬、紫草、红花或调服无价散，外用水杨汤浴之，兼用胭脂涂法。 \n一、痘疮红甚而引饮渴不止者，名曰燥痘，宜犀角地黄汤之属。 \n一、痘色红紫满顶或 肿者，血热毒盛也，宜凉血养营煎加丹皮、木通、牛蒡子之属主之。然 \n痘出六日以后，有此证者多死。 \n一、痘已出齐而热尚不退，或烦躁发渴引饮，或二火司气之令，可少与冷水数口无妨。盖水性 \n下流，不滞上膈，亦能使毒从小便而出。但不可用生果之类，恐伤脾气也。 \n痘疮贵颗粒分明，如彼此相串，皮肿肉浮，或于本痘四旁旋出小痘攒聚，胖长渐成一块，此候 \n最险，宜用快斑汤合六味消毒饮以解其毒。 \n一、出齐后，痘有小孔，自顶宣下至脚，不白不黑，与痘色相同者，名为蛀痘。此因表虚腠理 \n不密而为此证，失之不治，则大泄元气，不起不发，速人之祸也，宜保元汤，或六气煎，大加糯米 \n、川芎、丁香，提气灌脓，内补其孔，甚为快捷方式。连进二、三服，必孔满而痘自起，若至黑色，则 \n为疔矣。 \n一、口唇为脾之外候，人以脾胃为本，不宜受伤，如初发热即见口唇焦裂，此毒瓦斯攻脾，乃恶 \n侯也，宜用泻黄散之类以速解之。若不早治，则毒聚于唇，及众痘起发，而唇疮必已先熟，内带黄 \n浆，及诸痘成浆，而此 \n疮已靥，唇皮揭脱，渐变呕恶呛水昏沉，不可为矣。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>灌脓三朝治款（二十七）\n\n属性：脓者，血之变也。痘疮初出，一点血耳，渐起渐长，则由血成浆，由浆成脓，始成实矣。故有 \n血则有脓，无血则无脓也。痘至灌脓，大势已成，此时必以有脓为主，有脓则生，无脓则死，乃必 \n然之理也。故六日以前，有热则宜解毒，无热则宜调养血气，至此自然灌脓。若痘至七日以后，顶 \n陷不能灌脓者，必由先失调治故也，所以治不可缓，必俟浆足，斯可回生。若顶陷灰白，浆脓不至， \n此气血俱离，无生意矣。 \n一、痘疮灌脓，专以脾胃为主，脾胃强则气血充实，脓浆成而饱满坚浓，不须服药；脾胃弱则血 \n气衰少，所以不能周灌，故虽见浆而浆亦不满，或清淡灰白不能作脓，即所蓄微浆，仍是初时之血 \n水。而浆薄无以化脓者，总属血气大虚之候，若不速治，必成内攻外剥之证，宜急用六物煎，或六 \n气煎加减治之，或保元汤、或十全大补汤加人乳、好酒与服亦妙。欲辨脾胃强弱，当于饮食二便察 \n之。饮食虽少而大便坚者，脾胃之气犹可也，但微加调补，以能食为贵。若大便不实，或见溏泻， \n则最为可畏。盖一泻则浆停，泻止则灌满矣。速宜用温胃饮，甚者用陈氏十二味异功散主之。如痘 \n当作脓之时，犹是空壳，此血不附气也。血既不至，则毒何由化？宜五物煎，或四物汤，或紫草散 \n加蝉蜕主之。如顶陷脓少，或服内托药而暂起复陷者，血气大虚故也，宜十全大补汤倍加参、 、 \n当归、糯米，煎成和人乳、好酒服之，此助灌之妙法也。 \n一、灌脓三朝之内，若身凉而痘色灰白，或不进饮食，或寒气逆上而为呕吐，或腹胀，或泄泻 \n而手足逆冷，此皆纯阴无阳之证也，急宜用保元汤加二仙散，连进数服；甚者必须九味异功煎，或 \n陈氏十二味异功散，皆可择用。若寒战切牙泄泻等证，俱同此治。 \n一、手足灌脓饱满者，方见脾胃之强，气血之足也。若色见灰白，浆水清薄，或瘪 不起者， \n此必脾胃之弱也。或灌浆已完，而四肢犹有不灌者，恐终变痒 之证，宜快斑越婢汤，或六气煎加 \n防风、白芷以达之， \n庶无陷伏之患。若毒有未透，亦恐关节之处，靥后致生痈毒。 \n一、痒 不止者，虽曰气血俱虚，然亦由火力不足，故不作痛而作痒也，宜六气煎，或五物煎 \n加防风、白芷、木香、蝉蜕主之。《心鉴》曰∶气愈虚则愈痒，当用保元汤倍黄 以助表，少加芍 \n药以制血，其痒自止。若将靥发痒，此毒退血活，新肉和畅，自然之理也，不必治之。 \n一、灌脓痛楚不止者，气滞也，少下保元汤加山楂、木香以行滞气。如脓色盛满，大下四苓散 \n利之而痛自止。 \n一、痘疮起发之后，不作脓有四证∶有内虚而不灌者，专宜托补气血，治法如前。有感风寒， \n邪居肤腠而不灌者，宜温散之，以柴葛桂枝汤加黄 、白芷。有热毒炽盛身壮热，津液干涸，小便 \n赤热而不灌者，宜托里解毒利小便，以紫草饮子，或用辰砂六一散解之，俟热退后，方可用保元汤。 \n热甚者，大连翘饮。若大便坚热，数日不通而不灌者，宜猪胆导之，使气得疏通，则营卫和畅，不 \n然恐成黑陷也。有触秽气而不灌者，外宜熏解，用胡荽酒，或辟邪丹，内服紫草木香汤，或紫草快 \n斑汤。 \n程氏曰∶凡顶陷无脓者为逆，但得根窠红润，血犹不散，急用保元汤和芎、归、白芍、丁香、 \n糯米煎熟，加人乳、好酒温服。若色白如水晶，内无脓者，治亦同。但得脓痘相间者犹可治，若纯 \n是水晶色者决死。若地红血散有热者，去丁香，加白芍、地骨皮以敛血退热。若寒战切牙，宜以木 \n香散，异功散选用。 \n程氏曰∶凡正壮之时，有痘虽起壮而皮肤无力，按之水浆就出，虽肉色不暗，此乃名为假壮， \n至十一、二日决不能回浆结靥，内攻而死，可急用保元汤加丁香、川芎、糯米，提气 \n灌脓自愈。此即名内托也。凡内托之法，即保元汤加川芎、丁香便是，不必《千金》内托也，但 \n按本方佐使用之。 \n一、痘将灌脓之时，忽面上有干靥者，即倒陷证也，宜速用八珍汤或六物煎加金银花、牛蒡 \n子、连翘、麻黄之属，水煎熟，调独圣散服之。服药后，若干者复起作脓，未干者即壮而饱满，或 \n空地处再出补空小痘者上 \n也。若痘不作脓，空处或发痈毒者次也。若连进三服而干者不肿，未干者不饱满，补痘不多，则最 \n险证也，宜以十全大补汤加金银花调治之。 \n一、灌脓时发白泡如弹子者，用枣针刺去其水，外以滑石末敷之，内服保元汤加石榴皮、茯苓 \n以利皮肤之水。如发紫泡，乃毒溢皮肤之上也，此证必危。 \n一、疮烂成片，脓水不干者，用滑石末敷之，或收草散敷之，加珍珠尤妙。 \n一、痘疮有重出者，凡痘疮破损溃烂处，但得复肿复灌，不致干枯，或于原无痘处复出一层，如 \n初用之状，亦以渐起发灌脓者，此皆余毒未尽，赖里气充实，毒不得入，故犹出于表而不成倒陷， \n是皆逆中之顺证也。但痘疮重出一番，必其人能食而大便坚，乃足以胜其再作之毒，自无足虑也。 \n如食少而大便润者，宜用十全大补汤之类，补而调之，若自利者，宜陈氏十二味异功散、肉以蔻丸主 \n之。盖病久气虚，惟利温补，不可再解毒也。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>结靥三朝治款（二十八）\n\n属性：痘疮灌脓之后，肥泽坚实，以手摸之，疮头硬而微焦，此欲靥也。靥时干净，无突陷淫湿破绽， \n色苍蜡，皮坚浓，外明内暗，尖利碍指者，此为正靥。若痘虽似干而痂薄如纸，或有内证未除，此 \n痘之极险时也，急宜调补，庶不致害。 \n一、痘疮自出起至十日，十一、二日，当从口唇头面以渐收靥。但自上而下者为顺，自下而上 \n者为逆，察有他证，速宜治之。 \n一、将收靥时，而一向身温忽然发热者，名为干浆，是亦常候。此时不可轻用汗下，若有风寒 \n外感，及饮食所伤，乃当随证治之。 \n一、痘疮收靥太迟，或当靥不靥者，证有数种，当详辨治之。大部当靥不靥之证，惟脾胃弱， \n中气虚者居多。盖中气虚则不能营养肌肉，使之成实，亦或致溃烂也。但察其别无他证而形色气血 \n俱虚者，宜内用十全大 \n补汤，外用败草散衬之。若当靥不靥，微热脉大而别无他证者，此阴分之不足也，宜四物汤倍加芍 \n药、何首乌。若血虚热毒未清者，宜四物汤加牛蒡子、木通、山楂。若因食少脾胃气虚而不收者， \n宜六气煎、或六物煎加减主之。若频见泄泻，脾胃弱，肌肉虚，成腹胀烦渴而不收者，宜陈氏十二 \n味异功散，或木香散，外用败草散敷之。若当靥不靥之际，忽见头面温，足指冷，身不热，或泄泻 \n腹胀，气促烦渴，急与陈氏十二味异功散，或九味异功煎，迟则不救。凡痘疮将靥之时，而见泄泻 \n烦渴，腹胀切牙等证，多有难救。若与蜜水生冷等物，必烦躁转加而死。有因饮水过多，或触于湿 \n气，以致脾胃肌肉湿淫，不收难靥者，宜五苓散，或四苓散加山楂利之。有因热毒未退，肤腠郁蒸 \n，阴不能敛而当靥不靥者，若不速解，则毒必内攻，为害不浅，宜犀角散加芍药、牛蒡子。有内外 \n俱热，阳毒散漫，以致大便秘结，阴气不行而当靥不靥者，宜内用四顺清凉饮，或三黄丸以通其便 \n，外用败草散、猪胆导法。有天寒失于盖覆，疮受寒凝而不收者，宜服五积散，外用乳香，或芸香 \n于被内熏之。有天热过暖，痘被热蒸不收者，宜内服人参白虎汤，或五苓散、四苓散以利湿热，外 \n用天水散扑之。有为邪秽阴寒所触，致伤元气而不靥者，宜保元汤，或十二味异功散，外以辟邪丹 \n熏之，猪髓膏涂之即愈。 \n一、痘疮内热，毒邪未尽化而干靥太疾者，后必为目疾，成为痈毒，及诸怪证，宜凉血养营煎 \n少清其火∶若大便过于干结者，宜微利之以解其毒，当归丸主之。 \n一、痘疮有脓结靥则为善，无脓结靥则为凶，此治之不可缓也。若痘已脓成，不能结靥，而反 \n致溃烂，或和皮脱去者，此名倒靥，乃毒瓦斯入内也，急须大补中气以托其里，宜六气煎倍加芍药， \n及紫草、防风、白芷主之；若兼湿热者，宜六气煎加芍药合四苓散主之。如头面疮破，服补药后 \n，但得复肿复灌，或遍身无疮处，又出一层，谓之补空，虽过期延日而饮食不减，不为大害。若服 \n药后不起不补，此毒已入深，最凶候也。 \n一、痘疮无论已溃未溃，于十二日之后，但得结靥，便为佳兆。若痂皮不结，则必成倒靥。其 \n有回之未尽，或遍身俱靥而但有数颗不靥者，终致作痒抓破，亦难必其生也，速宜治之。 \n一、靥时色白如梅花片者，此为假回，十二日后当死，此不治之证也。如不泄泻，可速用六气 \n煎，或六物煎，合二仙散大进救之。 \n一、痘疮成脓不靥，以致溃烂，脓汁淋漓，粘着疼痛，不可着席者，用败草散，或荞麦散，以 \n绢袋盛扑之，更多布席上衬卧尤佳，或用秘传茶叶方亦佳。若欲面上不成瘢者，用救苦灭瘢散，以 \n密水调敷之。 \n一、痘疮溃烂先伤于面者，凶兆也。如饮食无阻，二便如常，更无他证者，宜内用十全大补汤。 \n如毒盛内热者，宜以解毒防风汤加当归、蝉蜕，相间服之，外以救苦灭瘢散敷之。 \n一、痘疮于未灌之先，或会伤犯破烂成疮，及诸痘收靥，此独不靥，脓汁不干，更多痛楚，若 \n不急治，渐成疳蚀，损伤筋骨，以致横夭，宜服十全大补汤，外敷救苦灭瘢散，或白龙散。 \n一、痘疮抓破去皮而犹有血水者，急用六气煎，或六物煎主之，外以白龙散敷之。 \n一、痘有臭气。凡当收靥之时，臭而带腥者，此痘疮成熟之气，邪气自内而出也，为吉。若臭 \n如烂肉浊恶不可近者，此虽似结痂，未可为真，急须清热滋血，宜凉血养营煎，或解毒防风汤。若 \n于养浆之时便见臭者，此毒火熏蒸之气，积于中而见于外也，大凶，速宜清热以解其毒。若痘疮溃 \n烂不靥而臭不可闻者，名为烂痘，间亦有收靥无事者。只要胃气不衰，饮食如故，不作烦躁，则为 \n可治，宜用八珍汤，或四味消毒饮，外用败草散敷之。 \n一、痘疮靥后而有生疮溃烂成坑者，须用托里消毒散，或解毒内托散主之。如气血俱虚而不敛 \n者，必用十全大补汤。如遍身疮多溃烂，深而无气血者必死。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>靥后落痂治款（二十九）\n\n属性：痘疮结痂自当根据期脱落，其有应落下落，及延绵日久者，此亦不可不察而治之，以防他变也。 \n一、结痂至半月、一月，粘肉不落或发痒者，此必表散太过，伤其津液，以致腠理虚涩，无力 \n脱卸故也， \n宜用人参固肌汤，或以真酥油、麻油润之。如久而不脱，宜六物煎加黄 、肉桂、蝉蜕主之。切不 \n可勉强剥去，恐伤皮肤，一时难愈。 \n一、遍身结痂虽完，若余热未退，蕴蓄肌表，或身热，或烦渴而痂不落者，宜凉血养营煎，或 \n解毒防风汤，酌宜用之。如热甚者，宜大连翘饮加地骨皮主之。外宜用滑石为末，以蜂蜜调匀，鸡 \n翎扫润痂上即落。 \n一、痘瘢突起作痒不止者，此热毒未尽也，宜解毒防风汤主之。 \n一、痘瘢发痒，剥去痂皮，或血出，或后成脓如疮疥者，此血热气虚也，宜四君子汤，或四物 \n汤加红花、紫草、牛蒡子治之。 \n一、收靥迟而痂不落，昏昏欲睡，此邪气已退，正气未复，脾胃虚弱也，宜五福饮，或调元汤 \n，缓缓调治之。若余火未清者，宜酸枣仁汤。 \n一、痘痂既落，中气暴虚，多有不能食者，宜五味异功散，或养中煎以调之。 \n一、收靥落痂之后，若余热不退，谵语昏沉者，用辰砂六一散，以小柴胡汤调服之。若大便秘 \n胀者，宜当归丸利之。热甚者，用大连翘饮最妙。 \n一、原痘不灌脓，干如豆壳，虽痂落而疤白，或有余热不退者，虽过一日亦要死，宜速用八珍、 \n十全之类调补之。或毒盛者，仍须先用消毒饮。 \n一、痘痂既落之后，血气未复，极当调护，切不宜澡浴及食饮生冷，伤饥过饱，损伤脏气，致 \n生他病，为终生之患也。慎之，慎之！ \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>痘后余毒发热（三十）\n\n属性：疮痘无论疏密，只要毒出得尽而无留伏，其发以渐而透，其收以期而净，岂尚有余毒哉！若出 \n不能尽，发不能透，收不能齐，其人自有余热，或渴而腹痛吐泻，或小便赤涩，大便秘结，精神昏 \n惯，四体倦怠，饮食减 \n少，坐卧不安，是皆余毒未净之证。凡出之净者，作三四次出，大小不一，至成浆收靥之时，于疮 \n空中犹有补出者，此皆出之尽也。若只始出一层，后无补空之痘，此必尚有伏也，又发之透者，必 \n于手足候之，盖手足部远，气不易达，若能充拓饱满，浆气颇足，可谓发之透也。若只平 不能成 \n脓，此毒虽出而未能旁达四肢，必有留而伏者。又收之齐者，自面而下，痂皮洁净，中无溃烂可谓 \n之齐。若收之太早，或不成痂，此必有内陷之毒也。凡若此者，皆有余毒，须察部位经络、寒热虚 \n实，或补或利，或解或散，以平为期。若治之不应不已者，此坏证也，不必妄行攻击。 \n一、尽后发热不减者，此有虚实二证，如能食而烦渴，小便赤，大便秘者，实也。宜四顺清凉饮 \n、三黄丸之类主之。若痘后余毒未净，有诸热证者，惟大连翘饮为最佳。如大便不秘，小便不赤， \n坐卧振摇，饮食少进者虚也，宜调元汤，或五福饮加芍药之类主之。 \n《心鉴》云∶痘后余热者，虚热也。虚热多发于午后，脸赤唇红，或妄言谵语，切不可作实热 \n治，当用调元汤，或保元汤加黄连，热甚者，宜大连翘饮。若妄用攻下，使胃气一虚，则变生他患 \n，致成坏证，不可治矣。 \n徐氏曰∶痘后余热不除者，当量其轻重而治之，大热则利小便，小热则宜解毒。盖利其小水， \n使心火有所导引，虽不用凉药，而余热自无容留矣。小热宜解毒者，盖小热不解，恐大热渐至矣。 \n利水者，宜导赤散；解毒者，宜犀角地黄汤。若但身表发热而别无他证者，止宜柴胡麦门冬散。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>禁忌（三十一）\n\n属性：一、痘疮起发之初，全要避风寒，远人物，节饮食，守禁忌。若到养浆之时，尤宜谨慎，如天 \n气大热则去衣被，当令清凉但谨门窗帷帐，勿使邪气透入；如天寒则宜浓添盖护，房中勿绝灯火； \n如或作痒，须为抚摩，勿使搔破，以致难灌，最当慎也。 \n一、痘疮房中，凡诸臭秽腥香之气，及僧道师巫之人，或骂詈呼怒，震惊歌乐，扫地，对面搔痒，对面梳 \n头之类，皆不可不避。 \n一、房中欲辟臭秽，惟烧避邪丹，或红干枣，或黄熟香皆佳。若苍术之气则太峻也。 \n一、饮食最宜调和，无使太过不及。或好食何物有不宜者，但少与之。以顺其意，苦禁固太严， \n使之忿怒，恐反助火邪，但不可纵耳。至若助火生风，及葱蒜泄气等物，皆所当慎。 \n一、痘疮前后，大忌猪肉、鱼酒之类，恐惹终身痰咳。 \n一、痘疮平复之后，勿与鸡鸭蛋，食之则伤神。 \n一、痘疹退后，须避风寒，戒水湿，如犯其邪，则终身咳嗽，患疮无有休日。 \n东垣曰∶痘疮宜避一切秽恶气及外人入房。远行劳汗气，腋下狐臭气，房中淫液气，麝香臊膻 \n气，妇人经候诸血腥臭气，硫黄蚊烟气，厕缸便桶气，误烧头发气，吹灭灯烛气，鸡毛鱼骨气，葱 \n蒜韭薤气，以上皆不可犯。须要时常烧乳香之类甘香之气，使之渐闻，则营卫气畅，可无倒靥陷伏 \n等患。 \n陈氏曰∶凡痘疹热渴，切不可与瓜柿蜜水等冷物，及清凉饮、消毒散等药，恐损脾胃，则腹胀 \n喘闷，寒战切牙而难治。轻变重者，犯房室，不忌口，先曾泻，饮冷水，饵凉药也。重变轻者，避 \n风寒，常和暖，大便调也。 \n薛氏曰∶前证苦兼吐泻，手足指冷，属内虚寒而外假热也，最忌寒凉。苦大便不通，渴欲饮水 \n，则蜜水之类又当用也。但当审其热之虚实可也。今北方出痘，多有用水，无不愈者，盖化方多睡 \n热炕故也。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>出不快（三十二）\n\n属性：陈氏曰∶凡痘疮出不快者，多属于虚，若误谓实热壅盛，妄用宣利之药，致脏腑受冷，营卫涩 \n滞，不能运达肌肤，则不能起发充满，亦不能结实成痂，后必痒 ，烦躁喘渴而死。 \n薛氏曰∶前证亦有各经热盛，壅遏而出不快者，亦有毒盛痘疔而不能起发者，亦有余毒而溃痒 \n者，当细审其因而药之。 \n景岳曰∶接此二子之说，皆为有理，但此出迟不起之证，总是气血内虚不能速达者为最多，若 \n风寒外闭，及痘疔留毒而不出不起者，虽亦有之，但不多耳。再若各经热盛而壅遏不出者，则尤为 \n最少，何也？盖热盛者毒必盛，毒盛者势必疾速，而或密或早，无能缓也。故凡治此者，必当察其 \n热之微甚，以辨虚实，再察外邪之有无以辨表里。如无外邪，亦无痘疔而火邪不甚者，则尽属虚证， \n宜从温补，不得杂乱以遗后患也。诸治法详报痘三朝治款中。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>陷伏（三十三）\n\n属性：凡看痘之法，其出欲尽，出不尽者伏也；其发欲透，发不透者倒陷也；其收欲净，收不净者倒 \n靥也。伏唯一证，陷有数种。凡毒之伏者，患在未壮之先，其人疮虽出而热不少减，或烦渴，或躁 \n闷，此必有伏毒未得全出也。陷则患于既壮之后，其血渐干而变黑者，谓之黑陷；浆脓未成而为痒 \n，或破损者，谓之倒陷；浆脓既成而复湿烂，皮破不肯结靥，收不干净者，谓之倒靥，亦陷类也 \n，是皆恶候。凡治此者，使非猛峻之剂，安能望其回生。时医欲以寻常之药救此危病，其犹放雀搏 \n，驱羊敌虎耳。故其轻者宜夺命丹，重者宜神应夺命丹，则其庶几耳。倘服药后而反增黑色者， \n为必不治之证。 \n一、痘之留伏毒不尽出者，证有不同，当辨治之。有元气不足而托送无力者，此必禀赋素弱，饮 \n食素少，身无大热而出有不透，即不足之证也，宜十宣散、蝉蜕膏之类，加独圣散主之，若虚而有 \n热者，宜人参透肌散。有毒盛气滞，留伏经络而出不透者，必其人气体浓浊，身有大热而汗不易出 \n，即皆有余之证，宜荆防败毒散主之。若表里俱实，外有大热，内有秘结烦满，而留伏不透者，宜 \n双解散。 \n一、干黑不起而倒陷者，当分五证∶一则内虚而阳气不能外达，故致出而复没，或斑点白色，或 \n见灰黑倒 \n陷者，必其人不能乳食，或腹胀内寒，或手足冷，或吐泻，或寒战咬于，皆内虚也，速宜温中，轻 \n则十宣散、六气煎；甚则陈氏十二味异功散，或九味异功煎；外用胡荽酒喷之，或更用十全大补汤 \n。但得冷者暖，陷者起，黑音红活，便是佳兆。若服药后而反加烦躁昏乱者死。二则毒瓦斯太盛，内 \n外熏灼，不能尽达于表，因而复陷于里，乃致热烦躁扰，气喘妄言，或大小便不利，渴而腹胀，是 \n皆毒瓦斯之倒陷也，轻者利小便，宜大连翘饮、通关散，或四顺清凉饮；甚者通大便，宜承气汤，并 \n外用水杨汤浴之。得利后疮出则佳，更用加味四圣散调治之。凡治此者，但得阳气不败，脾胃温暖 \n，身温欲饮水者生。苦加寒战身冷，汗出耳尻反热者死。三则外感风寒，肌窍闭塞，血脉不行，必 \n身痛，或四肢微厥，斑点不长，或变紫黑如瘾疹者，此倒伏也，宜温肌散表，用桂枝葛根汤加麻黄 \n、蝉蜕，或紫草饮，外用胡荽酒喷之，但令温散寒邪，使热气得行，则痘自长矣。四则或因误下， \n毒瓦斯入里而黑陷者，先宜六气煎，或温胃饮以培养胃气。如表有未解者，后宜柴葛桂枝汤以疏散于 \n外，甚者再加麻黄。五则以房室不洁，或为秽恶所触而黑陷者，宜内服紫草饮子，外用胡荽酒喷之 \n，或用茵陈熏法，并用辟邪丹。 \n一、将起发时，虽有浆水，但色见黑黯者，最为可畏，急宜六气煎加川芍以香血气，血气旺则 \n毒自散而色自活矣。或以十全大补汤合无价散主之。 \n一、凡倒靥之证，亦须看大便何如，苦大便秘结而内热者宜利之，以四顺清凉饮，或三黄丸主 \n之。若大便不实而内不热者宜补之，以六气煎，或十全大补汤加防风、白芷；甚而泄泻者，宜陈氏 \n十二味异功散。有虽不泄泻而虚寒甚者，宜九味异功煎，并外用败草散。 \n一、治陷伏证有三验法，凡服药之后，但得陷者复肿，渐以成脓，乃一验也；苦原疮已干而别 \n于空处另出一层，起发成脓，渐以收靥者，二验也；亦有不肿不出，只变自利，下去脓血而饮食精神 \n如故者，三验也，有验者吉，无则凶。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>痒抓破（三十四）\n\n属性：诀云∶虚则痒，实则痛。又曰∶诸痒为虚。此固其辨矣。然实即兼热也，虚印兼寒也。盖如疮 \n疡之痛，必由乎热，今不作痛而作痒，此其无热可知，无热由乎阳虚，阳虚便是寒证，诸有以初起 \n作痒为火者，皆谬也。且凡痘疮发痒，则多为不起不灌而 陷继之，最可虑也。故凡治痒之法，虽 \n云当补，然尤不可不温，惟温补则营卫和，气血行而痘自起矣。痘毒既起而透，则多有作痛，尚何 \n痒哉？故痘于起发之时，则宜痛不宜痒也。然痒有数证，亦当辨治如下∶ \n一、痘疮初见点便作痒者，此邪在半表半里之间，而进退迟疑总由元气无力，欲达不能也，速 \n当温补阳气，兼以疏散，但使腠理通畅，则痘自起而痒自止矣。宜六气煎加川芍、白芷、防风、荆 \n芥之属。若虚在血分而色白者，宜六物煎，或五物煎加减主之。 \n一、痘疮出齐之后，但是作痒，俱宜保元汤，或六气煎加川芎、当归、防风、荆芥治之，或用十 \n全大补汤，或用蝉蜕膏。 \n一、血渗肌肤，咸蜇皮肉而作痒者，亦以气虚而然，宜保元汤加芍药、当归以制血，或加丁香 \n以治里，官桂以治表，表里俱实，自不作痒。 \n程氏曰∶凡前后痒 ，宜保元汤加何首鸟、牛蒡子、白芍药。何首鸟须赤白兼用。 \n一、痘疮干而作痒者，宜养血润燥，以五物煎加防风、荆芥、外用茵陈熏法。 \n一、痘疮湿而作痒者，宜补气去湿，以四君子汤加防风、荆芥、桂枝以解之，外用菌陈熏法。 \n一、头面为诸阳之会，若痒而抓破，则泄气最甚，速宜六气煎，或十全大补汤加防风、荆芥、 \n何首乌之属以培补之。但得复肿复灌而饮食如常则无害，若痒不止而满面抓破者必死。 \n一、遍身发痒抓破，脓血淋漓者，宜参 内托散，倍加当归及白芷、荆芥、木香，使气和血行，其 \n痒自止， \n外以败草散敷之。 \n一、疮痒溃烂，粘衣连席难任者，内服十全大补汤加防风、荆芥，外用败草散。 \n一、痘疮见形而皮肉红艳，起发而皮嫩多水者，其后多致痒 也，急须先期调补之。 \n一、痘疮将收而痒者，其脓已成，其疮已回，邪散而正复，营卫和畅故痒也。不须服药，但谨 \n护之，勿令抓破，以致损伤成疮。 \n一、浆脓初化，脓未成而混身瘙痒不宁者，此恶候也，速当温补气血，用六气煎、六物煎之类 \n，加以防风、白芷、荆芥之属，必令痒去方保无虑。若痒甚不休，疮坏皮脱，其毒复陷，谓之痒 \n，必不能活矣。 \n《活幼心书》云∶凡作痒不止，用荆芥穗以纸束之，用刺痒处，以散郁邪，其痒自止，此屡验 \n之法。内服消风化毒汤加参、归以解之。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>作痛（三十五）\n\n属性：痘疮作痛，有实有虚，虽曰诸痛为实，然此言亦不可执。若身有大热而大便秘结，烦躁不宁， \n喘胀作渴而为痛者，此实痛也。若无大热而二便清利，脾气不健，卫气不充，营失所养而作痛者， \n此虚痛也。实者宜解毒清火，当用解毒汤，或四味消毒饮之类主之。虚者宜补香血气，当用保元汤 \n，或六物煎之类主之。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>头面肿（三十六）\n\n属性：经曰∶热甚则肿。大抵毒盛者必肿，毒微者不肿，故亦可以肿与不肿，察毒之甚与不甚也。然 \n痘疮应期起发，毒必以渐尽出，故头面亦必以渐浮肿，此毒火聚于三阳之分，欲化脓浆，其宜然也 \n。然止宜微肿，而甚肿者，大作所宜。若当起发之时，头面全然不肿，必其痘稀磊落，毒瓦斯轻浅者 \n然，此最吉兆也。 \n一、痘以渐起，面以渐肿，及灌脓收靥而肿以渐消，此常候也。如应肿不肿者，必其元气不足 \n；应消不消 \n者，必其毒瓦斯有余，须急治之。 \n一、有痘未起发而头面预肿，皮光色嫩，如瓠瓜之状，此恶毒上冲之候也。又有痘点已见，但隐 \n隐于皮肤之中，肉目肿而痘不起者决死。汪氏《理辨》曰∶痘起五六日之际，有面目先肿而光亮者 \n，是阳乘阴分，毒不能发也。何也？血乃气之本，气乃血之标，血有不足，则根本之力已亏，故致 \n虚阳动作，其气妄行肉分，区区不足之血，何能载毒而出？七日之后，传经已足，则气退毒陷，阴 \n阳各失其正，尚何可治之有？凡值此者，不可不预调气血，若待临期，无能为矣。 \n一、痘正起发头面肿胀时，正面之疮切防瘙痒，不可使之抓破，少有损伤，以致真气外泄，邪 \n气内蚀，则肿消毒陷，多致死矣。但得破者复灌，消者复肿，饮食二便如常，则变凶为吉矣，宜十 \n全大补汤，或合苦参丸治之。 \n一、头面肿胀而眼目咽喉痛闭者，急宜解毒，眼与咽喉相兼治之，宜消毒化斑汤去升麻，或 \n大连翘饮主之。 \n一、兼疫毒之气而头项腮颌预肿者，此必大头风及虾蟆瘟之属，宜以疫气治之，如大连翘饮， \n及普济消毒饮之类主之。但兼此者亦多凶少吉也。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>痘疔黑陷（三十七）\n\n属性：痘有紫黑枯硬而独大，针拨不动，手捻有核者，是为痘疔，若不去之，则一身之痘皆不能起发 \n，或皆变黑色，必致死矣、其有黑大而软者，此名黑痘，慎不可作痘疔治也。 \n痘疔者，以热毒蓄积，气血凝败而成也。然其类亦有数种，最为恶候，宜谨察之。有初出红点 \n，渐变黑色，其硬如石者，此肌肉已败，气血中虚，不能化毒，反致陷伏也。有肌肉微肿，状如堆 \n粟，不分颗粒者，此气滞血凝，毒瓦斯结聚不散也。有中心黑陷，四畔突起戴浆者，此血随毒走，气 \n不能充也。有中心戴浆自破溃烂者，此 \n气血俱虚，皮肤败坏也。有为水泡溶溶易破者，此脾虚不能制湿，气虚不能约束也。有为血泡色紫 \n易破者，此血热妄行，而气虚不能完固也。有疮头针孔浆水自出者，此卫气已败，其液外脱也。以 \n上数证，虽与痘疔不同，而危险无异，但于五六日间候之，若见一证，多不可治。 \n一、凡痘疔及黑陷者，宜内服六气煎加川芎、紫草、红花、木通之类，以补血凉血而疔自退。疔 \n退后，宜大进六气煎，或六物煎，外用四圣丹，以胭脂汁调点之。疔若大者，用银针挑破疮口，吸 \n出恶血，入后药末，即转红活。大抵黑陷而疔多，或余毒不起者多死。苦痘疔挑去黑血，搽药不变 \n，仍是黑色者必死。 \n《心鉴》曰∶痘疔见于四肢，不近脏腑者易治，若穿筋骨者亦难治。但有见于头面腹背，逼近 \n于内者，其势必攻穿脏腑矣。如未穿者，急须治之，用飞过雄黄，以真蟾酥拌勾为丸，如麻子大， \n挑疔点入，立效。又成用巴豆一粒，去皮膜，合朱砂一分，研烂点入，一时突出即愈。内服无价散 \n，汲井水加猪尾血三五点调下。 \n一、痘疮黑陷者，必气不足，血不活也，急宜托里散，或六物煎加川芍、肉桂、红花、蝉蜕， \n调无价散，或独圣散，甚者宜九味异功煎，或十全大补汤，调无价散，仍外用四圣丹点之。若见焦 \n紫而黑，混身皆是，及身有大热，或大便秘结，内热烦渴者，此亦有火毒之证，宜四顺清凉饮，或 \n承气汤，合万氏夺命丹以解其毒。俟火邪略退，即宜用六气煎，调无价散以托其内，亦可望其生也 \n。 \n一、痘疮起发之时，但见干燥，其根焦黑，即当速治之。如火邪不甚，证无大热者，惟五物煎， \n或六物煎为最宜也。如有火证火脉，血热毒盛而焦黑者，轻则凉血养营煎，或鼠粘子汤，甚则以万 \n氏夺命丹合而服之。 \n一、原有疮疥未愈，至痘出之时，其破处痘有攒聚，而形色黑溃者，急以银针挑破，吮去毒血， \n吐于水中，其血红者可治，黑者难治，须内服加味四圣散，或万氏夺命丹，外用万氏四圣散涂之。 \n一、靥后痘疔溃烂成坑，内见筋骨者，宜托里消毒散，或荆防败毒散加穿山甲、蝉蜕、僵蚕， \n外用神效当归膏，或太乙膏贴之，或以白龙散敷之。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>饮食（三十八）\n\n属性：痘疮终始皆以脾胃为主，但能饮食，则气血充实，而凡起发灌浆收靥，无不赖之。故能食者， \n虽痘疮稠密，亦自无害；不能食者，虽痘疮稀少，亦为可虞，此脾胃之调，所当先也。然证有不同 \n，最须详审施治。 \n一、痘有毒瓦斯正盛而不食者，当痘疮正出之时，虽不欲食，但得痘色真正，不为害也。盖热毒 \n未解，于将出未出之际，多有不欲食者，待毒瓦斯尽出自能食矣。其有痘已尽出而仍不欲食者，当徐 \n用四物汤加神曲、砂仁、陈皮，一、二剂必能食矣， \n一、痘见灰白，别无大热停滞等证，而食少或不食者，必脾胃虚也，宜五味异功散，或四君子 \n汤。若胃中阳气不足，不能运化而食少者，此处而且寒也，宜温胃饮、养中煎，或六气煎主之。 \n一、凡命门元畅不足，则中焦胃气不暖，故多痞满不食，下焦肾气不化，故多二阴不调，此必 \n用理阴煎加减治之，自见神效，勿谓小儿无阴虚证也。 \n一、凡泄泻，或见恶心，或呕吐而不食者，尤属胃气虚寒也，轻则理中汤、六气煎；甚则陈氏 \n十二味异功散，或用六气煎合二仙散主之。 \n一、凡脾气不虚，但胃口寒滞，或痛或呕而不食者，宜益黄散。 \n一、凡停食多食而不食者，宜大小和中饮以清宿滞，或五味异功散加山查、麦茅、神曲、砂仁， \n或合匀气散治之。 \n一、凡口疮不能进食，或咽喉疼痛而不能食者，但清其咽，痛止自会矣，宜廿桔汤，或加味甘 \n桔汤。 \n一、凡外感风寒，邪入胃口则不能食，须表散寒邪，邪散自能食矣，宜加减参苏饮，或柴陈煎 \n，或五味异功散加柴胡。 \n一、痘后别无他证而饮食不进者，此惟脾气不足，宜五味异功散，或温胃饮、养中煎之类主之。 \n程氏曰∶凡水谷不能运化而饮食不进者，只用保元汤加陈皮、麦茅、神曲、砂仁、扁豆、生姜 \n，呕者加真藿香。 \n徐氏曰∶痘疮不乳食者，有虚实二证∶或吐或利，面目青白或青黑色者为虚寒，宜温之补之； \n若大小二便干涩，面赤而气壅，或渴或热，或目睛黄赤，气粗中满者为实热，宜清之利之。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>咽喉口齿（三十九）\n\n属性：咽喉司呼吸之升降，乃一身之橐 也。毒瓦斯不能舒散，则壅聚于此，肿痛闭塞，水浆难入，则 \n死生系之，深可畏也。首尾俱宜甘桔汤加麦门冬、牛蒡子、玄参、杏仁，或加味甘桔汤，及《拔萃 \n》甘桔汤俱可用。热甚痛甚者，宜东垣凉膈散加牛蒡子，或以甘桔汤合黄连解毒汤加石膏、木通、 \n牛蒡子、山豆根、射干，并外用玉钥匙点之。咽痛便秘者，宜四顺清凉饮下之。以上证治，必其能 \n食肉热者，方可用此寒凉之剂。若上焦虽热而下焦不热，或不喜饮食者，只用加味甘桔汤，徐徐咽 \n服，不必用牛蒡子，恐其性凉伤脾也。 \n一、咽喉肿痛，凡痘疮多有是证，但七日前见者为逆，七日后见者无虑。盖起发灌脓之时，内外 \n之痘俱大，以致气道壅肿而然，此痘也，非喉痹之毒也。待外痘既靥，则内证自除矣，不必治之。 \n徐氏曰∶凡咽喉肿痛不能饮食者，内服加味甘桔汤。外看身上有痘之最大者，此其毒瓦斯相连， \n宜用香油灯草燃而淬之，一淬即愈。或用手捻破，以痘疔散涂之。 \n陈氏曰∶凡身壮热，大便坚实，或口舌生疮，咽喉肿痛，皆疮毒未尽，宜用四味射干鼠粘子汤 \n。如不应，宜七味白术散。 \n一、痘疮弄舌吐舌者，脾之热也，轻者导赤散，甚者泻黄散。 \n一、唇口与五内相通，故热毒内发，口舌必先受伤，毒甚则口舌或紫或白或黑，舌或肿大，此皆 \n实热之证，宜内服黄连解毒汤加石膏、牛蒡子、木通、生地，或东垣凉膈散。若大便干结者，宜《 \n局方》凉膈散，外用玉钥匙点之。若口舌生疳者，以吹口丹，或阴阳散敷之。 \n一、牙龈肿烂成疳者，此阳明热毒内攻也，杀人甚速，宜甘露饮主之，外用老茶叶、菲菜根煎浓汤 \n洗之，仍用翎毛刷去腐肉，洗见鲜血，乃以神授丹，或搽牙散敷之，日三次，或绵茧散亦可。若烂 \n至喉中者，用小竹管将绵茧散吹入，虽遍口牙齿烂落、口唇穿破者，皆可敷药而愈。然必有黄白脓 \n水者方可治，若色如干酱，其肉臭烂，日烂一分者俱不治。 \n一、牙疳臭烂，气粗热甚，舌白至唇，口臭如烂肉，大便泻脓血，肚腹胀痛，此胃虚毒瓦斯内攻 \n，胃烂之证。苦山根发红点者，此疳毒内攻，故见于山根，亦胃烂之证，俱不治。 \n一、痘疹退后，若有牙龈腐烂，鼻血横流者，并为失血之证，宜《局方》犀角地黄汤加山栀、 \n木通、玄参、黄芩之类以利小便，使热毒下行，外用神授丹治之，不可缓也。若疳疮色白者，为胃 \n烂，此不治之证。 \n\n\n\n<目录>卷之四十四烈集·痘疹诠\\痘疮（中）\n\n<篇名>痘疮中论列方（四十）\n\n属性：保元汤（痘一） 调元汤（痘二） 五味异功散（补四） 四君子汤（补一） \n五福饮（新补六） 九味异功（煎因二三） 四物汤（补八） 五物煎（新因二） \n十二味异功散（痘二二） 二阴煎（新补十） 六物煎（新因二十） 十一味木香散（痘二一） \n二仙散（痘二十） 六气煎（痘二五八） 十全大补汤（补二十） 十宣散（痘十四） \n八珍汤（补十九） 六味回阳饮（新热二） 温胃饮 \n（新热五） 理中汤（热一） 七味白术散（小七） 养中煎（新热四） \n理阴煎（新热三） 七味安神丸（小七三） 益黄散（和十九） 胃爱散（痘十九）莫能助 \n黄建中汤（补二七） 芎归汤（痘十五） 托里散（痘四） 参 内托散（痘七） \n惺惺散（小二三） 酸枣仁汤（补八四） 人参固肌汤（痘十二） 柴陈煎（新散九） \n柴葛煎（新因十八） 人参透肌散（痘十三） 柴归饮（新因十五） 苏葛汤（痘二七） 升 \n麻葛根汤（痘二六） 疏邪饮（新因十六） 小柴胡汤（散十九） 柴葛桂枝汤（痘三六） \n参苏饮（散三四） 柴胡饮子（痘四二） 加减参苏饮（痘三四） 五积散（散三九） \n五柴胡欲（新散五） 桂枝葛银渴（痘三七） 双解散（痘四一） 羌活散（痘三八） \n麻黄甘草汤（痘三五） 益元散（寒百十二） 搜毒煎（新因十九） 柴胡麦门冬散（痘二四） \n天水散（寒百十二） 败毒散（痘三一 又三二） 荆防败毒散（痘三一） 六一散（寒百十二） \n解毒汤（痘五一） 黄连解毒汤（寒一） \n甘露饮（寒十） 消毒散（痘四七） \n托里消毒散（痘六） 五苓散（和一八二） 泻黄散（寒五七） 解毒内托散（痘五） \n四苓散（和一八七） 退火丹（痘八四） 实表解毒汤（痘五四） 导赤散（寒一二二） \n苦参丸（痘九九） 四味消毒欲（痘四八） 当归丸（痘九五） 大和中饮（新和七） \n六味消毒饮（痘四九） 三黄丸（攻六八） 小和中饮（新和八） 毒 \n防风汤（痘五六） 承气汤（攻一） 肉豆蔻丸（小五六） 消风化毒汤（痘五八） 通 \n关散（痘八五） 橘皮汤（痘九二） 凉血化毒汤（痘五九） 独圣散（痘七八） 匀气 \n散（痘九三） 普济消毒饮（寒十三） 蝉退膏（痘四六） 化痰丸（小九九） 消毒化 \n斑汤（痘五十） 无价散（痘七九） 三酥饼（痘八十） 养血化斑汤（痘十八） 败草 \n散（痘一二六） 抱能丸（小八五） 凉血养营煎（新因十七） \n胡荽酒（痘百十八） 保婴丹（痘百五） 玄参地黄汤（痘八六） \n水杨汤（痘百二十） \n大连翘饮（寒七八） 速翘升麻汤（痘二八） 胭脂汁（痘一二五） 犀角散（痘六三） \n犀角地黄汤（寒七九） 猪髓膏（痘一二二） 快斑汤（痘七三） 快斑越婢汤（痘七四） \n荞麦散（痘一二四） 鼠粘子汤（痘七六） 射干鼠粘子汤（痘七七） 茶叶方（痘一二一） \n紫草欲子（痘六七） 柴草木通汤（痘七十） 白龙粉（痘一二七） 紫草饮（痘六六） \n紫草木香汤（痘六九） 神授丸（因一五六） 紫草散（痘六五） 柴草快斑汤（痘六八） \n绵茧散（痘一三四） 如圣汤（痘十一） 加味甘桔汤（痘九十） 痘疔散（痘百十四） \n甘桔汤（因一七五） 《拔萃》甘桔汤（因一七六） 阴阳散（外一三三） 四圣丹（痘百十五） \n参四圣散（痘八） 吹口丹（痘一三六） 玉钥匙（因一九三） 加味四圣散 \n（痘十） 搽牙散（痘一三五） 辟邪丹（痘百三十） 万氏四圣散（痘百十六） 茵陈薰法 \n（痘百十九） 人参白虎汤（寒三） 四顺清凉饮（攻二五） 《局方》凉隔散（痘十九） 东垣凉膈散 \n（痘八三） 前胡枳壳汤（痘九四） 万氏夺命丹（痘八二） 神应夺命丹（痘八一） 救苦 \n灭瘢散（痘一二八） 万氏牛黄清心丸（小九四） 神效当归膏（外三一四） 太乙膏（外三百八） \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>总论吐泻（四十一）\n\n属性：凡痘疹吐泻，有不必治者，有当速治者。如初热时即见吐泻，但欲其不甚而随止者吉，盖 \n吐利中自有疏通之意，邪气赖以宣泄，不必治也。其有吐利之甚者则不得不治。又有元气本 \n弱而见此证者，使不速为调补，必致脾气困惫则痘出之后，虚证叠见而救无及矣。此痘前之 \n吐利，其当治不必治，自有轻重之分也。若见点之后，则吐泻大非所宜，速当察其寒热虚实 \n而调治之。 \n一、痘疮吐泻，虽曰多属脾经，然亦有二焦五脏之辨。盖病在上焦，但吐而不利；病在 \n下焦，但利而不吐；病在中焦，则上吐下利。故在上焦者，当辨心肺之脾气；在下焦者，当 \n察肝肾之脾气。此五脏之气，各有相滋相制之机，设不明此，鲜不误矣。 \n一、痘疮吐泻，大都中气虚寒者，十居七八，然亦有邪实毒盛，及饮食过伤而为吐泻者， \n此宜详审脉证，自有可辨。若果有热毒实邪，则不可误认虚寒，轻用温补，恐反助邪以致余毒痈 \n肿，或为溃烂难收等证。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>呕吐（四十二）\n\n属性：痘疮呕吐，大都虚寒者多，实热者少，但当以温养脾胃为主。即或兼杂证者，亦必有实邪可 \n据，方可因病而兼治之，故不得轻用寒凉及消耗等药。 \n一、凡呕吐之病，病在上中二焦也，切不可妄用下药，致犯下焦元气，则必反甚而危矣。 \n即或有大便不通 \n者，亦当调补胃气，从缓利导，但得脾胃气和，则升降调而便自达，此不可不知也。 \n一、痘疮别无风寒食滞、胀满疼痛等证，而为呕吐或干呕恶心者，必脾胃虚寒也，宜六味 \n异功煎、五君子煎、参姜饮之类主之，或温胃饮、理中汤皆可酌用。 \n一、脾气微寒微呕而中焦不寒者，宜五味异功散。 \n一、胃口虚寒，呕吐而兼有痛滞者，六味异功煎送神香散，或调中汤亦佳。 \n一、脾胃虚寒吐泻并行者，温胃饮，甚者陈氏十二味异功散。 \n一、脾肾虚寒，命门不暖而为吐泻者，必饮食不化，水谷不分而下腹多痛，非胃关煎或理 \n阴煎不可。 \n一、凡寒气犯胃，腹胀腹痛而为呕吐者，神香散、益黄散，或加炮姜。若因饮水或食生冷 \n瓜果而作呕吐者，五苓散加炮姜。 \n一、饮食过伤，停滞胃口，胸膈胀满而为呕吐者，宜和胃饮，或大和中饮，或神香散。 \n一、痰饮停蓄胸膈而胀满呕吐者，宜二陈汤，或橘皮汤加炮姜。 \n一、三焦火闭，烦热壅滞胃口而为呕吐者，此必阳明火证也，宜橘皮汤加黄连，甚者再加石 \n膏，或用竹叶石膏汤。但此证甚少，勿以虚火作实火也。 \n程氏曰∶凡痘疮呕吐之证，须辨冷热。热吐者，宜六君子汤加姜汁炒芩、连；冷吐者， \n宜六君子汤加丁香、藿香、白豆蔻。 \n一、痘疮呕吐不已，声浊而长，或干哕者，最是疮家恶候。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>泄泻（四十三）\n\n属性：痘疮首尾皆忌泄泻，而后为尤甚，惟初热时，有随泄而随止者为吉。若自见黑点之后， \n以致收靥，毒瓦斯俱已在表，俱要元气内充，大便坚实，庶能托载收成，若略泄泻，则中气虚弱， \n变患百出矣。若初出之后而见 \n泄泻，则必难起难灌；既起之后而见泄泻，一泻则浆停，泻止则浆满；既灌之后而见泄泻， \n则倒陷倒靥，内溃内败等证，无所不至，此实性命所关，最可畏也。今多见妄药误治，败人脾 \n气以致莫救者，犹云欲去其毒，泻泻无害，欺耶昧耶，庸莫甚矣。 \n凡治痘疹泄泻，只在辨其寒热，热者必湿滞之有余，寒者必元阳之不足。但十泻九虚而实 \n热者极少，故凡见泄泻、呕吐、腹痛而别无实热等证者，无论痘前痘后，俱速宜温救脾肾。此 \n大要也，当详察之，若失其真，误治则死。 \n一、虚寒泄泻，凡证无大热，口不喜冷，脉不洪数，腹无热胀，胸无烦躁，饮食减少而忽然 \n自利者，则悉属虚寒，切不可妄用寒凉之剂，再伤脾土，必致不救，宜温胃饮、养中煎、五君 \n子煎，或理中汤、四君子汤之类，随宜用之。若腹有微滞微胀而为泄泻者，宜六味异功煎，或 \n五味异功散加砂仁。若泄泻兼呕兼痛而气有不顺者，宜养中煎加丁香、木香，或四君子汤合二 \n仙散。若泄泻而山根、唇口微见青色，或口鼻微寒，手足不热，指尖微冷，泻色淡黄，或兼青白 \n，睡或露睛，此皆脾肾虚寒之证，非速救命门，终不见效，宜胃关煎、理阴煎主之，或陈氏十 \n二味异功散亦可。若泄泻势甚，用温脾之药不效者，则必用胃关煎，或理阴煎之类主之。若久泻 \n滑脱不能止者，宜胃关煎、温胃饮，或陈氏十二味异功散，送五德丸或肉豆蔻丸。若胃本不虚， \n但以寒湿伤脾，或饮水而为泄泻者，宜佐关煎、抑扶煎，或益黄散加猪苓、泽泄，或五苓散俱佳。 \n一、蓄热泄泻，本不多见而间亦有之，然必有热证可据，方可用清利之药。如脉见洪数， \n身有大热，口有大渴，喜冷恶热，烦躁多汗，或中满气粗，或痘色 肿红紫，或口鼻热赤， \n小水涩痛之类，皆热证也。且热泻者必暴而甚，寒泄者必徐而缓，皆可辨之。然治热之法，当 \n察火之微甚，勿使药过于病，恐致伤脾，则必反为害。凡湿热内蓄，小水不利，微热不甚而为泄 \n泻者，宜五苓散、四苓散，或小厘清饮之类，加木通主之。若湿热稍甚，清浊不分而泄泻者， \n宜四苓散加姜炒黄连，或合黄芩汤治之。若食多脉盛气壮而泄泻者，当从热治，宜黄芩汤加 \n黄连。若热在下焦，小水赤涩而泄泻者，宜大厘清饮，或合益元散。若湿热在脾，泄泻内热 \n而兼腹 \n痛者，宜香连丸。若颊赤身热，头痛咽疼，口疮烦躁而泄泻者，阳明火证也，宜泻黄散。若 \n湿热在脾，泻而兼呕者，黄芩汤加半夏、生姜，或《御药》大半夏汤加黄芩。若内热泄泻而兼气 \n虚者，四君子汤加芍药、黄连、木香。 \n一、发渴乃泄泻之常候，盖水泄于下，则津涸于上，故凡患泄泻者，必多口干口渴。但干 \n与渴不同，渴者欲饮，干者不欲饮，渴属阳而干属阴，此其辨也。然有渴欲饮水者，此火证也。 \n有渴欲饮汤者，此非火也。有虽欲饮水而不能多者，有口虽欲凉而胸腹畏寒者，此皆非火证也。 \n然则病渴者尚有阴阳之辨，而矧夫但干而不渴者，此实以水亏而然，若作火治，鲜不为害。故凡 \n有久泻津亡而作渴者，当审其非热而不可不壮其水也。 \n程氏曰∶泄泻须分寒热，寒者小便清，宜理中汤，或参苓白术散。然白术、茯苓非泄泻发 \n泡者不宜用，以其渗利故也。按此说可见治痘者，即渗利亦忌，顾可妄为消伐以残其气血津液乎？ \n陈氏曰∶凡泻频津耗则血气不荣，疮虽起发亦难收靥。如身温腹胀，气促切牙，烦躁谵妄 \n者皆难治，缘谷食去多，津液枯竭，故多死也，速宜与十一味木香散，或十二味异功散。 \n万氏曰∶疮未出而利者，邪并于里，实也，宜从清毒。疮已出而利者，邪达于表，里虚也， \n宜治其虚。凡痘疮所忌，惟内虚泄泻，若温之固之而不愈者，此不治之证。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>寒战切牙（四十四）\n\n属性：寒战者，阳中之气虚也，阳气虚则阴乘之，阳不胜阴，故寒栗而战也。切牙者阴中之气 \n虚也，阴气虚者肾元惫，骨气消索，故切齿而鸣也。总之，虚在气分，则无非阴盛阳虚之 \n病耳，非大加温补不可也。 \n《心鉴》云∶七日前见寒战者，表虚也；切牙者，内虚也。七日后见寒战者，气虚极也； \n切牙者，血虚极也。气虚者，保元汤倍加肉桂以温阳分。血虚者，保元汤加芎、归以益 \n阴分。余常用六气煎，或六物煎加桂附治之，无不应手而止。其有独寒战、独切牙者，亦一 \n体治之，或合二仙散用之亦妙。 \n一、有寒邪在表，身体大热，脉紧数无汗，邪正相争而为战栗者，此即似疟之类，但散 \n其邪而战自止，宜柴葛桂枝汤之类主之。 \n一、痘疮灰白溃烂，泄泻而寒战切牙者，此纯阴无阳之证，宜九味异功煎，或陈氏十二 \n味异功散亦可。 \n一、痘色干紫黑陷，大小便不通，烦躁大渴而寒战切牙者，此纯阳无阴，火极似水之证 \n也，宜双解散。 \n一、养浆结靥之时，有红紫 肿，大小便秘，烦渴喜水者，乃表里俱热之证，以疮痛而振摇 \n忍痛而切牙也。此非寒战切牙之属。如热甚而便秘者，宜四顺清凉饮加连翘、木通、金银花之 \n类主之。 \n一、筋惕肉 似战者，以经络血气为疮所耗，不能荣养肌肉，主持筋脉，故惕惕然肌肉"}, {"n": 25, "text": "卷二十五\n\n自跳， 然肌肉自动，本非寒战之证也，宜十全大补汤之类主之。 \n陈氏曰∶切牙者，齿槁也，乃血气不荣，不可妄作热治。 \n一、寒战切牙而气喘谵妄，闷乱足冷者，非倒陷即倒靥也，不治。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>烦躁（四十五）\n\n属性：烦者，扰扰而烦，躁者，烦剧而躁，合言之，则烦躁皆热也，分言之则烦在阳分，躁在 \n阴分，烦浅而躁深也。《难知集》曰∶火入于肺，烦也。火入于肾，躁也。痘疹烦躁，大非 \n所宜，若吐利厥逆，腹胀喘促，谵妄狂乱，昏不知人而烦躁者，谓之闷乱，乃不治之证。 \n一、痘疮以安静为贵，若忽然烦躁多哭，切须详审其故。如别无逆证而忽然若此，是必疮 \n痛而然，待脓成则痛止而烦亦止矣，不必治之。其或饮食寒热偶有所因而致然者，但当随 \n证调理之，则无不即安者。 \n一、痘疮烦躁兼喘者，火毒在肺也，宜人参白虎汤加栀子仁。 \n一、烦躁多惊者，火在心经也，宜导赤散加栀子、麦门冬，或七味安神丸。 \n一、痘毒未透，热伏于内而烦躁者，宜六味消毒饮，或兼万氏夺命丹。 \n一、热甚于内而烦渴热躁者，宜导赤散，或玄参地黄汤加木通、麦门冬，或万氏牛黄清心丸， \n或四味消毒饮。 \n一、邪毒未解，热甚于表而烦躁者，宜柴胡麦门冬散，或羌活汤。 \n一、痘疮红紫干燥，壮热口渴，谵妄者，退火丹，或万氏牛黄清心丸，或用《良方》犀角地 \n黄汤。 \n一、阴虚假热，自利烦躁者，肝肾水亏也，轻则五阴煎，甚则九味异功煎，或陈氏十二味 \n异功散。 \n一、吐利不食而烦躁者，脾气虚也，轻则保元汤、温胃饮，甚则九味异功煎，或陈氏十二味 \n异功散。 \n一、疮密脓成，营血亏耗，心烦不得眠者，宜三阴煎加麦门冬。如有微火者，宜酸枣仁汤。 \n一、昼则烦躁，夜则安静。此阳邪盛于阳分也，宜人参白虎汤，或加栀子。如昼则安静， \n夜则烦躁者，此阴中之阳虚也，宜三阴煎。如有火邪，亦可加栀子仁。 \n一、大便干结不通而烦躁腹胀者，四顺清凉饮、当归丸，甚则承气汤。若大便秘结，痘疮 \n陷伏而烦躁者，百祥丸或承气汤。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>喘急（四十六）\n\n属性：喘与气促不同，喘者气粗而壅，壅而急，喘为肺邪有余也；促者气促而短，上下不相接续， \n促为肺肾不足也。此二者一实一虚，反如冰炭，若或误治，无不死也，当详辨之。 \n一、寒邪在肺作喘者，此外感之证，必咳嗽多痰，或鼻塞，或身有微热，或胸满不清，治当 \n疏散肺邪，宜六安煎，或二陈汤加苏叶主之。若寒邪外闭之甚者，仍宜加麻黄、北细辛之类。 \n若兼气血不足，而风寒在肺作喘者，惟金水六君煎为最。 \n一、痰因火动而为喘急者，当以清痰降火为主。若痰涎上壅者，先治其痰，宜抱龙丸、清 \n膈煎之类主之。 \n若火上刑肺，肺热叶举，大热大喘者，宜人参石膏汤。若微热作渴，肺燥液衰而喘者，宜人参 \n麦门冬散。若夏月热甚，火犯肺金而喘者，仲景竹叶石膏汤，或六味竹叶石膏汤。若火伏三焦， \n肺胃大肠俱热，胸腹胀，大便秘结而喘者，前胡枳壳汤。 \n一、喘以气虚者，人多不能知之。凡下泻而上喘者，必虚喘也。凡小儿喘息，觉在鼻尖 \n而气不长者，必虚喘也，此实气促，原非气喘。若见此证，急须速补脾肺，或救肾阴，轻则参 \n姜饮、六气煎，甚则六味回阳饮。若下为泄泻而上为喘促者，急用六味回阳饮，或九味异功 \n煎，不可疑也。若大便不泻，而或为多汗，或为腹膨，或见痰饮、狂躁，但以阴虚水亏， \n气短似喘，而脉气无神者，急宜贞元饮加人参煨姜之类主之。若治喘促用清痰降火等剂而愈甚 \n者，此必虚证也，速宜改用温补如前诸法，犹有可救，迟则恐无及矣。 \n一、痘疹发喘，乃恶候也，若利止喘定者生，其有泻利不止，或加胀满，或为狂躁，或 \n痘毒入肺，口张息肩，目闭足冷而喘甚者，皆不治之证。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>声音（四十七）\n\n属性：痘疮最要声音清亮，若卒有失音者，凶兆也。先哲云∶疮已出而声不变者，形病也，其病轻。 \n疮未出而声先变者，气病也，其病甚。疮出而声不出者，形气俱病也。凡此失音之证，大为 \n痘疮所忌，然亦有吉有凶，须当详辨治之。 \n一、风寒外袭皮毛，壅闭肺窍，或致咳嗽而偶为失音者，此惟外感之证，宜解散之， \n以加减参苏饮，或六安煎加薄荷、桔梗主之。或待风寒解散，其声自出，此固无足虑也。 \n一、火邪上炎，肺金受制，气道壅闭而声不出者，宜导赤散合甘桔汤加炒牛蒡子主之，或 \n用甘桔清金散。 \n一、上焦阳虚而声音低小不出者，此心肺不足之病。盖心主血，肺主气，痘疮稠密则血 \n气俱损，故声不能出，宜六物煎加麦门冬，或导赤通气散主之。 \n一、下焦阴虚而声不出者，其病在肝肾。盖肾为声音之根，若证由肝肾而痘疮稠密，则 \n精血俱为耗竭，水亏则肺涸，故声不能出，速当滋阴益水以救其本，宜大补元煎、五福饮， \n或十全大补汤之类，酌宜用之。 \n一、凡啼哭无声而但见泪出，语言无声而但见口动者，此皆毒瓦斯归肾而内败也。或声 \n哑如破如梗者，此咽喉溃烂也，皆难治之证。 \n一、痘后余毒失音，其证有二∶一以咽痛不能言者，此毒瓦斯不净也，宜甘桔清金散加天 \n花粉。一以肾气虚不能上达而声不出者，宜治如前，或用四物汤加麦门冬、白茯苓。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>惊搐（四十八）\n\n属性：惊者，忽然惊惕而手足搐搦，口眼歪斜，每多忽作忽止，其证多由风热。盖心主火 \n而恶热，肝主风而善动，惊痘之火，内生于心，心移热于肝，风火相搏，故发惊搐。然未出之 \n先发惊搐者多吉，既出之后发惊搐者多凶。何也？盖痘毒将散而溪谷开张，窍理疏解，因致牵 \n引伸缩，得疏散达之气，痘出而惊自止，则其内毒无留于此可见，故俗名惊痘，最为吉也。若 \n既出之后，则中之伏火亦宜散矣，倘仍见惊搐，则是外毒已出而内毒犹然未尽，此其毒盛莫测， \n乃可畏也。故凡发惊搐者，必随发随止者为吉，不必治也。苦连发不已，此毒伏于心肝二 \n脏，速宜随证治之，不得误以为吉证。 \n一、治惊搐之法，最当察其虚实，酌其微甚。如果有风热实邪，庶可解毒清火，但 \n得稍见清楚，盒饭培养心脾以防虚败之患。若止见微邪，则但当以调和气血为主。 \n一、惊搐证由风热相搏，故治宜平肝利小便。盖平肝则风去，利小便则热除，风热既平， \n惊自愈矣。若过用寒凉，则气敛而毒反陷伏，痘出不透，多致不救。 \n一、心脾阳气虚寒则神怯而易为惊搐，六气煎加枣仁、朱砂。 \n一、心脾血虚而惊搐者，七福饮、养心汤。 \n一、肝胆气虚，多恐畏而惊搐者，茯神汤。 \n一、心血虚，睡中惊搐，或兼微痰者，《秘旨》安毒丸。 \n一、心虚火盛，多热躁而惊搐者，宁神汤、酸枣仁汤。 \n一、痘既出，其色红紫而烦渴惊搐者，《良方》犀角地黄汤。若烦热之甚而大便干涩 \n者，多由阳明之火，人参石膏汤加朱砂。 \n一、心火独盛而烦热惊搐者，朱砂安神丸，或七味安神丸。 \n一、心火盛，小水不利而惊搐者，导赤散加黄连、朱砂，或合朱砂益元散。 \n一、痰涎壅盛，气急胸满而惊搐者，抱龙丸、清膈煎，或梅花饮、琥珀散。此宜暂用以 \n开痰涎，但得痰气稍清，即当酌虚实以调理血气。 \n一、肝胆实热，大便秘结而烦躁惊搐者，泻青丸，或七味龙胆泻肝汤。 \n一、血热见血而惊搐者，《局方》犀角地黄汤。热甚者，《良方》犀角地黄汤。若热甚 \n而大便秘结者，《拔萃》犀角地黄汤。 \n一、风寒外感，心脾阳虚而微热不退，或咳嗽恶寒而惊搐者，惺惺散。若虚在阴分， \n汗不能出，身热不退而惊搐者，柴归饮。若外有风邪，内有热邪，表里俱热而惊搐者，生犀散。 \n一、风寒外感，身热无汗，但有表邪，别无虚证而惊搐者，败毒散或苏葛汤。寒邪闭甚 \n者，红棉散。然此皆表散之剂，若兼虚邪，不得单用此类。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>昏睡（四十九）\n\n属性：凡痘疮将出未出而猝然昏睡者，其痘必重，当察其脉证虚实，预为治之。若痘后喜睡， \n此毒瓦斯已解，元气将复，故邪退而神安，乃否极泰来之象，不须服药妄治。如见寂然气虚， \n但以调元汤、保元汤、六物煎之类，察其寒热，渐以调之，自然平复，不可妄行消耗，致伤 \n其神，反必害矣。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>腰痛（五十）\n\n属性：经曰∶腰者肾之府。又曰∶太阳所至为腰痛。盖足太阳之脉，夹脊络肾，而痘疮之毒， \n多出于肾，循足太阳膀胱散行诸经，乃邪之由里传表也。如初见热而腰即痛，或日以渐甚者， \n此邪由膀胱直入于肾，而毒有不能达也，急宜解毒，以泄少阴之邪，以通太阳之经，务令邪 \n气不得深入，则痘虽稠密，亦可愈也。若不速治，则邪必日陷而表里俱甚，营卫之脉不行， \n脏腑之气皆绝，或为痒 ，成为黑陷，终莫能救矣。 \n一、凡痘毒自阴传阳，自里传外者为顺，自上传下，自外传里者为逆。若毒由太阳传入少 \n阴，则毒陷而不升，伏于骨髓之中，不能外达，所以腰痛。大凡疮疹之毒，归肾则死。故但见 \n腰痛，急宜治疗，若毒陷不起，即宜发散解毒，令其复出太阳而达乎阳道，斯无害也，宜人参 \n败毒散，或五积散主之。若肾气虚陷，不能传送外达者，必用理阴煎加细辛、官桂、杜仲、 \n独活之类主之。 \n一、治发热便见腰痛者，以热麻油按痛处揉之可止，仍急服前药之类。如小水不利者，宜 \n五苓散；如火毒内盛而小水不利者，宜四苓散加栀子、木通。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>腹痛（五十一）\n\n属性：治腹痛证当以可按拒按，及宜饱宜饥，辨其虚实，不得谓痛无补法，而悉行消伐也。又 \n当因脉因证，辨其寒热，不得妄用寒凉也。大都寒滞者十居八九，热郁者间或有之，若虚不知 \n补而寒因寒用，则害莫甚矣。 \n一、初见发热，痘疮未出，别无寒滞食滞而腹满腹痛者，此必起发不透，痘毒内攻而然， \n宜解表疏里，以化毒汤加紫苏、浓朴之类主之，或五积散加木香亦可。若大便不远，腹胀而 \n作痛者，桂枝大黄汤酌宜用之。 \n一、寒气犯胃，或食生冷而呕恶吐泻，腹无服满而但有疼痛者，温胃饮、理中汤加肉桂、 \n木香，或小建中汤，随宜用之。若胃气虚寒作痛而喜按者，黄 建中汤。 \n一、寒犯中焦，气滞作胀，而腹痛或泄泻者，和胃饮，或抑扶煎加丁香、木香，或陈氏十 \n一味木香散。 \n一、脾肾虚寒，下腹作痛，泻利不止者，胃关煎。 \n一、误饮冷水凉茶，寒湿留中，小水不利而腹痛者，五苓散或加木香，或用小建中汤。 \n一、饮食停滞，中满作痛者，大、小和中饮，或保和丸加木香、砂仁。若大便不通而痛 \n甚者，赤金豆或承气汤利之。 \n一、发热二、三日后，大便不通，燥粪留滞而腹痛者，当归丸，或用猪胆导法。 \n一、湿热下利，烦热大渴，小水热涩而腹痛者，大、小厘清饮，或黄芩汤加木香、青皮、 \n砂仁。 \n一、火毒内攻，谵妄狂乱而烦热腹痛者，退火丹，或朱砂益元散。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>腹胀（五十二）\n\n属性：痘疮腹胀之证，其要有二∶一以脾胃受伤，一以邪气陷伏。盖痘疮将发，毒由内生， \n其证无不发热或见微渴，此其常也。当此之时，只宜温平和解，或兼托散，怃抑遏，无穷追， \n无残及元气，惟贵轻扬善导，但令毒透肌表，则苗秀而实，无不善矣。设不知此，而见热即退热， \n见毒即攻毒，则未有妄用寒凉而不伤胃气者，未有但知攻毒而不伤元气者。胃气伤则营运无力 \n而脾寒，所以作胀，元气伤则托送无力而毒陷，所以作胀。虽作胀之由，犹不止此，然惟此最 \n多，而人多不能察也。诸未尽者，俱详如下。 \n一、误服凉药或过食生冷而作胀者，其人必不能食，或大小便利，或腹中雷鸣，此皆脾胃 \n中寒之证，速宜温中以疏逐冷气，冷气散则胀自消矣，宜益黄散加姜制浓朴，或人参胃爱散 \n加干姜。若胃寒兼虚，疮白神倦，或气促发厥者，惟温胃饮及陈氏十一味木香散俱为要药。 \n若寒在脾肾，下焦不化而作胀者，非理阴煎不可。 \n一、中气本虚，或过用消伐，以致元气无力，不能托送痘毒而陷伏作胀者，宜十宣散， \n或合二妙散或神香散。 \n一、痘毒陷伏于里者，必有热证相杂，如烦躁干渴，大小便秘而作胀者，此只宜温平快气兼 \n托之剂，当用紫草饮子。 \n一、寒邪外闭肌腠，身热无汗，或气喘鼻塞，则痘毒不能外达而陷伏腹胀者，宜五积散， \n或加减参苏饮。 \n一、饮食过伤，偶为停滞而腹胀者，此不过一时之滞，食去则胀消，宜大和中饮，或合二妙 \n散、神香散。 \n一、腹胀而目闭，口中如烂肉臭，或大便泄泻，或利脓血者，皆不治。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>厥逆（五十三）\n\n属性：厥逆者，四肢不温，或甚至于冷也。四肢为诸阳之本，故常宜和暖，若至厥逆，则其阳虚 \n可知。如指尖微寒者，亦阳气衰也。足心冷者，乃阴邪胜也。其有疮头焦黑，烦渴闷顿，大 \n便热结而厥逆者，此阳毒内陷，火极似水，所谓热深厥亦深也。又有疮本灰白，大便不结 \n而厥逆者，此元气虚惫，阳衰而寒也。凡痘疹之候，头常欲凉，足常欲温，若头温足冷者多不 \n治，故厥逆为疮家恶候。 \n一、痘疹十指微寒者，即宜五君子煎、六气煎，或六物煎加姜、桂温之，以防虚寒之变。 \n一、痘疹泻利，气虚而逆者，胃关煎，或陈氏十二味异功散。 \n一、痘疮始出，手足便冷，或其人先有吐利，致伤脾胃，脾胃气虚则为厥逆，宜六气煎、 \n六物煎加姜、桂主之，甚者人参附子理阴煎。 \n一、痘疮起胀之时，手足厥逆，此阳气欲绝之候，必其自利或呕吐，脉见沉细微弱，或 \n浮大而虚，速宜温补元阳，轻则六气煎加肉桂，甚则六味回阳饮，或九味异功煎。服药后手足 \n和暖者生，厥不止者死。 \n一、热毒内甚而厥者，必有烦热便秘，胀满脉滑等证，宜四顺清凉饮，或承气汤。 \n一、痘后厥逆者，此其气血已虚，脾胃已困，无怪其有厥也，宜保元汤或六气煎、六物煎 \n加附、桂之类主之。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>发渴（五十四）\n\n属性：痘疹发渴者，里热也。以火起于内，销烁真阴，所以发渴。又其津液外泄，化马脓浆， \n则营气虚耗，亦以致渴。此痘疮之常候也，若微渴不甚，不必治之。惟大渴者，乃由火盛， \n然亦须察其虚实以为调理，切不可因其作渴，即以西瓜、梨、柿之类，轻以与之，恐脾 \n肺受寒，致生他患也。外有干渴，论在泄泻条中，所当参阅。 \n痘疮气血内耗，微热微渴而喜汤者，宜七味白术散，或五福饮加麦门冬、五味子。 \n一、脾肺多热，渴而喜冷者，宜人参麦门冬散，或生脉散。 \n一、痘疮多热多躁，口燥咽干，大渴引饮，喜冷能食，或大便干结者，此热在肺胃二经， \n宜人参白虎汤，甚者再加黄连。若痘后热渴者，此余火未清也，其治亦然。 \n一、痘疮自利不止，肾阴亏损而作渴者，病作少阴，速宜陈氏十二味异功散，或九味异功煎。 \n一、大便秘结，腹满烦热，内火不清而作渴者，四顺清凉饮。 \n一、痘疮发热时，便见大渴，唇焦舌燥，此心火太炎，肾水不升，故血液枯耗也，急宜解之 \n，苡葛根解毒汤。 \n程氏曰∶痘疮初发之源，乃壬癸水也，水既流出，其源必竭，奚不作渴？由此观之，可见治 \n渴者，必不可不滋肾水。 \n薛氏曰∶凡渴欲饮水者，当审其热之虚实，若属虚热，虽欲水而不多饮，当用七味白术散； \n若系实热，索水喜饮者，当以犀角磨水服，其后亦无余毒之患。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>失血（五十五）\n\n属性：经曰∶阳络伤则血外溢，阴络伤则血内溢。血外溢则衄血，血内溢则便血。疮疹之火由内而发， \n毒不能 \n达，则燔灼经络而迫血妄行，血随火动，从上而出，则为衄为吐，从下而出，则为便为溺， \n阴阳俱伤，则上下俱出。凡痘疹失血，若从鼻出者，则有阳明外达之意，尚可望生，若从他处， \n则总属阴分而火毒内陷，乃悉为危证。 \n一、痘疹发热见血者，多属火证。若衄血者，宜玄参地黄汤，或加茅根汁，或加京墨汁同 \n饮之。衄止者生，不止者不治。溺血者，大厘清饮，或八正散。大便秘而见血者，宜四顺清凉饮。 \n一、痘疮已出未出之间，凡诸血证，俱宜用犀角地黄汤三方酌宜治之最佳。血止后，可进调元 \n汤加木通。 \n一、痘疮十日之后，忽脓血大作，大便陡出者，此为胃烂不治。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>发泡（五十六）\n\n属性：痘疮发泡亦与黑陷相类，虽一以外出，一以外入，形有不同，而邪气留结，毒则一也。或 \n发水泡，或发血泡，或赤或紫或黑，但见此证，十无一生。然亦有似泡而实非者，不可不辨。或 \n其人身上原有破伤，或疮疖未痊，或虽痊而瘢痕尚嫩，一旦痘出，则疮瘢四围痘必簇，此 \n物从其类之理也。因疮作泡，则其腐败皮肉，气色本异，宜与完肤有别，不得即认为紫黑泡也。 \n至若治泡之法，先以针刺破，吮去恶血，后用胭脂汁涂法，又用百花膏敷之。此疮极易作痒， \n起发之后，宜常用茵陈熏法熏之，勿令抓伤。若不慎之，则反复灌烂，淹延不愈，变为疳蚀坏 \n疮，以致不治者多矣。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>溃烂（五十七）\n\n属性：痘疮脓熟或微有溃烂者，亦常候也。惟于未成脓之先即有溃者，此名斑烂；有当靥不靥而 \n身多破烂不收者，此名溃烂。良由未出之先，当发散而不发散，则热毒内藏，必溃烂而兼喘 \n促闷乱，或不当发散而误发散，则 \n表虚毒滥亦致遍身溃烂，此皆不善表之故也。又有阳毒内炽，火盛脉实，便结喜冷而失于清利， \n以致阳明蓄热，肌肉溃烂者，此不善解毒之故也。故治此之怯，表热者仍宜清理火邪，表虚者 \n即宜补养营卫。且脾主肌肉，尤宜调脾进食，务令大便得，所以生肌解毒。但解毒不至于过冷， \n调养不至于太热，必得中和，方为良法。 \n一、表虚不收者，必其卫气不足，别无热证，宜十全大补汤之类，或去肉桂，加防风、荆 \n芥穗，多服自愈。 \n一、火盛胃热溃烂者，宜大连翘饮之类；若大便秘者，以猪胆导之。 \n一、痘疮或发表太过，或清解过当，以致表里俱虚，阳气不守，则内为泄泻，外为溃烂， \n急当救里，宜陈氏十二味异功散，或九味异功煎。 \n一、溃烂脓水淋漓者，以败草散，或荞麦散衬之。若斑烂作脓痛甚者，以天水散和百花膏 \n敷之。 \n一、痘疮衣以浓绵，围以浓被，或向火偎抱，或任其饮酒，未七日而靥，日期未足， \n其收太急，以致自面至腰溃烂平 不作痂者，盖此非正靥，乃倒靥也，急宜解去衣被，勿近火， \n勿饮酒。因立一方，用黄 、白芷以排脓，防风、蝉蜕以疏表，青皮、桔梗以和中，牛蒡子、甘 \n草以解毒。服后溃疮复胀，则中外毒瓦斯俱得无留，而渐可收矣。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>多汗（五十八）\n\n属性：痘疹自汗者，以阴中之火自里及表，达于卫气，故皮肤为之缓，腠理为之疏，津液流行， \n故多自汗，但得痘疹身常潮润，实为美证。此乃阴阳气和，血脉通畅，盖热随汗减，毒随汗散， \n邪不能留，则易出易解，虽见热甚，而汗出之后身必清凉，此即毒之消散也，不必治之。 \n然只宜微汗不宜大汗，若汗出过多，则阳气泄而卫气弱，恐致难救难靥，或为痒 寒战之患， \n此则速宜固表以敛其汗也。又有汗出不止，其热反甚者，此邪热在表，阴为阳扰之患，速宜清 \n火解毒，阳邪退而汗自敛也。若汗出如油，或发润如洗而喘不休者，此肺脱之证，不可治。 \n一、别无邪热，但以卫气虚，肌表不固而多汗者，调元汤倍加黄 ，或白术散。 \n一、脾虚于中，卫虚于外，肌肉无主，别无他证而汗不敛者，人参建中汤。 \n一、心气虚，神怯多惊而汗不固者，团参散。 \n一、或吐或泻，气脱于中，阳脱于外，而汗出不收，微者五福饮加炮姜、枣仁。甚至手足 \n厥冷，或呕恶不止而汗不收者，速宜人参理阴煎，或六味回阳饮，迟则恐致不救。 \n一、阴中火盛，或身有大热而汗多不收者，当归六黄汤。 \n一、睡中汗出不收者，以阳入阴中，而阴不能静也，当归六黄汤。 \n一、阳明热盛，火邪燔灼肌肉，或身热烦渴，或二便热涩而汗不收者，人参白虎汤，或 \n加黄连。 \n一、收靥痂脱之后，自汗不止者，此邪去而气虚也，宜十全大补汤，或调止汗散，或以滑 \n石粉扑之。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>夹疹（五十九）\n\n属性：痘疮止宜单出，若与疹并出者，谓之夹疹。盖痘、疹之发，皆有时气，而二者并见，其毒必 \n甚。《心鉴》曰∶夹疹者，即痘之两感证也，大为不顺之候。若痘本稀少而夹疹者，名为麻 \n夹痘，其证则轻；若痘本稠密而更加以疹，彼此相混，些碎莫辨，其证则凶。急宜以辛凉 \n之剂解散为先，而托里次之。但得疹毒渐消，痘见垒落者，乃为可治。若痘疹相杂，毒不少 \n减者，必危无疑。 \n一、治夹疹之法，先当察痘之稀密，疹之微甚。若疹轻热微者，但当以痘为主，痘获吉而 \n疹无虑也。若疹多热甚者，即当急解疹毒，务令疹散而后痘可保也。 \n一、痘疮初出，内有细密如蚕子者，即夹疹证也。若痘稀疹多者，宜但解疹毒为主。如表 \n邪不解，外热甚，内火不甚而夹疹者，宜疏邪饮、升麻葛根汤、荆防败毒散，或十味羌活散。 \n如表里俱热，毒盛而夹疹者，柴葛 \n煎、解毒防风汤、或十三味羌活散。如内热毒盛而夹疹者，六味消毒饮，或合黄连解毒汤。如阳明火盛，多热 \n多渴，或烦躁而夹疹者，白虎汤、化斑汤，或葛根麦门冬散。 \n以上诸治如法，而疹散痘出者可治然后随证调。 \n理之。若疹不散毒不解者难治。 \n一、痘疹俱多者，毒必大盛，虽治得其法，疹毒已解，亦必气血重伤，终难为力。凡遇此者， \n惟当以保养脾胃，调和气血为主，庶克有济。 \n一、收靥后复出疹者，此余毒解散之兆，不必治之。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>夹斑（六十）\n\n属性：痘疹夹斑与夹疹不同，盖疹则细碎有形，斑则成片无形也。凡痘疮初出，有片片红肿如绵 \n纹者，有红晕与地皮相平而全无兴起之意者，是皆夹斑证也。斑以热毒郁于血分，而浮于肌肉 \n之间，乃足阳明胃经所主，或以寒邪陷入阳明，郁而成热者，亦致发斑，俱宜凉血解毒，但使 \n斑退而痘见者吉，否则皮肤斑烂，疮易搔痒，而皮嫩易破也。又有赤斑成块，其肉浮肿结 \n硬者，乃名丹瘤，其毒尤其，疮未成就，此必先溃，不可治也。 \n一、治斑之法，大抵斑在起发之前者多用表散，在灌脓之后者多用解利。如遍身通红者， \n其治亦同。 \n一、痘出夹斑轻者，只以升麻葛根汤加石膏、玄参，甚者宜人参白虎汤合六味消毒饮。 \n一、风寒外感，表邪不解而夹斑者，宜荆防败毒散，或加石膏、玄参。 \n一、斑色紫赤而大便秘结者，宜四顺清凉饮利之。斑既已退，即宜用四君子之类以固 \n其脾，庶可免其内陷。 \n程氏曰∶凡治夹斑，急宜凉血解毒，以羌活散加酒炒芍药、紫草、红花、蝉蜕、木通、 \n官桂、糯米，连进数服。斑退后，以保元汤加木香、豆蔻煎服，以解紫草之寒，防其泄泻。如 \n痘中夹疹，治亦同此，如稍迟则恐变成黑斑，为难治矣。 \n一、痘疮结痂之后而见斑者，此余毒煎熬血分，必致溃烂，宜黄连解毒汤加当归、芍药、 \n黄芩、石膏，甚则大连翘饮。若热毒熏蒸于内，大便脓血臭秽而见斑者，此胃烂之证，不可治。 \n一、发斑溃烂者，以救苦灭瘢散敷之。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>昼夜啼哭（六十一）\n\n属性：凡小儿出痘而昼夜啼哭者，当辨其虚实表里而治之。其有内未得出，或外未得散而啼哭者， \n此毒瓦斯不解之使然也。有阳邪火盛，红赤 突而啼哭者，此痘盘疼痛之使然也。有心肾本虚，邪 \n热乘阴而啼哭者，此或以神志不摄，或以烦热不宁之使然也。有饮食不节，或偶停滞而啼哭者， \n此胃气不和，腹痛腹胀之使然也。知此之由，而辨得其真，则内未出者表之托之，外未散者 \n解之化之，火之盛者清其热，神之虚者养其阴。若痘毒本微而无故啼哭者，多由饮食内伤，或二便 \n秘结，此或去其停滞，或通其壅闭，务令表里和畅，营卫通行，则神魂安泰，而痘无不善矣。 \n或谓啼哭非痰即热，而不究其本，则失之远矣。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>大小便闭（六十二）\n\n属性：凡痘疹小便欲其清而长，大便欲其润而实，则邪气不伏，正气不病。若小便利者，大便必实， \n虽二三日不更衣者无碍也。若小便少则病必进，小便秘则病必甚，以火盛故也。但初热时，大 \n便不宜太实，若二三日不行，宜微润之，不然恐肠胃不通，则营卫不行，而疮出转密。惟起发 \n之后，大便却宜坚实，若太实而四五日不行，恐热甚难靥，亦宜微利之。 \n一、痘疹小水不利而热微者，宜导赤散；热甚而小水不利者，宜八正散。 \n一、痘疹发热时，大便秘结不行而内外俱热，有不得不通以疏其毒者，轻则柴胡饮子，甚则三 \n黄丸，再甚则承气汤。 \n一、自起发后以至收靥，凡大便不行而火不盛，或虚弱不可通利者，只宜用猪胆导法， \n或以酱瓜一条如指许导之即出，切不可轻用利药。 \n一、大小便俱不通而内热甚者，八正散或通关散，酌宜用之。 \n一、热毒内盛而痘疮干黑倒陷，烦躁便结者，百祥丸或承气汤。然宜慎用，毋轻易也。 \n一、痘后余热不尽，内陷膀胱而小水不利者，导赤散或五苓散。大便不通者，四顺清凉饮。 \n陈氏曰∶凡痘疮四五日不大便，用嫩猪脂一块，以白水煮熟，切如豆粒与食之，令脏腑 \n滋润，亦使疮痂易落。切不可妄投宣泄之药，以致元气内虚，多伤儿也。 \n薛氏曰∶前证若因热毒内蕴，宜用射干鼠粘子汤解之。或发热作渴，或口舌生疮，咽喉作 \n痛，并宜用之。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>目证（六十三）\n\n属性：目虽肝之窍，而实五脏六腑之精气皆上注于目，故其赤脉属心，瞳子属肾，白珠属肺， \n黑珠属肝，裹约属脾。又太阳为上网，阳明为下网，少阴循外 ，太阳出内 ，此其部分各 \n有所主，故可因证以察其本也。然痘疮之病目而为障为翳者，多由火炎于内而热以生风，风 \n热散于诸经，因多红赤肿痛之患。故治此者，亦当察其所属而因证以调之也。 \n一、戴眼证，凡痘疮灌脓之后，或大汗大泻之后，多有目睛上吊，或露白者，谓之戴眼。 \n此精气为脓血汗液所耗，乃太阳少阴真阴亏竭大虚之证。盖太阳为上网，血枯则筋急，所以上吊 \n也，速宜大补气血，以六物煎、六气煎，或十全大补汤之类主之。其有以此为风热而散之解 \n之者，是皆速其死也。若七日以前见此者多不治，或无魂失志，不省人事者亦不治。 \n一、痘疮目赤肿痛翳障等证，无不谓之风热，故古方亦多用清火散风等剂。夫痘疮之火由中 \n生，目为肝窍，肝主风木而病在目，故云风热，实以风生于火由内热也。所以凡治目赤目 \n痛者，不必治风，但治其火，火去则风自息矣。何也？盖内生之风与外感之风不同，外感 \n之风，升之散之则解散而去，内生之风而再加升散，则火愈炽而热愈高矣。常见治目多难救而 \n寒凉反以伤脾者，正以升降相杂，而用药有不精耳。经曰∶高者抑之，果 \n何谓乎。今如古方之治火眼，凡用洗肝散，及洗肝明目散、芍药清肝散之类，总不如《良方》 \n龙胆泻肝汤，而《良方》泻肝汤又不如加味龙胆泻肝汤之为得宜也。 \n一、痘疮眼中流浪赤痛，或多眼眵，此肝火之盛也，宜清解之，以加味龙胆泻肝汤或抽 \n薪饮，加木贼、蝉蜕之类主之；若大便结闭不通者，亦可少加大黄。 \n一、痘疮入眼肿痛，或痘后生翳膜者，宜蒺藜散、蝉菊散，或通神散，外以秦皮散洗之。 \n一、痘疮目病，热少风多而昏暗涩痛，眵泪羞明翳障者，宜密蒙花散，亦以秦皮散洗之。 \n一、痘后眼闭泪出不敢见明者，此内火不清而阳光烁之，故畏明也，宜洗肝明目散。 \n一、痘后眼皮风毒赤烂，或痛或痒，燥涩羞明多眵泪者，秦皮散洗之。 \n一、痘疮靥后，精血俱耗，而眼涩羞明，光短倦开，或生翳障者，宜四物汤，甚者六 \n物煎加木贼、蝉蜕、白蒺藜。 \n一、痘斑入眼，在白珠上者不必治，久当自去，惟在黑珠上宜治之，当清肝火。 \n一、凡病目热者，最宜忌酒及椒、姜、牛、羊、鸡、鹅、鸭一应热物，并鸡鹅鸭蛋皆 \n不可用，以防连绵不愈之患。 \n一、痘疮热毒伤目，凡必用之药，如生地、芍药、麦门冬、山栀、玄参、草决明、连翘、 \n黄芩、黄运，肝热者龙胆草，阳明实热者石膏、石斛，肾火盛者黄柏、知母，三阴俱热者地骨皮， \n火浮不降者木通、泽泻，翳障不去者木贼草、蝉蜕、白蒺藜，气虚者人参、黄 ，血虚者当归、 \n熟地。但火炎于上者不宜升，阴虚于下者不宜泄，是皆治眼之大法。 \n一、痘疮护眼法，宜钱氏黄柏膏为佳，从耳前眼皮上下颧面间，日涂三四次，可以护 \n眼稀痘。 \n一、用点药者，凡目中生痘，或食发物，或热毒太盛，上蒸目窍，以致热毒或生翳障， \n切不可妄用一切点药。盖其非毒即冷，必致寒热相激，反以为害。惟余之金露散乃为相宜， \n可间用之以解热毒之急。 \n徐氏曰∶痘之毒瓦斯自里达表，故有目病，治宜活血解毒而已。活血不至热，解毒不至寒， \n但得血活毒散，则目疾自愈。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>痘痈痘毒（六十四）\n\n属性：（又痘母，见前怪痘形证） \n痘发痈毒者，亦名痘母。经曰∶痘前发母者凶，痘后发母者半吉半凶，大都毒发不透， \n必发痈疽，故蕴结于经络之间。然其壅结也犹无足虑，而惟其不能消散，及治之不得其法， \n则乃为可虑。然散之之法，当知要领，其在虚实之辨而已。如痘痈之有大毒者，不得不为解 \n毒，有大热者，不得不为清火，俟火毒略清，盒饭调理脾气。其有外虽见热而内本不足者， \n则当专用托法，务令元气完固，饮食不减，则毒无不化，何害之有？若不察根本强弱，而但 \n知攻毒清火，则无不伤脾，多致饮食日减，营气日削，脓血不化，毒日以陷，而痘变百出矣。 \n所以痘疮始末，皆当以脾气为主，苟不知此，则未有中气虚败而痘能保全者。 \n一、痘痈初起，壅盛疼痛，元气无损，饮食如常者，宜先用连翘归尾煎，或仙方活命饮 \n以解其毒，俟毒瓦斯稍平，即当用四君、归、 之类，以补托元气。 \n一、凡用托里之剂，如痈毒内无大热，亦无便闭烦渴等证，或素非强盛之质，或以阴 \n毒深陷，形不 突，不红肿，不化脓，痛有不甚者，此其毒皆在内，俱速宜用托里之药，以六 \n气煎加金银花、甘草节、防风、荆芥、白芷、穿山甲、牛蒡子之类，如阳气不足者，仍可加 \n肉桂、附子，用酒水各半煎服，或全用酒煎亦可，或托里消毒散俱可酌用。 \n一、凡内热晡热而饮食少思者，多属脾胃不足，血气虚弱，宜六气煎或温胃饮，加金银 \n花、白芷。若痈毒色白而作痒者，气虚也，治同上。若根赤而作痒者，血虚血热也，宜四 \n物汤加丹皮、白芷。若肿而不溃者，血气虚也，托里消毒散或加肉桂。若溃而不收者，脾 \n气虚也，宜六气煎或六物煎加肉桂。 \n一、凡饮食如常而内外俱热，痈毒肿痛，或烦渴，或大小便俱热涩者，宜大连翘饮，或 \n仙方活命饮，可间 \n用之。若饮食如常，内热作痛，或兼口舌生疮者，宜间用射干鼠粘子汤。 \n一、痘毒发痈，有结硬实热难解者，宜排毒散。 \n一、痘后发痈疖者，乃痘中未尽之毒，留于经铬肢节而为痈肿也，或解毒，或清火，各有 \n所宜。凡欲表里兼解者，宜柴胡麦门冬散；欲润肠解毒者，宜消毒散及四顺清凉饮；欲凉血解 \n毒者，宜犀鱼地黄汤；欲清火利便解毒者，宜大连翘饮。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>疳蚀疮（六十五）\n\n属性：陈氏曰∶凡痘疮已靥未愈之间，五脏未实，肌肉尚虚，血气未复，被风邪所搏，则津液涩 \n滞，遂成疳蚀，宜用雄黄散、绵茧散等药治之。久而不愈，则多致不起。 \n薛氏曰∶前方乃解毒杀虫之剂，若毒发于外，元气未伤者，用之多效，若元气伤损，邪 \n火上炎者，用大芜荑汤、六味丸。若赤痛者，用小柴胡汤加生地黄。若肝脾疳证，必用四味肥 \n儿丸，及人参白术散，更佐以九味芦荟丸。 \n万氏曰∶凡痘后疳蚀疮，至毒壅肌肉，内透筋骨，外连皮肤，时痛出血，日久不痊者， \n此毒在脾经，甚为恶候，乃不足之证也，内服十全大补汤，外用绵茧散贴之。疳蚀出血者，难治。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>痘药正品（六十六）\n\n属性：\\x人参\\x 益元气，生精血，复元神，补五脏。凡痘疮表散、起胀、灌浆、收靥，始终皆赖之。 \n\\x黄 \\x 固腠理，补元气，内托陷下皆用之。 \n\\x当归\\x 生血、养血，活血止血，痘疮赖以调血，凡虚者能补，滞者能行。欲其升散，当 \n佐以川芎；欲其敛附，当佐以芍药。 \n\\x熟地黄\\x 痘疹之病，形质之病也，形质之本在精血。熟地以至静之性，以至甘至浓之味， \n实精血形质中第一品纯浓之药。凡痘疮起发灌浆收敛之用，以参 配之，其功乃倍。且其得升、 \n柴则能发散，得桂、附则能回阳，得参、 则入气分，得归、芍则入血分。今见痘家、伤寒家 \n多不用此，岂亦古人之未之及耶？抑不知四物汤为何物耶？ \n\\x生地黄\\x 凉血，行血，养血，治痘疮血热血燥，凡吐血衄血，痘疮红紫，及解毒药中皆 \n宜用之。 \n\\x芍药\\x 可升可降，能清能敛，治痘疮血散不归，赖以收之使附气分。能泻肝脾之火，故 \n止腹之热痛，亦能止汗。 \n\\x川芎\\x 能升能散，能引清气上行头角，以起头面之痘；能佐参、 以行阳分而解肌表之邪， \n此可为引导通行之使。但性多辛散，凡火在上而气虚者当避之。 \n\\x白术\\x 健脾利水，燥湿温中。能补气故能发痘，能固脾故能止泻。 \n\\x甘草\\x 味甘平，得土气之正，故能补中和中而兼达四脏，佐理阴阳。惟其甘和而润，故能 \n解刚暴之毒，泻枯涸之火。 \n\\x麦门冬\\x 生津止渴，清肺滋阴，除烦热，解燥毒。痘疹阴虚而多火者宜之。 \n\\x糯米\\x 善滋脾胃，益中气，助血生浆，能制痘毒，不能内攻。 \n\\x扁豆\\x 健脾和中，养胃止呕。 \n\\x柴胡\\x 发散热邪，泻肝胆之火，解肌开表，退往来寒热。 \n\\x升麻\\x 升阳气，达肌表，散风寒，善走阳明。 \n\\x防风\\x 散风热，解表邪，举陷气，佐黄 能托里祛毒。 \n\\x干葛\\x 解肌清热，凉散表邪，故能止渴。 \n\\x荆芥穗\\x 解风热，消疮毒，利肌表，退肿清咽，亦散头目之风邪。 \n\\x白芷散\\x 风邪，逐寒湿，止头疼，除搔痒，化痈毒，善走阳明，故能起头面之痘，亦托 \n肌肉之脓。 \n\\x麻黄\\x 阴寒沉滞之邪，非此不能散，亦痘家之要药，而人多畏之，由不能察也。 \n\\x薄荷\\x 散风热，清头目，能利咽喉，亦能解毒。 \n\\x羌活散\\x 肌表之毒风，利筋骨，走经铬，故能止周身之痛。 \n\\x官桂\\x 味甘辛，能养营解表，性温热，能暖血行经。凡痘疮营卫不充而见寒滞者，必用 \n此以导达血气，且善行参、 、熟地之功。 \n\\x附子\\x 脾肾虚寒，元阳大亏，凡泄泻呕吐不能止，寒战厥逆不能除者，非此不可以益火之源。 \n\\x生姜\\x 辟恶气，散寒气，温中气，开脾胃，止呕吐之要药。若欲理中寒，止腹痛，则炮干 \n姜尤胜。 \n\\x陈皮\\x 和脾胃，达阴阳，开痰行气，和胃消胀，可降可升。 \n\\x山楂\\x 消食快胃，解利宿滞，开导六腑，无辛香之耗，故可为参、术之导引。 \n\\x木香\\x 调诸气，和胃行滞止泻，除胸腹痛，亦能温中。若气虚烦热者不宜轻用。 \n\\x丁香\\x 暖胃逐寒，顺气止呕，且除腹痛寒滞者不可少也。 \n\\x肉豆蔻\\x 固肠温中，行滞止泻，中寒滑泄者最宜之。 \n\\x茯苓\\x 利水益脾去湿热，故能止泻除烦以通津液。 \n\\x泽泻\\x 利水下行，能去湿热以消肿，亦导诸药以降火。 \n\\x木通\\x 大利小水，善泄心与小肠之火，能使痘疮湿热之毒从小便而出。凡内热毒盛者宜 \n之，若热退中虚者不可概用。 \n\\x桔梗\\x 性味轻浮，能载药上升，清火解毒，故治喉痹。 \n\\x鼠粘子\\x 性味清凉，能润肺散气，利咽退肿，欲解痘疹热毒，此不可缺。 \n\\x紫草\\x 味苦性寒，能凉血活血，制热邪，解痘毒，滑利大便。程氏曰∶大抵凡下紫草， \n必下糯米五十粒以制其 \n冷性，庶不损胃气而致泄泻，惟大热便秘者不必糯米也。 \n\\x蝉蜕\\x 散风清热疏邪气，故能解痘疮之毒风。 \n\\x僵蚕\\x 散风消痰解毒，尤利咽喉。 \n\\x穿山甲\\x 性窜而利，善通经脉，直达病所。凡痘有毒盛而郁遏不能出者，宜此达之， \n然必藉血气诸药为之主，而以此为佐引则可。 \n\\x犀角\\x 解心火及肝脾之火，凡痘中血热吐衄，及焦黑惊搐，烦躁不宁等证，皆可用之以解 \n热毒。 \n\\x蜂蜜\\x 益脾生津润燥，可结痂亦可落痂。 \n\\x朱砂\\x 镇心气，除热毒，坠痰涎，安惊悸，定神魂，凡心经痘毒，及痰火上壅有余之证， \n皆宜用之。 \n\\x琥珀\\x 安神定志，利水镇惊。 \n\\x玄参\\x 能解血中之热，清游火，滋肝肺，除痘疹之热毒。 \n\\x黄连\\x 解诸热毒，泻心肝大肠之火。 \n\\x滑石\\x 甘凉下降，利水道，清解六阳之烦热。 \n\\x石膏\\x 清肃大寒，善降阳明之火，凡属阳明实热，而为头痛目肿，口疮咽痛，身热烦渴， \n狂躁便结者，非此不能解。 \n\\x连翘\\x 清三焦浮游之火，解痘疹痈疡之毒。 \n\\x栀子\\x 利小水，降脾肺膀胱之火，使从小便中出。 \n\\x龙胆草\\x 性寒而降，大清肝肾之火，上退眼目之赤痛，下清足膝之热肿。 \n\\x黄芩\\x 性味轻浮，能清肺金大肠之火。 \n\\x大黄\\x 通壅滞，逐瘀血，退热攻坚，非有大实证，则不可轻用。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>痘家药忌（六十七）\n\n属性：人参、黄 ，皆补气助阳之剂，凡痘色白陷者宜用之，若红紫壮实者，用之则愈热而毒愈 \n炽，红紫者转为枯黑，反甚矣。 \n白术能燥湿，专补气分，亦能闭气，多用则润，气不行，痘难成浆，助阳生火，亦难收敛。 \n茯苓、猪苓、泽泻渗泄燥湿，能令水气下行，多服则津液耗散，凡阴虚于下而精血不足者当 \n避之。 \n川芎性升气散，凡气虚者不宜多用，火浮于上而头痛浮肿者忌之。 \n生地性寒，肠胃虚寒者慎之。 \n升麻提气上冲，凡下虚上实，气壅烦躁者忌之。 \n柴胡清散而润利，汗多者不宜用，脾泄者不宜多用。 \n紫草性寒利窍，多服成泄泻，脾气虚者忌之。 \n鼠粘子通肌滑窍，多服恐内损中气，外致表虚。 \n蝉蜕能开肌窍，多服恐泄元气以致表虚。 \n麻黄开窍，大泄肌表，妄用恐表虚气脱。 \n干葛，性凉解肌，多用恐致表虚。 \n枳壳，下气宽肠，多用则损中气。 \n山楂，散血解结，多则伤血陷气。 \n砂仁，散气动气，气虚者不宜用。 \n乌梅，酸敛，宜散宜行者不宜用。 \n穿山甲，锐性有余，补性不足，若任用攻毒而不以王道为之帅，则无异追穷寇而出孤 \n注，能善其终者鲜矣。 \n人牙，性烈，发表太过，若妄用之，则内动中气，外增溃烂。 \n诃子、龙骨、枯矾皆能阻塞肌窍，欲通利者宜避之。 \n大黄，耗削力雄，血气中虚者不可轻用。 \n黄连，大苦大寒，原非浓肠之物，泄泻无火者大忌之。 \n山栀、黄芩、黄柏、石膏、龙胆草、滑石、远翘、前胡、天花粉之类，皆大寒之物， \n非有实火热毒者，不得妄行滥用。 \n附子、干姜、肉桂、吴茱萸之类，性皆温热，凡烦热、紫黑、便结、毒盛者，皆不可轻用。 \n栝蒌仁开结陷气滑肠，凡虚痰虚火及中气不足，而为喘促胀满，大便不实者，皆大忌之。 \n桑虫，亦名桑蚕，不知创自何人，用以发痘，今浴医以为奇品，竞相传用。余尝遍考本草、 \n痘疹诸书，皆所不载，及审其性质，不过为阴寒湿毒之虫耳。惟其有毒，所以亦能发痘，惟其 \n寒湿，所以最能败脾。且发痘者，不从血气而从毒药，痘虽起而中则败矣，此与揠苗者何异？ \n矧以湿毒侵脾，弱稚何堪？故每见多服桑虫者，毒发则唇肤俱裂，脾败则泄泻不止，前之既 \n覆，后可鉴矣。其奈蒙蒙者，率犹长夜之不醒何？盖其但见痘之死，总未知败在虫毒也。余 \n欲呼之，用斯代柝，而并咎夫作俑者之可恨。 \n\n\n\n<目录>卷之四十五烈集·痘疹诠\\痘疮（下）\n\n<篇名>痘疮下论列方（六十八）\n\n属性：保元汤（痘一） 调元汤（痘二） \n十全大补汤（补二十） 调中汤（小三） \n五福饮（新补六） 五味异功散（补四） \n养中煎（新热四） 七福饮（新补七） \n六味异功煎（新热七） 温胃饮（新热五） \n三阴煎（新补十一） 九味异功煎（新因二二） \n胃关煎（新热九） 五阴煎（新补十三） \n六味回阳饮（新热二） 佐关煎（新热十） \n理中汤（热一） 七味白术散（小七） \n六气煎（新因二一） 理阴煎（新热三） \n人参白术散（小七） 六物煎（新因二十） \n四君子汤（补一） 参苓白术散（补五四） \n四物汤（补八） 六君子汤（补五） \n金水六君煎（新和一） 六味丸（补百二十） \n五君子煎（新热六） 人参建中汤（补二六） \n贞元饮（新补十九） 小建中汤（补二二） \n黄 建中汤（补二七） 生脉散（补五六） \n大补元煎（新补一） 人参麦门冬散（痘二三） \n胃爱散（痘十九） 酸枣仁汤（补八四） \n朱砂安神丸（寒一四二） 团参散（小十） \n大和中饮（新和七） 七味安神丸（小七二） \n参姜饮（新热八） 小和中饮（新和八） \n《秘旨》安神丸（小七一） 益黄散（和十九） \n大厘清饮（新寒五） 加减参苏饮（痘三四） \n养心汤（小五九） 小分中饮（新和十） \n升麻葛根汤（痘二六） 宁神汤（小五七） \n小柴胡汤（散十九） 柴葛桂枝汤（痘三六） \n茯神汤（小六十） 柴胡饮子（痘四二） \n柴胡麦门冬散（痘二四） 止汗散（小十一） \n大连翘饮（寒七八） 葛根麦门冬散（痘一四一） \n抑扶煎（新热十一） 紫草饮子（痘六七） \n解毒防风汤（痘五六） 苏葛汤（痘二七） \n大芜荑汤（痘五六） 前胡枳壳散（痘九四） \n柴葛煎（新因十八） 肉豆蔻丸（小五六） \n仙方活命饮（外一） 五积散（散三九） \n疏邪饮（新因十六） 连翘归尾煎（新因三二） \n柴归饮（新因十五） 败毒散（散三六） \n荆防败毒散（痘三一） 双解散（痘四一） \n羌活散（痘三八） 十味羌活散（痘三八） \n二陈汤（和一） 羌活汤（痘四十） \n十三味羌活散（痘三九） 橘皮汤（痘九二） \n白虎汤（寒二） 人参白虎汤（寒三） \n惺惺散（小二三） 化斑汤（寒三） \n人参石膏汤（寒三） 十宣散（痘十四） \n化毒汤（痘五七） 黄连解毒汤（寒一） \n和胃饮（新和五） 排毒散（痘九八） \n葛根解毒汤（痘五三） 六安煎（新和二） \n消毒散（痘四七） 托里消毒散（痘六） \n清膈煎（新寒九） 抽薪饮（新寒三） \n四味消毒饮（痘四八） 黄芩汤（寒百五） \n退火丹（痘八四） 六味消毒散（痘四九） \n生犀散（小二八） 益元散（寒百十二） \n玄参地黄汤（痘八六） 二妙散（寒一三四） \n天水散（寒百十二） 当归六黄汤（寒六五） \n泻黄散（寒五七） 导赤散（寒一二二） \n导赤通气散（痘八八） 二仙散（痘二十） \n神香散（新和二十） 五苓散（和八二） \n射干鼠粘子汤（痘七七） 五德丸（新热十八） \n四苓散（和一八七） 《御药》大半夏汤（和十一） \n保和丸（小三五） 八正散（寒百十五） \n九味芦荟丸（小百十五） 抱龙丸（小八五） \n甘桔汤（因一七五） 甘桔清金散（痘八九） \n百祥丸（痘九六） 承气汤（攻一） \n四顺清凉饮（攻二五） 万氏夺命丹（痘八二） \n赤金豆（新攻二） 桂枝大黄汤（痘四三） \n琥珀散（小八一） 三黄丸（攻六八） \n《良方》龙胆泻肝汤（寒六二） 梅花饮（小八三） \n香连丸（寒百十三） 加味龙胆泻肝汤（寒六四） \n泻青丸（寒一五一） 当归丸（痘九五） \n七味龙胆泻肝汤（寒六三） 通关散（痘八五） \n洗胆散（痘百七） 洗肝明目散（痘百六） \n通神散（痘百十二） 蒺藜散（痘百九） \n芍药清肝散（寒六一） 蝉菊散（痘百十） \n密蒙花散（因三十） 仲景竹叶石膏汤（寒五） \n秦皮散（痘百十一） 茵陈熏法（痘百十九） \n六味竹叶石膏汤（寒六） 雄黄散（痘一三三） \n胭脂涂法（痘一二五） 《局方》犀角地黄汤（寒七九） \n荞麦散（痘一二四） 败草散（痘一二六） \n《良方》犀角地黄汤（寒八十） 百花膏（痘一二三） \n黄柏膏（痘百十三） 《拔萃》犀角地黄汤（寒八一） \n红绵散（痘七二） 绵茧散（痘一三四） \n十一味木香散（痘二一） 金露散（新因四四） \n救苦灭瘢散（痘一二八） 十二味异功散（痘二二） \n万氏牛黄清心丸（小九四） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>经义（一）\n\n属性：《痈疽篇》∶黄帝曰∶血气已调，形气乃持。余已知血气之平与不平，未知痈疽之所从 \n生，成败之时，死生之期，有远近，何以度之，可得闻乎。岐伯曰∶经脉流行不止，与天同 \n度，与地合纪。故天宿失度，日月薄蚀；地经失纪，水道流溢，草 不成，五谷不殖；径路 \n不通，民不往来，巷聚邑居，则别离异处；血气犹然。请言其故∶夫血脉营卫，周流不休， \n上应星宿，下应经数。寒邪客于经络之中则血泣，血泣则不通，不通则卫气归之，不得复反 \n，故痈肿。寒气化为热，热胜则腐肉，肉腐则为脓；脓不泻则烂筋，筋烂则伤骨，骨伤则髓 \n消，不当骨空，不得泄泻，血枯空虚，则筋骨肌肉不相荣，经脉败漏，熏于五脏，脏伤故死 \n矣。黄帝曰∶愿尽闻痈疽之形，与忌曰名。岐伯曰∶痈发于嗌中，名曰猛疽。猛疽不治，化 \n为脓，脓不泻，塞咽，半日死；其化为脓者，泻则合豕膏，冷食，三日而已。发于颈，名曰 \n夭疽。其痈大以赤黑，不急治，则热气下入渊腋，前伤任脉，内熏肝肺，熏肝肺，十余日而 \n死矣。阳气大发，消脑留项，名曰脑烁。其色不乐，项痛如刺以针，烦心者，死不治。发于 \n肩及 ，名曰疵痈。其状赤黑，急治之，此令人汗出至足，不害五脏。痈发四五日，逞 \n之。发于腋下赤坚者，名曰米疽，治之以砭石，欲细而长，疏砭之，涂以豕膏，六日已 \n，勿裹之。其痈坚而不溃者，为马刀挟缨，急治之。发于胸，名曰井疽。其状如大豆，三四 \n日起，不早治，下入腹，不治，七日死矣。发于膺，名曰甘疽。色青，其状如谷实 KT ， \n常苦寒热，急治之，去其寒热，十岁死，死后出脓。发于胁，名曰败疵。败疵者，女子 \n之病也。灸之，其病大痈脓，治之，其中乃有生肉，大如赤小豆，锉FS 草根各一升 \n，以水一斗六升煮之，竭为取三升，则强饮浓衣，坐于釜上，令汗出至足已。发于股胫，名 \n曰股胫疽。其状不甚变，而痈脓搏骨，不急治，三十日死矣。发于尻，名曰锐疽。其状赤坚大 \n，急治之；不治，三十日死矣。发于股阴，名曰赤施。不急治，六十日死。在两股之内，不 \n治，十日而当死。发于膝，名曰疵痈。其状大痈，色不变，寒热，如坚石。勿石，石之者死 \n；须其柔，乃石之者，生。诸痈疽之发于节而相应者，不可治也。发于阳者，百日死。发于 \n阴者，三十日死。发于胫，名曰兔啮。其状赤至骨，急治之，不治害人也。发于内踝，名曰 \n走缓。其状痈也，色不变，数石其输，而止其寒热，不死。发于足上下，名曰四淫。其状大 \n痈，急治之，百日死。发于足傍，名曰厉痈。其状不大，初如小指。发，急治之，去其黑者 \n，不消，辄益；不治，百日死。发于足指，名脱痈。其状赤黑，死不治。不赤黑，不死，不 \n衰，急斩之，不则死矣。黄帝曰∶夫子言痈疽，何以别之。岐伯曰∶营卫稽留于经脉之中， \n则血泣而不行，不行则卫气从之而不通，壅遏而不得行，故热。大热不止，热胜则肉腐， \n腐则为脓。然不能陷，骨髓不为焦枯，五脏不为伤，故曰痈。黄帝曰∶何谓疽。岐伯曰∶ \n热气淳盛，下陷肌肤，筋髓枯，内连五脏，血气竭，当其痈下，筋骨良肉皆无余，故命曰疽 \n。疽者，上之皮夭以坚，上如牛领之皮。痈者，其皮上薄以泽，此其候也。 \n《玉版篇》∶黄帝曰∶病之生时有喜怒不测，饮食不节，阴气不足，阳气有余，营气不 \n行，乃发为痈疽。阴阳不通，两热相搏，乃化为脓，小针能取之乎。岐伯曰∶以小治小者， \n其功小，以大治大者，多害，故其已成脓血者，其唯砭石铍锋之所取也。黄帝曰∶多害者其 \n不可全乎。岐伯曰∶其在逆顺焉。以为伤者，其白眼青，黑眼小，是一逆也。内药而呕者， \n是二逆也。腹痛渴甚，是三逆也。肩项中不便，是四逆也。音嘶色脱，是五逆也。除此五者，为顺矣。 \n《寒热病篇》曰∶五脏，身有五部∶伏兔一，腓二，腓者 也，背三，五脏之 四， \n项五。此五部有痈疽者死。凡刺之害，中而不去则精泄，不中而去则致气。精泄则病甚而 ，致气则生为痈疽也。 \n《生气通天论》曰∶高梁之变，足生大疔，受如持虚。汗出见湿，乃生痤痱。劳汗当风 \n，寒薄为 ，郁乃痤。营气不从，逆于肉理，乃生痈肿。陷脉为 ，留连肉腠，因而饱食 \n，筋脉横解，肠 为痔。 \n《阴阳别论》曰∶三阳为病，发寒热，下为痈肿。 \n《脉度篇》曰∶六腑不和，则留结为痈。 \n《异法方宜论》曰∶东方之域，其民食鱼而嗜咸，其病皆为痈疡。其治，宜砭石。故砭 \n石者，亦从东方来。 \n《气穴论》曰∶肉之大会为谷，肉之小会为溪。肉分之间，溪谷之会，以行荣卫，以会 \n大气。邪溢于壅，脉热肉败，荣卫不行，必将为脓，内消骨髓，外破大 。留于节凑，必将为败，积 \n寒留舍，荣卫不居，卷肉缩筋，肋肘不得伸，内为骨痹，外为不仁，命曰不足。大寒留于溪 \n谷也。 \n《刺节真邪篇》曰∶虚邪之中人也，洒淅动形，起毫毛而发腠理。其入深，内搏于骨， \n则为骨痹；搏于筋，则为筋挛；搏于脉中，则为血闭；不通则为痈。虚邪之入于身也深，寒 \n与热相搏，久留而内着。寒胜其热，则骨疼肉枯。热胜其寒，则烂肉腐肌为脓，内伤骨，内 \n伤骨为骨蚀。有所疾前筋，筋屈而不得伸，邪气居其间而不反，发为筋溜。有所结，气归之， \n卫气留之，不得反，津液久留，合而为肠溜。久者，数岁乃成，以手按之柔，已有所结，气 \n归之，津液留之，邪气中之，凝结日以易甚，连以聚居，为昔瘤。以手按之坚，有所结，深 \n中骨，气因于骨，骨与气并，日以益大，则为骨疽。有所结，中于肉，宗气归之，邪留而不 \n去，有热则化为脓，无热则为肉疽。凡此数气者，其发无常处，而有常名也。 \n《病能论》∶黄帝问曰∶人病胃脘痈者，诊当何如。岐伯对曰∶诊此者当候胃脉，其脉 \n当沉细，沉细者气逆，逆者人迎甚盛，甚盛则热。人迎者胃脉也。逆而盛，则热聚于胃口而 \n不行，故胃脘为痈也。帝曰∶有病颈痈者，或石治之，或针灸治之，而皆愈，其真安在。岐 \n伯曰∶此同名异等者也。夫痈气之息者，宜以针开除去之。夫气盛血聚者，宜石而泻之。此 \n所谓同病异治也。 \n《脉要精微论》帝曰∶诸痈肿筋挛骨痛，此皆安生。岐伯曰∶此寒气之肿，八风之变 \n也。帝曰∶治之奈何。岐伯曰∶此四时之病，以其胜治之愈也。 \n《厥论》曰∶少阳厥逆，机关不利。机关不利者，腰不可以行，项不可以顾，发肠痈， \n不可治，惊者死。 \n《寒热篇》帝曰∶寒热瘰 在于颈腋者，皆何气使然。岐伯曰∶此皆鼠 寒热之毒瓦斯 \n也，留于脉而不去者也。鼠 之本，皆在于脏，其末上出于颈腋之间，其浮于脉中，而未内 \n着于肌肉，而外为脓血者，易去也。黄帝曰∶去之奈何。岐伯曰∶请从其本引其末，可使衰 \n去，而绝其寒热。宜按其道以予之，徐往徐来以去之。其小如麦者，一刺知，三刺而已。黄 \n帝曰∶决其死生奈何。岐伯曰∶反其目视之，其中有赤脉，上下贯瞳子，见一脉，一岁死； \n见一脉半，一岁半死；见二脉，二岁死；见二脉半，二岁半死；见三脉，三岁死。见赤脉 \n不下贯瞳子，可治也。 \n《通评虚实论》曰∶所谓少针石者，非痈疽之谓也。痈疽不得顷时回。 \n《气交变大论》曰∶岁火太过，民病身热骨痛，而为浸淫。岁金太过，民病两胁下少腹 \n痛，目赤痛， 伤，耳无所闻。岁木不及，复则炎暑流火。湿性燥，病寒热疮疡痱疹痈痤。 \n岁金不及，复则寒雨暴至，民病口疮。岁水不及，民病寒疡流水。 \n《五常政大论》曰∶委和之纪，其病支废痈肿疮疡。卑监之纪，其动疡涌分溃痈肿。赫 \n曦之纪，其病笑疟疮疡。坚成之纪，其动暴折疡疰。少阳司天，火气下临，鼻窒疮疡。太阳 \n司天，寒气下临，甚则 肿，身后痈。少阴司天，热气下临，甚则疮疡。地有高下，气有 \n温凉。高者气寒，下者气热。故适寒凉者胀，之温热者疮。下之则胀已，汗之则疮已。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>脉候（二）\n\n属性：浮数之脉，应发热，其不发热而反恶寒者，若有痛处，痈疽之谓也。 \n洪大之脉，其主血实，积热疮肿。凡洪大者，痈疽之病进也。脓未成者，宜下之。脓溃 \n之后，脉见洪大，则难治。若兼自利，尤有凶候。 \n数脉主热，浮而数者，为表热。沉而数者，为里热。诸紧数之脉，应发热而反恶寒者， \n痈疽也。仲景曰，数脉不时见，则生恶疮也。又曰，肺脉数者，生疮也。凡诸疮，脉至洪数 \n，其内必有脓也。 \n实脉，主邪盛，邪气盛则实也。痈疽得此，可下之。若久病虚人，则最忌之，以正不胜邪也。 \n滑脉，多阳，或为热，或为虚。疮疡得此，脓未成者，可内消脓。已溃者，宜托里。所谓始为热，终为虚也。 \n散脉，为血虚有表无里也。凡疮毒脓溃之后，脉见洪滑粗散，而烦痛不除者，难治，以 \n其正气虚，邪气实也。又曰，肢体沉重，肺脉大则毙，谓其浮散无根也。 \n长脉，主阳气充实。伤寒得之，将欲汗解也。长而缓者，胃脉也，百病得之皆愈。故曰长则气治也。 \n芤脉，主阴虚血虚，脓溃后得之为宜，以脉病相应也。 \n弦脉，主肝邪。《疮疽论》曰，弦洪相搏，内寒外热，欲发疮疽也。 \n紧脉，主切痛积癖。凡疮疽得此，则气血留滞，邪结不散，多为痛也。 \n短脉，主虚。经曰，短则气病，以其乏胃气也。疮疡脉短，真气虚也。诸病见之，皆为难治，尤不可攻也。 \n涩脉，主血虚气涩。疮疡溃后得之无妨。 \n沉脉，为阴。疮疡得之，邪气深也。 \n迟脉，主阳气不足。疮疡得之，溃后自愈。 \n缓脉，无邪。长而缓者，百病皆宜。疮疡得此，则易愈，以其有胃气也。 \n弱脉，主气血俱虚，形精不足。大抵疮家之脉，凡沉迟濡弱者，皆宜托里。 \n微脉，主虚。真气复则生，邪气胜则死。疮疡溃后，微而和者，将愈也。 \n脉细，主阳衰。疮疡脉细而沉者，里虚而欲变证也。 \n虚脉，空而无力。脉虚则血虚，血虚生寒，阳气不足也。疮疡得之，只宜托里养血补气也。 \n软脉，少神元气弱也。凡疮疡之脉，但见虚迟软弱者，悉宜补虚排脓托里。 \n牢脉，坚强，阴之亏也。凡瘰 结肿之类，诊得牢脉者，皆不可内消也。 \n结促之脉，凡阴衰则促，阳衰则结。大抵结促之脉，由气血俱虚而断续者居多。疮疡得 \n之，多宜托里。然有素禀结促者，又当以有力无力，辨其虚实。实者可下，虚者不可不补。 \n右痈疽脉二十二种，大都微弱虚细迟缓短涩者，必气血皆虚，形精不足，俱当用补用托 \n，不可妄攻，无待言也。即如浮滑弦洪结促等脉，此中最有疑似，亦不得以全实论治，必须 \n详审形证，或攻或补，庶无误也。 \n齐氏曰∶疮疡之证，若不诊候，何以知阴阳勇怯，血气聚散。又曰∶脉洪大而数者，实 \n也。细微而数者，虚也。 \n河间曰∶脉沉实者，其邪在脏。浮大者，其邪在表。 \n立斋曰∶痈疽未溃，而脉先弱者，何以收敛。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>论证（三）\n\n属性：凡疮疡之患，所因虽多，其要惟内外二字；证候虽多；其要惟阴阳二字。知此四者，则 \n尽之矣。然内有由脏者，有由府者，外有在皮肤者，有在筋骨者，此又其浅深之辨也。至其 \n为病，则无非血气壅滞，营卫稽留之所致。盖凡以郁怒忧思，或淫欲丹毒之逆者，其逆在肝 \n脾肺肾，此出于脏而为内病之最甚者也。凡以饮食浓味，醇酒炙爆之壅者，其壅在胃，此 \n出于腑，而为内病之稍次者也。又如以六气之外袭，寒暑之不调，侵入经络，伤人营卫，则 \n凡寒滞之毒，其来徐，来徐者，其入深，多犯于筋骨之间，此表病之深者也。风热之毒其来 \n暴，来暴者，其入浅，多犯于皮肤之间，此表病之浅者也。何也。盖在脏在骨者多阴毒，阴 \n毒其甚也。在腑在肤者多阳毒，阳毒其浅也。所以凡察疮疡者，当识痈疽之辨∶痈者热壅于 \n外，阳毒之气也，其肿高，其色赤，其痛甚，其皮薄而泽，其脓易化，其口易敛，其来速， \n者其愈亦速。此与脏腑无涉，故易治而易愈也。疽者结陷于内，阴毒之气也，其肿不高，其痛 \n不甚，其色沉黑，或如牛领之皮，其来不骤，其愈最难。或全不知痛痒，甚有疮毒未形，而 \n精神先困，七恶叠见者，此其毒将发而内先败，大危之候也。知此阴阳内外，则疮痈之概， \n可类见矣。然此以外见者言之，但疮疡之发原无定所，或在经络，或在脏腑，无不有阴阳之 \n辨。若元气强，则正胜邪，正胜邪则毒在腑，在腑者便是阳毒，故易发易收而易治。元气弱 \n则邪胜正，邪胜正则毒在脏，在脏者便是阴毒，故难起难收而难治。此治之难易，全在虚实 \n。实者易而虚者难也，速者易而迟者难也。所以凡察痈疽者，当先察元气以辨吉凶，故无论 \n肿疡溃疡，但觉元气不足，必当先虑其何以收局，而不得不预为之地。万勿见病治病，且顾 \n目前，则鲜不致害也。其有元气本亏，而邪盛不能容补者，是必败逆之证。其有邪毒炽盛， \n而脉证俱实者，但当直攻其毒，则不得误补助邪，所当详辨也。 \n华元化曰∶痈疽疮肿之作，皆五脏六府蓄毒不流，非独因营卫闭塞而发也。其行也有处 \n，其主也有归。假令发于喉舌者，心之毒；发于皮毛者肺之毒，发于肌肉者脾之毒，发于骨髓者肾之毒， \n发于筋膜者，肝之毒；发于下者，阴中之毒；发 \n于上者，阳中之毒；发于外者，六腑之毒；发于内者，五脏之毒。故内曰坏，外曰溃，上曰从 \n，下曰逆。发于上者，得之速；发于下者，得之缓；感于六腑，则易治；感于五脏，则难瘳 \n。又近骨者多冷，近肤者多热。近骨者，久不愈，则化成血虫。近肤者，久不愈，则传气成 \n漏。成虫，则多痒少痛，或先痒后痛。成漏，则多痛少痒，或不痒不痛。内虚外实者，多痛 \n少痒。血不止，则多死。溃脓，则多生。证候多端，要当详治。 \n伍氏云∶痈疽之疾有二十余证∶曰 发、痼发、石发、岩发、蜂巢发、莲子发、椒眼 \n发、连珠发、竟体发、肠痈内发、脑背发、眉发、腮颔发、肺痈、瓜瓠发。大率随病浅深内 \n外施治，不可迟缓。初发如伤寒，脉浮而紧是其候也。 \n又曰∶五脏六腑俞穴皆在背，凡患疮证，有伤脏膜者多致不救。腑气浮行于表，故痈肿 \n浮高为易治；脏血沉寒主里，故疽肿内陷为难治。 \n又曰∶疖者节也，痈者壅也，疽者沮也。一寸至二寸为疖，三寸至五寸为痈，一尺为 \n疽，一尺至二尺为竟体疽。若脉洪数者难治，脉微涩者易治。初觉，宜清热拔毒。已溃则排 \n脓止痛。脓尽则长肌敷痂，当酌轻重顺逆而审治之。 \n马益卿《痈疽论》曰∶人有四肢五脏，一觉一寐，呼吸吐纳，精气往来，流而为营卫， \n畅而为气色，发而为声音，阳用其形，阴用其精，此人之常数所同也。至其失也，蒸则生热 \n，否则生寒，结则为瘤赘，陷则为痈疽，凝则为疮癣，愤则结瘿，怒则结疽。又五脏不和 \n，则九窍不通，六气不和，则留结为痈，皆经络涩滞，气血不流，风毒乘之而致然也。 \n薛立斋曰∶疮疡之作，皆由膏梁浓味，醇酒炙爆，房劳过度，七情郁火，阴虚阳辏 \n，精虚气节，命门火衰，不能生土；营卫虚弱，外邪所袭，气血受伤而为患。当审其经络受 \n证，标本缓急以治之。 \n陈良甫曰∶外如麻，里如瓜。又曰，外小如钱，内可容拳。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>善恶顺逆（四）\n\n属性：痈疽证，有五善七恶，不可不辨∶凡饮食如常，动息自宁，一善也；便利调匀，成微见干 \n涩，二善也；脓溃肿消，水浆不臭，内外相应，三善也；神彩精明，语声清亮，肌肉好恶分） \n明，四善也；体气和平，病药相应，五善也。七恶者∶烦躁时嗽，腹痛渴甚，眼角向鼻，泻 \n利无度，小便如淋，一恶也；气息绵绵，脉病相反，脓血既泄，肿 尤甚，脓色臭败，痛 \n不可近，二恶也；目视不正，黑睛紧小，白睛青赤，瞳子上视，睛明内陷，三恶也；喘粗短 \n气，恍惚嗜卧，面青唇黑，便污未溃，肉黑而陷，四恶也；肩背不便，四肢沉重，已溃青黑 \n，筋腐骨黑，五恶也；不能下食，服药而呕，食不知味，发痰呕吐，气噎痞塞，身冷自汗， \n耳聋惊悸，语言颠倒，六恶也；声嘶色败，唇鼻青赤，面目四肢浮肿，七恶也。五善者，病 \n在腑，在腑者轻。七恶者，病在脏，在脏者危也。 \n齐氏曰∶病有证合七恶，皮急紧而如善者。病有证合五善，而皮缓虚如恶者。夫如是岂 \n浅识之所知哉。然五善并至，则善无加矣。七恶并至，则恶之极矣。凡五善之中，乍见一二 \n善证，疮可治也。七恶之内，忽见一二恶证，宜深惧之。大抵疮疽之发，虚中见恶证者不可 \n救。实证无恶候者自愈。又凡脓溃之后，而烦疼不除，诊其脉洪数粗散者难痊，微涩迟缓者 \n易愈。此善恶之证，于诊候中，亦可知也。若发背脑疽及诸恶疮，别有五逆之证者，白睛青 \n黑而眼小，服药而呕，伤痛渴甚，膊项中不便，音嘶色败者，是为五逆。其余热渴利呕，盖 \n毒瓦斯入里，脏腑之伤也，可随证以治之。（出《外科精义》，宋齐德之着。） \n陈氏曰∶病有甚而致生，有微而致死，病证难辨，死生何从决乎。答曰∶发背，溃透内 \n膜者死。未溃内陷，面赤唇黑，便污者死。烦闷者不治，溃喉者不治。阴患入腹者不治，入 \n囊者不治。鬓深寸许者不治。颐后一寸三分，名铣毒，亦不治。无此者生。流注虽多，疗 \n之必愈。（出《外科精要》，宋临江陈自明着。） \n《发挥》曰∶大抵发背、脑疽、脱疽，肿痛色赤者，乃水衰火旺之色，多可治。若黑若 \n紫，则火极似水之象，乃其肾水已竭，精气枯涸也，决不治。又骨髓不枯，脏腑不败者，可 \n治。若老弱患此，疮头不起，或肿硬色夭，坚如牛领之皮，脉更涩，此精气已绝矣，不可治 \n，或不待溃而死。有溃后气血不能培养者，亦死。 \n立斋曰∶疮疡之证，有五善七恶。善者，勿药自愈。恶者，乃五脏亏损之证。多因元气 \n虚弱。或因脓水出多，气血亏损；或因汗下失宜，营卫消铄；或因寒凉克伐，血气不足； \n或因峻厉之治，胃气受伤；以致真气虚而邪气实，外似有余而内实不足。法当纯补胃气，多有 \n可生，不可因其证恶，遂弃而不治。若大渴发热，或泄泻淋闭者，邪火内淫，一恶也。竹叶 \n黄汤。气血俱虚，八珍汤加黄 、麦冬、五味、山茱萸。如不应，佐以加减八味丸煎服。 \n脓血既泄，肿痛尤甚，脓色败臭者，胃气虚而火旺，二恶也。人参黄 汤。如不应，用十全 \n大补汤加麦冬、五味。目视不正，黑睛紧小，白睛青赤，瞳子上视者，肝肾阴虚而目系急， \n三恶也。六味丸料。如或阴中有火，加炒山栀、麦冬、五味。如不应用八珍汤加炒山栀、麦 \n冬、五味。喘粗短气，恍惚嗜卧者，脾肺虚火，四恶也。六君加大枣、生姜。如不应，用补 \n中益气汤加麦冬、五味。心火刑克肺金，人参平肺散。阴火伤肺，六味丸加五味子煎服。肩 \n背不便，四肢沉重者，脾肾亏损，五恶也。补中益气汤加熟地、山药、山茱萸、五味。如不 \n应，用十全大补汤加山茱萸、山药、五味。不能下食，服药而呕，食不知味者，胃气虚弱， \n六恶也。六君子汤加木香、砂仁。如不应，急加附子。声嘶色败，唇鼻青赤，面目四肢浮肿 \n者，脾肺俱虚，七恶也。补中益气汤加大枣、生姜。如不应，用六君子汤加炮姜。更不应， \n急加附子，或用十全大补汤加附子、炮姜。腹痛泄泻，咳逆昏愦者，阳气虚，寒气内淫之恶 \n证也。急用托里温中汤，后用六君子汤加附子，或加姜桂温补。此七恶之治法也。此外，更 \n有溃后发热，恶寒作渴；或怔忡惊悸，寤寐不宁，牙关紧闭；或头目赤痛，自汗盗汗，寒战 \n切牙，手撒身热，脉洪大，按之如无；或身热恶衣，欲投于水，其脉浮大，按之微细，衣浓 \n仍寒。此血气虚极，传变之恶证也。若手足逆冷，肚腹疼痛，泄利肠鸣，饮食不入，呃逆呕 \n吐，此阳气虚，寒气所乘之恶证也。若有汗而不恶寒，或无汗而恶寒，口噤足冷，腰背反 \n张，颈项强劲，此血气虚极，变痉之恶证也。俱急用参、 、归、术、熟地、附、桂之属救 \n之，间有可生者。宋时齐院令虽尝纂其状，而未具其因。皇明陶节庵，虽各立一方，亦简而 \n未悉，予故补其缺云。 \n又曰∶前证善者，乃五脏未伤，病微邪浅，使能慎起居，节饮食，则勿药自愈。恶者 \n，乃五脏亏损之证，前哲虽云不治，若能补其脾胃，固其根本，多有可生者，岂可以其恶而遂弃之耶。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>虚实（五）\n\n属性：齐氏曰∶疮疽之证，有脏腑气血上下，真邪虚实不同也，不可不辨∶如肿起坚硬，脓 \n稠者，疮疽之实也；肿下软慢，脓稀者，疮疽之虚也；大便硬，小便涩，饮食如故，肠满膨 \n胀，胸膈痞闷，肢节疼痛，口苦咽干，烦躁多渴，身热脉大，精神闷塞者，悉脏腑之实也； \n泻利肠鸣，饮食不入，呕吐无时，手足厥冷，脉弱皮寒，小便自利，或小便短少，大便滑利 \n，声音不振，精神困倦，悉脏腑之虚也。凡疮疽，肿起色赤，寒热疼痛，皮肤壮热，脓水稠 \n粘，头目昏重者，血气之实也。凡脓水清稀，疮口不合，聚肿不赤，不堪热痛，肌寒肉冷， \n自汗色夭者，气血之虚也。头痛鼻塞，目赤心惊，咽喉不利，口舌生疮，烦渴引冷，睡语咬 \n牙者，上实也。精滑不禁，大便自利，腰脚沉重，睡卧不宁者，下虚也。肿 尤甚，痛不 \n可近，寒热往来，大便秘涩，小便如淋，心神烦闷，恍惚不宁者，邪气之实也。肩项不便，四 \n肢沉重，目视不正，睛不了了，食不知味，音嘶色败，四肢浮肿，多日不溃者，真气之虚也 \n。又曰∶邪气胜则实，真气夺则虚。又曰∶诸痛为实，诸痒为虚也。又曰∶诊其脉洪大而数 \n者实也，细微而软者虚也。虚则补之，和其气以托里也。实则泻之，疏利而导其滞也。《内 \n经》曰∶血实则决之，气虚则掣引之。又曰∶形伤痛，气伤肿。先肿而后痛者，形伤气也； \n先痛而后肿者，气伤形也。 \n《精要》曰∶凡疮疽肿高痛甚，烦渴饮冷，此病气元气俱有余，宜用清热消毒散、仙方 \n活命饮为主。若肿高痛甚，口干饮热，此病气有余，元气不足，宜用托里消毒散为主。若漫 \n肿微痛，食少体倦，此病气元气俱不足，宜用六君、补中二汤，壮其脾胃，则未成者消，已 \n成者溃，已溃者敛矣。 \n《心法》曰∶凡疮口不合，脓水清稀，气血俱虚也。饮食少而难化，脾胃虚寒也。肌体 \n瘦弱，面色痿黄，胆气不行也，非参 归术之类不能补，非附子不能助其功。今饮食进少， \n且难消化，属脾胃虚寒。盖脾胃属土，乃命门火虚不能生土而然。不宜直补脾胃，当服八味 \n丸补火以生土也。 \n立斋曰∶疮疡之作，当审其标本虚实，邪正缓急而治之。若病急而元气实者，先治其标 \n；病缓而元气虚者，先治其本；或病急而元气又虚者，必先于治本而兼以治标。大要肿高 \n痛，脓水稠粘者，元气未损也，治之则易。漫肿微痛，脓水清稀者，元气虚弱也，治之则难 \n。不肿不痛，或漫肿黯黑不溃者，元气虚甚，治之尤难也。主治之法，若肿高 痛者，先用 \n仙方活命饮解之，后用托里消毒散。漫肿微痛者，用托里散；如不应，加姜、桂。若脓出而 \n反痛者，气血虚也，八珍汤。不作脓，不腐溃，阳气虚也，四君子加归、 、肉桂。不生肌 \n，不收敛，脾气虚也，四君加地黄、木香。恶寒憎寒，阳气虚也，十全大补加姜、附。晡热 \n内热，阴血虚也，四物加参、术。欲呕作呕，胃气虚也，六君加炮姜。自汗盗汗，五脏虚也 \n，六味丸料加五味子。食少体倦，脾气虚也，补中益气加茯苓、半夏。喘促咳嗽，脾肺虚也 \n，前汤加麦冬、五味。欲呕少食，脾胃虚也，人参理中汤。腹痛泄泻，脾胃虚寒也，附子理 \n中汤。小腹痞，足胫肿，脾肾虚也，十全大补汤加山茱、山药、肉桂。泄泻足冷，脾肾虚寒 \n也，前药加桂附。热渴淋秘，肾虚阴火也，加减八味丸。喘嗽淋秘，肺肾虚火也，补中益气 \n汤加减八味丸。 \n又曰∶大凡虚怯之人，不必分其肿溃，惟当先补胃气。或疑参 满中，间有用者，又加 \n发散败毒，所补不偿，所损又有，泥于气质素实。或有痰不服补剂者，多致有误。殊不知疮 \n疡之作，缘阴阳亏损，其脓既泄，则气血愈虚，岂有不宜补者哉。故丹溪曰∶但见肿痛，参 \n之脉证，虚弱便与滋补气血，无亏，可保终吉。旨哉斯言。 \n又曰∶气无补法，俗论也。以其为病，痞满壅塞，似难于补，不知正气虚，而不能营运 \n，则邪气滞而为病。经云∶壮者气行则愈，怯者弱者则着而为病。苟不用补气，何由而行乎。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>浅深辨（六）\n\n属性：齐氏《精义》曰∶疮候多端，欲辨浅深，直须得法。简而论之，则疮疽概举有三∶肿高 \n而软者，发于血脉；肿下而坚者，发于筋骨；皮肉之色不变者，发于骨髓。又曰∶凡疗疮疽 \n，以手按摇疮肿，根牢而大者，深也；根小而浮者，浅也。又验其人，初生疮之时，便觉壮 \n热恶寒，拘急头痛，精神不宁，烦躁饮冷者，其疮疽必深也。若人虽患疮疽，而起居平和， \n饮食如故者，其疮浮浅也。恶疮初生，其头如米粟，微似有痛痒，误触破之即 展，觉有深 \n意，速服犀角升麻汤，及漏芦汤、通气等药，取通利疏畅，兼用浴毒汤， 溃之类。若浮浅 \n者，贴膏 求差。以此推之，则深浅之变，始终之次也。又曰∶憎寒壮热，所患必深。肉 \n色不变，发于内也。 \n曾氏曰∶凡痈疽，其脉浮数洪紧，肿 作痛，身热烦渴，饮食如常，此六腑不和，毒 \n发于外而为痈。其势虽急，投以凉剂，多保全生。其脉沉细伏紧，初发甚微，或无疮头，身 \n不热而内燥，体重烦疼，情绪不乐，胸膈痞闷，饮食无味，此五脏不和，毒蓄于内而为疽。 \n急投五香连翘汤，或神仙截法蜡矾丸、制甘草汤防托毒瓦斯，免致变证内攻，尤宜当头隔蒜灸 \n。若涂毒药，迷其腠理；投凉药，虚其真气。故善恶之证，在乎医之工拙耳。或噫气痞塞， \n咳逆，身冷自汗，目瞪耳聋，恍惚惊悸，语言颠倒，皆深恶证也。五善见三则瘥，七恶见四 \n则危。五善并至，则善无以加，七恶并臻则恶之极矣。 \n李氏曰∶疽初发一粒如麻豆，发热肿高，热痛色赤，此为外发。势虽炽盛，治得其法， \n可保其生。若初时不发热，体倦怠，患处如故，数日不肿痛，五内已坏。虽有卢、扁之药， \n亦未如之何矣。 \n立斋曰∶前证有因元气虚而不能发出者，有因敷贴寒药而不发出者，有因攻伐过伤气 \n血而不能发出者，有因热毒内蕴而失疏托者，审而治之，多有生者。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>总论治法（七）\n\n属性：疮疡之治，有宜泻者，有宜补者，有宜发散者，有宜调营解毒者，因证用药，各有所主 \n。经曰∶形气有余，病气有余，当泻不当补；形气不足，病气不足，当补不当泻。此其大纲 \n也。故凡察病之法，若其脉见滑实洪数，而 肿痛甚，烦热痞结，内外俱壅者，方是大实之 \n证。此其毒在脏腑，非用硝黄猛峻等剂，荡而逐之，则毒终不解。故不得不下，然非有真实 \n滞者不可下，此下之不可轻用也。其有脉见微细，血气素弱，或肿而不溃，溃而不敛，或饮 \n食不加，精神疲倦，或呕吐泄泻，手足常冷，脓水清稀，是皆大虚之候。此当全用温补，固 \n无疑矣。然不独此也。即凡见脉无洪数，外无烦热，内无壅滞，而毒有可虑者，此虽非大虚 \n之证，然察其但无实邪，盒饭托里养营，预顾元气。何也。盖恐困苦日久，或脓溃之后，不 \n待损而自虚矣。及其危败，临期何能及哉。故丹溪云∶痈疽因积毒在脏腑，宜先助胃壮气，以 \n固其本。夫然则气血，凝结者自散，脓瘀已成者自溃，肌肉欲死者自生肌肉，已死者自腐肌 \n肉，已溃者自敛。若独攻其疮，则脾胃一虚，七恶蜂起，其不死者幸矣，即此谓也。其有脉 \n见紧数，发热憎寒，或头痛，或身痛，或四肢拘急无汗，是必时气之不正，外闭皮毛，风热 \n壅盛而为痈肿，此表邪之宜散者也。如无表证，则不宜妄用发散，以致亡阳损卫。故仲景曰 \n∶疮家不可汗，此之谓也。其有营卫失调，气血留滞而偶生痈肿，但元气无损，饮食如常， \n脉无凶候，证无七恶，此其在腑不在脏，在表不在里。有热者清其热，有毒者解其毒，有滞 \n者行其气，所当调营和卫而从平治者也。大都疮疡一证，得阳证而病气形气俱有余者轻，得 \n阴证而形气病气俱不足者重。若正气不足而邪毒有余，补之不可，攻之又不可者危。若毒虽 \n尽去，而脾肾已败，血气难复者，总皆不治之证。故临证者，当详察虚实，审邪正，辨表里 \n，明权衡。尚举措略乖，必遗人大害。斯任非轻，不可苟也。"}, {"n": 26, "text": "卷二十六\n\n王海藏《元戎》曰∶若人气血壅盛，营卫充满，抑遏不行，腐化而为痈者，当泄之，以 \n夺其盛热之气。若人饮食少思，精神衰弱，营卫短涩，寒搏而为痈者，当补之，以接其虚怯之气。 \n丹溪亦曰∶肿疡内外皆虚，宜以补接行散为主。 \n东垣曰∶疮疽之发，其受之有内外之别，治之有寒热之异。受之外者，法当托里以温剂 \n。反用寒药，则使皮毛始受之邪引入骨髓。受之内者，法当疏利以寒剂。反用温药托里，则 \n使骨髓之病上彻皮毛，表里通溃，共为一疮，助邪为毒，苦楚百倍，轻则危殆，重则死矣。 \n《病机机要》云∶内之外者，其脉沉实，发热烦躁，外无 赤痛，深于内其邪气深，故宜疏 \n通脏腑以绝其源。外之内者，其脉浮数， 肿在外，形证外显，恐邪气极而内行，故先宜托 \n里也。内外之中者，外无 恶之气，内亦脏腑宣通，知其在经，当和营卫也。用此三法之后 \n，虽未即瘥，必无变证，亦可使邪气峻减，而易愈。故治疮大要，须明此托里、疏通、和营卫之三法。 \n陈良甫曰∶诸痛痒疮疡，皆属心火。前辈云痈疽多生于丹石房劳之人。凡人年四十以上， \n宜先用内托散，次用五香连翘汤，更以骑竹马法，或隔蒜并明灸足三里，以发泄其毒。盖邪 \n之所凑，其气必虚；留而不去，其病乃实。故痈疽未溃，则一毫热药断不可用。痈疽已溃， \n脏腑既亏，一毫冷药亦不可用。犹忌敷贴之药，闭其毫孔。若热渴便闭，脉沉实洪数者，宜 \n用大黄等药，以泄其毒，后以国老膏、万金散、黄矾丸、远志酒之类，选而用之。 \n立斋曰∶按前证，若热毒蕴于内，大便秘结，元气无亏者，宜用大黄等药泄其热毒。若 \n阴虚阳凑，精虚气怯，脾胃虚弱者，宜用甘温之剂，培其本源。若疮不 肿，不作脓者， \n虽其未溃，仍须温补。若疮已溃，而肿不退，痛不止者，仍宜清凉之剂治之。若病急而元气实 \n者，先治其标。病缓而元气虚者，先治其本。或病急而元气更虚者，必先治本而兼以治标。 \n大抵肿高 痛，脓水稠粘者，元气未损也，治之则易。漫肿微痛，脓水清稀者，元气虚弱 \n也，治之则难。不肿不痛，或漫肿色黯，不溃者，发于阴也，元气虚甚，理所不治。若肿高 \n痛者，先用仙方活命饮，后用托里消毒散。漫肿微痛者，宜托里散；如不应，加姜、桂。若 \n脓出而反痛，气血虚也，八珍汤。不作脓，不腐溃，阳气虚也，四君加归、 、肉桂。不生 \n肌，不收敛，脾气虚也，十全大补加姜、桂。晡热内热，阴血虚也，四物加参、术。欲呕作 \n呕，胃气虚也，六君加炮姜。自汗盗汗，五脏虚也，六味丸加五味子。食少体倦，脾气虚也 \n，补中益气加茯苓、半夏。喘促咳嗽，脾肺虚也，前汤加麦冬、五味。欲呕少食，脾胃虚也 \n，人参理中汤。腹痛泄泻，脾胃虚寒也，附子理中汤。小腹痞，足胫肿，脾肾虚弱也，十全 \n大补加山萸、山药、肉桂。泄泻足冷，脾肾虚寒也，前药加桂、附。热渴淋闭，肾虚阴火也 \n，加减八味丸。喘嗽淋闭，肺肾虚火也，补中益气汤加减八味丸。凡此变证，皆因元气亏损 \n，失于预补所致。又曰∶凡疮疡用药，当审其经络受证，标本虚实，以治之。不可泥于热毒 \n内攻，专用寒凉克伐之剂，亏损脾胃气血，多致有误。且以虚弱之人，用峻利之药，则药力 \n未到，胃气先伤，虚虚之祸，有所不免。故凡元气不足者，既治其初患，更当内用参 归术 \n温补脾胃，外用桑枝葱熨接补阳气，使自消散。又曰，凡痈疽肿痛，初生便觉脉沉细而烦闷 \n，脏腑弱而皮寒，邪毒猛暴，恍惚不宁，外证深沉者，亦当即用托里散及温热之剂，以从治 \n之。又曰∶前证若发热烦渴，大便秘结者，由邪蓄于内，宜内疏黄连汤，以泄内毒。若头痛 \n拘急，发热恶寒者，由邪客于外，宜人参败毒散，以散表邪。若肿痛 赤，发热作渴，此 \n毒瓦斯凝于肉里，宜仙方活命饮，解散其毒。若食少体倦，发热恶寒，此中气虚弱，宜六君子汤 \n，以补脾胃。又曰∶大抵证有本末，治有权宜。治其主，则末病自退。用其权，则不拘于时。 \n泥于守常，必致病势危甚。况杂用攻剂，动损各经乎。罗谦甫云∶守常者众人之见，知变者 \n智者之事。知常而不知变，因细事而取败者多矣。 \n凡痈疽，实证不可温补，虚证不可凉泄，此大法也。观前条陈良甫曰∶凡疮疡未溃，一 \n毫热药断不可用。痈疽已溃，脏腑已亏，一毫冷药亦不可用。又立斋云，若肿 痛甚，烦躁 \n脉大，寒热往来，大便秘结，小便涩痛，心神愦闷，皆邪热之证。凡辛热之剂，不但肿疡不 \n可用，虽溃疡亦不可用也。此固然矣。然二公已道其半，犹未尽也。余读之曰，凡痈疽阴盛 \n阳衰者，但见体虚脉弱，阳气无权等证，则凡苦寒之剂，非为溃疡不可用，即肿疡亦不可用 \n也。又若阴邪凝结之毒，非用温热，何以营运。而陈氏谓肿疡不可用热药，恐不可以概言也。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>败毒（八）\n\n属性：《外科枢要》曰∶疮疡之证，当祭经之传受，病之表里，人之虚实，而攻补之。假如肿 \n痛热渴，大便秘结者，邪在内也，疏通之。 肿作痛，寒热头疼者，邪在表也，发散之。 \n肿痛甚者，邪在经络也，和解之。微肿微痛，而不作脓者，气血虚也，补托之。漫肿不痛， \n或不作脓，或脓成不溃者，气血虚甚也，峻补之。色黯而微肿微痛，或脓成不出，或腐肉不 \n溃，阳气虚寒也，温补之。若泥其未溃，而概用败毒，复损脾胃，不惟肿者不能成脓，而溃 \n者亦难收敛，七恶之证蜂起，多致不救。马益卿曰∶肿疡内外皆壅，宜以托里表散为主。如 \n欲用大黄，宁无孟浪之非。溃疡内外皆虚，宜以托里补接为主，如欲用香散，未免虚虚之失，治者审之。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>托里（九）\n\n属性：齐德之曰∶凡疮疽丹肿，结核瘰 ，初觉有之，即用内消之法。经久不除，血气渐衰， \n肌寒肉冷，脓汁清稀，毒瓦斯不出，疮口不合，聚肿不赤，结核无脓，外证不明者，并宜托里 \n。脓未成者，使脓早成。脓已溃者，使新肉早生。血气虚者，托里补之。阴阳不和，托里调 \n之。大抵托里之法，使疮无变坏之证。凡为疮医不可一日无托里之药。然而寒热温凉，烦渴利 \n呕，临证宜审其缓急耳。 \n马益卿曰∶痈疽因积毒在脏腑，当先助胃壮气，使根本坚固，次以行经活血药为佐，参 \n以经络时令，务使毒瓦斯外泄，治之早者，可以内消。此托里之旨也。 \n立斋曰∶大凡疮疡之作，由胃气不从。疮疡之溃，由胃气腐化。疮疡之敛，由胃气营养 \n。余尝治初结未成脓者，托而散之。已成欲作脓者，托而腐之。脓成未溃者，托而开之。脓 \n已溃者，托而敛之。东垣云∶脾为仓廪之官，胃为水谷之海，主养四旁以生血气，故胃气乃 \n生发之源，为人身之本。厥有旨哉。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>论汗下（十）\n\n属性：仲景治伤寒，有汗吐下三法。东垣治疮疡，有疏通、托里、和营卫之三法。用之得宜， \n厥疾瘳矣。假如疮疡肿硬木闷，烦热便秘，脉沉而实，其邪在内，当先疏其内以下之。 肿 \n作痛，便利调合，脉浮而洪，其邪在表，当先托其里以汗之。仲景曰∶疮家虽身体疼痛，不 \n可发汗，汗之则发痉。苟不详审，而妄为汗下，以致血气亏损，毒反延陷，少壮者难以溃敛 \n，老弱者多致不救。（见《外科枢要》。） \n罗谦甫云∶丁巳岁冬月，予从军曹州，有牛经历者，病头目赤肿，身前后尤甚，疼痛不 \n可忍，发热恶寒，牙关紧急，涕唾稠粘，饮食难下，不得安卧。一疡医，于肿上砭刺四五百 \n针，肿亦不减，其痛益甚，莫知所由。予往诊视，其脉浮紧，按之洪缓。此证乃寒覆皮毛， \n郁遏经络，热不得散，聚而为肿。经云∶天寒则地冻水冰，人气在身中，皮肤致密，腠理闭 \n，汗不出，气血强，肉坚涩。当是之时，善行水者不能往冰，善穿地者不能凿冻，善用针者 \n亦不能取四厥。必待天温冻解，而后水可行，地可穿，人脉亦犹是也。又云∶冬月闭藏，用 \n药多而少针石也。宜以苦温之剂，温经散寒，其病自已。所谓寒致腠理，以苦发之，以辛散 \n之也，遂用托里温中汤，根据方饵之。以薄衣覆其首，以浓被覆其身，卧于暖处，使经血温， \n腠理开，寒气散，阳气升。大汗出后，肿减八九。再服则去麻黄、防风，加连翘、鼠粘子， \n肿痛悉愈。经言∶汗之则疮已。信哉斯言。或云∶仲景言，疮家虽身痛不可发汗，其理何也 \n。余曰∶此说乃营气不从，逆于肉理，而生疮肿作身疼痛，非外感寒邪之病，故戒之，以不可 \n发汗，汗之则成痉也。又问∶仲景言鼻衄者不可发汗，复言脉浮紧者当以麻黄汤发之，衄血 \n自止，所说不同，其故何也。予曰∶此正与疮家概同，夫人身血之与汗，异名而同类，夺汗 \n者无血，夺血者无汗，今衄血妄行，为热所逼，更发其汗，是反助热邪，重竭津液，必变凶 \n证，故不可汗。若脉浮则在表，脉紧则在寒，寒邪郁遏，阳不得伸，热伏营中，迫血妄行， \n上出于鼻，故当用麻黄汤散其寒邪，使阳气得舒，其血自止，又何疑焉。或者叹曰∶知其要 \n者，一言而终，不知其要，流散无穷。洁古之学，可谓知其要者矣。 \n东垣云∶疮疡有因风热外郁，其人多怒，其色赤，其肿高，结硬而痛，其脉洪紧而弦， \n是邪客于血脉之上，皮肤之间，故发其汗而通其营卫，则邪气去矣。又曰∶疮疡诸病，凡面 \n赤者，虽伏大热，禁不得攻里，攻里则下利，此以阳邪怫郁在经，宜发表以去之，故曰火郁 \n则发之。虽大便数日不见，宜多攻其表，以发散阳气，少加润燥之药以润之。如见风脉风证， \n只宜用风药发表，风邪解则大便自通也。若只干燥闭涩，止宜润之，切不可下也。但疮疡郁 \n冒，俗乎昏迷是也，宜汗之则愈。 \n初虞氏云∶凡痈疽始作，须以大黄等药亟转利之，勿以困苦为念。与其溃烂而死，不若 \n利之而死，况有生道哉。古人立法，率用五香连翘漏芦等药，贫乏者单煮大黄汤以利之，至 \n于脓溃乃服黄 等药以排脓，《千金》、《外台》备矣。世以疮发于外，不行转利而死者多 \n矣。立斋曰∶按前证，若肿高 痛，脏腑闭结，属内外俱实者，当用前药泻之。若漫肿微痛 \n，脏腑不实，属内外俱虚者，当用内托补之。若患肿无头，肉色不变，当助胃壮气，令其内 \n消。若疼痛不止， 肿不消，当用人参黄 汤以托里排脓。若饮食少思，肌肉不生，当用 \n参托里散，以补养脾胃。 \n立斋曰∶王德之患发背，脉浮数按之则涩，大便五六日不行，腹不加胀。余曰∶邪在表 \n不在里，但因气血虚，饮食少，故大便不行，非热结也，宜生气血为主。彼不信，以为积毒 \n在内，仍用大黄，遂连泻不止，更加发热呃逆，饮食不进而死。其子曰∶泻亦能为害乎。余 \n曰∶服利药而利不止者死。不当泻而强泻，令人洞泻不禁者死。下多亡阴者死。曰∶疮疡 \n乃积毒在脏，若不驱逐，何以得解。余曰∶疮疡虽积毒在脏腑，治法先当助胃气，使根本坚固 \n，参以行经活血时宜之药，非宜妄用大黄也。今其病在表，而反以峻利之剂，重夺其阴，其 \n可乎哉。故曰表病里和而反下之，则中气虚表邪乘虚而入，由是变证百出。虽云脉浮数者邪 \n在表，当用托里复煎散，然其间黄芩、苍术亦不敢妄用。脉沉实者邪在里，当用内疏黄连汤 \n，然其中大黄槟榔亦不敢妄用。况浮数涩主气血皆虚，且邪既在表，而反用峻剂重伤其里， \n诛伐无过，不死何俟。 \n愚谓疮肿之属表邪者，惟时毒、丹毒、斑疹，及头面、颈项、上焦之证多有之。察其果 \n有外邪而脉见紧数，证有寒热者，方宜表散。然散之之法，又必辨其阴阳盛衰，故或宜温散 \n，或宜凉散，或宜平散，或宜兼补而散，或宜解毒而散，此散中自有权宜也。又如里证用下 \n之法，则毒盛势剧者大下之，滞毒稍轻者微下之，营虚便结而毒不解者养血滋阴而下之，中 \n气不足而便结壅滞者润导而出之。凡此皆通下之法，但宜酌缓急轻重而用得其当耳。故必察 \n其毒果有余及元气壮实，下之必无害者，方可用下，否则不但目前，且尤畏将来难治之患。 \n是以表证不真者不可汗，汗之则亡阳。里证不实者不可下，下之则亡阴。亡阴亦死，亡阳亦 \n死，医固可以孟浪乎。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>论灸法（十一）\n\n属性：王海藏曰∶疮疡自外而入者，不宜灸，自内而出者宜灸。外入者托之而不内，内出者 \n接之而令外。故经曰∶陷者灸之。灸而不痛，痛而后止其灸。灸而不痛者，先及其溃，所以 \n不痛，而后及良肉，所以痛也。灸而痛，不痛而后止其灸。灸而痛者，先及其未溃，所以 \n痛，而次及将溃，所以不痛也。 \n李氏云∶治疽之法，灼艾之功胜于用药，盖使毒瓦斯外泄。譬诸盗入人家，当开门逐之， \n不然则入室为害矣。凡疮初发一二日，须用大颗独蒜切片三分浓，贴疽顶，以艾隔蒜灸之。 \n每三壮易蒜，疮溃则贴神异膏，如此则疮不开大，肉不坏，疮口易敛，一举三得。此法之妙 \n，人所罕知。若头顶见疽，则不可用此法。（《五府极观碑》载。） \n又曰∶凡患背疽，漫肿无头者，用湿纸贴肿处，但一点先干处，乃是疮头。可用大蒜十 \n颗、淡豆豉半合、乳香钱许，研烂置疮上，铺艾灸之。痛否，皆以前法为度。 \n陈氏曰∶脑为诸阳之会，颈项近咽喉，肾俞乃致命之所，皆不可灼艾。 \n伍氏曰∶凡用蒜饼灸者，盖蒜味辛温有毒，主散痈疽，假火势以行药力也。只有用艾炷 \n灸者，此可施于顽疽痼发之类。凡赤肿紫黑毒甚者，须以蒜艾同灸为妙。又曰∶凡治疽痈， \n发背、疔疮，若初灸即痛者，由毒瓦斯轻浅，灸而不痛者，乃毒瓦斯深重，悉宜内服追毒排脓， \n外敷消毒之药。大抵痈疽不可不痛，又不可大痛，闷乱不知痛者，难治。又曰∶凡隔蒜灸者 \n，不论壮数，则邪无所容，而真气不损。但头项见疮，宜用骑竹马法，及足三里灸之。 \n《千金》云∶痈疽始作，或大痛，或小痛，或发如米粒，既便出脓，宜急断口味，利去 \n其毒，用骑竹马灸法，或就患处灼艾。重者四面，中央总灸一二百壮，更用敷药，其效甚速。 \n立斋云∶夫疮疡之证，有诸中，必形诸外。在外者，引而拔之。在内者，疏而下之。灼 \n艾之功甚大。若毒瓦斯郁结，瘀血凝滞轻者，或可药散，重者药无全功矣。东垣曰∶若不针烙 \n则毒瓦斯无从而解。是故善治毒者，必用隔蒜灸。舍是而用苦寒败毒等剂，其壮实内热者，或 \n可，彼怯弱气虚者，未有不败者也。又有毒瓦斯沉伏，或年高气弱，或服克伐之剂，气益以虚 \n，脓因不溃者，必假火力以成功。大凡蒸灸，若未溃则拔引郁毒，已溃则接补阳气，祛散寒 \n邪，疮口自合，其功甚大。尝治四肢疮疡气血不足者，祗以前法灸之，皆愈。疔毒甚者，尤 \n宜灸。盖热毒中隔，内外不通，不发泄则不解散。若处贫居僻，一时无药，则用隔蒜灸法尤 \n便。每三壮一易蒜片，大概以百壮为度。用大蒜，取其辛而能散。用艾炷，取其火力能透。 \n如法灸之，必疮发脓溃。继以神异膏贴之，不日自愈。一能使疮不开大，二内肉不坏，三疮 \n口易合，见效甚神。丹溪云∶惟头为诸阳所聚，艾壮宜小，而少。 \n曹工部，发背已十八日，疮头如粟，疮内如锥，痛极时有闷瞀，饮食不思，气则益虚， \n以大艾隔蒜灸十余壮，尚不知，而痛不减，遂明灸二十余壮，内疮悉去，毒瓦斯大发，饮食渐 \n进。更以大补药及桑木燃灸，瘀肉渐溃。 \n刘贯卿，足患疔疮已十一日，气弱，亦灸五十余壮，更以托里药而愈。 \n黄君，腿痈，脓清脉弱。一妇，臂结一块已溃。俱不收敛。各灸以豆豉饼，更饮托里药而愈。 \n一男子，胸肿一块，半载不消。令明灸百壮方溃。与大补药不敛，复灸以附子饼而愈。 \n一男子，患发背，疮头甚多，肿硬色紫，不甚痛，不腐溃，以艾铺患处灸之，更以大补 \n药数日，死肉脱去而愈。陈工部，患发背已四五日，疮头虽小，根畔颇大，以隔蒜灸三十余 \n壮，其根内消。惟疮头作脓，数日而愈。 \n余丙子年忽恶心，大锥骨甚痒，须臾，臂不能举，神思甚倦，此夭疽危病也。急隔蒜灸 \n之，痒愈甚。又明灸五十余壮，痒遂止，旬日而愈。《精要》云，灸法有四生之功，信矣。（薛按） \n史氏引证曰∶疡医常器之，于甲戌年，诊太学史氏之母，云内有蓄热，防其作疽。至辛 \n巳六月，果背胛微痒，疮粒如黍，灼艾即消，隔宿复作，用膏药覆之，晕开六寸许，痛不可 \n胜，归咎于艾。适遇一僧，自云病疮甚危，尝灸八百余壮方苏。遂用大艾壮如银杏者，灸疮 \n头及四傍各数壮，痛止。至三十余壮，赤晕悉退。又以艾作团，如梅杏大者四十壮，乃食粥 \n安寝，疮实四寸，小窍百许，患肉俱坏而愈。立斋曰∶灼艾之法，必使痛者灸至不痛，不痛 \n者灸至痛，则毒必随火而散。否则非徒无益，而反害之。 \n愚意，痈疽为患，无非血气壅滞留结不行之所致，凡大结大滞者最不易散，必欲散之，非 \n藉火力不能速也，所以极宜用灸。然又有孙道人神仙熏照方，其法尤精尤妙。若毒邪稍缓， \n邪深经远，而气有不达，灸之为良。若毒邪炽盛，其势猛急，而垂危者，则宜用熏照方，更胜于灸。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>脓针辨（十二）\n\n属性：齐氏曰∶若发肿都软而不痛者，血瘤也。发肿日渐增长而不大热，时时牵痛者，气瘤也 \n。气结微肿，久而不消，后亦成脓，此是寒热所为也。留积经久，极阴生阳，寒化为热，以 \n此溃者，必多成 ，宜早服内塞散以排之。又凡察痈疽，以手掩其上，大热者，脓成自软也 \n。若其上薄皮剥起者，脓浅也。其肿不甚热者，脓未成也。若患瘰 结核，寒热发渴，经久 \n不消，其人面色痿黄者，被热上蒸，已成脓也。至于脏腑肠胃内疮内疽，其疾隐而深藏，目 \n既不见，手不能近，所为至难，但以诊脉而辨之，亦可知也。有患胃脘痈者，当候胃脉。胃脉 \n者，人迎也。其脉沉数，气逆则甚，甚则热聚胃口，而胃脘为痈也。若其脉洪数者，脓已成 \n也。设脉迟紧，虽脓未就，已有瘀血也。宜急治之。不尔，则邪气内攻，腐烂肠胃，不可救 \n也。又《肺痈论》曰∶始萌则可救，脓成即死，不可不慎也。久之，咳脓如粳米粥者，不治 \n。呕脓而止者，自愈也。又《肠痈论》曰∶或绕脐生疮，脓从疮出者，有出脐中者，惟大便 \n下脓血者，自愈也。 \n伍氏曰∶疮肿赤色，按之色不变者，此脓已成也。按之随手赤色者，其亦有脓也。按之 \n白色良久方赤者，此游毒已息，可就赤白尽处灸断，赤肿自消。凡痈疽以手按之，若牢硬未 \n有脓也，若半软半硬已有脓也。又按肿上不热者，为无脓。热甚者，为有脓，宜急破之。 \n立斋曰∶疮疡之证，毒瓦斯已结者，但可补其气血使脓速成。脓成者，当验其生熟浅深， \n视其可否，针而去之。不可论内消之法。小按便痛者，脓浅也。大按方痛者，脓深也。按之 \n不复起者，脓未成也。按之即复起者，脓已成也。脓生而用针，气血既泄，脓反难成。脓熟 \n而不针，则腐溃益深，疮口难敛。若疮深而针浅，内脓不出，外血反泄。若疮浅而针深，内 \n脓虽出，良肉受伤。若元气虚弱，必先补而后针，勿论尻神，其脓一出，诸证自退，若脓出 \n而反痛，或烦躁呕逆，皆由胃气亏损也。宜急补之。若背疮热毒炽盛，中央肉黯，内用托里 \n，壮其脾胃，外用乌金膏涂于黯处。其赤处渐高，黯处渐低，至六七日间赤黯分界，自有裂 \n纹，如刀划然，黯肉必渐溃矣。当用 针利剪徐徐去之，须使不知疼痛，不见鲜血为妙。 \n若 \n虽有裂纹，脓未流利，及脓水虽出而仍痛者，皆未通于内，并用针于纹中引之。若患于背胛 \n之间，凡人背近脊处并胛，皮里有筋一层。患此处者，外皮虽破，其筋难溃，以致内脓不出 \n，令人胀痛苦楚，气血转虚，变证百出。若待自溃，多致不救，必须开之引之，兼以托里。 \n常治此证，以利刀剪之，尚不能去，似此坚物，待其自溃，不反甚乎。此非气血壮实者，未 \n见其能自溃也。若元气虚弱而误服克伐，患处不痛，或肉将死，急须温补脾胃，亦有生者。 \n后须纯补之药，庶可收敛。若妄用刀针，去肉出血，则气血愈虚愈伤矣，何以生肌收敛乎。 \n大凡疮疡脓即溃，当大补血气为先，须有他证，当以未治。 \n又曰∶凡疮不起者，托而起之；不成脓者，补而成之，使不内攻。脓成则及时针之，不 \n数日即愈矣。常见患者皆畏针痛而不肯用，又有恐伤肉而不肯用，殊不知疮虽发于肉薄之所 \n，若其脓成必肿高寸余，疮皮又浓分许，用针深不过二分。若发于背，必肿高二三寸，入 \n针只于寸许。况患者肉既已坏，何痛之有。何伤之虑。凡怯弱之人，或患附骨等疽，待脓自 \n通，以致大溃不能收敛，气血沥尽而已者为多矣。 \n又曰∶凡疮既成脓，皮肤不得疏泄，昧者待其自穿，殊不知少壮而充实者，或能自解， \n若老弱之人，气血枯槁，或兼攻发太过，不行针刺，脓毒乘虚内攻，穿肠腐膜，鲜不误事。 \n若毒结四肢，砭刺少缓，则腐溃深大，亦难收敛。毒结于颊项胸腹紧要之地，不问壮弱，急 \n宜针刺，否则难治。如沈氏室、黄上舍等，皆以此而殁者多矣。大抵疮疡之证，感有轻重， \n发有深浅，浅者肿高而软，发于血脉，深者肿下而坚，发于筋骨，然又有发于骨髓者，则皮 \n肉不变。故古人制法，浅宜砭而深宜刺，使瘀血去于毒聚之始，则易消。若脓成之时，气血 \n壮实者，或自出，怯弱者，不行针刺，鲜有不误。凡疮疡透膜，十无一生，虽以大补药治之 \n，亦不能救，此可为待脓自出之戒也。故东垣云∶毒瓦斯无从而解，脓瘀无从而泄，过时不烙 \n，反功于内，内既消败，欲望其生，岂可得乎。兹举一二以告同道，并使患者知所慎云。 \n又曰∶凡患疮疽，虽因积热所成，若初起未成脓，脉洪数，乃阴虚阳亢之证。若脓溃于 \n内，不得发泄于外，身必发热，故脉见洪数，乃痈疽之病进也。脓既去则当脉静身凉，肿消 \n痛息，如伤寒表证之得汗也。若反发热作渴，脉洪数者，此真气虚而邪气实，死无疑矣。 \n又曰∶若治元气不足之证，即其初患，盒饭用参 归术，温补脾胃，外用桑枝葱熨，接 \n补阳气，使自消散。若久而不能成脓者，亦用前二法，补助以速之。若脓既成而不溃，用艾 \n于当头灸数炷以出之，却服十全大补汤。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>论针法（十三）\n\n属性：上古有砭石之制，《内经》有九针之别，制虽不同，而去病之意则一也。且疮疡一科， \n用针为贵。用之之际，虽云量其溃之浅深，尤当随其肉之浓薄。若皮薄针深，则反伤良肉， \n益增其溃。肉浓针浅，则脓毒不出，反益其痛。用针者，不可不慎哉。至于附骨疽，气毒流 \n注，及有经久不消，肉溃不痛者，宜燔针开之。若治咽喉之患，当用三棱针。若丹瘤及痈 \n毒四畔 赤疼痛如灼，宜用砭石去血，以泄其毒，则重者轻，轻者消。如洪氏室患腹痈，脓 \n胀闷瞀，以卧针刺脓出即苏。一人患囊痈，脓熟肿胀，小便不利，几殆，急针之，脓水大泄 \n，气通而愈。大抵用针之法，迎而夺之，顺而取之，所谓不治已成，治未成，正此意也。今 \n之患者，畏针而不用，医者又徇患者之意而不针，遂至脓已成而不得溃，或得溃而伤已深矣 \n，卒之夭枉者十常八九，亦可悲矣。见《外科心法》 \n经曰∶天温日明，则人血淖溢，而卫气浮，故血易泄，气易行。天寒日阴，则人血凝涩 \n，而卫气沉。是以因天时而调血脉也。故凡遇天寒水冰，或阴气凝滞之时，欲行针刺，则先 \n当温衣覆盖，或以艾叶炒热，或热盥热衣类，先熨其处，务令血脉温和，而后刺之，则血泄 \n气行，其病立已。若血寒脉涩，遽尔用针，则邪毒不泻，徒伤良肉，反以益其病也。 \n立斋曰∶凡元气虚弱者，必当补助脾胃，禁用刀针，若妄用之，而去肉去血，便阳随阴 \n散，是速其危也。 \n薛按曰∶四明有屠寿卿者，当门齿，忽如所击，痛不可忍，脉洪大而弦。余曰，弦洪相 \n搏，将发疮毒也。先用清胃散加白芷、银花、连翘一剂，痛即止。至晚鼻上发一疮，面肿黯 \n痛，用前药加犀角一剂，肿至两额，口出秽气，脉益洪大，恶寒内热。此毒炽血瘀，药力不 \n能敌也。乃数砭患处，出紫血，服犀角解毒之药。异日肿痛尤甚。又砭患处与唇上，并刺口 \n内赤脉，各出毒血，再服前药，至数剂而愈。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>用针勿忌FS神（十四）\n\n属性：立斋曰∶针灸之法，有太乙人神，周身血忌，逐年FS 神，逐日人神。而其穴有禁针禁灸 \n之论。犯者，其病难瘳，理固然也。但疮疡气血已伤，肌肉已坏，急宜迎而夺之，顺而取之 \n，非平人针灸之比，何忌之有。《外科精义》云∶疮疡之证，毒瓦斯无从而解，脓瘀无从而泄 \n，反攻于内，内既消败，欲望其生，岂可得乎。危恶之证，发于致命之所，祸在反掌。腹痈 \n囊痈，二便不通，胸腹胀闷，唇疔喉痹，咽喉肿塞，其祸尤速，患者审之。 \n邻人苏子遇之内，左手指患疔，麻痒寒热恶心，左半体皆麻，脉数不时见。余曰，凡疮 \n不宜不痛，不宜大痛，烦闷者不治，今作麻痒尤其恶也。用夺命丹二服不应，又用解毒之剂 \n，麻痒始去，乃作肿痛。余曰，势虽危，所喜作痛，但毒瓦斯无从而泄，欲针之。适值望日， \n其家俱言FS 神不从，势愈肿甚。余强针之，诸证顿退，又用解毒之剂，其疮乃愈。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>围药（十五）\n\n属性：《内经》云∶五脏不和，九窍不通，六腑不和，则留结为痈。又云∶形伤痛，气伤肿。此 \n则脏腑不和，而疮发于外也，明矣。若涂贴寒凉，岂能调合脏腑，宣通气血耶。若其肿痛热渴 \n，脉滑数而有力，证属纯阳者，宜内用济阴汤，外用抑阳散，则热毒自解，瘀滞自散。若似 \n肿非肿，似痛非痛，似溃不溃，似赤不赤，脉洪数而无力，属半阴半阳者，宜内用冲和汤， \n外用阴阳散，则气血自和，瘀滞自消。若微肿微痛，或色黯不痛，或坚硬不溃，脉虽洪大， \n按之微细软弱，属纯阴者，宜内服回阳汤，外敷抑阴散，则脾胃自健，阳气自回也。丹溪曰 \n∶敷贴之剂，应酬轻小热证耳。若不辨其阴证阳证之所由分，而妄敷寒凉之剂，则迷塞腠理 \n，凝滞气血，毒反内攻，而肉反死矣。况运气得寒而不健，瘀血得寒而不散，败肉得寒则不 \n溃，新肉得寒则不生，治者审焉。（见《外科枢要》） \n立斋曰∶大抵疮之起发溃敛，皆血气使然，各人元气虚实不同，有不能发出而死者，有 \n发出不能成脓而死者，有成脓不能腐溃而死者，有腐溃不能收敛而死者。敷贴之法，但可应 \n酬轻小之证耳。若血气已竭，其患必死，不但敷贴不效，且气血喜温而恶寒，腠理喜通而恶 \n塞，气血因而愈滞，肿患因而愈盛，邪气因而愈深，腐溃因而愈大，怯弱之人取败多矣。况 \n疮疡乃七情相火，或食膏梁，或饵金石，以伤阴血，阳盛阴虚，受病于内而发于外。若不别 \n气分血分，阴阳虚实，腐溃浅深，即服药，尚有不能保生者，可敷贴而已乎。 \n施二守，项右患一核，用凉药敷贴，颈皆肿。又敷之，肿胤胸腋，冷应腹内，不悟凉药 \n所致，尚以为毒盛。形体困惫，自分不起，延余治之。见其敷药处热气如雾，急令去药，良 \n久疮色变赤，刺出脓血，用托里药而愈。 \n张侍御，发背，专用敷药，疮黯不起，胸膈闷气，不能呼吸，自分不治，余用辛温托里 \n药而愈。 \n一男子，臀痈腐溃，肌肉不生，用药敷之，肌肉四沿反硬。予诊之，脉涩而弱，此气血 \n俱虚，不能营于患处，故敷凉药反硬，乃血气受寒凝结而非毒也。用大补药而愈。 \n一男子，患胸疽，肿高作痛，肿处敷药，痛虽止，而色变黯，肿外作痛。仍敷之，肉色 \n亦黯，喉内作痛。不悟此为凉药所误，反尽颈敷之，其颈皆溃而死。 \n一男子，因怒左胁肿一块，不作痛，脉涩而浮。余曰，此肝经邪火炽盛，而真气不足为 \n患，宜培养血气为主。彼以草药敷贴，遂致不救。 \n王安人，发背正溃时，欲速效，敷以草药，即日而死。 \n张宜人，年逾六十，患发背三日，肉色不变，头如粟许，肩背肿，脉洪数，寒热饮冷。 \n予以人参败毒散二剂，及隔蒜灸五十余壮，毒大发，背始轻。再用托里药渐溃，因血气虚甚 \n而作渴，用参 归熟等药，而渴亦止。彼欲速效，乃自用草药罨患处，毒瓦斯复入，遂不救。 \n（薛按） \n凡痈疡肿痛，宜用围药敷治者，惟降痈散为第一，无论阴毒阳毒，皆所宜也。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>腐肉（十六）\n\n属性：齐德之曰∶夫疮疡生于外，皆由积热蕴于内。《内经》谓血热肉败，荣卫不行，必将为 \n脓，留于节腠，必将为败。盖疮疽脓溃之时，头小未破，疮口未开，或毒瓦斯未出，疼痛难忍 \n，所以立追蚀腐溃之法，使毒瓦斯外泄而不内攻，恶肉易去，好肉易生也。若 其疮血出不止 \n者，则未可 ，于疮上掺追蚀之药，待其熟，可 方 。若 其疮而痛应心根者，亦不可强 \n之。误触其疮， 痛必倍，变证不测，不可不慎也。若疮疖脓成未破，于上薄皮剥起者， \n即当用破头代针之剂安其上，以膏贴之。脓出之后，用搜脓化毒之药，取效如神矣。若脓血 \n未尽，便用生肌敛疮之剂，欲其早愈，殊不知恶肉未尽，其疮早合，后必再发。不可不慎也。 \n立斋曰∶疮疡之证，脓成者，当辨其生熟浅深。肉死者，当验其腐溃连脱。余尝治脉证 \n虚弱者，用托里之药，则气血壮而肉不死。脉证实热者，用清热之剂，则毒瓦斯退而肉自生。 \n凡疮聚于筋骨之间，肌肉之内，皆因血气虚弱，用十全大补汤壮其脾胃，则未成者自解，已 \n成者自溃，又何死肉之有。若不大痛，或大痛，或不赤，或内脓不溃，或外肉不腐，乃血气 \n虚弱，宜用桑枝灸，及十全大补加姜桂，壮其阳气，则四畔即消，疮头即腐，其毒自散，又 \n何待于针割。若脾胃虚弱，饮食少思，用六君倍加白术，壮其营气，则肌肉受毒者自溃，已 \n死者自活，已溃者自敛。若初起或因克伐，或犯房事，以致色黯而不痛者，乃阳气脱陷， \n变为阴证也。急用参附汤，温补回阳，亦有可生。 \n又曰∶夫腐肉者，恶肉也。大凡痈疽疮肿溃后，若有腐肉凝滞者，必取之，乃推陈致新 \n之意。若壮者筋骨强盛，气血充溢，真能胜邪，或自去，或自平，不能为害。若年高怯弱之 \n人，血液少，肌肉涩，必迎而夺之，顺而取之，是谓定祸乱以致太平。设或留而不去，则有 \n烂筋腐肉之患。如刘大尹、汪夫人，收之及时，而新肉即生，得以全愈；金工部、郑挥使 \n，取之失期，大溃而毙。予尝见腐肉既去，虽少壮者，不补其气血，尚不能收敛；若怯弱者 \n，不取恶肉，不补血气，未见其生也。故古人曰∶坏肉恶于野狼虎，毒于蜂虿，缓去之则戕 \n贼性命。信哉。 \n又曰∶疮疡之证，若毒瓦斯已结，肿赤炽盛，中央肉死黯黑者，内用托里健脾之剂，外用 \n乌金膏涂之，则黯处渐低，赤处渐起。至六七日间，赤黯之界自有裂纹，如刀划状，其黯渐 \n溃。若用铍针利剪徐去犹好。须使不知疼痛，不见鲜血为善。若脓未流利，宜用针于纹中引 \n之。若脓水已出，肿痛仍作，乃内筋间隔，亦用针引之。若元气虚弱，误服克伐之剂，患处 \n不痛，或肉死不溃者，急温补脾胃，亦有复生者。后须纯补脾胃，庶能收敛。此则不可妄用 \n针刀，若误用之以去肉出血，使阳随阴败，是速其危也。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>腐肉（十六）\n\n属性：针头散（外一四四去腐管） \n代针膏（一四五溃头） \n透骨丹（外一四三溃头） \n猪蹄汤（外一二五洗腐） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>舍时从证（十七）\n\n属性：立斋曰∶经云∶诸痛痒疮，皆属于心。若肿赤烦躁，发热大痛，饮冷便秘作渴，脉洪数 \n实者，为纯阳，虽在严冬之时，必用大苦寒之剂，以泻热毒。若不肿不痛，脉细皮寒，泻利 \n肠鸣，饮食不入，呕吐无时，手足厥冷，是为纯阴，虽在盛暑之时，必用大辛温热之剂，以助 \n阳气。不拘严寒盛暑，但当舍时从证。若微肿微痛，似溃不溃，时出清脓者，为半阴半阳， \n宜用辛热之剂，温补胃气，此亦治阴阳法也。经曰∶用寒远寒，用热远热，有假者反之。虽 \n违其时，必从其证。若执常法，无不误矣。壬午仲冬，金台一男子患腹痛，误服干姜理中丸， \n实时口鼻出血，烦躁发狂，入井而死。辛卯冬，一吏患伤寒，误服附子药一钟，下咽发躁， \n奔走跌死。夫盛暑之际，附子姜桂三药并用，连进三四剂无事；严冬时令，三药单用一味， \n止进一剂者，即死。可见罗谦甫先生有舍时从证，权宜用药之妙。余宗此法，凡冬间疮证， \n如脉沉实洪数，大便秘，疮 痛，烦躁，或饮冷不绝者，即用硝黄芩连之剂攻之。虽在夏令 \n而脉见虚弱，或浮大，疮不溃，脓清稀，恶寒饮者，即用姜桂参 之剂补之。如脉见沉细， \n疮不溃不痛作呃逆，手足冷，大便不实，或泻利，或腹痛，更加附子，皆获大效。昧者反以 \n为非，惑乱患人。恪守常法，必使冬用温热，夏用清凉，以致误人，深可哀也。（薛按） \n至元壬午五月二十八日，王伯禄年逾五旬有七，右臂膊肿甚，上至肩，下至手指，色变 \n皮肤凉，六脉沉细而微，此乃脉证俱寒。余与疡医孙彦和视之曰，此乃附骨痈，开发已迟， \n以燔针启之，脓清稀解。次日肘下再开之，加呃逆不绝。彦和以丁香柿蒂散两剂，稍缓。次 \n日，呃逆尤甚，自利，脐腹冷痛，腹满，饮食减少，时发昏愦。于左乳下黑尽处，灸二七壮 \n，又处托里温中汤，用干姜、附子、木香、沉香、茴香、羌活等药， 咀一两半，欲与服。 \n或者曰∶诸痛痒疮，疡皆属心火，又当盛暑之时，用干姜附子可乎。予应之曰∶理所当然，不得 \n不然。《内经》曰∶脉细皮寒，泻利前后，饮食不入，此谓五虚。况呃逆者，胃中虚寒故也 \n。诸痛痒疮，皆属心火，是言其定理也。此证内外相反，须当舍时从证，非大方辛热之剂急 \n治之，则不能愈也。遂投之，诸证悉去，饮食倍进，疮势温，脓色正。彦和复用五香汤数服 \n，后月余平复。噫。守常者，众人之见，知变者，知者之能。知常不知变，因细事而取败者 \n，亦多矣，况乎医哉。（见罗氏《卫生宝鉴》） \n愚意，罗先生以舍时从证之法，垂训后人，诚百世不磨之要道也。但时之迁变，本所难 \n知，而证之幽显，尤不易识。何也。盖常人之所谓时者，春夏秋冬之时也，岁岁时常之主气 \n也，谁不得而知之。而不知五六周环，则长夏有寒淫之令，三冬有炎暑之权，此则虽若舍时 \n，而实以从时，昧者固能知此乎。又如察证之法，则凡脉细皮寒，泄泻厥冷之类，是皆已见 \n之寒证也，又谁不得而知之。不知其来有源，其甚有渐，即诸证未见之前，而本来已具，此 \n际便难错认，使必待焦头烂额，而后曲突徙薪，则已晚矣。此罗先生之所以明已然，而余则 \n更为虑未然，盖恐人之见之迟，而无及于事也。虽然余常见今人之于已然者尚不能见，而复 \n欲其见未然，诚哉迂矣。然余慨然之念，则不能不道其详，而深望于知音者。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>阳气脱陷（十八）\n\n属性：立斋曰∶疮疡阳气脱陷，或因克伐之剂，或因脓血大泄，或因吐泻之后，或因误以入房 \n。大凡溃后劳后，元气亏损，或梦遗精脱，或脉数便血，或外邪乘虚而入，以致发热头痛， \n小便淋涩，或目赤烦喘，气短头晕，体倦热渴，意欲饮水投水，身热憎寒恶衣，扬手掷足， \n腰背反张，郑声自汗，脉浮洪大，此无根虚火之假热证也。若畏寒头痛，咳逆呕吐，耳聩 \n目蒙，小便自遗，泻利肠鸣，里急腹痛，玉茎短缩，齿牙浮痛，肢体麻痹，冷汗时出，或厥冷 \n身痛，咬舌啮唇，舌本强硬，呃逆喘促，脉微沉细，此阳气脱陷之真寒证也。凡此危候，无 \n论脉证，但见有一二，急用参附汤，或用托里消毒散去连翘、白芷、金银花三味，急加桂附 \n大剂补之，多有复生者。 \n内翰杨皋湖，孟夏患背疽，服克伐之剂，二旬余矣，漫肿坚硬，重如负石，隔蒜灸五十 \n余壮，背遂轻，以六君加砂仁两剂，涎沫涌出，饮食愈少。此脾虚阳气脱陷也。剂用温补， \n反呕不食，仍用前药作大剂加附子姜桂，又不应。遂以参 各一斤，归术陈皮各半斤，附子 \n一两，煎服三日而尽，流涎顿止，腐肉顿溃，饮食顿进。再用姜桂等药，托里健脾，腐脱而疮愈矣。 \n少参史南湖之内，夏患疽，不起发，脉大而无力，发热作渴，自汗盗汗，用参 大补之 \n剂，益加手足逆冷，大便不实，喘促时呕，脉细微，按之如无，唯太冲不绝。仍以参、 \n、白术、当归、茯苓、陈皮，计斤许，加附子五钱，水煎二钟作一服，诸证悉退，脉息顿复 \n。翼日疮起而溃，仍用前药四剂后，日用托里药，调理两月余而愈。（薛按） \n一妇人，于癸卯冬，失物发怒，缺盆内微肿，甲辰春，大如覆碗，左肩胛亦肿，肉色如 \n故。或针出鲜血三碗许，腹痛如锥，泄泻不止，四肢逆冷，呕吐恶寒，或时发热，绝食已七 \n日矣。其脉洪大，时或微细，此阳气脱陷也。用六君加炮姜三钱、附子二钱，早服至午，不 \n应。再剂加附子五钱，熟睡觉来，诸证顿退六七，可进稀粥。再四剂，诸证悉退，饮食如故 \n，缺盆始痛。针出清脓二碗许，诸证复生，此虚极也。以十全大补加姜、桂、附各一钱，三 \n剂而安。后减姜、附各五分，与归脾汤兼服五十余剂而愈。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>温补按则（十九）\n\n属性：留都郑中翰，仲夏患发背，已半月。疮头十余枚，皆如粟许，漫肿坚硬，根如大盘，背 \n重如负石，即隔蒜灸五十余壮，其背顿轻，彼因轻愈，不守禁忌，三日后大作，疮不起发， \n但苦作痛。用活命饮四剂，势少退。用香砂六君子汤四剂，饮食少进。彼恃知医，自用败毒 \n药二剂，饮食益少，口流涎沫，若不自知，此脾虚之甚也。每用托里药加参 各三钱，彼密 \n自拣去大半，后虽用大补药加姜桂亦不应。遂令其子，以参 各一斤，归术各半斤，干姜、 \n桂、附各一两，煎膏一罐，三日饮进，涎顿止，腐顿溃，食顿进，再用托里健脾药，腐肉自 \n脱而愈。（下俱薛按） \n张侍御，患背疮三枚，皆如粟，彼以为小毒，服清热化痰药，外用凉药贴敷，数日尚 \n不起，色黯不 ，胸中气不得出入，势甚可畏。连用活命饮二剂，气虽利，脓清稀，疮不 \n起。欲用补剂，彼泥于素有痰火，不受参术之补。因其固执，遂阳以败毒之剂与视之，而阴以 \n参归术各五钱，姜桂各二钱，服二剂，背觉热，腐肉得溃，方信余言，始明用大补药乃愈。 \n南都聂姓者，时六月患发背，腐肉已去，疮口尺许，色赤 肿，发热不食，欲呕不呕， \n服十宣散等药，自为不起，请余决之。其脉轻诊则浮而散，重诊则弱而涩，此溃后之正脉。 \n然疮口开张，血气虚也。欲呕不呕，脾胃虚也。色赤 肿，虚火之象也，尚可治。遂与十全 \n大补汤加酒炒黄柏、知母、五味、麦冬，及饮童便，饮食顿进，肌肉顿生。服至八剂，疮口 \n收如粟许。又惑于人言，谓余毒未尽，乃服消毒药二剂，复发热昏愦，急进前药，又二十余 \n剂乃愈。后两月，因作善事，一昼夜不睡，以致劳倦发热，似睡不睡。与前汤二剂，更加发 \n热，饮食不进，惟饮热汤后，以前药加附子一钱，二剂复愈。 \n高秋官贞甫，孟秋发背，色黯而硬，不痛不起，脉沉而细，四肢逆冷，急用大艾隔蒜灸 \n三十余壮，不痛。遂用艾如粟大者，着肉灸七壮，乃始知痛。与六君子汤二剂，每剂入附子 \n二钱，不应。后剂又加肉桂二钱，始应而愈。 \n一男子，胁肿一块，日久不溃，按之微痛，脉微而涩，此形证俱虚也。经曰∶形气不足 \n，病气不足，当补不当泻。予以人参养营汤治之，彼不信，乃服流气饮。虚证悉至，方服前 \n汤。月余少愈。但肿处尚硬，以艾叶炒热熨患处，至十日余日脓成。以火针刺之，更灸以豆豉饼 \n，又服十全大补汤，百剂而愈。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>定痛（二十）\n\n属性：齐氏曰∶疮疽之证候不同，凡寒热虚实，皆能为痛，故止痛之法，殊非一端。世人皆谓 \n，乳没珍贵之药，可住疼痛，而不知临病制宜，自有方法。盖热毒之痛者，以寒凉之药折 \n其热，而痛自止也。寒邪之痛，以温热之剂熨其寒，则痛自除也。因风而痛者，除其风。因 \n湿而痛者，导其湿。燥而痛者，润之。塞而痛者，通之。虚而痛者，补之。实而痛者，泻之 \n。因脓郁而闭者，开之。恶肉侵溃者，去之。阴阳不和者，调之。经络秘涩者，利之。临机 \n应变，方为上医，不可执方而无权也。 \n立斋曰∶疮疡之作，由六淫七情所伤。其痛也，因气血凝滞所致。假如热毒在内，便秘 \n而作痛者，内疏黄连汤导之。热毒炽盛， 肿而作痛者，黄连解毒汤治之。不应，仙方活 \n命饮解之。瘀血凝滞而作痛者，乳香定痛丸和之。作脓而痛者，托里消毒散排之。脓胀而痛者 \n，针之。脓溃而痛者，补之。若因气虚而痛，四君加归 。血虚而痛，四物加参 。肾虚而 \n痛，六味地黄丸。口干作渴，小便频数者，加减八味丸。此皆止痛之法也，慎勿概用寒凉之 \n药。况血气喜温而恶寒，若冷气入里，血即凝滞，反为难瘥之证矣。丹溪云∶脓出而反痛， \n此为虚也，宜补之。秽气所触者，和解之。风寒所逼者，温散之。若专用龙竭生肌，乳没止 \n痛，吾知其必无效也。 \n凡痈毒 肿赤痛之甚者，虽内治之法已具如前，然煎剂功缓，而痛急难当者，必须外 \n用敷药，既欲其止痛，又欲其散毒，则无如降痈散之神妙也。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>生肌收口（附成漏证二十一）\n\n属性：陈良甫曰∶痈疽之毒有浅深，故收敛之功有迟速，断不可早用收口之药。恐毒瓦斯未尽， \n后必复发，为患匪轻。若痈久不合，其肉白而脓少者，此气血俱虚，不能潮运，而疮口冷涩 \n也。每日用艾叶一把煎汤，避风热洗，及烧松香烟熏之，或用猪蹄汤洗之，更以神异膏贴之， \n必须守禁调理，否则不效。又曰∶脉得寒则下陷，凝滞肌肉，故曰留连肉腠，是为冷漏。须 \n温补之。 \n丹溪曰∶诸经惟少阳厥阴之生痈者，宜须防之，以其多气少血也。血少则肌肉难长，故 \n疮久未合，必成败证。苟反用驱利毒药，以伐其阴分之血，祸不旋踵矣。 \n立斋曰∶肌肉者，脾胃之所主。收敛者，血气之所使，但当纯补脾胃，不宜泛敷生肌之 \n剂。夫疮不生肌，而色赤甚者，血热也，四物加山栀、连翘。色白而无神者，气虚也，四君 \n加当归、黄 。晡热内热，阴血虚也，四物加参术。脓水清稀者，气血虚也，十全大补汤。 \n食少体倦，脾气虚也，补中益气汤。烦热作渴，饮食如常，胃火也，竹叶黄 汤。不应，竹 \n叶石膏汤。热渴而小便频数，肾水虚也，用加减八味丸料煎服。若败肉去后，新肉微赤，四 \n沿白膜者，此胃中生气也，但用四君子汤，以培补之，则不日自敛。若妄用生肌之药，余毒 \n未尽，而反益甚耳。殊不知疮疡之作，由胃气不调，疮疡之溃，由胃气腐化，疮疡之敛，由 \n胃气荣养。东垣云∶胃乃发生之源，为人生之本。丹溪亦谓，治疮疡当助胃壮气，使根本坚 \n固。诚哉是言也，可不慎欤。 \n又曰∶若肌肉伤，而疮口不敛，用六君子汤以补脾胃。若气虚恶寒而疮口不敛，用补中 \n益气汤以补脾肺。若血虚发热而疮口不敛，用四物参术以滋肝脾。若脓多而疮口不敛，用八 \n珍汤，或十全大补汤，以养血气。如不应，但用四君归 以补脾胃。更不应，乃属命门火衰 \n，急用八味丸以壮火生土。若脉数发渴者，难治，以真气虚而邪气实也。 \n又曰∶生肌之法，当先理脾胃助气血为主。若气血俱虚不能生者，当用托里之剂。若 \n有风寒袭于疮所不能生者，宜用豆豉饼灸之。若流注顽疮内有脓管，或瘀血，或 核，须用 \n针头散腐之，锭子尤妙。如背疮、杖疮、汤火疮大溃，当用神效当归膏，则能去腐生新止痛，大有神效。 \n又曰∶痈疽溃后，毒尽则肉自生。常见世之治者，往往用龙骨血竭之属以求生肌，殊不 \n知余毒未尽，肌肉何以得生。气血既虚，龙竭岂能得效。设若脓毒未尽，就用生肌，则反增 \n溃烂。壮者轻者不过复溃，或迟敛而已。怯者重者必致内攻，或溃烂不敛，反致危矣。 \n又曰∶凡疮疡成漏，皆因元气不足，营气不从。阳气虚寒，则寒气逆于肉里，稽留血 \n脉，腐溃既久，即成是患。故凡治不足之证，于其初患，盒饭内用参 归术，温补脾胃，外 \n用桑枝葱熨，接补阳气，使自消散。若久而不能成脓，亦用前二法，补助以速之。若脓既成 \n而不溃，用艾于当头灸数炷而出之，却服十全大补汤。患者又当慎起居，节饮食，庶几收敛 \n。若用冷针开刺，久而内出清脓，外色黑黯。或误用生肌散，速其口敛，反束其邪，必成败证。 \n诸疮患久成漏，常有脓水不绝，其脓不臭，若无歹肉者，法用炮附子去皮尖，为细末， \n以唾津和为饼，如三钱浓，安疮上，以艾炷灸之。漏大艾亦大，漏小艾亦小，但灸令微热， \n不可令痛。干则易之，每灸一二十壮不论，灸后贴以膏药。隔二三日，又如前再灸，更服大 \n补气血之药，直至肉平为度。或用炮附子切片三分浓灸之亦可。或用江西淡豆豉为饼，多灸之亦效。 \n若疮久成漏，外有腐肉，内有脓管，不能收口者，以针头散和 \n作细条， 入口内，外用膏药贴之，待脓管尽去，自然渐平收口。或先用灸法，数日后用 \n此药亦可，仍内服十全大补等药。 \n郭氏灸法，疮疽久不收敛，及有脓水恶物，渐溃根深者，用白面、硫黄、大蒜三物，一 \n处捣烂，看疮大小捻作饼子，浓约三分，安于疮上，用艾炷灸二十一壮，一灸一易。后隔四 \n五日，用药锭针头散等药， 入疮内，歹肉尽去，好肉长平，然后贴收敛之药，内服应病 \n之剂，调理即瘥矣。 \n一男子，年逾二十，禀弱，左腿外侧患毒三月方溃，脓水清稀，肌肉不生，以十全大补 \n汤加牛膝，二十余剂渐愈。更以豆豉饼灸之，月余而痊。 \n一妇人，左臂结核，年余方溃，脓清不敛，一男子患贴骨痈，腿细短软，疮口不合，俱 \n用十全大补汤，外以附子饼及贴补药膏，调护得宜，百剂而愈。大凡不足证，宜大补之剂， \n兼灸以补接阳气，祛散寒邪为上。 \n京师董赐，年逾四十，胸患疮成漏，日出脓碗许，喜饮食如常，以十全大补汤加贝母、 \n远志、白蔹、续断，灸以附子饼，脓渐少，谨调护岁余而愈。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>用香散药（二十二）\n\n属性：伍氏曰∶气血闻香则行，闻臭则逆。大抵疮疡多因营气不从，逆于肉理，故郁聚为脓， \n得香散药则气流行，故当多服五香连翘汤、万金散、清心内固金粉散。凡疮本腥秽，又闻臭 \n，浊则愈甚。若毒瓦斯入胃，则为咳逆。古人用此，可谓有理，且如饮食调令香美，则益脾土 \n，养真元，保其无虞矣。 \n立斋曰∶今人有疮疡，不审元气虚实，病之表里，病者多喜内消，而医者即用十宣散及 \n败毒散、流气饮之类。殊不知十宣散，虽有参 ，然防风、白芷、浓朴、桔梗，皆足以耗气 \n，况不分经络时令气血多少，而概用之乎。败毒散乃发表之药，果有表证，亦止宜一二服， \n多则元气反损，其毒愈盛，虽有人参莫能补也，况非表证而用之乎。流气饮乃耗血之剂，果 \n气结膈满，亦止宜二三服，多则血气愈伤。夫血气凝滞，多因荣卫气弱，不能营运，岂可 \n用流气饮以益其虚。况诸经气血多寡不同，而流气饮通行十二经，则诸经皆为所损，反为败 \n证。虽有芎归亦难倚伏。若服之过度，则气虚血耗，何以成脓。苟不察其由，而泛投克伐之 \n剂，能无危乎。此三药者，其不可轻用亦明矣。河间云∶凡疮止于一经，或兼二经者，止当 \n求责其经，不可干扰余经也。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>槐花酒（二十三）\n\n属性：槐花，治湿退热之功，最为神速。大抵肿毒，非用蒜灸及槐花酒先去其势。虽用托里诸 \n药，其效未必甚速，惟胃寒之人，不可过用。 \n滁洲于侍御，髀胛患毒痛甚，服消毒药其势未减。即以槐花酒一服，势逐大退。再以托 \n里消毒之药而愈。 \n王通府，患发背十余日，势危脉大。先以槐花酒二服，杀退其势，更以败毒散二剂，再 \n以托里药数剂渐溃。又用桑柴燃灸患处，每日灸良久，仍以膏药贴之。灸至数次，脓溃腐脱 \n，以托里药加白术、陈皮，月余而愈。 \n刘大尹，发背六七日，满背肿痛，势甚危。与隔蒜灸百壮，饮槐花酒二碗，即睡觉。以 \n托里消毒药十去五六，令以桑枝灸患处而溃，数日而愈。 \n一上舍，肩患疽，脉数。以槐花酒一服，势顿退。再与金银花、黄 、甘草，十余服而平。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>忍冬酒（二十四）\n\n属性：忍冬酒，治痈疽发背，初发时盒饭服此，不问疽发何处，或妇人乳痈，皆有奇效。如或 \n处乡落贫家，服此亦便且效。仍兼以麦饭石膏，及神异膏贴之，甚效。 \n一园丁，患发背甚危，令取金银藤五六两捣烂，入热酒一钟，绞取酒汁温服，相罨患 \n处，四五服而平。彼用此药治疮，足以养身成家，遂弃园业。诸书云∶金银花治疮疡未成者 \n即散，已成者即溃，有回生之功。 \n一男子患脑痈，其头数多，痛不可忍，先服消毒药不应，更以忍冬酒服之，即酣睡觉， \n而势去六七，再四剂而消。又一男子所患尤甚，亦令服之，肿痛顿退，但不能平。加以黄 \n、当归、栝蒌仁、白芷、甘草书、桔梗，数剂而愈。 \n一男子被鬼击身，有青痕作痛，以金银花煎汤，饮之即愈。《本草》谓此药大治五种飞 \n尸，此其验也。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>肿疡（二十五）\n\n属性：立斋曰∶肿高 痛脉浮者，邪在表也，宜托之。肿硬痛深脉沉者，邪在里也，宜下之 \n。外无 肿，内则便利调和，邪在经络也，当调营卫。 肿烦躁，或咽干作渴者，宜降 \n火。 肿发热，或拘急，或头痛者，邪在表也，宜散之。大痛或不痛者，邪气实也，隔蒜 \n灸之，更用解毒。烦躁饮冷， 痛脉数者，邪在上也，宜清之。恶寒而不溃者，气虚而兼 \n寒邪也，宜宣而补之。 痛发热，汗多大渴，便结谵语者，结阳证也，宜下之。不作脓， \n或熟而不溃者，虚也，宜补之。 \n又曰∶大抵痈肿之证，不可专泥于火为患，况禀有虚实，及老弱不同，岂可概用寒凉之 \n药。设若毒始聚，势不盛者，庶可消散。尤当推其病因，别其虚实。若概用凉药，必致误事 \n。如脓将成，邪盛气实者，用消毒之剂先杀其毒，虽作脓不为大苦，溃亦不甚。若就用托里 \n，必益其势。如脓将成不成，及不溃者，方用托里。脓成势盛者，针之，脓一出，诸证悉退矣。 \n丹溪曰∶肿疡内外皆壅，宜以托里表散为主，如欲用大黄，宁无孟浪之非。溃疡内 \n外皆虚，宜以补接为主，如欲用香散，未免虚虚之失。 \n愚意，前论肿疡，有云忌补宜下者，有云禁用大黄者，此其为说若异，而亦以证有不同 \n耳。盖忌补者，忌邪之实也。畏攻者，畏气之虚也。即如肿疡多实，溃疡多虚，此其常也 \n。然肿疡亦多不足，则有宜补不宜泻者，溃疡亦或有余，则有宜泻不宜补者，此其变也。或 \n宜补或宜泻，总在虚实二字。然虚实二字，最多疑似，贵有定见。如火盛者，宜清者也。气 \n滞者，宜行者也。既热且壅，宜下者也。无滞无壅，则不宜妄用攻下，此用攻之宜禁者也 \n。至若用补之法，亦但察此二者。凡气道壅滞者，不宜补火。邪炽盛者，不宜温。若气道无 \n滞，火邪不甚，或饮食二便清利如常，而患有危险可畏者，此虽未见虚证，或肿疡未溃，亦 \n宜即从托补。何也。盖恐困苦日久，无损自虚。若能预固元气，则毒必易化，脓必易溃，口 \n必易敛，即大羸大溃，犹可望生。若必待虚证叠出，或既溃不能收敛，而后勉力支持，则轻 \n者必重，重者必危，能无晚乎。此肿疡之有不足也，所系非细不可不察。 \n向予长男生，在癸丑及乙卯五月，甫及二周，而患背疽。初起时，背中忽见微肿。数日 \n后，按之则根深渐阔，其大如碗，而皮色不变，亦不甚痛。至十余日，身有微热，其势滋甚 \n，因谋之疡医。或云背疽，或云痰气，咸曰荤腥温补一毫不可入口。乃投以解毒之药一剂， \n而身反大热，神气愈困，饮食不进矣。予危惧之甚，因思丹溪有云∶痈疽因积毒在脏腑，当 \n先助胃气为主，使根本坚固，而以行经活血佐之。又曰∶但见肿痛，参之脉证，虚弱便与滋 \n补，气血无亏，可保终吉。是诚确论也。因却前医，而专固元气，以内托其毒。遂用人参三 \n钱，制附子一钱，佐以当归、熟地、炙甘草、肉桂之属，一剂而饮食顿进，再剂而神彩如旧 \n，抑何神也。由是弛其口腹，药食并进，十剂而脓成。以其根深皮浓，复用针出脓甚多，调 \n理月余而愈。向使倾信庸流，绝忌温补滋味，专意解毒，则胃气日竭，毒瓦斯日陷，饮食不进 \n，尚致透隔内溃，则万万不保矣。且此儿素无虚病，何敢乃尔。盖以其既属阴证，又无实邪 \n见有确真，故敢峻补脾肾，方保万全。呜呼。医之关系，皆是类也。因录此按，用告将来， \n以见肿疡溃疡，凡虚证未见而但无实热壅滞可据者，便宜托补如此，则其受益于不识不知， \n有非可以言语形容者。（新按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>肿疡不足（二十六）\n\n属性：汪太夫人，年逾八十，脑疽已溃，发背继生，头如粟米，脉大无力。此膀胱经湿热所致 \n，然脉大无力，乃血气衰也。遂以托里消毒散数服，稍可。更加参 之剂。虽疮起而作渴， \n此气血虚甚，以人参、黄 各一两，当归、熟地各五钱，麦冬、五味各一钱，数服渴止而愈 \n。此不有脏腑能言，气血能告，岂能省悟。病者至死，皆归于命，深可哀也。又有患者，气 \n质素实，或有痰不服补剂，然不知脓血内溃，气血并虚，岂不宜补。余常治疮，阴用参 大 \n补之剂，阳书败毒之名，与服之，俱不中满，疮亦随效。虚甚者，尚加姜桂，甚至附子，未 \n尝有不效也。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>溃疡（二十七）\n\n属性：立斋曰∶脓熟不溃者，阳气虚也，宜补之。瘀血不腐者，宜大补阳气，更以桑木灸之。 \n脓清不敛者，气血俱虚，宜大补。脓后食少无睡，或发热者，虚也，宜补之。倦怠懒言， \n食少不睡者，虚也，宜补之。寒气袭于疮口，不能收敛或陷下不敛者，温补之。脉大无力，或涩 \n微者，气血俱虚也，峻补之。出血或脓多，烦躁不眠者，乃亡阳也，急补之。 \n凡脓溃而清，或疮口不合，或聚肿不赤，肌寒肉冷，自汗色脱者，皆气血俱虚也，非补 \n不可。 \n凡脓血去多，疮口虽合，尤当补益。务使气血平复，否则更患他证，必难治疗也。 \n又曰∶大抵脓血大泄，当大补血气为先，虽有他证，以未治之。凡痈疽大溃，发热恶寒 \n，皆属气血虚甚。若左手脉不足者，补血药当多于补气药；右手脉不足者，补气药当多于补 \n血药，切不可发表。 \n大凡痈疽，全藉血气为主，若患而不起，或溃而不腐，或不收敛，及脓少或清，皆血气 \n之虚也，俱宜大补之，最忌攻伐之剂。亦有脓反多者，乃气血虚而不能禁止也。常见血气充实 \n之人患疮者，必肿高色赤，易腐溃而脓且稠，又易于收敛。怯弱之人，多不起发，不腐溃， \n及难于收敛。若不审察而妄投攻剂，虚虚之祸不免矣。及患后，更当调养。若瘰 流注之属 \n，尤当补益也。否则更患他证，必难措治。慎之。 \n又曰∶溃疡若属气血俱虚，固所当补，若患肿疡而气血虚弱者，尤宜预补。否则虽溃而不 \n敛矣。又凡大病之后，气血未复，多致再发，若不调补，必变为他证而危，或误以疮毒复发 \n，反行攻伐，则速其不起，深可为戒也。 \n又曰∶若疮疡肿 痛甚，烦躁脉大，则辛热之剂，不但肿疡不可用，即溃疡亦不可用也。 \n《太平圣惠方》云∶凡痈疽脓溃之后，脉微涩迟缓者，邪气去而真气将复也，为易愈。 \n若脉来沉细而直者，里虚而欲变证也。若脓血既去，则当脉静身凉，肿消痛息，如伤寒表 \n证之得汗也。若反发热作渴，脉洪数者，此真气虚而邪气实也，死无疑矣。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>溃疡有余（二十八）\n\n属性：溃疡有余之证，其辨有四∶盖一以元气本强，火邪本盛，虽脓溃之后，而内热犹未尽 \n除，或大便坚实而能食，脉滑者。此其形气病气俱有余，仍宜清利，不宜温补。火退自愈， \n亦善证也。一以真阴内亏，水不制火，脓既泄而热反甚，脉反躁者。欲清之则正气以虚，欲 \n补之则邪气愈甚，此正不胜邪，穷败之证，不可治也。一以毒深而溃浅者，其肌腠之脓已溃 \n，而根盘之毒未动，此乃假头，非真溃也，不得遽认为溃疡而概施托补，若误用之，则反增 \n其害，当详辨也。又有一种元气已虚极，似宜补，然其禀质滞浊，肌肉坚浓，色黑而气道多 \n壅者。略施培补，反加滞闷。若此辈者，真虚既不可补，假实又不可攻，最难调理，极易招 \n怨，是亦不治之证也。总之，溃疡有余者，十之一二，故溃疡宜清者少。肿疡不足者，十常 \n四五，故肿疡宜补者多，此亦以痈疽之危险，有关生死者为言，故贵防其未然也。至若经络 \n浮浅之毒，不过肿则必溃，溃则必收，又何必卷卷以补泻为辨也，观者审之。 \n一男子年逾三十，腹患痈肿，脉数喜冷。齐氏云∶疮疡肿起坚硬，疮疽之实也。河间 \n云∶肿硬木闷，烦躁饮冷，邪气在内也。遂用清凉饮倍加大黄，三剂稍缓。次以四物汤加芩 \n、连、山栀、木通，四剂遂溃。更以十宣散去参、 、肉桂加金银花、天花粉，渐愈。彼欲 \n速效，自服温补药，遂致肚腹俱肿，小便不利。仍以清凉饮治之，脓溃数碗。再以托里药而 \n愈。 \n赵宜人年逾七旬，患鬓疽已溃， 肿甚痛，喜冷脉实，大便秘涩。东垣曰∶烦躁饮冷 \n，身热脉大，精神昏闷者，皆脏腑之实也。遂以清凉饮一剂，肿痛悉退。更以托里消毒药三 \n十余剂而平。若谓年高溃后，投以补剂，实实之祸不免矣。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>溃疡作痛（二十九）\n\n属性：立斋曰∶脓出而反痛者，虚也，宜补之。脉数虚而痛者，属虚火，宜滋阴。脉数实而 \n痛者，邪气实也，宜泄之。脉实便秘而痛者，邪在内也，宜下之。脉涩而痛者，气血虚寒也 \n，温补之。大抵疮之始作也，先发为肿，气血郁积，蒸肉为脓，故多痛。脓溃之后，肿退肌 \n宽，痛必渐减。若反痛者，乃虚也，宜补之。亦有秽气所触者，宜和解之；风寒所逼者，宜温散之。 \n丁兰，年二十余，股内患毒日久，欲求内消。诊其脉滑数，知脓已成，因气血虚不溃， \n遂刺之。脓出作痛，以八珍汤治之，少可。但脓水清稀，更以十全大补汤加炮附子五分，数 \n剂渐愈。仍服十全大补汤，三十余剂而痊。 \n一僧股内患肿一块，不痛不溃，治以托药二十余剂，脓成，刺之作痛。予谓∶肿而不溃 \n，溃而反痛，此气血虚甚也，宜峻补之。彼云∶气无补法。予谓∶正气不足，不可不补，补 \n之则气化而痛，邪自除。遂以参、 、归、术、熟地黄治之，两月余而平。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>溃疡发热（附恶寒三十）\n\n属性：用手摸热有三法∶以轻手扪之则热，重按之则不热，是热在皮毛血脉也。重按之至筋 \n骨之分则热蒸手极甚，轻手则不热，是邪在筋骨之间也。不轻不重按之而热，是热在筋骨之 \n上，皮毛血脉之下，乃热在肌肉也。 \n仲景曰∶脉虚则血虚，血虚生寒，阳气不足也。寸口脉微，为阳不足，阴气上入阳中， \n则洒淅恶寒。尺脉弱为阴不足，阳气下陷入阴中，则发热也。 \n王氏曰∶病热而脉数，按之不鼓动，乃寒盛格阳而致之，非热也。形证似寒，按之而脉 \n气鼓击于指下盛者，此为热甚，拒阴而生病，非寒也。 \n东垣曰∶发热恶热，大渴不止，烦躁肌热，不欲近衣，或目痛鼻干，但脉洪大，按之无 \n力者，非白虎汤证也，此血虚发躁，当以当归补血汤主之。又有火郁而热之证，如不能食而 \n热，自汗气短者，虚也，当以甘寒之剂泻热补气。如能食而热，口舌干燥，大便难者，当以 \n辛苦大寒之剂下之，以泻火保水。又曰∶昼则发热，夜则安静，是阳气自旺于阳分也。昼则 \n安静，夜则发热烦躁，是阳气下陷入阴中也，名曰热入血室。昼夜发热烦躁，是重阳无阴也 \n，当急泻其阳，峻补其阴。 \n立斋曰∶脉浮或弱而热，或恶寒者，阳气虚也，宜补气。脉涩而热者，血虚也，宜补血 \n。脉浮数发热而痛者，邪在表也，宜散之。脉沉数发热而痛者，邪在里也，当下之，午前热 \n者，补血为主；午后热者，补气为主。左手脉小于右手而热者，用血药多于气药；右手脉小 \n于左手而热者，用气药多于血药。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>发热烦躁（三十一）\n\n属性：王太仆曰∶大寒而甚，热之不热，是无火也，当治其心。大热而甚，寒之不寒，是无水 \n也，热动夏止，悠忽往来，时动时止，是无水也，当补其肾。故心盛则生热，肾盛则生寒。 \n肾虚则寒动于中，心虚则热收于内。又热不胜寒，是无火也，寒不胜热，是无水也。夫寒之 \n不寒，责其无水；热之不热，责其无火。热之不久，责之心虚；寒之不久，责肾之弱。 \n治者当深味之。 \n立斋曰∶疮疡发热烦躁，或出血过多，或脓溃大泄，或汗多亡阳，或下多亡阴，以致阴 \n血耗散，阳无所根据，浮散于肌表之间，而非火也。若发热无寐者，血虚也，用圣愈汤。兼汗 \n不止，气虚也，急用独参汤。发热烦躁，肉 筋惕，血气俱虚也，用八珍汤。大渴面赤， \n脉洪大而虚，阴虚发热也，用当归补血汤。肢体微热，烦躁面赤，脉沉而微，阴盛发躁也， \n用四君加姜、附。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>作呕（三十二）\n\n属性：立斋曰∶喜热恶寒而呕者，宜温养胃气。脉细，肠鸣腹痛，滑泄而呕者，宜托里温中。 \n喜寒恶热而呕者，宜降火。脉实便秘而呕者，宜泻火。若不详究其源，而妄用攻毒之药，则 \n肿者不能溃，溃者不能敛矣。虽丹溪曰，肿疡时呕，当作毒瓦斯攻心治之，溃疡时呕，当作阴 \n虚补之，殊不知此大概之言耳。况今之热毒内攻而呕者，十才一二，脾胃虚寒或痰气而呕者 \n，十居八九，故不可执以为言也。又曰∶凡痈疡肿赤痛甚，烦躁脉实而呕者，为有余，当下之 \n。若肿硬不溃，脉弱而呕者，乃阳气虚弱，当补之。若呕吐食少者，乃胃气虚寒，当温补脾 \n胃。若痛伤胃气，或感寒邪秽气而呕者，虽在肿疡，当助胃壮气，若妄用攻伐，多致变证不治。 \n薛氏《枢要》曰∶疮疡作呕，不可泥于热毒内攻，而概用败毒等药。如热甚 痛，邪 \n气实也，仙方活命饮解之。作脓 痛，胃气虚也，托里消毒散补之。脓熟胀痛，气血虚也 \n，先用托里散，后用针以泄之。 痛便秘，热壅于内也，内疏黄连汤导之。若因寒药伤胃 \n而呕者，托里建中汤。胃寒少食而呕者，托里益中汤。中虚寒淫而呕者，托里温中汤。肝木 \n乘脾而呕者，托里抑青汤。胃脘停饮而呕者，托里清中汤。脾虚自病而呕者，托里益黄汤。 \n郁结伤脾而呕者，托里越鞠汤。又曰∶大凡诸疮作呕，若饮冷便秘是热毒也，黄连消毒散解 \n之。饮冷便实是胃火也，竹叶石膏汤清之。懒食饮汤是胃虚也，补中益气汤补之。大便不实 \n，喜饮热汤是脾胃虚寒也，六君加炮姜以温之。常见脾胃虚弱者，用前散反心膈阴冷致呕， \n而喉舌生疮，乃肾水枯涸，虚火炎上也，其证甚恶，急用加减八味丸，亦有得生者。 \n热毒作呕，证如刘贵患腹痈， 痛烦躁脉实作呕。河间云∶疮疡者，火之属，须分内外 \n，以治其本。若脉沉实者，先当疏其内，以绝其源。又曰∶呕哕心烦，脉沉而实，肿硬木闷， \n或皮肉不变，邪气在内，宜用内疏黄连汤治之。然做呕脉实，毒在内也。遂以前汤通利二三 \n行，诸证悉去，更以连翘消毒散而愈。 \n金台王时亨，年逾四十，患臂毒 痛作呕，服托里消毒药愈甚，予用凉膈散二剂顿退 \n，更以四物汤加芩连，四剂而消。（薛按） \n胃寒作呕，证如顾浩室人，年逾四十，患发背，治以托里药而溃。忽呕而疮痛，胃脉弦 \n紧，彼以为余毒内攻。东垣云∶呕吐无时，手足厥冷，脏腑之虚也。丹溪云∶溃后发呕不 \n食者，湿气侵于内也。又云∶脓出而反痛，此为虚也，今胃脉弦紧，木乘土位，其虚明矣。 \n予欲以六君子汤加酒炒芍药、砂仁、藿香治之。彼自服护心散，呕愈甚，复邀治。仍用前药， \n更以补气血药，两月而愈。大抵湿气内侵，或感秽气而作呕者，必喜温而脉弱，热毒内攻而 \n作呕者，必喜凉而脉数。必须辨认明白。亦有大便不实，或腹痛，或膨胀，或呕吐，或吞酸 \n嗳腐，此皆肠胃虚寒也，以理中汤治之。如不应，加熟附子二三片。予尝饮食少思，吞酸嗳 \n腐，诸药不应，惟服理中汤及附子理中丸有效。盖此证皆因中气虚寒，不能运化郁滞所致， \n故用温补之剂，使中气温和，自无此证矣。张生患漆疮作呕，由中气虚弱，漆毒侵之，予以 \n六君子汤加砂仁、藿香、酒炒芍药治之，彼不信，另服连翘消毒散，呕果甚。复邀治，仍以 \n前药，外用麻油调铁锈末涂之而愈。（薛按） \n戴氏曰∶如恶心者，无声无物，欲吐不吐，欲呕不呕，虽曰恶心，实非心经之病，皆在 \n胃口上，宜用生姜，盖能开胃豁痰也。（名元礼南院使） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>作渴（三十三）\n\n属性：李氏曰∶人病疽多有，愈后发渴而不救者，十有八九；或先渴而后患疽者，尤为难治。急用 \n加减八味丸可免前患。若疽安而渴者，服此丸则渴止。疽安而未渴者，预服此丸，则永不生 \n渴。或未发疽而先发渴者，服此不惟渴止，且疽亦不作，气血加壮，真神剂也。又曰∶痈疽 \n已安之后，或未安之际，口舌燥黄，如鸡内金者，乃肾水枯竭，心火上炎。此证最恶。古人 \n云∶玉华池竭七朝亡。若误投以丹药，则祸在反掌，急用加减八味丸、桑枝煎、五味子汤， \n以滋补之。又云∶一贵人病疽未安而渴作，一日饮水数升。予以加减八味丸治之，诸医大笑 \n云，此能止渴，我辈当不复业医。皆用木瓜、紫苏、乌梅、人参、茯苓、百药煎等剂，服多 \n而渴愈甚。不得已用此药，三日渴止，久服遂不复渴，饮食加倍，健于少壮。盖此药非出鄙 \n见，自为儿时，闻先君言有人病渴，用渴药累年不愈，一名医使服此药，降心火，生肾水为 \n最。家藏此方，亲用尝验，患者当知所鉴。（详《外科精要》） \n马益卿曰∶痈疽作渴，乃气血两虚，宜用参 以补气，当归、地黄以养血，或用黄 六 \n一汤，或用忍冬丸。其方以忍冬藤入瓶内，加无灰酒，微火煨一宿，取出晒干。少加甘草， \n俱为末，仍用余酒调糊，为丸桐子大。每服百余丸，温酒下，兼治五痔诸瘿气。 \n立斋曰∶尺脉大或无力而渴者，宜滋阴降火。上部脉沉实而渴者，宜泻火。上部脉洪数 \n而渴者，宜降火。胃脉数而渴者，宜清胃火。气虚不能生津液而渴者，宜补中气。脉大无力 \n或微弱而渴者，宜补气血。脓血大泄或疮口出血而渴者，宜大补气血。如不应，急用独参汤。 \n薛氏《枢要》曰∶疮疡作渴，若 肿发热，便利调和者，上焦热也，用竹叶石膏汤。 \n肿痛发热，大便秘涩者，五内热也，用四顺清凉饮。 肿痛甚者，热毒蕴结也，用仙方活 \n命饮。漫肿微痛者，气血虚壅也，用补中益气汤。若胃火消烁而津液短少者，用竹叶黄 汤 \n。若胃气虚弱不生津液者，用补中益气汤。若胃气受伤内无津液者，用七味白术散。若肾水 \n干涸作渴，或口舌干燥者，用加减八味丸。或先口干作渴，小便频数，而后患疽，或疽愈后 \n作渴饮水，或舌黄干硬小便数而疽生者，尤其恶也，苟能逆知其因，预服加减八味丸、补中 \n益气汤，以滋化源，可免是患。《心法》曰∶予治疮疡作渴，不问肿溃，但脉数发热而渴， \n以竹叶黄 汤治之。脉不数，不发热，或脉数无力而渴，或口干，以补中益气汤。若脉数而 \n便秘，以清凉饮。若尺脉洪大，按之无力而渴，以加减八味丸，若治口燥舌黄，饮水不歇， \n此丸尤妙。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>泻痢（三十四）\n\n属性：立斋曰∶疮疡大便泄泻，或因寒凉克伐，脾气亏损。或因脾气虚弱，食不克化。或因脾 \n虚下陷，不能升举。或因命门火衰，不能生土。或因肾经虚弱，不能禁止。或因脾肾虚寒， \n不能司职。所主之法，若寒凉伤脾，六君加木香、砂仁，送二神丸。脾虚下陷，用补中益 \n气，送二神丸。命门火衰，用八味丸料，送四神丸。肾虚不禁，用姜附汤加吴茱萸、五味。 \n脾肾虚寒，用参附汤，送四神丸。《病机》云∶脉沉而细，身不动作，睛不了了，饮食不下 \n，鼻准气息者，姜附汤主之。身重，四肢不举者，参附汤主之。仲景云∶下痢肠鸣，当 \n温之。脉迟紧，痛未止，当温之。大孔痛，当温之。心痛当救里，可与理中、附子、四逆辈 \n。《精要》云∶痈疽呕吐，肾脉虚者，不治。凡此难治之证，如按前法治之，多有可生者。 \n御医王彭峰之内，年逾四十，背疽不起发，泄泻作呕，食少厥逆，脉息如无，属阳气虚 \n寒。用大补剂加附子、姜、桂，不应。再加附子二剂，泻愈甚。更以大附子、姜、桂各三 \n钱，参、 、归、术各五钱，作一剂，腹内始热，呕泻乃止，手足渐温，脉息遂复。更用大 \n补而溃，再用托里而敛。十年后，仍患脾胃虚寒而殁。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>大便秘结（三十五）\n\n属性：立斋曰∶疮疡大便秘结，若作渴饮冷，其脉洪数而有力者，属实火，宜用内疏黄连汤。 \n若口干饮汤，其脉浮大而无力者，属气虚，宜八珍汤。若肠胃气虚而燥而不通者，宜用十全大 \n补汤培养之。若疮证属阳，或因入房伤肾，而不通者，宜用前汤加姜附回阳，多有得生者。若 \n饮食虽多，大便不通，而肚腹不胀者，此内火消烁，切不可通之。若肚腹痞胀，而直肠干涸 \n不通者，宜用猪胆汁导之。若误行疏利，复伤元气，则不能溃敛。经曰∶肾开窍于二阴，藏 \n精于肾。津液润则大便如常。若溃疡有此，因气血亏损，肠胃干涸，当大补为善，设若不 \n审虚实，而一于疏利者，鲜有不误。若老弱或产后而便难者，皆气血虚也，猪胆汁最效。甚 \n者多用之。更以养气血药助之，万不可妄行攻伐。 \n居宾鸥，仲夏患发背，黯肿尺余，皆有小头如铺粟状，四日矣。此真气虚而邪气实也。 \n遂隔蒜灸之，服活命饮二剂，其邪顿退。乃纯补其真阴，又将生脉散以代茶饮，疮邪大退。 \n余因他往三日，复视之，饮食不入，中央肉死，大便秘结，小便赤浊。余曰∶中央肉死，毒 \n气盛而脾气虚也。大便不通，肠虚而不能传送也。小便赤浊，脾虚而火下陷也治亦难矣。 \n彼始云∶莫非间断补药之过也。余曰∶然。乃急用六君子加当归、柴胡、升麻，饮食渐进， \n大便自通。外用乌金膏，涂中央三寸许，四周红肿渐消，中央黑腐渐去。乃敷当归膏，用地 \n黄丸与前药间服，将百剂而愈。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>小便淋涩不利（三十六）\n\n属性：立斋曰∶疮疡，小便淋漓频数，或茎中涩者，肾经亏损之恶证也，宜用加减八味丸，以 \n补阴。足胫逆冷者，宜用八味丸，以补阳。若小便频数而黄者，宜用四物汤加参、术、麦门 \n、五味，以滋肺肾。若小便短而少者，宜用补中益气加山药、麦门、五味，以补脾肺。若热 \n结膀胱而不利者，宜用五淋散，以清热。若脾气燥热而不能化者，宜用黄芩清肺饮，以滋阴 \n。若膀胱阴虚，阳无以生者，宜用滋肾丸。若膀胱阳虚，阴无以化者，宜用六味地黄丸。肾 \n虚之患，多传此证，非滋化源则不救。若用黄柏知母反泻其阳，是速其危也。若老人阴痿思 \n色，精气内败，茎中痛而不利者，用加减八味丸加车前子、牛膝。不应，更加附子，多有复 \n生者。若精已竭而复耗之，大小便中牵痛，愈痛则愈便，愈便则愈痛，以前药加附子，亦有 \n复生者。王太仆云∶无阴则阳无以化，无阳则阴无以生。当滋其化源，若专用淡渗，复损真 \n阴，乃速其危也。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>发痉（三十七）\n\n属性：立斋曰∶疮疡发痉，因气血亏损，或为外邪所搏，或内虚郁火所致。其形则牙关紧急， \n四肢劲强，或腰背反张，肢体抽搐。其有汗而不恶寒者，曰柔痉。风能散气，故有汗也。其 \n无汗而恶寒者，曰刚痉。寒能涩血，故无汗也。皆由亡血过多，筋无所养，故伤寒汗下过多 \n，与溃疡、产后多患之，乃败证也。若大补气血，多有可治者；若作风治，速其危也。 \n痉论法，俱详见《杂证谟十二卷·痉证门》，所当参阅。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>无寐（三十八）\n\n属性：立斋曰∶疮疡溃后无寐，发热烦躁，血虚也，圣愈汤。自汗不止无寐，气虚也，四君子 \n加黄 、五味子。发热烦躁，肉 筋惕，气血虚也，八珍汤。大渴面赤，脉洪大而浮，阴 \n虚发热也，当归补血汤。肢体微热，烦躁面赤，脉沉微，阴盛发躁也，四君加姜附。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>疮疡出血（三十九）\n\n属性：立斋曰∶疮疡出血，因五脏之气亏损，虚火动而错经妄行也。当求其经，审其因而治之 \n。若肝热而血妄行者，宜四物加炒山栀、芩、术、丹皮。肝虚而不能藏血者，六味地黄丸。 \n心虚而不能主血者，四物加炒黄连、丹皮、苓、术。脾虚热而不能统血者，四君子加炒栀子 \n、丹皮。若脾经郁结，用归脾汤加五味子。脾肺气虚，用补中益气汤加五味子。气血俱虚，"}, {"n": 27, "text": "卷二十七\n\n用十全大补汤。阴火动者，用六味丸加五味子。大凡失血过多，见烦躁发渴等证。勿论其脉 \n，急用独参汤，以补气。经云∶血生于气。苟非参 归术，甘温等剂，以生心肝之血，决不 \n能愈。若发热脉大者，不治。凡患血证，皆当以犀角地黄汤为主。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>戒忌调护（四十）\n\n属性：李氏云∶病疽之人，当戒酒面、炙爆腌腊、生冷油腻、鸡鹅鱼腥之类。若起居七情， \n尤为深戒。必令卧室洁净馨香，使气血流畅。仍忌僧道孝子，产妇经妇，及鸡犬猫畜。之类若背疽 \n难于隐几，宜用绿豆十斗做一袋，隐伏其上，以解毒凉心也。又曰∶大凡脏腑已利，疮毒已溃 \n，气血既虚，最当调护，若发热而服凉药，无不致祸。 \n立斋曰∶绿豆性寒，主丹毒烦热、风疹或金石所发。实热烦渴，饮食如常，证属纯阳者 \n，极宜用之，否则不可轻用也。又曰∶疮疡食肉，乃自弃也。疮疡之毒，发于营气，今反助 \n之，与自弃何异。虽用药施治，亦不能愈。 \n东垣云∶胃为五脏之根本。胃气一伤，诸证皆虚，七恶蜂起，可不慎哉。 \n愚按∶疮疡当忌荤腥，然以愚见言之，则惟热火证及疔毒阳痈，则毫不可犯，宜切慎之。至 \n若营卫大虚，而毒不能化，肉不能长，凡宜温宜补等证，岂亦不宜滋补乎。故古人号黄 为 \n羊肉，则既宜黄 ，未有不宜羊肉者。惟猪肉、牛肉、醇酒及伤脾助湿等物，则不可不忌。 \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>阴阳证变（四十一）\n\n属性：太监刘关，患发背，肿痛色紫，诊其脉息沉数。陈良甫云∶脉细发热而痛者，发于阳也 \n。且疮疡赤甚则紫，即火极似水也。询之，尝服丹石药半载，乃积温成热所致。遂以内疏黄 \n连汤再服，稍平。更用排脓消毒药乃猪蹄汤、太乙膏而愈。经曰∶色与脉当相参应治之者。在 \n明亢害承制之理，阴阳变化之机焉耳。 \n举人潘光甫，年四十，患脑疽 肿，诊其脉沉静。予谓此阳证阴脉，断不起，已而果然 \n。盖疮疡之证，虽属心火，尤当分表里虚实。果元气充实，内有实火者，寒剂或可责效。若 \n寒凉过度，使胃寒脾弱，阳证变阴，或结而不溃，溃而不敛，阴阳乖戾，水火交争，死无日 \n矣。（薛按） \n\n\n\n<目录>卷之四十六圣集·外科钤（上）\\外科钤（上）\n\n<篇名>论列方（外科上）\n\n属性：参附汤（补三七） 托裹散（外四三） 八珍汤（补十九） 六君子汤（补五） 圣愈汤 \n（补九一） 归脾汤（补三二） 回阳汤（外三七） 八味丸（补一二一） \n败毒散（散三六） 冲和汤（外二四） 四神丸（热一五一） 流气饮（外五五） \n五淋散（寒百十七） 五香渴（末入，即外五一方） 姜附汤（热三二） 四君子汤（补一） \n独参汤（补三五） 四物汤（补八） 理中汤（热一） 六味丸（补百二十） \n滋肾丸（寒一六三） 护心散（外七二） 二神丸（热百五十） 清凉饮（外九十） \n麻黄汤（散一） 凉膈散（痘八三） 清胃散（寒五四） 十宣散（痘十四） \n清阴汤（外八五） 白虎汤（寒二） 离金散（外六七） 漏芦汤（外九五） \n夺命丹（外七七） 蜡矾丸（外七四） 忍冬酒（外百二） 槐花酒（外百四） \n通志酒（外百六） 国老膏（外六八） 桑枝煎（外百九） 掣甘草汤（外六八） \n五味子汤（补五七） 神仙截法（外百十） 十全大补汤（补二十） 仙方活命饮（外一） \n人参黄 汤（外二六） 补中益气汤（补三十） 托裹消毒散（外二） 托里温中汤（外十二） \n托里健中汤（外十一） 托里清中渴（外十六） 托里益黄汤（外十五） \n托里益中汤（外十三） 托里抑青汤（外十七） 托里越鞠汤（外十九） \n托里温经汤（外十四） 七味白求散（小七） 丁香柿蒂散（热六四） 黄 六一汤（补四九） \n当归补血汤（补四四） 加减八味丸（外三八） 人参养营汤（补二一） 人参平肺散 \n（寒三七） 人参理中汤（热一） 人参败毒散（散三六） 附子理中汤（外三四） 竹叶黄 \n汤（寒七） 黄连消毒散（外六十） 黄连解毒汤（寒一） 竹叶石膏汤（寒五） 连翘消毒散（外六一） \n内疏黄连汤（外九三） 五香连翘渴（外五一） 四顺清凉饮（攻二五） 黄芩清肺饮（寒三八） \n内固金粉散（外七三） 犀角地黄汤（外四六） 乳香定痛丸（外五七） 犀角升麻汤（外四七） \n香砂六君汤（补七） 神仙熏照方（外一二二） 附子饼（外百十六） 豆豉饼（外百十七） \n桑枝灸（外百二十） 葱熨法（外一二一） 隔蒜灸（外百十五） 骑竹马法（外百十四） \n针头散（外一四四） 降痈散（新因三六） 麦饭石膏（外一三九） 乌金膏（外一四二） \n阴阳散（外一三三） 抑阴散（外一三一） 抑阳散（外一三二） 猪蹄汤（外一二五） \n当归膏（外三一四） 神异膏（外三百十） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>发背（四十二）\n\n属性：发背，属督脉膀胱经，凡阴虚火盛，或醇酒浓味，或郁怒房劳，或丹石热毒，皆能致之 \n。若肿赤痛甚，脉洪数而有者，热毒之证也，为易治。若漫肿微痛，色黯作渴，脉虽洪数而 \n无力者，阴虚之证也，为难治。若不肿不痛，或漫肿色黯，脉微细者，阳气虚甚也，尤为难 \n治。大抵发背之证，其名虽多，总惟阴阳二证为要。若发一头或二头，其形 赤肿高，发 \n热疼痛，头起者为痈，属阳易治。若初起一头如粟，不肿不赤，闷痛烦躁，大渴便秘，睡语 \n切牙，四五日间，疮头不计其数，疮口各含如粟形，如莲蓬，故名莲蓬发。积日不溃，按之 \n流血。至数日或八九日，其头成片，所含之物俱出，通结一衣，揭去又结，其口共烂为一疮 \n，其脓内攻，其色紫黯者，为疽。属阴，难治。且此证不可大痛，又不可不痛，若见烦闷者 \n，多不治。总之，疮疡虽云属火，然未有不由阴虚而致者，故经云∶督脉经虚从脑而出，膀 \n胱经虚从背而出。故不可专泥于火。 \n陈良甫曰∶背疽之源有五∶一天行，二瘦弱气滞，三怒气，四肾气虚，五饮冷酒，食炙 \n爆，服丹药。 \n立斋曰∶大抵发背之证，虽发热疼痛，情势高硕，烦渴不宁，但得脉息有力，饮食颇进 \n，可保无虞。其脓一溃，诸证悉退，多有因脓不得外泄，以致疼痛，若用败毒寒药攻之，反 \n致误事。若有脓，急针之，脓一出，苦楚即止。脓未成而热毒作痛者，可用解毒之药。亦有 \n腐溃尺余者，若无恶证，则投以大补之剂，肉最易生，亦无所妨。惟忌肿不高，色不赤，不 \n痛，脉无力，不饮食，肿不溃，腐不烂，脓水清，或脓多不止，皆属元气虚也，为难治 \n， \n宜峻补之。其或脓血既泄，肿痛尤甚，浓水臭败，烦躁时嗽，腹痛渴甚，泻利无度，小便如 \n淋，乃恶证也，皆不可治。 \n又《灸法》曰∶予常治发背，不问日期阴阳肿痛，或不痛，或痛甚，但未成脓，或不溃 \n者，即与灸之，随手取效。或麻木者，明灸之，毒瓦斯自然随火而散。或疮头如黍者，灸之尤 \n效，亦有数日色尚微赤，肿尚不起，痛不甚，脓不作者，尤宜多灸，勿拘日期。更服甘温托 \n里药，切忌寒凉之剂。其有势未定者，或先用箍药围之，若用乌金膏点患处尤妙。凡人初 \n觉发背，赤热肿痛，莫辨其头者，但以湿纸覆其上，立候视之，其纸有先干处，即是结痈头 \n也。取大蒜切成片如二三钱浓薄，安于头上，用大艾炷灸之，三壮换一蒜片，痛者灸至不痛 \n、不痛灸至痛时方止。最要早觉早灸为上。一日二日，十灸十活，三日四日六七活，五日六 \n日三四活，过七日则难为力矣。若有十数头作一处者，即用大蒜研成膏，作薄饼铺头上，聚 \n艾于蒜饼上烧之，亦能活也。若背上初发赤肿一片，中间有一片黄粟米头子，便用独蒜切去 \n两头，取中间半寸浓者，正安于疮上，灸十四壮，多至四十九壮。盖如此恶证，惟隔蒜灸及 \n涂乌金膏有效。又《治法》曰∶肿硬痛深脉实者，邪在内也，可下之。肿高 痛脉浮者， \n邪 \n在表也，宜托之。 痛烦躁或咽干，火在上也，宜泻之。肿高或不作脓者，邪气凝结也， \n宜 \n解之。肿痛饮冷，发热睡语者，火也，宜清之。不作脓或不溃不敛者，阳气虚也，宜补之。 \n瘀肉不腐，或积毒不解者，阳气虚也，宜助阳气。脓多或清者，气血俱虚也，宜峻补之。脉 \n浮大或涩，而肌肉迟生者，气血俱虚也，宜补之。右关脉弱，而肌肉迟生者，宜补脾胃。 \n又《诸毒治法》曰∶如头痛有表证者，宜先服人参败毒散一二剂。如 痛发热脉数者 \n， \n用金银花散、槐花酒、神功托里散。如疼痛肿硬脉实者，以清凉饮、仙方活命饮、苦参丸。 \n肿硬木闷，疼痛发热，烦躁饮冷便秘，脉沉实者，内疏黄连汤，或清凉饮。大便已通，欲其 \n作脓，宜仙方活命饮、托里散、蜡矾丸，外用神异膏。如饮食少思，或不甘美，用六君子汤 \n加藿香，连进三五剂，更用雄黄解毒散洗患处，每日用乌金膏涂疮口处。俟有疮口，即用纸 \n作捻蘸乌金膏 入疮内。若有脓为脂膜间隔不出，或作胀痛者，宜用针引之。腐肉堵塞者 \n去 \n之，若瘀肉腐动，用猪蹄汤洗之。如脓稠或痛，饮食如常，瘀肉自腐，用消毒与托里药相兼 \n服之，仍用前二膏涂贴。若腐肉已离好肉者，宜速去之。如脓不稠不稀，微有疼痛，饮食不 \n甘，瘀肉腐迟，更用桑柴灸之，亦用托里药。若瘀肉不腐，或脓清稀，不 痛者，急服大 \n补之剂，亦用桑木灸之，以补接阳气，解散郁毒。常观患疽稍重未成脓者，不用蒜灸之法， \n及脓熟不开，或待腐肉自去，则多致不救。大抵气血壮实，或毒少轻者，可假药力，或自 \n腐溃。若怯弱之人，热毒中隔，内外不通，不行针灸，药无全功矣。此证若脓已成，急宜开 \n之，否则重者溃通脏腑，腐烂筋骨。若使透膈则不可治。轻者延溃良肉，难于收功，因而不 \n敛者多矣。 \n又《诸补治法》曰∶若肿 作痛，寒热作渴，饮食如常，此形气病气俱有余也，先用 \n仙 \n方活命饮，后用托里消毒散解之。漫肿微痛，或色不赤，饮食少思，此形气病气俱不足也， \n用托里散调补之。不作脓或脓成不溃，阳气虚也，托里散倍加肉桂、参、 。脓出而反痛 \n，或脓清稀，气血俱虚也，八珍汤。恶寒形寒，或不收敛，阳气虚也，十全大补汤。晡热内 \n热或不收敛，阴血虚也，四物加参术。作呕欲呕，或不收敛，胃气虚也，六君加炮姜。食少 \n体倦，或不收敛，脾气虚也，补中益气汤加茯苓、半夏。肉赤而不敛，血热也，四物加山栀 \n、连翘。肉白而不敛，脾虚也，四君加酒炒芍药、木香。小便频数者，肾阴亏损也，加减八 \n味丸。大抵病毒势甚，若妄用攻剂，怯弱之人必损元气，因而变证者众矣。 \n又《三证治法》曰∶若初患未发出，而恶寒疼痛，作渴饮冷，此邪气内蕴也，仙方活命 \n饮。若口干饮热，漫肿微痛，此元气内虚也，托里消毒散。若饮食少思，肢体倦怠，此脾胃 \n虚弱也，六君子汤，如未应，加姜、桂。其有死者，乃邪气盛，真气虚而不能发出也，在于 \n旬余之间见之。若已发出，用托里消毒散。不腐溃，用托里消毒散。如不应，急宜温补脾胃 \n。其有死者，乃真气虚而不能腐溃也，在于二旬之间见之。若已腐溃，用托里散以生肌。如 \n不应，急温补脾胃。其有死者，乃脾气虚而不能收敛也，在于月余见之。此三证虽不见于经 \n籍，余尝治而历验者。 \n《千金方》灸法治发背，已溃未溃者，用淡豆豉以水和捣成硬泥，根据肿大小作饼三四分 \n浓。如已有疮孔，勿置疮孔上，但四布豆饼，列艾其上灸之，使微热，勿令破肉，如热痛急 \n少起之，日灸二度。如先有疮孔，孔出汁即瘥。 \n一、验透膈法，凡背疽大溃，欲验穿透内膜者，不可用皂角散嚏法，但以纸封患处，令 \n病者用意呼吸，如纸不动者，未穿透也。倘用取嚏法鼓动内膜，则反致穿透，慎之慎之。 \n都宪周弘冈，背患疽肿而不溃，脉大而浮，此阳气虚弱而邪气壅滞也，用托里散倍加参 \n、。反内热作渴，脉洪大鼓指，此虚火也，用前散急加肉桂。脉证顿退，仍用托里而愈。 \n若以为热毒而用寒药则误矣。 \n上舍张克恭，患此，内服外敷皆寒凉败毒，遍身作痛，欲呕少食，晡热内热，恶寒畏寒 \n。余曰∶遍身作痛，营卫虚而不能营于肉里也。欲呕少食，脾胃虚寒而不能消化饮食也。内 \n热晡热，阴血内虚而阳气陷于阴分也。恶寒畏寒，阳气虚弱而不能卫于肌肉也。此皆由脾胃 \n之气不足所致。遂用补中益气汤，诸证渐退。更以十全大补汤，腐肉渐溃。又以六君子汤加 \n芎、归，肌肉顿生而愈。 \n府庠彭碧溪，患腰疽，服寒凉败毒之药，色黯不痛，疮头如铺黍，背重不能安寝，耳 \n聩目白，面色无神，小便频涩，作渴迷闷，气粗短促，脉浮数，重按如无。余先用滋水之 \n药 \n一剂，少顷便利渴止，背即轻爽。乃砭出瘀血，以艾半斤许，明灸患处，外敷乌金膏，内服 \n参、 、归、术、肉桂等药。至数剂，元气稍复，自疑肉桂辛热，一日不用，手足并冷，大 \n便不禁，仍用肉桂及补骨脂二钱，肉豆蔻一钱，大便复常，其肉渐溃。更用当归膏以生肌肉 \n，八珍汤以补气血而愈。 \n上舍蔡东之，患此，余用托里之药而溃，疮口尚未全敛。时值仲冬，且兼咳嗽。余曰∶ \n疮口未敛，脾气虚也，咳嗽不止，肺气虚也，法当补其母。一日与之同宴，见忌羊肉，余曰 \n∶补可去弱，人参羊肉之类是也，最宜食之。遂每日不彻，旬余而疮敛，嗽亦顿愈矣。 \n一男子，年逾五十，患发背色紫肿痛，外皮将溃，寝食不安，神思甚疲，用桑柴灸患 \n处出黑血，即鼾睡觉，而诸证如失。服仙方活命饮二剂，又灸一次，脓血皆出。更进二剂， \n肿痛大退，又服托里消毒散数剂而敛。夫疮势炽甚，本宜峻剂攻之，但年老血气衰弱，况又 \n发在肌表，若专于攻毒，则胃气先损必反误事。（薛按） \n予长男于一周患背疽，治按在肿疡条中。（新按） \n论外通用方 \n神仙熏照法（外一二三） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>脑疽（四十三）\n\n属性：立斋曰∶脑疽，属膀胱经积热，或湿毒上壅，或阴虚火炽，或肾水亏损，阴精消涸所致 \n。若肿痛未作脓者，宜除湿消毒。大痛或不痛，或麻木者，毒甚也，隔蒜灸之，更用解毒药 \n。肿痛便秘者，邪在内也，宜泄之。不甚痛，或不做脓者，虚也，托里为主。脓成胀痛者，针 \n之，更以托里。上部脉数，实而痛者，宜降火。上部脉数虚而痛者，宜滋阴降火为主。尺部 \n脉数而作渴者，滋阴降火。脉数而虚细无力，或脓清，或不敛，或脓多者，大补血气。不作 \n脓，或不溃者，托里药主之。烦躁饮冷，脉实而痛者，宜泻火。 \n又《治法》曰∶初起肿赤痛甚，烦渴饮冷，脉洪数而有力，乃湿热上壅，当用黄连消毒 \n散，并隔蒜灸，以除湿热。若漫肿微痛，渴不饮冷，脉洪数而无力，乃阴虚火炽，当用六味 \n丸，及补中益气汤，以滋化源。若口干舌燥，小便频数，或淋漓作痛，乃肾水亏损，急用加 \n减八味丸，及前汤，以固根本，而引火归经。若不成脓，不腐溃，阳气虚也，四君加归 。 \n若不生肌，不收敛，脾气虚也，十全大补汤。若色黯不溃，或溃而不敛，乃阴精消涸，名曰脑 \n烁，为不治。若攻补得宜，亦有可愈。大凡肿 痛甚，宜活命饮，隔蒜灸之，以解散瘀血 \n，拨引郁毒。但艾炷宜小而少，若欲其成脓腐溃生肌收敛，并用托里为主。 \n李氏曰∶脑疽及颈项有疽，不可用隔蒜灸，恐引毒上攻，宜灸足三里穴五壮，气海穴三七 \n壮，仍服凉血化毒之药，或以骑马穴法灸之。凡头项咽喉生疽，古法皆为不治，若用此法， \n多有生者。如五香连翘漏芦等汤、国老膏、万金散，皆可选用。（见《外科精要》） \n一老人患此，色赤肿痛，脉数而有力，与黄连消毒散二剂少退，更与清心莲子饮四剂而消。 \n一男子肿痛脉数，以荆防败毒散二剂而痛止，更以托里消毒药而消。 \n一男子 肿疼痛，发热饮冷，脉洪数，与凉膈散二剂而痛止，以金银花散四剂而溃， \n更以托里药而愈。 \n一老妇，禀壮实，溃而痛不止，脉实便秘，以清凉饮二剂而痛止，更以托里消毒药而愈。 \n一妇人，冬间患此，肿痛热渴，余用清热消毒溃之而愈。次年三月，其舌肿大，遍身发 \n疔如葡萄，不计其数，手足尤多，乃脾胃受毒也。先各刺出黑血，随服夺命丹七粒，出鼻汗 \n，疮热益甚，便秘二日。与大黄、芩、连各三钱，升麻、白芷、出栀、薄荷、连翘各二钱， \n生甘草一钱，水煎三五沸，服之，大小便出，臭血甚多，下体稍退。乃磨入犀角汁再服，舌 \n本及齿缝出臭血，诸毒乃消。更以犀角地黄汤而愈。 \n一妇人患前证，口干舌燥，内服清热，外敷寒凉，色黯不 ，胸中气噎，此内真寒而 \n外 \n假热也。彼疑素有痰火，不欲温补，余以参 各五钱，姜桂各二钱，一剂顿溃。又用大补药 \n而愈。 \n一男子头项俱肿，虽大溃，肿痛益甚，兼作泻，烦躁不睡，饮食少思，其势可畏。诊其 \n脉则毒尚在。与仙方活命饮二剂，肿痛退半，与二神丸及六君子汤加五味子、酸枣仁四剂， \n诸证少退，饮食少进，睡亦少得。又与参苓白术散数服，饮食顿进。再与十全大补汤加金银 \n花、白芷，月余而瘥。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>耳疮（四十四）\n\n属性：立斋曰∶耳疮，属少阳三焦经，或足厥阴肝经，血虚风热，或肝经燥火风热，或肾经虚 \n火等因。若发热 痛，属少阳厥阴风热，用柴胡清肝散。若内热痒痛，属二经血虚，用当 \n归 \n川芎散。若寒热作痛，属肝经风热，用小柴胡汤加山栀、川芎。若内热口干，属肾经虚火， \n用加减地黄丸。如不应，用加减八味丸，余当随证治之。 \n愚按，薛氏所治耳证，凡气虚者，以补中益气汤加山栀、黄芩。血虚者，用八珍汤加柴 \n胡、丹皮。肝火血虚者，用栀子清肝散。怒动肝火者，用加味逍遥散。肝脾受伤者，朝用加 \n味归脾汤，暮用加味逍遥散。此其治之大约也。予尝治一儒者，年近三旬，素有耳病，每年 \n常发，发必肿溃。至乙亥二月，其发则甚，自耳根下连颈项，上连头角，耳前耳后莫不肿痛 \n。诸医之治，无非散风降火。至一月后，稠胀鲜血自耳迭出，每二三日必出一酒钟许。然脓 \n出而肿全不消，痛全不减，枕不可近，食不可加，气体俱困，自分其危，延余治之。察其形 \n气，已大不足。察其病体，则肿痛如旧，仍若有余。察其脉息则或见弦急，或见缓弱。此非 \n实热可知，然脉不甚紧而或时缓弱，亦得溃疡之体，尚属可治。遂先以六味汤二三剂，而元 \n气稍振；继以一阴煎加牛蒡、茯苓、泽泻，仍倍加白蒺藜为君，服五十余剂，外用降痈散， \n昼夜敷治，两月而后愈。盖此证虽似溃疡有余，而实以肝肾不足，上实下虚一奇证也，故存 \n识之。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>鬓疽（四十五）\n\n属性：立斋曰∶鬓疽属肝胆二经怒火，或风热血虚所致。若 痛或发热者，宜祛风清热。 痛 \n发寒热，或拘急者，发散表邪。作脓 痛，托里消毒。脓已成作痛者，针之。不作脓或脓 \n成而不溃者，俱宜托里。不敛或脓清者，宜峻补之。 \n又《治法》曰∶若发热作渴者，用柴胡清肝散。肿 痛甚者，仙方活命饮。若大势已 \n退 \n，余毒未散，用参苓归术为主，佐以川芎、白芷、金银花以速其脓。脓成仍用参苓之类，托 \n而溃之。若欲其生肌收敛，肾虚者六味丸，血虚者四物汤加参 ，或血燥者四物汤，或水不 \n能生木者六味地黄丸，气虚者用补中益气汤，皆当滋其化源为善。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>腮（四十六）\n\n属性：立斋曰∶ 腮，属足阳明胃经，或外因风热所乘，或内因积热所致。若肿痛寒热者，白 \n芷胃风汤。内热肿痛者，升麻黄连汤。外肿作痛，内热口干者，犀角升麻汤。 \n内伤寒凉不能消溃者，补中益气汤。发热作渴，大便 \n秘结，清凉饮。表里俱解而仍肿痛者，欲作脓也，托里散。若饮食少思，胃气虚弱者，六君 \n子汤。肢体倦怠，阳气虚弱也，补中益气汤。脓毒既溃，肿痛不减，热毒未解也，托里消毒 \n散。脓出而反痛，气血虚也，参 内托散。发热晡热，阴血虚也，八珍汤。恶寒发热，气血 \n俱虚也，十全大补汤。若 肿痛连耳下者，属手足少阳经，当清肝火。若连颐及耳后者，属 \n足少阴经虚火，当补肾水。此证而有不治者，多泥风热，用克伐之剂耳。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>瘰（四十七）\n\n属性：瘰 之病，属三焦肝胆等经风热血燥，或肝肾二经精血亏损，虚火内动。或恚怒忧思， \n气逆于肝胆二经。二经常多气少血，故怒伤肝，则木火动而血燥，肾阴虚则水不生木而血 \n燥。 \n血燥则筋病，肝主筋也，故累累然结若贯珠。其候多生于耳前后，连及颐颔，下至缺盆，及 \n胸腋之侧，又谓之马刀。其初起如豆粒，渐如梅李核，或一粒，或三五粒。按之则动而微痛 \n，不甚热，久之则日以益甚。或颈项强痛，或午后微热，或夜间口干，饮食少思，四肢倦怠 \n，或坚而不溃，或溃而不合，皆由气血不足，故往往变为痨瘵。《外台秘要》云∶肝肾虚热 \n则生 。《病机》云∶瘰 不系膏粱丹毒火热之变，总因虚劳气郁所致。止宜以益气养营之 \n药调而治之，其疮自消，盖不待汗之下之而已也。若不详脉证虚实之异，而概用追蚀攻下及 \n流气饮、十宣散之属，则必犯经禁病禁，以致血气愈损，必反为败证矣。若脉洪大，以元气 \n虚败为不治。若面色 白为金克木，亦不治。若眼内赤脉贯瞳人，见几条则几年死。使不 \n求本而妄用伐肝之剂则误矣，盖伐肝则脾土先伤，脾伤则损五脏之源矣。可不慎哉。 \n齐氏曰∶瘰 结核初觉时，宜内消之。如经久不除，气血渐衰，肌寒肉冷，或脓汁清稀 \n，毒瓦斯不出，疮口不含，聚肿不赤，结核无脓，外证不明者，并宜托里。脓未成者，使脓早 \n成；脓已溃者，使新肉早生。血气虚者，托里补之。阴阳不和者，托里调之。大抵托里之法 \n，使疮无变坏之证，所以宜用也。 \n丹溪曰∶瘰 必起于足少阳一经，不守禁忌，延及足阳明经。食味之浓，郁气之久，曰 \n毒，曰风，曰热，皆此三端。拓引变换，须分虚实，实者易治，虚者可虑。此经主决断，有 \n相火，且气多血少，妇人见此，若月水不调，寒热变生，稍久转为潮热，自非断欲食淡，神 \n医不能疗也。 \n立斋曰∶ 肿脉沉数者，邪气实也，宜泄之。肿痛憎寒发热，或拘急者，邪在表也， \n宜 \n发散。因怒结核，或肿痛，或发热者，宜疏肝行气。肿痛脉浮数者，祛风清热。脉涩者，补 \n血为主，脉弱者，补气为主。肿硬不溃者，补气血为主。抑郁所致者，解郁结，调气血。溃 \n后不敛者，属气血俱虚，宜大补。虚劳所致者，补之。因有核而不敛者，腐而补之。脉实而 \n不敛，或不消者，下之。 \n又《治法》曰∶若寒热 痛者，此肝火风热而气病也，用小柴胡汤以清肝火，并服加 \n味四物汤以养肝血。若寒热既止，而核不消散者，此肝经火燥而血病也，用加味逍遥散以清肝 \n火，六味地黄丸以生肾水。若肿高而稍软，面色萎黄，皮肤壮热，脓已成也，可用针以决之 \n，及服托里之剂。若经久不愈，或愈后复发，脓水淋漓，肌肉羸瘦者，必纯补之剂，庶可收 \n敛，否则变成九 。《内经》曰∶陷脉为 ，留连肉腠，即此病也。外用豆豉饼、琥珀膏， \n以驱散寒邪，补接阳气；内服补中益气汤、六味丸，以滋肾水，培肝木，健脾土，亦有可愈 \n者。 \n又《治法》曰∶大抵此证原属虚损，若不审虚实，而犯经禁病禁，则鲜有不误。常治此 \n证，先以调经解郁，更以隔蒜灸之，多自消。如不消，即以琥珀膏贴之。俟有脓，即针之 \n，否则变生他处。设若兼痰兼阴虚等证，只宜加兼证之剂，不可干扰余经。若气血已复而 \n核不消，却服散坚之剂至月余，不应，气血亦不觉损，方进必效散，或遇仙无比丸，其毒一下 \n即止二药。更服益气养营汤，以调理之。若疮口不敛，宜用豆豉饼灸之，用琥珀膏贴之。若 \n气血俱虚，或不慎饮食起居七情者，俱不治。然此证以气血为主，气血壮实者不用追蚀之剂 \n，彼亦能自腐，但取去之，亦使易于收敛。若气血虚者，不先用补剂，而数用追蚀之药，适 \n足以败之矣。若发寒热，眼内有赤脉贯瞳人者，不治。 \n灸瘰 法，取肩尖、肘尖骨缝交接处各一穴，即手阳明经肩 、曲池二穴也，各灸七 \n壮 \n，在左灸左，在右灸右，左右俱病者，俱灸之。余常用之甚效，薛氏以曲池云肘 ，似亦 \n未的也。 \n又《薛氏经验方》云∶治瘰 已成未成，已溃未溃者，以手仰置肩上，微举起，则肘骨 \n尖自见，即是灸处。灸以三四十壮为度，更服益气养营汤，灸三次，疮自除。如患三四年不 \n愈者，辰时灸至申时，三灸即愈，更服补剂。按此法乃单灸曲池，以多为贵也。然但用前法 \n而已妙矣，尚有未应者，又当以此法治之。又曰∶此治瘰 之秘法。凡男子妇人若困恚怒伤肝， \n气血壅遇而不愈者，宜灸此穴，以疏通经络。如取此穴，当以指甲掐两肘两肩四所，患处觉有 \n酸麻方是其穴。 \n又法灸瘰 未成脓者，用大蒜切片三钱浓，安患处，用艾壮于蒜上灸之，每三五壮即换 \n蒜再灸。每日灸十数蒜片，以拔郁毒。如破久不合，更以江西豆豉为末，以唾津和作饼，如 \n前灸之，以助阳气。内服补药，外贴琥珀膏，或太乙膏，疮口自合。又或疮口已破，核不腐 \n，则疮口不能敛，或贴琥珀膏不应，须用针头散敷之，以去腐肉。再以如神散敷之，更服益 \n气养营汤。若气血虚者，先服益气养营汤。待血气稍充，方用针头散，仍服前汤。 \n一男子患而肿硬，久不消，亦不做脓，服散坚败毒药不应，令灸肩尖、肘尖二穴，更服 \n益气养营汤，月余而愈。 \n一妇人久溃发热，月经每过期且少，用逍遥散兼前汤两月余，气血复而疮亦愈。但一口 \n不收，敷针头散，更灸前穴而痊。常治二三年不愈者，连灸三次，兼用托里药必愈。 \n一妇人因怒结核肿痛，察其气血俱实，先以必效散下之，更以益气养营汤三十余剂而消 \n。常治此证，虚者先用益气养营汤，待其气血稍充，乃用必效散，取去其毒，仍进前药，无 \n不效者。 \n田氏妇，年逾三十，瘰 已溃不愈，与八珍汤加柴胡、地骨皮、夏枯草、香附、贝母 \n，五十余剂，形气渐转，更与必效散二服，疮口遂合，惟气血未平，再与前药三十余剂而愈 \n。后田生执此方不问虚实，概以治人，殊不知散中斑蝥性毒，虽治瘰 ，多服则损元气。若 \n气血实者，先用此下之，而投补剂或可愈。若虚而用下药，或用追蚀药，瘀血虽去，而疮口 \n不合，反致难治。（俱薛按） \n治瘰 痰核方，凡瘰 初起未甚者，即宜服此，或加夏枯草更佳。 \n用忍冬花、蒲公英各四五钱，以水二碗同煎汤，朝夕代茶饮之，十余日渐消。然此药但可 \n治标，若欲除根，必须灸肩 、曲池二穴。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>疔疮（四十八）\n\n属性：齐氏曰∶夫疔疮者，以其疮形如丁盖之状者是也。古方之论，凡有十种。华元化之论， \n有五色疔，《千金方》说疔有十三种，以至《外台秘要》《神巧万全》，其论颇同，然皆不离毒 \n气客于经络，及五脏内蕴热毒。凡初生一头，凹而肿痛，青黄赤黑无复定色，令人烦躁闷乱 \n，或憎寒头痛，或呕吐心逆，以针刺疮不痛无血，是其候也。多因肥甘过度，不慎房酒，以 \n邪致毒蓄结，遂生疔疮。《内经》曰∶膏粱之变，足生大疔。此之谓也。其治之法，急以艾 \n炷灸之。若不觉痛者，针疔四边，皆令血出，以夺命丹或回生丹从针孔 之，上用膏药贴 \n之 \n，仍服五香连翘汤、漏芦汤等剂，疏下之为效。若或针之不痛无血者，以猛火烧铁针通红， \n于疮上烙之，令如焦炭，取痛为效，亦 前药，用膏药贴之，经一二日脓溃根出，服托里 \n汤 \n散，根据常疗之，以取平复。如针之不痛，其人眼黑，或见火光者，不可治也。此邪毒之气， \n入于脏府故也。《养生方》云∶人汗入肉食，食之则生疔疮。不可不慎也。 \n立斋曰∶此证多由膏粱浓味之所致，或因卒中饮食之毒，或感四时不正之气，或感蛇虫 \n之毒，或感死畜之秽，各宜审而治之。其毒多生于头面四肢，形色不一，或如小疮，或如水 \n泡，或疼痛，或麻木，或寒热作痛，或呕吐恶心，或肢体拘急，并宜隔蒜灸之。痛则灸至不 \n痛，不痛灸至痛。若灸而不痛，则明灸之。及针疔四畔去恶血，以夺命丹一粒入疮头孔内， \n仍以膏药贴之，并服解毒之剂，或用荆防败毒散。若针之不痛无血者，宜用烧针，治如前齐氏 \n之法。若不省人事，或牙关紧急者，以夺命丹为末，葱酒调灌之。候醒更服败毒散，或夺命 \n丹，甚效。若生两足者，多有红丝至脐。生两手者，多有红丝至心腹。生唇面口内者，多有 \n红丝入喉。皆为难治。急宜用针于血丝尽处挑破，使出恶血。若红丝近心腹者，更挑破疮头 \n去恶水，以泄其毒，亦以膏药贴之，多有生者。若患于偏僻下部之处，药力所难到者。若专 \n假药力，则缓不及事，惟灸之，则大有回生之功。疔之名状虽有十三种之不同，而治法，但 \n当审其元气虚实，邪之表里，庶不误人之夭札也。若专泥于疏利表散，非为无益而反害之。 \n凡人暴死者，多是疔毒，急取灯遍照其身，若有小疮，即是其毒，宜急灸之。并服夺命丹等 \n药，亦有复苏者。 \n又曰∶脉浮数者散之，脉沉实者下之。表里俱实者，解表攻里。麻木或大痛及不痛者， \n并灸之，更兼攻毒。 \n操江张恒山，左足次指患之，痛不可忍，急隔蒜灸三十余壮，即能举步。彼欲速愈，自 \n敷凉药，遂致血凝肉死，毒瓦斯复炽。再灸百壮，服活命饮，出紫血，其毒方解，脚底通溃 \n，腐筋烂肉甚多。及将愈，予因考绩北上，又误用生肌药，反助其毒，使元气亏损，疮口难 \n敛。予回用托里药补之。喜其禀实，且客处，至三月余方瘥。 \n表甥居富，右手小指患之，或用针出血，敷以凉药，掌指肿三四倍，六脉洪大，此真气 \n夺则虚，邪气盛则实也。先以夺命丹一服，活命饮二剂，势稍缓。余因他往，或又遍刺出血 \n，肿延臂腕，如大瓠，手指肿大数倍，不能消溃，乃真气愈虚，而邪气愈盛也。余回，用大剂 \n参归术之类及频灸。遍手肿势渐消后，大便不实，时常泄气，此元气下陷，以补中益气汤 \n加补骨脂、肉豆蔻、吴茱萸、五味子，又以生脉散代茶饮。大便渐实，手背渐溃，又用大补药 \n五十余剂渐愈。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>时毒（四十九）\n\n属性：齐氏曰∶时毒者，为四时邪毒之气而感之于人也。其候发于鼻面耳项咽喉，赤肿无头，或 \n结极有根，令人憎寒发热头痛，肢体甚痛，恍惚不守，咽喉闭塞。人不识者，将谓伤寒。原 \n夫此疾，古无方论，世俗通谓丹瘤，病家恶言时毒，切恐传染。经曰∶人身忽经变赤，状如 \n涂丹，谓之丹毒。此风热恶毒所为，自与时毒不同。盖时毒者，感四时不正之气，初发状如 \n伤寒，五七日之间乃能杀人，若至十日之外，则不治自愈也治宜辨之。先诊其脉，凡滑数 \n浮洪、沉紧弦涩皆其候也。但浮数者，邪在表也；沉涩者，邪气深也。察其毒之甚者，急服化 \n毒丹，以攻之。实热便秘者，大黄汤下之。其有表证者，犀角升麻汤以发之。或年高气郁者 \n，五香连翘汤主之。 \n又于鼻内 通气散，取十余嚏作效，若 药不嚏者，不可治之。若嚏出脓血者，治 \n之必愈。凡左右看病之人，日日用 药嚏之，必不传染，切须记之。其病患每日用嚏药三五次 \n，以泄热毒，此治时证之良法也。 \n凡经三四日不解者，不可大下，犹宜和解之，以犀角散、芩连消毒饮，甚者连翘汤之类 \n。至七八日，大小便通利，而头面肿起高赤者，可服托里散、托里黄 汤。如肿甚者，宜砭 \n患处，出恶血，以泄其毒瓦斯。此病若五日以前，精神昏乱，咽喉闭塞，语言不出，头面赤肿， \n食不知者，必死之候，治之无功矣。然而此疾有阴有阳，有可汗者，有可下者，尝见粗工但 \n云热毒，只用寒药，殊不知病有微甚，治有逆从，不可不审矣。 \n罗谦甫云∶泰和二年，先师监济源税时，四月民多疫疠。初觉憎寒体重，次传头面肿， \n盛目不能开，上喘，咽喉不利，舌干口燥。俗云大头天行，亲戚不相访问，染之多不救。张 \n县令侄亦得此病。至五六日，医以承气加板蓝根下之，稍缓。翌日，其病如故，下之又缓， \n终莫能愈，渐至危笃。或曰∶李明之存心于医，可请治之。遂请诊视，具说其由。先师曰∶ \n夫身半以上天之气也，身半以下地之气也。此邪热客于心肺之间，上攻头目而为肿盛，用承 \n气下之以泻胃中之实热，是诛伐无过也，殊不知适其病所为故。遂处一方，用黄芩、黄连苦 \n苦寒泻心肺间热以为君；橘红苦平，玄参苦寒，生甘草甘寒，人参甘平，泻火补气以为臣；连翘 \n、鼠粘子、薄荷叶苦辛平，板蓝根味苦寒，马勃、白僵蚕味苦平，行少阳阳明二经气不得伸 \n，桔梗味辛温为舟楫不令下行，升麻、柴胡苦辛以散表邪。共为细末，半用汤调，时时服之 \n，半蜜为丸噙化之，服尽良愈。因叹曰，往者不可追，来者犹可及，凡他所有病者，皆书方 \n以贻之，全活甚众。时人皆曰，此方天人所制，遂刊于石，以传永久，命曰普济消毒饮。 \n薛立斋曰∶此感四时不正之气，邪客心肺之间，上攻头目而为患，与膏粱积热之证不同 \n，硝黄之剂，非大便秘实者不可用，若不审其因，不辨表里虚实而概用攻，必致有误。里实 \n而不利者，下之。表实而不解者，散之。表里俱实而不解者，解表攻里。 \n表里俱解而不消者，和之。肿甚 痛者，砭去恶 \n血，更用消毒之剂。不作脓或不溃者，托之。饥年普患者，不宜用峻利药，当审而治之。 \n又《治法》曰∶若脉浮者，邪在表也，用葛根牛蒡汤、犀角升麻汤、人参败毒散之类以 \n发之。脉沉涩者，邪在里也，用栀子仁汤、五利大黄汤之类以下之。表里俱病而肿不退者， \n用犀角升麻汤，甚者砭出恶血，并用通关散 鼻内取嚏，以泄其毒。表里俱不解而内外俱实 \n者，防风通圣散。欲其作脓者，用托里消毒散。欲其收敛者，用托里散。此法最为稳当。常 \n见饥馑之际，刍荛之人，多患之，乃是胃气有损，邪气从之为患也。故凡以凶荒劳役而患此 \n者，多宜安里为主。或用普济消毒饮最善。 \n一老人，冬月头面耳项俱肿痛甚，便秘，脉实，此表里俱实病也，与防风通圣散不应。 \n遂砭患处出黑血，仍投前药即应，又以荆防败毒散而 。盖前药不应者，毒血凝聚上部经络 \n，药力难达故也。恶血既去，其药自效。或拘用寒远寒及年高畏用硝黄，而用托里与夫寻常 \n消毒之剂，或不砭泄其毒，专假药力，鲜不危矣。 \n一男子，头面肿痛，服硝黄败毒之剂愈甚。诊之脉浮数，其邪在表尚未解散，用荆防败 \n毒散加玄参牛蒡子二剂，势退大半，以葛根牛蒡子汤四剂而痊。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>肺痈肺痿（五十）\n\n属性：此证初起，邪结在肺者，惟桔梗杏仁煎为治此之第一方。在新因三三。 \n齐德之曰∶肺者五脏之华盖也，处于胸中，主于气候，于皮毛。劳伤血气，腠理虚，而 \n风邪乘之，内感于肺也，故汗出恶风，咳嗽短气，鼻塞项强，胸胁胀满，久久不瘥，已成肺 \n痿也。风中于卫，呼气不入，热至于营，则吸而不出。所以风伤皮毛，热伤血脉，风热相搏 \n，气血稽留，蕴结于肺，变成疮疽。诊其脉候，寸口脉数而虚者，肺痿也。数而实者，肺痈 \n也。若欲知其有脓，但脉见微紧而数者未有脓也，紧甚而数者已有脓也。肺痿之候，久嗽不 \n已，汗之过度，重亡津液，便如烂瓜，下如豕膏，小便数而不渴。渴者自愈，欲饮者将瘥 \n。此由肺多唾涎而无脓者，肺痿也。肺疮之候，口干喘满，咽燥而渴，甚则四肢微肿，咳唾 \n脓血，或腥臭浊沫，胸中隐隐微痛者，肺疽也。又《圣惠》曰，中府隐隐微痛者，肺疽也。 \n上肉微起者，肺疮也。中府者，穴名也。是以候始萌则可救，脓成则多死。又《内经》曰∶ \n血热则肉败营卫不行，必将为脓。大凡肺疮当咳嗽短气，胸满，时唾脓血，久久如粳米粥者 \n，难治。若呕脓而不止者，亦不可治。其呕脓而自止者，将自愈。其脉短而涩者，自痊。浮 \n洪而大者，难治。其面色当白而反面赤者，此火之克金，皆不可治。仲景曰∶上气面浮肿， \n肩息，其脉浮大，不治。又加利尤甚。 \n马益卿曰∶肺痈治法要略，先以小青龙汤一帖，以解其风寒邪气，然后以葶苈大枣泻肺 \n汤、桔梗汤、苇茎汤（见《金匮要略》）随证用之以取脓，此治肿疡之例也。终以内补黄 汤， \n以补里之阴气，此治溃疡之例也。又曰∶肿痈已破，入风者不治，或用太乙膏丸服，以搜风汤 \n吐之，若吐脓血状如肺痈口臭，他方不应者 \n，宜消风散，入男子发灰，清水饮调下，两服可除。 \n立斋曰∶凡劳伤血气，腠理不密，外邪所乘，内感于肺，或入房过度，肾水亏损，虚火 \n上炎，或醇酒炙爆，辛辣浓味，熏蒸于肺，或咳唾痰涎，汗下过度，重亡津液，皆能致之 \n。其候恶风，咳嗽，鼻塞，项强，胸胁胀满，呼吸不利，咽燥作渴，甚则四肢微肿，咳唾脓 \n血。若吐痰臭浊，脓血腥秽，胸中隐隐微痛，右手寸口脉数而实者，为肺疽。若唾涎沫而无 \n脓，脉数而虚者，为肺痿也。 \n又《治法》曰∶大抵劳伤气血则腠理不密，风邪乘肺，风热相搏，蕴结不散，必致咳嗽 \n。若误用汗下过度，则津液重亡，遂成斯证。凡喘嗽气急胸满者，表散之。咳嗽发热者，和 \n解之。咳而胸膈隐痛，唾痰腥臭者，宜排脓散。喘急恍惚，痰盛者，宜平肺。唾脓，脉短涩者，宜补之。 \n又《治法》曰∶若咳嗽喘急者，小青龙汤。咳嗽胸胀者，葶苈大枣泻肺汤。咳脓腥浊者 \n，桔梗汤。咳喘短气或小便短少者，佐以参 补肺汤。体倦食少者，佐以参术补脾汤。咳唾 \n痰壅者，肾虚水泛也，六味地黄丸。口干咽燥者，虚火上炎也，加减八味丸。此证皆因脾土 \n亏损不能生肺金，肺金不能生肾水，故始成则可救，脓成则多死。苟能补脾肺滋肾水，庶有 \n生者。若专攻其疮，则脾胃益虚，鲜有不误者矣。 \n陆司厅子，春间，咳嗽唾痰腥秽，胸满气促，皮肤不泽，项强脉数，此肺疽也。盖肺系 \n在项，肺伤则系伤，故牵引不能转侧。肺者气之本，其华在毛，其充在皮，治以黄 、当归 \n、川芎、白芷、贝母、知母、麦冬、栝蒌仁、桔梗、防风、甘草，兼以蜡矾丸及太乙膏治 \n之，脓尽脉涩而愈。 \n一男子，面白神劳，咳而胸膈隐痛，其脉滑数。予以为肺痈，欲用桔梗汤，不信。仍服 \n表药，致咳嗽愈甚，唾痰腥臭，始悟。乃服前汤四剂，咳嗽少定，又以四顺散四剂而脉静， \n更以托里药数剂而愈。 \n一男子，咳嗽喘急，发热烦躁，面赤咽痛，脉洪大。用黄连解毒汤二剂少退，更以栀 \n子汤四剂而安。 \n一男子患肺痿，咳嗽喘急，吐痰腥臭，胸满咽干，脉洪数。用人参平肺散六剂，及饮童 \n便，诸证悉退，更以紫苑茸汤而愈。童便虽云专治虚火，常治疮汤 肿疼痛，发热作渴， \n及肺痿肺痈发热口渴者尤效。 \n一男子面赤吐脓，发热做渴，烦躁引饮，脉洪数而无伦次。先用加减八味丸加麦冬大剂 \n一服，热渴顿止。即熟睡良久，觉而神爽索食，再剂诸证顿减。仍用前药，更以人参五钱 \n，麦冬二钱五分，五味二钱，水煎代茶，日饮一剂，月余而安。此证面赤者，当补肺肾，面 \n白者，当补脾肺，治者审之。 \n一妇人，素血虚，发热咳嗽，或用痰火之剂后吐脓血，面赤脉数，其势甚危，此脓成而 \n气血虚也。余用八珍汤以补元气，用桔梗汤以治肺证，因得渐愈。 \n一儒者患肺痈，鼻流清涕，咳吐脓血，胸膈作胀，此风邪外伤也。先用消风散加乱发灰 \n，二服而鼻利。又用四君加芎归及桔梗汤而愈。后因劳役，咳嗽吐脓，小便滴沥，面色黄白 \n，此脾土不能生肺金，肺金不能生肾水也，用补中益气汤、六味地黄丸而愈。 \n一仆年逾三十，嗽久不愈，气壅不利，睡卧不安，咯吐脓血，甚虚可畏，其主已弃矣。 \n余以宁肺散，一服少愈，又服而止大半，及以宁肺汤数剂而痊。所谓有是病，必用是药，若 \n泥前散性涩而不用，何以得愈。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>乳痈乳岩（五十一，妇人门亦有乳证当互察之）\n\n属性：立斋曰∶乳房属足阳明胃经，乳头属足厥阴肝经。男子房劳恚怒伤于肝肾，妇人胎产忧 \n郁损于肝脾，皆能致之。若因暴怒或儿口气所吹肿痛者，宜疏肝行气。 痛发寒热者，发散 \n表邪。 肿痛甚者，清肝消毒，并宜隔蒜灸。未成脓者，疏肝行气。不作脓或不溃者，托 \n里为主。溃而不敛或脓清者，宜大补脾肺气血为主。 \n又治法曰∶若脓出反痛，或作寒热，气血虚也，十全大补汤。体倦口干，中气虚也，补 \n中益气汤。晡热内热，阴血虚也，八珍汤加五味子。欲呕作呕，胃气虚也，补胃为主，或用 \n香砂六君子汤。食少作呕，胃气虚寒也，前汤加干姜。食少泄泻，脾气虚寒也，理中汤或加 \n人参、附子。若劳碌以致肿痛，气血未复也，八珍汤倍用参、 、归、术。若因怒气以致肿 \n痛，肝火伤血也，八珍汤加柴胡、山栀。若肝火血虚而结核不消者，四物汤加柴胡、升麻。 \n若肝脾气血俱虚而结核者，四君子加芎、归、柴胡、升麻。郁结伤脾而结核者，归脾汤兼神 \n效栝蒌散。若为儿所吹而发肿 痛，须吮通揉散，否则成痈矣。若兼余证，亦当治以前法 \n。若妇人郁怒伤肝脾而结核，不痒不痛，一二载始溃者，名曰乳岩，最难治疗。 \n又治法曰∶若忿怒伤肝，浓味积热，以致气不行，窍不通，乳不出，则结而为肝为痛， \n此阳明之血热。甚则肉腐为脓。若脓一成，即针出之，以免遍溃诸囊之患。亦有所乳之子， \n膈有滞痰，口气 热，含乳而睡，热气所吹，遂成肿痛。于初起时，须吮咂使通，或忍痛 \n揉散之，失治必成痈患。宜用青皮以疏厥阴之滞，石膏以清阳明之热，甘草节以行污浊之血， \n栝蒌子以消肿导毒。或加没药、橘叶、皂角针、金银花、当归更宜，随证消息加减而治。仍 \n用少酒佐之，更用隔蒜灸之，其效尤捷。若有脓即针之，否则通溃难于收敛。 \n乳痈，用蒲公英忍冬藤，入少酒煎服，即欲睡，是其功也，及觉而病安矣。（见《外科心法》） \n一妇人患乳痈，寒热头痛，与荆防败毒散一剂，更与蒲公英一握捣烂，入酒二三盏再捣 \n，取汁热服， 热罨患处而消。丹溪云∶此草散热毒，消肿核，又散滞气，解金石毒之圣药。 \n一妇人左乳内肿如桃，不痛，色不变，发热，渐消瘦，以八珍汤加香附、远志、青皮 \n、柴胡百余剂，又间服神效栝蒌散三十余剂，脓溃而愈。常见患者责效太速，或不解七情 \n及药，不分经络虚实者，俱难治。大抵此证四十以外者尤难治，盖因阴血日虚也。 \n一妇人，因怒左乳内肿痛发热，表散太过，致热益甚，以益气养营汤数剂，热止脓成。 \n欲用针，彼不从，遂肿胀大热发渴。始针之，脓大泄，仍以前汤，月余始愈。 \n一男子，左乳肿硬痛甚，以仙方活命饮二剂而痛止，更以十宣散加青皮四剂，脓成，针 \n之而愈。此证若脓成未破，疮头有薄皮剥起者，用代针之剂点起皮处，以膏药贴之，脓亦自 \n出。但不若及时针之，则不致大溃。如脓出不利，更 入搜脓化毒之药。若脓血未尽，辄 \n用生肌之剂，反助邪气。纵早合，必再发。不可不慎也。 \n一产妇因乳少服药通之，致乳房肿胀发热作渴，状类伤寒，以玉露散补之而愈。夫乳汁乃 \n气血所化，在上为乳，在下为经。若冲任之脉盛，脾胃之气壮，则乳汁多而浓，衰则少而 \n淡，所乳之子亦弱而多病，此自然之理。亦有屡产有乳，再产却无，或大便涩滞，乃亡津液 \n也。《三因论》云，产妇乳脉不行有二，有血气盛闭而不行者，有血气弱涩而不行者，虚当 \n补之，盛当疏之。盛者当用通草、漏芦、土瓜根辈，虚者当用炼成钟乳粉、猪蹄、鲫鱼之属 \n，概可见矣。（俱薛按） \n一妇人久郁，右乳内结三核，年余不消，朝寒暮热，饮食不甘，此乳岩也。乃七情所 \n伤，肝经气血枯槁之证，宜补气血解郁结药治之。遂以益气养营汤百余剂，血气渐复；更 \n以木香饼灸之。喜其谨疾，年余而消。若用克伐之剂以复伤血气，则一无可保者。 \n一外家，乃放出宫人，乳内结一核如栗，欲用前汤，彼不信，乃脓疮科流气饮及败毒散， \n三年后大如覆碗，坚硬如石，出水不溃而殁。大抵郁闷则脾气阻，肝气逆，遂成隐核，不痛 \n不痒，人多忽之，最难治疗。若一有此，宜戒七情，远浓味，解郁结，更以养血气之药治之 \n，庶可保全，否则不治。亦有数载方溃而陷下者，皆曰乳岩，盖其形似岩穴而最毒也，慎之 \n则可保十中之一二。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>胃脘痈（五十二）\n\n属性：立斋引《圣济总录》云∶胃脘痈，由寒气隔阳，热聚胃口，寒热不调，故血肉腐坏。以 \n气逆于胃，故胃脉沉细，以阳气不得上升，故人迎热甚，令人寒热如疟，身皮甲错，或咳嗽 \n，或呕脓唾血。若脉见洪数，脓已成也，急宜排之。设脉迟紧，其脓未就，有瘀血也，急下 \n之。否则邪毒内攻，腐烂肠胃矣。丹溪云∶内疽者，因饮食之毒，七情之火，相郁而发，用 \n射干汤主之。愚常以薏苡仁汤、牡丹皮散、太乙膏选用之，亦效。若吐脓血，饮食少思，宜 \n助胃壮气为主，而佐以前法，不可专治其疮。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>腹痈（五十三）\n\n属性：立斋曰∶腹痈，谓疮生于肚腹，或生于皮里膜外，属膏粱浓味，七情郁火所致。若漫肿 \n坚硬，肉色不变，或脉迟紧，未成脓也，四君加芎、归、白芷、枳壳，或托里散。肿软色赤 \n，或脉洪数，已成脓也，托里消毒散。脓成而不外溃者，气血虚也，卧针而刺之。 肿作 \n痛者，邪气实也，先用仙方活命饮，隔蒜灸，以杀其毒，后用托里以补其气。若初起，欲其内 \n消，当助胃壮气，使根本坚固，而以行经活血之药佐之。若用克伐之剂，欲其消散，则肿者 \n不能溃，溃者不能敛。若用疏利之药， \n下其脓血，则少壮者，多为难治，老弱者，立见危亡。若有食积疝气类此者，当辨而治之。 \n进士边云庄，腹痛、恶寒，脉浮数。余曰∶浮数之脉而反恶寒，疮疽之证也。不信。数 \n日后，复请视之，左尺洪数。余曰∶内有脓矣。仍不信。至小腹痛胀，连及两臀，始悟 \n。余曰∶脓溃臀矣，气血俱虚，何以收敛。急服活命饮一钟，臀溃一孔，出脓斗许，气息奄 \n奄。用大补药一剂，神思方醒。每去后，粪从疮出，痛不可当，小腹间如有物上挺，即发痉 \n不省人事，烦躁，脉大，举按皆实。省而细察之，脉虽洪大，按之如无，以十全大补，倍加参、 \n至四斤，更加附子二枚，煎膏服之而痉止。又用十全大补汤，五十余剂而疮敛。 \n上舍周一元，患腹痈三月不愈，脓水清稀，朝寒暮热，服四物、黄柏、知母之类，食少 \n作泻，痰涎上涌。服二陈、枳实之类，痰涎愈甚，胸膈痞闷。谓余曰∶何也。余曰∶朝寒暮 \n热，血气虚也。食少作泻，脾肾虚也。痰涌胸痞，脾肺虚也。悉因真气虚，而邪气实也。当 \n先壮其胃气，使诸脏有所禀，而邪自退矣。遂用六君加黄 、当归，数剂诸证渐退。又用十 \n全大补汤，肌肉渐敛。更用补中益气汤，调理而愈。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>肠痈（五十四）\n\n属性：孙真人云∶肠痈为病，小腹重强，按之则痛，小便如淋，时时汗出，复恶寒，身皮甲 \n错，腹皮急如肿，甚者腹胀大，转侧有水声。或绕脐生疮，或脓从脐出，或大便脓血。脉洪 \n数者，已有脓也，血下则安。若妄治者，必杀人。 \n陈无择曰∶肠痈为病，身甲错，腹皮急，按之濡，始肿状，腹无聚积，身无热。脉数 \n，此为肠内有脓，久积阴冷所成也，故《金匮》有用附子温之。其脉迟紧者，脓未成，可下 \n之，当有血。洪数者，脓已成，不可下，此以内结热所成也，故《金匮》有用大黄利之。 \n《千金方》灸法∶曲两肘，正肘头锐骨，灸百壮，下脓血而安。 \n一男子，里急后重，下脓胀痛，此脾气下陷也，用排脓散、蜡矾丸而愈。后因劳役，寒 \n热体倦，用补中益气汤而安。 \n一妇人，脓成腹胀痛，小便不利，脉滑数，此脓毒内溃也。服太乙膏三钱，脓下升许， \n胀痛顿退。更以神效栝蒌散，二剂而全退。又以蜡矾丸及托里药，十余剂而安。 \n一产妇小腹疼痛，小便不利，以薏苡仁汤，二剂痛止。更以四物汤加桃仁、红花，下瘀血升许而愈。 \n一妇人产后恶露不尽，小腹患痛，服瓜子仁汤，下瘀血而痊。凡瘀血停滞，宜急治之， \n缓则腐化为脓，最难治疗。若使流注骨节，则患骨疽，失治，多为败证。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>附骨疽（五十五）\n\n属性：附骨疽一证，近俗呼为贴骨痈。凡疽毒最深，而结聚于骨际者，皆可谓之附骨疽。然尤 \n惟两股间，肉浓处，乃多此证。盖此证之因，有劳伤筋骨而残损其脉者，有恃酒力房而困烁 \n其阴者，有忧思郁怒而留结其气者，有风邪寒湿而凑滞其经者。凡人于环跳穴处，无故酸痛 \n，久而不愈者，便是此证之兆，速当因证调治，不可迟也。盖其初起，不过少阳经一点逆滞 \n，逆而不散，则以渐而壅，壅则肿，肿则溃，至其延漫，则三阴三阳，无不连及，而全腿俱 \n溃。然此证，无非元气大亏，不能营运，故致留滞不散，而后至决裂，诚危证也。若溃后脉 \n和，虽见困弱之甚，只以大补气血为主，皆可保全。若溃后脉反洪芤，而烦躁不宁，发热口 \n渴，则必不可治。 \n至若治此之法，凡以劳伤筋骨而致者，宜大营煎，兼大防风汤治之。若酒色伤阴者，宜 \n八味丸、六味丸，或右归饮，兼大防风汤主之。若忧思郁怒结气者，宜疮科流气饮，或五香 \n连翘汤。兼大防风汤主之。若风寒外袭者，宜五积散，兼大防风汤主之。大抵此证初起，即宜 \n用大营煎，温补气血，或兼仙方活命饮，通行毒瓦斯。有火者，宜速用连翘归尾煎，以解散其 \n毒。仍宜速用隔蒜灸，或豆豉饼寻头灸之。以速散其毒，最为捷法。其有湿热痰饮等证，当 \n并求后法以治之，庶免大害也。若环跳久痛不已，或见臀股微肿，度其已成，势不能散，只 \n宜速用托补，专固根本，使其速起速溃，则根本既实，虽凶亦无大害，必且易溃易敛而易愈 \n也。若脉见滑数，按之软，熟脓已成也。速宜针之，无使久留，以防深蚀之患。其有不明利 \n害，苟图目前，或用克伐消散，再伤元气。或用寒凉敷药，以遏其毒瓦斯，必致日延日甚，而 \n元气日败，则一溃不可收拾矣。考诸方书，俱未详及此证，故悉其所因，并附治按于后。 \n立斋曰∶附骨疽，有因露卧，风寒深袭于骨者。有因形气损伤，不能起发者。有因克 \n伐之剂，亏损元气，不能发出者。有因外敷寒药，血气凝结于内者。凡此皆宜灸熨患处，解 \n散毒瓦斯，补接元气，温补脾胃为主。若饮食如常，先用仙方活命饮，解毒散郁，随用六君子 \n汤，补托营气。若体倦食少，但用前汤，培养诸脏，使邪不得伤正。若脓已成，即针之 \n，使毒瓦斯不得内侵，带生用针亦无妨。如用火针，亦不痛，且使易敛。其隔蒜灸，能解毒行 \n气，葱熨法能助阳气，行壅滞。此虽不见于方书，予常用之大效，其功不能尽述，惟气血虚 \n脱者，不应。又曰∶大抵此证，虽云肿有浅深，感有轻重，其所受皆因真气虚弱，邪气得以深袭。若真气 \n壮实，邪气焉能为患也。故附骨痈疽，及鹤膝风证，惟肾虚者多患之。前人用附子者，以温补 \n肾气，而又能行药势，散寒邪也。亦有体虚之人，秋夏露卧，为冷气所袭，寒邪伏结，多成 \n此证，不能转动，乍寒乍热而无汗，按之痛应骨者是也。若经久不消，极阴生阳，寒化为热 \n而溃也。若被贼风所伤，患处不甚热，而洒淅恶寒，不时汗出，熨之痛止，少者须大防风 \n汤，及火龙膏治之，若失治则为弯曲、偏枯。有坚硬如石者，谓之石疽。若热缓，积日不溃 \n，肉色赤紫，皮肉俱烂，名缓疽。其始末皆宜服前汤，欲其驱散寒邪，以补虚托里也。 \n又曰∶此证亦有产后恶血未尽，脐腹刺痛，或流于四肢，或注于股内，疼痛如锥，或两 \n股肿痛。此由冷热不调，或思虑动作，气所壅遏，血蓄经络而然，宜没药丸治之。亦有经血 \n不行，流注四肢；或股内疼痛如锥，或因水湿所触，经水不行而肿痛者，宜当归丸治之。 \n凡恶血停滞，为患匪轻，治之稍缓，则流注为骨疽，多致不救。 \n一妇人膝肿痛，遇寒痛益甚，月余不愈，诸药不应，脉弦紧，此寒邪深伏于内也，用大 \n防风汤，及火龙膏治之而消。 \n一男子，腿根近环跳穴，患痛彻骨，外皮如故，脉数而滞滑，此附骨疽，脓将成也。用 \n托里药六剂，肿起作痛，脉滑数，其脓已成。针之出碗许，更加补剂，月余而瘳。 \n一男子患附骨疽，肿硬发热，骨痛筋挛，脉数而沉，用当归拈痛汤而愈。 \n一男子腿内患痈，漫肿作痛，四肢厥逆，咽喉闭塞，发寒热，诸治不效，乃邪郁经络而 \n然也。用五香连翘汤一剂，诸证少退。又服之，大便行二次，诸证悉退而愈。 \n一男子，先腿痛，后四肢皆痛，游走不定，至夜益甚，服除湿败毒之剂不应，其脉滑而 \n涩，此湿痰浊血为患。以二陈汤加苍术、羌活、桃仁、红花、牛膝、草乌，治之而愈。凡湿 \n痰湿热，或死血流注关节，非辛温之剂，开发腠理，流通隧道，使气行血和，焉能得愈。 \n王时亨室，产后腰间肿痛，两腿尤甚，此由瘀血滞于经络而然也。不早治，必作骨疽。 \n遂与桃仁汤二剂稍愈，更以没药丸数服而痊。（薛按） \n一魏生者，年三十余，素多劳碌。忽患环跳酸痛，数月后，大股渐肿。延予视之曰∶此 \n附骨疽也，速当治之。与以活命饮二剂，未及奏效，而肿益甚。因慌张乱投，或清火，或解毒 \n，遂致呕恶发热，饮食不进，其势甚危，然后恳求相救。遂以参 内托散大加炮姜，数剂而 \n呕止食进。其肿软熟，知其脓成，速令针之，针处出脓不多。复以九味异功煎与之，遂得大 \n溃，且瓣瓣出脓，溃者五六处，而腿肉尽去，止剩皮骨矣。溃后复呕恶，发热不食，遂以十 \n全大补汤，及九味异功煎，相间与之。然后热渐退，食渐近，稍有生色。然足筋短缩，但可 \n竖膝仰卧，左右挨紧，毫不能动，动则痛极，自分已成废物。此后，凡用十全大补汤八十余 \n剂，人参三斤，而腿肉渐生，筋舒如故，复成一精壮男子，此全得救本之功也。 \n一男子陈姓者，年近三旬，素不节欲，忽见环跳酸痛，月余不愈。予曰∶此最可畏，恐 \n生痈毒之患。彼不信，又谋之一庸医，反被其诟曰∶此等胡说真可笑也。筋骨之痛，亦常 \n事耳，不过风热使然，何言痈毒。遂用散风清火等药，至半年后，果见微肿，复来求治。予 \n曰∶速用托补，以救根本，尚不迟也。彼又不信，而谋之疡医曰∶岂可肿疡未溃，而遽可温 \n补耶。复用清火清毒之剂。及其大溃而危，再延余视，则脉证俱败，方信予言。而痛悔前失，已无及矣。 \n一膏粱子茅姓者，年未三旬，素以酒色为事，亦患此证。早令服药，执拗不从。及其肿 \n而脓成，令速针之，亦畏痛不从。而偏听庸流，敷以苦寒解毒之药。不知脓既已成，尤不可 \n解，但有愈久愈深，直待自溃，而元气尽去，不可收拾矣。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>臀痈（五十六）\n\n属性：马益卿曰∶臀痈证，臀居小腹之下，此阴中之阴也，道远位僻，虽曰多血，然气运不到 \n，血亦罕来，中年之后，尤虑患此。才有肿痛，参之脉证，但见虚弱，便与滋补。气血无亏，可保终吉。 \n立斋曰∶凡治此者，毋伤脾胃，勿损脾气，但当以固根本为主。若 痛，尺脉紧而无力者 \n，托之。肿硬痛甚者，隔蒜灸之，更以解毒。不作脓者，托里为主。不作脓而痛者，解毒为 \n主。不溃或溃而不敛者，托里为主。 \n又《治法》曰∶若肿硬作痛者，形气虚而邪气实也，用托里消毒散。微肿微痛者，形气病 \n气俱虚也，用托里散补之。欲作脓者，用内托羌活汤。若痛甚者，用仙方活命饮。大势既退 \n，亦用托里消毒散。若脾虚不能消散，或不溃不敛者，六君子加芎、归、黄 。若阴虚不能 \n消散，或作渴便淋者，六味丸加五味子。若阳虚不能溃，或脓清不能敛者，用补中益气汤。 \n气血俱虚者，十全大补汤。若肿硬未成脓者，用隔蒜灸，及活命饮。溃后，宜豆豉饼，及补 \n中益气、十全大补二汤。若灸后大势已退，余毒未消，频用葱熨，以补其气，以消余毒为善。 \n又曰∶凡毒瓦斯已退不起者，但可补其血气，使脓速成而针去之，不可用内消之论。若 \n肿高而软者，发于血脉，肿下而坚者，发于筋骨，肉色不变者，发于骨髓也。脓血大泄之后 \n，当大补气血为先，虽有他证，以末治之。 \n巡按陈和峰，脾胃不健，常服消导之剂，左腿股及臀患肿。余曰∶此脾气虚而下注，非 \n疮毒也，当用补中益气，倍加白术。彼惑于众人云，白术能溃脓，乃专以散肿消毒为主，而 \n肿益甚，体益倦。余用白术一味煎饮而消。 \n儒者杨启元，左臀患此，敷贴凉药，肿彻内股。服连翘消毒散，左体皆痛。余以为足三 \n阴亏损，用补中益气汤，以补脾肺；用六味丸加五味子，以补肝肾。股内消而臀间溃，又用 \n十全大补汤而疮口敛。 \n一儒者， 肿痛甚，此邪毒壅滞，用活命饮、隔蒜灸而消。后因饮食劳倦，肿痛复作 \n，寒热头痛，此元气虚而未能复也，与补中益气汤，频用葱熨法，两月而愈。 \n一男子，患臀痈作脓而痛，以仙方活命饮，二剂痛止。更以托里消毒散，脓溃而瘥。 \n一弱人，臀痈脓成不溃，以十全大补汤数剂始托起。乃针之，又二十余剂而愈。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>流注（五十七）\n\n属性：立斋曰∶流注之证，多因郁结，或暴怒，或脾气虚湿气逆于肉理，或腠理不密，寒邪客 \n于经络，或湿痰，或闪扑，或产后瘀血流注关节，或伤寒余邪未尽为患，皆因真气不足，邪 \n得乘之，故气凝血聚为患也。然此证，或生于四肢关节，或生于胸腹腰臀，或结块，或漫肿 \n，或痛，或不痛，悉宜用葱熨法，及益气养营汤，固其元气，则未成者自消，已成者自溃， \n可全愈也。若不补气血及节饮食，慎起居，戒七情，而专用寒凉克伐者，俱不治。又《治法 \n》曰∶常治此证，凡暴怒所致，胸膈不利者，调气为主。抑郁所致而不痛者，宜调经脉，补 \n气血。肿硬作痛者，行气和血。溃而不敛者，补气血为主。伤寒余邪未尽者，和而解之。脾 \n气虚，湿热凝滞肉理者，健脾除湿为主。闪跌，瘀血凝滞为患者，和血气，调经络。寒邪所 \n袭，筋挛骨痛，或遍身痛，宜温经络，养血气。若久而不敛，疮口无阳者，宜豆豉饼或附子 \n饼灸之，以祛散寒邪，接补阳气。或外用琥珀膏贴之。若内有脓管，或生瘀肉，而不敛者， \n用针头散腐之自愈，锭子尤效。 \n《医林集要》云∶骨疽乃流注之败证也。如用凉药，则内伤其脾，外冰其血。脾主肌肉 \n，脾气受伤，饮食必减，肌肉不生。血为脉络血，受冰则气血不旺，而愈滞。宜用理脾，脾 \n健则血自生，而气自营运矣。又有白虎飞尸，留连周期，或展转数岁，冷毒朽骨出尽自愈。若 \n附骨腐者可痊，正骨腐则为终身废疾矣。有毒自手足，或头面肿起，或兼疼痛，上至颈项骨 \n节去处，如疡 贯珠，此风湿流气之证也，宜以加减小续命汤，及独活寄生汤治之。有两膝 \n肿痛起，或至遍身骨节疼痛者，此风湿痹，又名历节风，宜附子八物汤治之。又有结核在项 \n腋，或两乳旁，或两胯软肉处，名曰 痈，属冷证也。又有小儿宿痰失道，致结核于颈 \n项臀膊胸背之处，亦令证也，俱宜热药敷贴。以上诸证，皆缘于肾。肾主骨，肾虚则骨冷，而 \n为患也。所谓骨疽，皆起于肾，亦以其根于此也，故用大附子以补肾气，肾实则骨有生气，而疽不附骨矣。 \n一男子，臀肿一块微痛，脉弦紧，以疮科流气饮，四剂而消。 \n一妇人，暴怒，腰肿一块，胸膈不利，时或气走作痛，用方脉流气饮，数剂而止，更 \n以小柴胡汤对四物加香附、贝母，月余而愈。 \n一妇人，禀弱性躁，胁臂肿痛，胸膈痞闷，服流气败毒药反发热，以四七汤数剂，胸 \n宽气利。以小柴胡汤对四物加陈皮、香附，肿痛亦退。大抵妇人性情执着，不能宽解，多被 \n七情所伤，遂致遍身做痛。或肢节肿痛，或气填胸满，或如梅核塞喉咽吐不出，或痰涎壅盛 \n，上气喘急，或呕逆恶心，甚者渴闷欲绝。产妇多有此证。宜服四七汤，先调滞气，更以养 \n血之药。若因忧思致小便白浊者，用此汤吞青州白丸子，屡效。 \n一老人，伤寒表邪未尽，股内患肿发热，以人参败毒散二剂热止。灸以香附饼，又小柴 \n胡汤加二陈、羌活、川芎、归、术、枳壳，数剂而散。 \n一男了，退患溃而不敛，用人参养营汤及附子饼，更以补剂煎膏贴之，两月余而愈。 \n一男子，腿患肿，肉色不变，不痛，脉浮而滑，以补中益气汤加半夏、茯苓、枳壳、木 \n香饮之，以香附饼熨之。彼谓气无补法，乃服方脉流气饮，虚愈甚。复求治，以六君了汤加 \n芎归数剂，饮食少进。再用补剂，月余而消。夫气无补法，俗论也。以其为病痞塞，似难于补 \n，殊不知卫气虚而不能营运，则邪气滞而为病。经云∶壮者气行则愈，怯者弱者则着而为病 \n。苟不用补法，元气何由而行乎。 \n一妇人，腿患筋挛骨痛，诸药不应，脉迟紧，用大防风汤，二剂顿退，又二剂而安。又 \n一妇人亦然，先用前汤二服，更服黑丸子而痊。此二患若失治，必溃成败证。 \n一男子，肩胛患之，微肿，形劳气弱，以益气养营汤服黑丸子，以及木香生地黄作饼， \n覆患处熨之，月余脓成。针之，仍服前药而愈。 \n一男子，臂肿，筋挛骨痛，年余方溃，不敛，诊其脉更虚，以内塞散一料少愈，以十全 \n大补汤，及附子饼灸之而愈。《精要》云∶留积经久，极阴生阳，寒化为热。以此溃多成痿 \n，宜早服内塞散排之。 \n一男子，臂患出腐骨三块，尚不敛，发热作渴，脉浮大而涩，乃气血俱损，须多服生血 \n气之药，庶可保全。彼惑于火尚未尽，仍用凉药内服外敷，几危，求治。其形甚瘁，其脉愈 \n虚，先以六君子汤加芎归，月余饮食渐进。以八珍汤加肉桂三十余剂，疮色乃赤。更以十全 \n大补汤，外以附子饼灸之，仅年而瘥。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>鹤膝风（五十八）\n\n属性：凡肘膝肿痛，臂 细小者，名为鹤膝风，以其象鹤膝之形而名之也。或止以两膝肿大 \n，腿枯细，不能屈伸，俗又谓之鼓槌风，总不过风寒湿三气流注之为病也。然肿痛者，必 \n有邪滞，枯细者，必有血虚。凡治此者，必宜以养气滋血为主。有风者兼散其风，有寒湿者， \n兼去其寒湿。若果由邪郁成热者，必宜滋阴清火，自无不愈。其有痢后而成者，又名痢后风 \n，此以泻痢亡阴，尤宜壮肾。凡寒胜者，宜三气饮、五积散，或大防风汤之类主之。湿胜者， \n宜五苓散、理中汤之类主之。热胜者，宜保阴煎，大秦艽汤之类主之。若以阳气不足，而败及 \n四肢者，非右归丸、理阴煎及八味地黄丸之类不可。 \n立斋曰∶鹤膝风，乃调摄失宜，亏损足三阴经，风邪乘虚而入，以致肌肉日瘦，内热 \n减食，肢体挛痛，久则膝大而腿细，如鹤之膝，故尔名之。若伤于脾胃者，用补中益气汤为主。 \n若伤于肝肾者，六味地黄丸为主。若欲其作脓，或溃后者，十全大补汤为主。皆佐以大防风 \n汤。初起者，须用葱熨法，可以内消。若津涸口干，中气不足也，补中益气汤加五味子。头 \n晕头痛，阳气不升也，补中益气汤加蔓荆子。发热晡热，阴血虚弱也，用四物参、 、白术 \n。畏寒憎寒，阳气虚弱也，用十全大补汤。饮食少思，胸膈膨胀，脾胃虚痞也，用四君子汤 \n。面色痿黄，饮食少思，脾胃虚弱也，用六君子汤。脓水清稀，肌肉不生，气血俱虚也，用 \n八珍汤。热来复去，有时而动，无根虚火也，用十全大补汤。形瘦嗜卧，寝息发热，痰盛作 \n渴，小便频数，五脏虚损也，用六味丸。脐腹疼痛，夜多漩溺，脚膝无力，头晕吐痰，肾气 \n冷败也，用八味丸。发热大渴，不欲近衣，面目赤色，脉大而虚，血虚发燥，用当归补血汤 \n。或有痢后而患者，亦治以前法，余当临证制宜。 \n又曰∶夫立方之义，各有所宜。凡体气虚弱，邪入骨界，遏绝隧道，若非用附桂辛温之 \n药，开散关节腠理之寒邪，通畅隧道经络之气血，决不能愈。且《本草》云，附子治寒湿痿 \n，拘挛膝痛，不能行步，以白术佐之，为寒湿之圣药。又云，桂通血脉，消瘀血，坚骨节 \n，治风痹骨挛脚软，宣导诸药。及十全大补汤以治前证，不但不可去桂，亦不可不加附子， \n无此二味，何以行参 之功，健芎归之性，而补助血气，使之宣通经络，扶大虚之证，以收 \n必效之功哉。况前证在骨节之间，关键之地，治之不速，使血气循环，至此郁而为脓，从此 \n而泄，气血沥尽，无可生之理矣。亦有秋夏露卧，为寒所袭， 热内作，遂成附骨疽。亦有 \n贼风搏于肢节，痛彻于骨，遇寒尤甚，以热熨之则少减，尤当以大防风汤治之，更以蒜捣烂 \n摊患处，用艾铺蒜上烧之，蒜坏再易，皮肤尚破无妨。若经久不消，则极阴生阳，溃而出水 \n，必致偏枯，或为漏证，宜服内塞散，及附子饼灸之。或脉大，或发渴者，俱不治，以其真 \n气虚而邪气实也。 \n张上舍，患前证，伏枕半载，流脓三月。彼云∶初服大防风汤去附子，将溃服十宣散， \n今用十全大补汤而去肉桂，俱不应。视其脉证甚弱，予以十全大补汤，每帖加熟附子一钱， \n服三十余剂少愈。乃去附子五分，又服三十余剂将愈。却全去附子，更三十余剂而痊。 \n一男子，左膝肿大，三月不溃。予谓体虚之人，风邪袭于骨节，使气滞而不行，故膝 \n愈大而腿愈细，名曰鹤膝风，遂以大防风汤，三十余剂而消。 \n州守张天泽，左膝肿痛，胸膈痞闷，饮食少思，时欲作呕，头晕痰壅，日晡益倦，此脾 \n肺气虚也。用葱熨，及六君加炮姜，诸证顿退，饮食少进。用补中益气加蔓荆子，头目清 \n爽。间与大防风汤十余剂，又用补中益气汤，三十余剂而消。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>多骨疽（五十九）\n\n属性：立斋曰∶多骨疽者，由疮疡久溃，气血不能营于患处，邪气陷袭，久则烂筋腐骨，而脱 \n出，属足三阴亏损之证也，用补中益气汤，以固根本。若阴火发热者，佐以六味丸，壮水 \n之主，以镇阳光。阳气虚寒者，佐以八味丸，益火之源，以消阴翳。外以附子饼，葱熨法， \n祛散寒邪，补接营气，则骨自脱，疮自敛也。夫肾主骨，若肾气亏损，其骨渐肿，荏苒岁月 \n，溃而出骨，亦用前法。若投以克伐之剂，复伤真气，鲜有不误者。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>下疳疮（六十）\n\n属性：下疳一证，本肝肾湿热证也。若无外因而病者，不过去其湿热，或滋真阴。湿热既清， \n其疮自愈，无足虑也。惟感触淫毒而患者，毒有浅深，则病有微甚，皆宜用百草煎熏洗，外 \n以螵蛸散敷之，则轻者自愈。若湿热甚，而为肿为痛者，宜用芍药疾藜煎，兼而治之。如毒 \n甚者，必用萆 汤方可。若感触淫邪毒，自少阴直入精宫者，不易愈。即治如前法，然必 \n见便毒、广疮发出，而后下疳始愈。既见疮毒，即当于本证条下，求法治之。 \n余尝治一少年，因偶触秽毒，遽患下疳，始溃龟颈，敷治不效，随从马口延入尿管，以 \n渐而深，直至肛门，逐节肿痛，形如鱼骨。每过夜则脓结马口，胀不得出，润而通之，则先 \n脓后尿，敷洗皆不能及，甚为危惧。余尝遇一山臾，传得槐花蕊方，因以治之，不十日而茎 \n根渐愈，半月后即自内达外，退至马口而全愈。疳愈后，即见些微广疮，复以五加皮饮，十 \n余剂而全愈。向彼传方者曰∶此方善治淫疮热毒，悉从小便泄去，所以能治此疳，但服此者 \n，可免终身疮毒后患。然犹有解毒奇验，则在疮发之时，但见通身忽有云片红斑，数日而没 \n者，即皆疮毒应发之处。疮毒已解，而疮形犹见，是其验也。予初未之信，及此人疮发之时 \n，疮固不多，而通身红斑果见，凡两日而没。予始知疮之有奇，一至如此。（新按） \n立斋曰∶下疳，属肝经湿热下注，或阴虚火燥治法，肿痛发热者，血虚而有热也，四 \n物汤加柴胡、山栀。肿痛寒热者，肝经湿热也，小柴胡汤加龙胆草、黄连。肿痛便涩者，湿 \n热壅滞也，龙胆泻肝汤。肿痛腐溃者，气血虚而有火也，八珍汤加山栀、柴胡。日晡热甚者 \n，阴血虚而有火也，小柴胡汤加参、术、芎、归。日晡倦怠者，阳气虚而下陷也，补中益气 \n汤。有经久不愈而发寒热者，肾水不能生肝木也，宜六味丸。若筋缩或纵，或为痒痛，或 \n出白津，此筋疝也，用龙胆泻肝汤。气虚者，补中益气汤加炒山栀、炒龙胆。阴虚火燥者， \n用六味丸。茎中痒，出白津，用补中益气汤，与清心莲子饮间服。盖此证，肝经阴虚为本， \n肿痛寒热等证为标，须用六味丸，以生肝血。凡脾土虚不能生金水，而见一切肝证者，当佐 \n以补中益气汤加麦门冬，以滋化源。 \n一男子肿痛不消。一男子溃而肿痛发热，小便秘涩，日晡或热。一小儿肿痛，诸药不应 \n。俱以小柴胡汤吞芦荟丸，数服而愈。 \n一小儿，十五岁，患前证，杂用消毒之药，虚证悉具，二年余矣。询之乃禀所致，用萆 \n汤，月余诸证渐愈。又用补阴八珍汤、补中益气二汤而痊。 \n庶吉士刘华甫，或茎中作痛，或窍出白津，或小便秘涩。先用小柴胡汤加山栀、泽泻、 \n黄连、木通、胆草、茯苓二剂，以清肝火，导湿热，诸证渐愈。后因劳倦，忽然寒热，此元 \n气复伤也，用补中益气而安。又用六味丸，以生肝血滋肾水而全愈。 \n一男子，玉茎肿痛，小便如淋，自汗，甚苦，时或尿血少许，尺脉洪数，按之则涩。 \n先用清心莲子饮加牛膝、山栀、黄柏、知母、柴胡，数剂少愈，更以滋肾丸，一剂而痊。《 \n玉机微义》曰∶如自汗小便少，不可以药利之。既已自汗，则津液外亡，小便自少。若再利 \n之，则营卫枯竭，无以制火，而烦热愈甚，当俟热退汗止，小便自行也。兼此证，乃阳明经 \n病，大忌利小便。（俱薛按） \n\\x海藏治下疳久不愈方\\x \n橡斗子二个，合盛黄丹令满，以乱发浓缠定，烧烟尽为度，同研为细末。先用葱白热 \n浆水，洗疮脓尽，次上药。甚者不过三次，如神。 \n\\x又下疳方\\x \n下疳，疮内毒盛者，必须治内方愈。外治者，须螵蛸散，或此方亦佳。 \n人中白（生用） 官粉（ 黄） 红丹（飞炒） \n上等分为末，先用药汤或浓茶洗净，然后敷药。每日二三次，或用猪油，或用蜜水调敷之。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>便毒（六十一）\n\n属性：便毒论治如薛氏之法，固已详矣，然又惟交感不洁，遭淫毒而患者为最多。每每先起下 \n疳，下疳未已，便毒继之，此湿热秽毒之为患也。凡初起肿痛，尚未成脓，而元气尚强者，速 \n宜先去其毒，唯会脓散，或牡蛎散为最善。若已成脓，则或针或蚀，惟速去其脓，随因证调补 \n，使速收口为善。若初起一核，其痛微，其肿漫者，此有二证，一以邪轻，一以元气虚弱毒 \n深而然。若邪轻者，只用会通膏加麝香贴之，无有不散，或降痈散亦可。若元气虚弱而毒深 \n者，既不肯散，又不早溃，愈久必愈甚，最为可畏。及其溃后，多不能收，轻则为 ，重则 \n殒命。此惟大补元气，方不致害。若 肿痛甚，脓已将成，势不能消，宜用降痈散留头围 \n之，则势可敛，痛可解，脓可速成而溃也。 \n立斋曰∶便痈，属足厥阴肝经，内热外寒，或劳役过度，或房欲不节，或欲火不遂， \n或强固其精，或肝经湿热而致，大抵多患于劳役不足，精气俱虚之人。俗云一石米疮，此言百 \n日方可愈。若大补血气，不旬日可愈，何用百日。盖疮之收敛，在乎血气之盛也。亦有内蕴 \n热毒而生者，须辨虚实及成脓与否，不可概投攻药。凡妇人患此者，多在两拗肿痛，或腹中 \n结块，小便涩滞，苟治者得法，患者又能调摄，无足虑也。常见治此证者，概用大黄之类之下 \n之，以求内消，或其脓成，令脓从大便而出，鲜有见其痊也。人多欲内消者，恐收口之难也。 \n若知补养血气，不旬日而收矣，何难之有。若脓既成，岂有可消之理。如再用克伐之剂，必 \n致难治。 \n又曰∶便痈者，血疝也，俗呼为便毒，言于不便处为痈也。乃足厥阴之经络，及冲任督 \n脉，亦属肝之傍络。此气血流通之道路，今壅而肿痛，是则热毒所致，宜先疏导其滞，更以 \n托里之剂，此临证制宜之法也。 \n又《治法》曰∶内热外寒者，牛黄双解散。湿热壅滞者，宜用龙胆泻肝汤，疏肝导滞。 \n欲心不遂致逆精气者，先用五苓散加大黄，疏其逆滞，后用地黄丸，以补肝肾强固其精。房欲 \n不节者，宜六味丸料。劳倦过度者，补中益气汤。 \n一男子，患便毒 肿作痛，大小便秘，脉有力，以玉烛散二剂顿退，更以龙胆泻肝汤 \n，四剂而消。 \n一男子，脓未成大痛，服消毒托里等药不应。诊之脉洪大，毒尚在，以仙方活命饮，一 \n剂痛止，又剂而消。 \n一儒者，肿痛便涩，用八正散二剂，以清肝火，导湿热，而肿痛愈。再以小柴胡加芎、 \n归、泽泻、山栀二剂，以清火补血，而小便利。 \n一男子，已溃而痛不止，小便秘涩，此肝火未解也，与小柴胡加黄柏、知母、芎、归， \n痛止便利，更以托里当归汤而疮敛。若毒未解，而痛不止者，须用活命饮。 \n府庠沈尼文，年二十，左拗患之。余以肝肾阴虚，先用托里药，溃而将愈。因入房发热 \n作渴，右边亦作痛，脓水清稀，虚证悉至，脉洪大而无力，势甚可畏。用十全大补加附子一 \n钱，脉证顿退，再剂全退。后用大补汤，三十剂而愈。 \n一男子肿而不溃，此因阳气虚弱，用参、 、归、术，以补托元气，用白芷、皂刺、柴"}]);
